function isValidFirebaseConfig(cfg) {
  if (!cfg || typeof cfg !== 'object') return false;
  if (!cfg.apiKey || typeof cfg.apiKey !== 'string') return false;
  if (cfg.apiKey.includes('Demo') || cfg.apiKey.length < 20) return false;
  if (!cfg.projectId || cfg.projectId.includes('demo')) return false;
  return true;
}

function getFirebaseConfig() {
  if (window.CAMPUS_OS_FIREBASE_CONFIG && isValidFirebaseConfig(window.CAMPUS_OS_FIREBASE_CONFIG)) {
    return window.CAMPUS_OS_FIREBASE_CONFIG;
  }
  const saved = safeGetStorage('cos_firebase_config', null);
  if (saved && isValidFirebaseConfig(saved)) {
    return saved;
  }
  return DEFAULT_FIREBASE_CONFIG;
}

let db = null;
let auth = null;
let currentUser = null;
let cloudUnsubscribe = null;
let firebaseInitError = null;

function initFirebase() {
  firebaseInitError = null;
  const cfg = getFirebaseConfig();

  if (typeof firebase !== 'undefined' && firebase.apps) {
    try {
      if (!firebase.apps.length) {
        firebase.initializeApp(cfg);
      }
      auth = firebase.auth();

      // Initialize Firestore with recommended cache settings (eliminates enableMultiTabIndexedDbPersistence deprecation)
      db = firebase.firestore();
      try {
        if (typeof firebase.firestore.persistentLocalCache === 'function') {
          const tabManager = (typeof firebase.firestore.persistentMultipleTabManager === 'function')
            ? firebase.firestore.persistentMultipleTabManager()
            : undefined;
          db.settings({
            localCache: firebase.firestore.persistentLocalCache(tabManager ? { tabManager } : {})
          });
        }
      } catch (cacheErr) {
        // Graceful fallback if offline IndexedDB is restricted in browser context (e.g. private browsing)
        console.info("Firestore cache note (non-fatal):", cacheErr?.message || cacheErr);
      }

      // Process redirect authentication result if Returning from redirect sign-in
      auth.getRedirectResult().then(result => {
        if (result && result.user) {
          trackUsage('signin_done', 'google');
          currentUser = result.user;
          updateSyncUI();
          if (state.currentPage === 'settings') renderPage('settings');
        }
      }).catch(err => {
        console.warn("Firebase redirect auth result error:", err);
        handleAuthError(err);
      });

      // Opened from an email sign-in link: finish it, or ask first.
      handleEmailLinkOnStartup();

      auth.onAuthStateChanged(user => {
        currentUser = user;
        updateSyncUI();
        if (user) {
          subscribeUserCloudData(user.uid);
        } else {
          if (cloudUnsubscribe) { cloudUnsubscribe(); cloudUnsubscribe = null; }
        }
        if (state.currentPage === 'settings') renderPage('settings');
      });
    } catch (e) {
      console.warn("Firebase initialization error:", e);
      firebaseInitError = e.message || "Failed to initialize Firebase SDK.";
      updateSyncUI();
    }
  } else {
    firebaseInitError = "Firebase SDK not loaded. Please check your internet connection or ad blocker.";
    console.warn(firebaseInitError);
    updateSyncUI();
  }
}

// triggerConfetti removed — calm confirmation used instead


function getToastContainer() {
  let toastContainer = document.getElementById('toast-container');
  if (!toastContainer) {
    toastContainer = document.createElement('div');
    toastContainer.id = 'toast-container';
    // Announce toast text to screen readers -- these messages (saved,
    // error, etc.) previously had no non-visual equivalent.
    toastContainer.setAttribute('role', 'status');
    toastContainer.setAttribute('aria-live', 'polite');
    toastContainer.setAttribute('aria-atomic', 'true');
    document.body.appendChild(toastContainer);
  }
  return toastContainer;
}

function showToast(msg, type = 'info') {
  const toastContainer = getToastContainer();

  const toast = document.createElement('div');
  toast.className = `toast toast-${type}`;
  
  const iconSpan = document.createElement('span');
  iconSpan.style.fontSize = '0.95rem';
  iconSpan.textContent = type === 'success' ? '✓' : type === 'error' ? '⚠️' : 'ℹ️';
  
  const textSpan = document.createElement('span');
  // Success toasts already get a ✓ icon; drop a trailing ✓ from the text so it isn't shown twice.
  textSpan.textContent = type === 'success' ? String(msg).replace(/\s*✓\s*$/, '') : msg;

  toast.appendChild(iconSpan);
  toast.appendChild(textSpan);
  toastContainer.appendChild(toast);

  requestAnimationFrame(() => {
    toast.classList.add('toast-show');
  });

  setTimeout(() => {
    toast.classList.remove('toast-show');
    setTimeout(() => toast.remove(), 250);
  }, 3200);
}

// A calm "well done" card for real milestones (all tasks done, attendance
// back on target, countdown days). Shares the toast container so screen
// readers announce it; tap to close, otherwise it fades after ~4.5s.
function showCelebration(icon, title, subtitle = '') {
  const container = getToastContainer();

  const card = document.createElement('div');
  card.className = 'toast celebrate-card';
  const iconEl = document.createElement('span');
  iconEl.className = 'celebrate-icon';
  iconEl.setAttribute('aria-hidden', 'true');
  iconEl.textContent = icon;
  const body = document.createElement('span');
  body.className = 'celebrate-body';
  const titleEl = document.createElement('strong');
  titleEl.textContent = title;
  body.appendChild(titleEl);
  if (subtitle) {
    const sub = document.createElement('span');
    sub.className = 'celebrate-sub';
    sub.textContent = subtitle;
    body.appendChild(sub);
  }
  card.appendChild(iconEl);
  card.appendChild(body);

  const close = () => {
    card.classList.remove('toast-show');
    setTimeout(() => card.remove(), 250);
  };
  card.addEventListener('click', close);
  container.appendChild(card);
  requestAnimationFrame(() => card.classList.add('toast-show'));
  setTimeout(close, 4500);
}

// true/false once there is attendance data, null before. Same rule the
// Today page uses (v2 decides from the exact fraction).
function isOverallAttendanceOnTarget() {
  const o = getOverallAttendance();
  if (!o || !o.hasAnyData || o.pct === null) return null;
  return o.pctLabel ? o.isSafe !== false : o.pct >= getAttendanceTarget();
}

// Call with the value from before a student's own attendance tap.
function maybeCelebrateAttendanceTarget(wasOnTarget) {
  if (wasOnTarget !== false) return;
  if (isOverallAttendanceOnTarget() !== true) return;
  const o = getOverallAttendance();
  const pct = o.pctLabel ?? o.pct;
  showCelebration('🎯', 'Back on track', `You're at ${pct}%, at or above your ${getAttendanceTarget()}% target.`);
}

// One-tap "a new version is ready" banner, shown when the service worker
// detects an update -- unlike showToast() this does not auto-dismiss,
// since the user should decide when it's a good moment to reload.
function showUpdateAvailableBanner() {
  if (document.getElementById('update-available-banner')) return;
  const banner = document.createElement('div');
  banner.id = 'update-available-banner';
  banner.setAttribute('role', 'status');
  banner.style.cssText = 'position:fixed;left:12px;right:12px;bottom:calc(var(--nav-h, 60px) + 12px);z-index:9999;background:var(--surface-2);border:1px solid var(--border);border-radius:10px;padding:10px 12px;display:flex;align-items:center;justify-content:space-between;gap:10px;box-shadow:0 4px 18px rgba(0,0,0,0.18);font-size:0.875rem;color:var(--text-primary)';
  banner.innerHTML = `
    <span>✨ A new version of Clarity Desk is ready.</span>
    <div style="display:flex;gap:6px;flex-shrink:0">
      <button type="button" onclick="document.getElementById('update-available-banner')?.remove()" style="background:none;border:none;color:var(--text-muted);font-size:0.875rem;padding:4px 8px;cursor:pointer">Later</button>
      <button type="button" onclick="window.location.reload()" style="background:var(--accent);color:#fff;border:none;border-radius:6px;font-weight:600;padding:6px 14px;font-size:0.875rem;cursor:pointer">Refresh</button>
    </div>
  `;
  document.body.appendChild(banner);
}

// Last cloud push failed (not offline: Firestore just queues those). Shown
// on the badge until a push works again; data is always safe on the phone.
let cloudPushFailed = null;
let cloudPushFailToastShown = false;

function onCloudPushOk() {
  if (!cloudPushFailed) return;
  cloudPushFailed = null;
  updateSyncUI();
}

function onCloudPushError(err) {
  const code = (err && err.code) || 'unknown';
  console.warn('Cloud push error:', err);
  if (code === 'permission-denied') { updateSyncUI('denied'); return; }
  cloudPushFailed = code;
  updateSyncUI('failed');
  if (!cloudPushFailToastShown) {
    cloudPushFailToastShown = true;
    showToast(code === 'invalid-argument'
      ? 'Couldn’t sync: your desk is too big for one save. Everything is still on this phone. Remove large vault files to fix it.'
      : 'Couldn’t sync to your account. Everything is still saved on this phone, and it will try again on your next change.', 'error');
  }
}

function updateSyncUI(status = null) {
  const icon = document.getElementById('sync-icon');
  const text = document.getElementById('sync-text');
  const dot  = document.querySelector('.storage-status-dot');
  const btn  = document.getElementById('sync-status-btn');
  if (!btn && !icon) return;

  const isOnline = typeof navigator !== 'undefined' && ('onLine' in navigator) ? navigator.onLine : true;

  if (status === 'denied') {
    if (icon) icon.textContent = '🔒';
    if (text) text.textContent = 'Sync denied';
    if (dot) dot.style.background = 'var(--red)';
    if (btn) btn.title = 'Access denied. Check the cloud Firestore permissions in Settings.';
    if (btn) btn.setAttribute('aria-label', 'Cloud sync denied. Opens Settings');
  } else if (isOnline && currentUser && (status === 'failed' || (cloudPushFailed && !status))) {
    if (icon) icon.textContent = '⚠️';
    if (text) text.textContent = 'Sync failed · Saved here';
    if (dot) dot.style.background = 'var(--yellow)';
    if (btn) btn.title = 'Your last change could not reach your account. Everything is saved on this device; it tries again on your next change.';
    if (btn) btn.setAttribute('aria-label', 'Sync failed, saved on this device. Opens Settings');
  } else if (status === 'offline' || !isOnline) {
    if (icon) icon.textContent = '💾';
    if (text) text.textContent = 'Offline · Saved';
    if (dot) dot.style.background = 'var(--yellow)';
    if (btn) btn.title = 'Working offline · All changes are saved locally to this device';
    if (btn) btn.setAttribute('aria-label', 'Offline, saved on this device. Opens Settings, where backup is');
  } else if (currentUser) {
    if (icon) icon.textContent = '⚡';
    if (text) text.textContent = 'Cloud synced';
    if (dot) dot.style.background = 'var(--green)';
    if (btn) btn.title = 'Cloud sync active · Saved locally & synced to your account';
    if (btn) btn.setAttribute('aria-label', 'Saved and synced to your account. Opens Settings, where backup is');
  } else {
    if (icon) icon.textContent = '💾';
    if (text) text.textContent = 'Saved locally';
    if (dot) dot.style.background = 'var(--green)';
    if (btn) btn.title = 'Local offline storage active · All data is saved automatically on this device';
    if (btn) btn.setAttribute('aria-label', 'Saved on this device. Opens Settings, where backup is');
  }
  // The save status shows in Settings (the topbar badge is hidden).
  const settingsText = document.getElementById('settings-sync-text');
  if (settingsText && text) settingsText.textContent = text.textContent;
}

// ── Vision AI Service (Groq primary → Gemini fallback) ────────
const AIService = {
  // Was 'qwen/qwen3.6-27b' -- silently 404ing on Groq's current platform
  // (verified live against api.groq.com/openai/v1/models: 3.6 isn't listed,
  // 3.8 is, and a direct test call to 3.6 returns model_not_found). This
  // means callGroqText/generateContentFromText's Groq leg had been dead on
  // arrival with no visible symptom -- it just always threw and silently
  // fell through to the Gemini leg below. Re-verify against the live
  // /models endpoint before trusting any Groq model id here again.
  GROQ_MODEL: 'qwen/qwen3.8-27b',
  // 'gemini-2.5-flash', 'gemini-2.0-flash', and 'gemini-1.5-flash' were all
  // retired by Google (404 "no longer available to new users") -- use the
  // evergreen "-latest" aliases so this doesn't silently rot again, with one
  // pinned model in between as a fallback in case an alias has an outage.
  //
  // gemini-3.1-flash-lite goes FIRST (v163). Test-kit scores through the
  // live proxy on 2026-09-24 (recall/precision): 100/100, 98/100 (twice),
  // 95/88 on the three timetables and 100% on the attendance sample, in
  // ~10-20 s. flash-lite-latest (3.5) swung between 70% and 93% on the same
  // spreadsheet timetable, and the two flash models answered "overloaded"
  // on every attempt that day while allowing only 20 free requests each.
  // Google counts free quota per model, so each model in this list adds its
  // own daily allowance; the AI proxy skips ones already used up.
  //
  // Re-measured 2026-10-19 on all 9 kit timetables (timetable-test-kit +
  // scanner-practice-kit): 3.1-flash-lite was overloaded on 3 of 9 (each
  // failure 35-54 s, the main cause of 2-minute scans) and scored 55-69% on
  // other colleges' layouts; flash-lite-latest failed 0 of 9, answered in
  // 9-34 s and averaged ~82% (83-90% on our own SY-AIDS samples, 71-100% on
  // the others). Reliability for a public launch wins, so it goes first.
  MODEL: 'gemini-flash-lite-latest',
  FALLBACK_MODELS: ['gemini-3.1-flash-lite', 'gemini-flash-latest', 'gemini-3.6-flash'],
  // Re-verified live against the real key: llama-4-scout (the previous
  // value) returns "model does not exist" -- it isn't in the key's
  // /v1/models list -- so this Groq leg always failed. qwen/qwen3.8-27b IS
  // listed and now accepts image input (an earlier check found it rejecting
  // images; that has changed): on the SY-AIDS test-kit timetable it
  // answered in ~5s in the requested grid format at 78% recall / 82%
  // precision -- weaker than Gemini (98%/100%) but a working, fast fallback
  // when Gemini is overloaded or out of free quota. Re-check
  // api.groq.com/openai/v1/models with your own key if this starts failing.
  GROQ_VISION_MODEL: 'qwen/qwen3.8-27b',
  // OpenRouter's ":free" catalog churns often (models get added/retired), so
  // this is a short ordered list rather than one pinned id -- same reasoning
  // as FALLBACK_MODELS above. inclusionai/ling-3.0-flash-vl:free and
  // qwen/qwen3.8-27b:free were retired (404 as of Oct 2026). The other free
  // vision models listed then were blocked (403), too slow for the 60s
  // timeout, or preview-only, so none replaced them. Note OpenRouter's free
  // pool is shared and often returns 429 "rate-limited upstream" for all of
  // these at once -- it's a
  // last resort, not a dependable leg. Verify current free vision models at
  // https://openrouter.ai/api/v1/models before relying on any one of these.
  OPENROUTER_VISION_MODELS: ['google/gemma-4-31b-it:free', 'google/gemma-4-26b-a4b-it:free'],
  // Cloudflare's own vision models, reachable only through the AI proxy
  // (the Worker's AI binding -- no key). Free plan: 10,000 "neurons" a day
  // shared by the whole app; once used up the call fails (never billed)
  // and the next provider is tried. Each id must also be listed in
  // WORKERS_AI_MODELS in ai-proxy/wrangler.toml.
  // Test-kit scores (recall/precision, 2026-09-24, one run each):
  //   mistral-small-3.1-24b  61/100  61/100  48/50  (~45 s, ~230 neurons)
  //   gemma-4-26b (no think)  78/69   76/85   8/6   (~30 s, ~70 neurons)
  //   llama-4-scout-17b       46/75   39/82  timed out
  // Mistral is kept: it almost never invents a class (a wrong class is
  // worse than a missing one) and was the only one to read the WhatsApp
  // photo. All are below Gemini/Groq, so this leg comes after them.
  WORKERS_AI_VISION_MODELS: ['@cf/mistralai/mistral-small-3.1-24b-instruct'],
  // Per-model request extras. Gemma 4 "thinks" before answering by default,
  // which on a full timetable used the whole output budget and returned no
  // answer; with thinking off a short reply took 33 tokens instead of 306.
  // (Mistral on Workers AI rejects this option, so it is not sent globally.)
  WORKERS_AI_MODEL_OPTIONS: {
    '@cf/google/gemma-4-26b-a4b-it': { chat_template_kwargs: { enable_thinking: false } }
  },

  getApiKey() {
    if (window.CAMPUS_OS_GEMINI_KEY) return window.CAMPUS_OS_GEMINI_KEY;
    const envKey = (typeof process !== 'undefined' && process.env && (process.env.VITE_GEMINI_API_KEY || process.env.NEXT_PUBLIC_GEMINI_API_KEY || process.env.GEMINI_API_KEY));
    if (envKey) return envKey;
    return null;
  },

  getGroqKey() {
    if (window.CAMPUS_OS_GROQ_KEY) return window.CAMPUS_OS_GROQ_KEY;
    const envKey = (typeof process !== 'undefined' && process.env && (process.env.VITE_GROQ_API_KEY || process.env.GROQ_API_KEY));
    if (envKey) return envKey;
    return null;
  },

  getOpenRouterKey() {
    if (window.CAMPUS_OS_OPENROUTER_KEY) return window.CAMPUS_OS_OPENROUTER_KEY;
    const envKey = (typeof process !== 'undefined' && process.env && (process.env.VITE_OPENROUTER_API_KEY || process.env.OPENROUTER_API_KEY));
    if (envKey) return envKey;
    return null;
  },

  // Optional server-side proxy (ai-proxy/, a free Cloudflare Worker) that
  // holds the provider keys so they never ship to the browser. When
  // window.CAMPUS_OS_AI_PROXY is set (firebase-config.js), every provider
  // call goes through it; otherwise the direct-key calls work as before.
  getProxyUrl() {
    const raw = typeof window !== 'undefined' ? window.CAMPUS_OS_AI_PROXY : null;
    if (typeof raw !== 'string' || !/^https?:\/\/\S+$/i.test(raw.trim())) return null;
    return raw.trim().replace(/\/+$/, '');
  },

  hasProvider(provider) {
    if (this.getProxyUrl()) return true;
    if (provider === 'workersai') return false; // proxy-only
    if (provider === 'gemini') return !!this.getApiKey();
    if (provider === 'groq') return !!this.getGroqKey();
    if (provider === 'openrouter') return !!this.getOpenRouterKey();
    return false;
  },

  // Where one provider call goes and with which headers. Throws when the
  // provider has neither the proxy nor a key -- every caller already treats
  // a throw as "try the next model/provider".
  async _route(provider, model) {
    const headers = { 'Content-Type': 'application/json' };
    const proxy = this.getProxyUrl();
    if (proxy) {
      // Signed-in students get the proxy's per-account limit; without a
      // token the proxy treats the call as a guest (per-network limit).
      try {
        const user = typeof currentUser !== 'undefined' ? currentUser : null;
        if (user && typeof user.getIdToken === 'function') {
          headers['Authorization'] = `Bearer ${await user.getIdToken()}`;
        }
      } catch (_) { /* no token: guest */ }
      const path = provider === 'gemini' ? `gemini/${encodeURIComponent(model)}` : provider;
      return { url: `${proxy}/v1/${path}`, headers };
    }
    if (provider === 'gemini') {
      const key = this.getApiKey();
      if (!key) throw new Error('No Gemini API key configured.');
      return { url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${key}`, headers };
    }
    if (provider === 'workersai') throw new Error('Cloudflare Workers AI is only available through the AI proxy.');
    if (provider === 'groq') {
      const key = this.getGroqKey();
      if (!key) throw new Error('No Groq API key configured.');
      return { url: 'https://api.groq.com/openai/v1/chat/completions', headers: { ...headers, 'Authorization': `Bearer ${key}` } };
    }
    const key = this.getOpenRouterKey();
    if (!key) throw new Error('No OpenRouter API key configured.');
    return {
      url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: {
        ...headers,
        'Authorization': `Bearer ${key}`,
        'HTTP-Referer': (typeof window !== 'undefined' && window.location) ? window.location.origin : 'https://clarity-desk.app',
        'X-Title': 'Clarity Desk'
      }
    };
  },

  getModelsList() {
    return [this.MODEL, ...this.FALLBACK_MODELS];
  },

  // Remembers, for this session only, which models just failed in a way
  // that lasts a few minutes (free quota used up, model retired, no answer
  // in time). The next scan tries the healthy ones first instead of waiting
  // on the same stuck model again. Nothing is skipped: a cooling model only
  // moves to the back of the line, so it still gets its turn.
  _cooldowns: {},
  _coolDown(id, status) {
    const mins = (status === 401 || status === 403 || status === 404) ? 30
      : (status === 429 || status === 'timeout') ? 5
      : (status >= 500) ? 2 : 0;
    if (mins) this._cooldowns[id] = Date.now() + mins * 60000;
  },
  _isCooling(id) {
    return (this._cooldowns[id] || 0) > Date.now();
  },
  _healthyFirst(items, idOf) {
    return [...items.filter(x => !this._isCooling(idOf(x))), ...items.filter(x => this._isCooling(idOf(x)))];
  },
  // fetchWithTimeout plus the cooldown bookkeeping above.
  async _post(id, url, init, ms) {
    let response;
    try {
      response = await fetchWithTimeout(url, init, ms);
    } catch (err) {
      if (/^No response within/.test((err && err.message) || '')) this._coolDown(id, 'timeout');
      throw err;
    }
    if (!response.ok) this._coolDown(id, response.status);
    return response;
  },

  async callGroqText(ocrText, promptText) {
    const route = await this._route('groq');
    
    console.log(`[AIService] Attempting extraction with Groq model: ${this.GROQ_MODEL}`);
    
    const response = await this._post(`groq:${this.GROQ_MODEL}`, route.url, {
      method: 'POST',
      headers: route.headers,
      body: JSON.stringify({
        model: this.GROQ_MODEL,
        messages: [
          { role: "system", content: "You are an expert AI that structures raw OCR data into valid JSON." },
          { role: "user", content: promptText + "\n\nRaw OCR Text:\n" + ocrText }
        ],
        temperature: 0.1,
        response_format: { type: "json_object" }
      })
    });
    
    if (!response.ok) {
      const errObj = await response.json().catch(() => ({}));
      const rawMsg = errObj.error?.message || `HTTP ${response.status} from Groq`;
      throw new Error(`Groq (${this.GROQ_MODEL}): ${rawMsg}`);
    }
    
    const resData = await response.json();
    const rawText = resData.choices?.[0]?.message?.content || '';
    
    const parsed = safeParseGeminiJson(rawText);
    if (!parsed) {
      throw new Error(`Groq returned unparseable content.`);
    }
    console.log(`[AIService] ✅ Extraction succeeded with Groq:`, parsed);
    return parsed;
  },

  async generateContentFromText(ocrText, promptText) {
    let lastError = null;
    // Groq just failed (see _cooldowns): ask Gemini first this time.
    const groqLast = this._isCooling(`groq:${this.GROQ_MODEL}`) && this.hasProvider('gemini');

    if (!groqLast) {
      try {
        return await this.callGroqText(ocrText, promptText);
      } catch (err) {
        lastError = err;
        console.warn(`[AIService] Groq text failed:`, err.message || err);
      }
    }

    if (!this.hasProvider('gemini')) {
      throw new Error(lastError ? lastError.message : 'No AI API key configured.');
    }

    const models = this._healthyFirst(this.getModelsList(), m => `gemini:${m}`);
    for (const model of models) {
      try {
        const route = await this._route('gemini', model);
        console.log(`[AIService] Attempting extraction with Gemini model: ${model}`);
        const parsed = await this._generateContent(route, {
          contents: [{
            parts: [
              { text: promptText },
              { text: "\n\nRaw OCR Text:\n" + ocrText }
            ]
          }],
          generationConfig: {
            responseMimeType: 'application/json',
            temperature: 0.1
          }
        }, model);
        console.log(`[AIService] ✅ Extraction succeeded with model: ${model}`, parsed);
        return parsed;
      } catch (err) {
        lastError = new Error(`${lastError ? lastError.message + ' (Gemini Fallback: ' + (err.message || err) + ')' : (err.message || err)}`);
        console.warn(`[AIService] Model attempt ${model} failed:`, err.message || err);
      }
    }

    if (groqLast) {
      try {
        return await this.callGroqText(ocrText, promptText);
      } catch (err) {
        lastError = err;
        console.warn(`[AIService] Groq text failed:`, err.message || err);
      }
    }

    throw lastError || new Error('AI service unavailable. Please try again later.');
  },

  // Shared by generateContentFromText and generateContentFromImage: posts a
  // generateContent request and parses the response. Google's free-tier
  // models occasionally return 503 "temporarily unavailable" under load
  // (seen in practice minutes apart on the same key/model) -- a real
  // outage looks the same as a momentary spike from here, so one short
  // retry before giving up on this model is worth it: without it, a single
  // bad moment burns through all 3 fallback models at once and the whole
  // scan falls back to raw, uncorrected OCR text for no real reason.
  async _generateContent(route, body, model) {
    let response;
    for (let attempt = 1; attempt <= 2; attempt++) {
      const startedAt = Date.now();
      response = await this._post(`gemini:${model}`, route.url, {
        method: 'POST',
        headers: route.headers,
        body: JSON.stringify(body)
      });
      // A 503 the AI proxy answered itself (model known to be overloaded)
      // would only be answered the same way again -- move on instead.
      if (response.status !== 503 || attempt === 2 || response.headers.get('X-Proxy-Skipped')) break;
      // An overloaded model answers slowly and then refuses (measured 35-54 s
      // before the 503). Retrying it just repeats that wait, so only a quick
      // refusal -- a momentary spike -- gets its second try.
      if (Date.now() - startedAt > 15000) break;
      console.warn(`[AIService] Model ${model} returned 503 (overloaded), retrying once...`);
      await new Promise(resolve => setTimeout(resolve, 1500));
    }

    if (!response.ok) {
      const errObj = await response.json().catch(() => ({}));
      const rawMsg = errObj.error?.message || `HTTP ${response.status} from ${model}`;
      throw new Error(friendlyGeminiError(response.status, rawMsg));
    }

    const resData = await response.json();
    const candidate = resData.candidates?.[0];

    const finishReason = candidate?.finishReason;
    if (finishReason && finishReason !== 'STOP' && finishReason !== 'MAX_TOKENS') {
      throw new Error(`Gemini blocked the response (reason: ${finishReason}). Try a clearer image.`);
    }

    const rawText = candidate?.content?.parts?.[0]?.text || '';
    const parsed = safeParseGeminiJson(rawText);
    if (!parsed) {
      throw new Error(`Model ${model} returned unparseable content. Raw: ${rawText.slice(0, 120)}`);
    }
    return parsed;
  },

  // True vision-based extraction: sends the actual photo to a multimodal
  // Gemini model, instead of only Tesseract's OCR text output. This is
  // the only path that can recover information Tesseract lost at the
  // pixel level (heavy skew, poor lighting, handwriting) --
  // generateContentFromText can only ever polish what Tesseract already
  // read, and has no way to see anything Tesseract missed or misread.
  // Only ever called when the user has already configured a Gemini API
  // key (the caller checks this before invoking it) -- sending the photo
  // itself is a bigger privacy step than sending text, so this must never
  // run without that same key already present.
  async generateContentFromImage(base64Data, mimeType, promptText) {
    if (!this.hasProvider('gemini')) {
      throw new Error('No Gemini API key configured for vision extraction.');
    }

    const models = this._healthyFirst(this.getModelsList(), m => `gemini:${m}`);
    let lastError = null;

    for (const model of models) {
      try {
        const route = await this._route('gemini', model);
        console.log(`[AIService] Attempting VISION extraction with Gemini model: ${model}`);
        const parsed = await this._generateContent(route, {
          contents: [{
            parts: [
              { text: promptText },
              { inline_data: { mime_type: mimeType, data: base64Data } }
            ]
          }],
          generationConfig: {
            responseMimeType: 'application/json',
            temperature: 0.1
          }
        }, model);
        console.log(`[AIService] ✅ Vision extraction succeeded with model: ${model}`, parsed);
        return parsed;
      } catch (err) {
        lastError = new Error(`${lastError ? lastError.message + ' (Vision Fallback: ' + (err.message || err) + ')' : (err.message || err)}`);
        console.warn(`[AIService] Vision model attempt ${model} failed:`, err.message || err);
      }
    }

    throw lastError || new Error('Vision AI service unavailable. Please try again later.');
  },

  // Second vision provider, same contract as generateContentFromImage
  // (same schema-instruction prompt in, same {schedule:[...]} JSON out) so
  // extractStructuredFromImage below can rotate between them without either
  // caller knowing which provider actually answered.
  async callGroqVision(base64Data, mimeType, promptText) {
    const route = await this._route('groq');

    console.log(`[AIService] Attempting VISION extraction with Groq model: ${this.GROQ_VISION_MODEL}`);

    const response = await this._post(`groq:${this.GROQ_VISION_MODEL}`, route.url, {
      method: 'POST',
      headers: route.headers,
      body: JSON.stringify({
        model: this.GROQ_VISION_MODEL,
        messages: [
          { role: 'user', content: [
            { type: 'text', text: promptText },
            { type: 'image_url', image_url: { url: `data:${mimeType};base64,${base64Data}` } }
          ] }
        ],
        temperature: 0.1,
        response_format: { type: 'json_object' }
      })
    });

    if (!response.ok) {
      const errObj = await response.json().catch(() => ({}));
      const rawMsg = errObj.error?.message || `HTTP ${response.status} from Groq vision`;
      throw new Error(`Groq vision (${this.GROQ_VISION_MODEL}): ${rawMsg}`);
    }

    const resData = await response.json();
    const rawText = resData.choices?.[0]?.message?.content || '';
    const parsed = safeParseGeminiJson(rawText);
    if (!parsed) {
      throw new Error('Groq vision returned unparseable content.');
    }
    console.log('[AIService] ✅ Vision extraction succeeded with Groq:', parsed);
    return parsed;
  },

  // Third vision provider (OpenRouter's free-tier catalog). Tries each
  // OPENROUTER_VISION_MODELS entry in order since any one of them can be
  // retired or rate-limited independently of the others.
  async callOpenRouterVision(base64Data, mimeType, promptText) {
    const route = await this._route('openrouter');
    let lastError = null;

    for (const model of this._healthyFirst(this.OPENROUTER_VISION_MODELS, m => `openrouter:${m}`)) {
      try {
        console.log(`[AIService] Attempting VISION extraction with OpenRouter model: ${model}`);
        const response = await this._post(`openrouter:${model}`, route.url, {
          method: 'POST',
          headers: route.headers,
          body: JSON.stringify({
            model,
            messages: [
              { role: 'user', content: [
                { type: 'text', text: promptText },
                { type: 'image_url', image_url: { url: `data:${mimeType};base64,${base64Data}` } }
              ] }
            ],
            temperature: 0.1,
            response_format: { type: 'json_object' }
          })
        });

        if (!response.ok) {
          const errObj = await response.json().catch(() => ({}));
          const rawMsg = errObj.error?.message || `HTTP ${response.status} from ${model}`;
          throw new Error(`OpenRouter (${model}): ${rawMsg}`);
        }

        const resData = await response.json();
        const rawText = resData.choices?.[0]?.message?.content || '';
        const parsed = safeParseGeminiJson(rawText);
        if (!parsed) {
          throw new Error(`OpenRouter model ${model} returned unparseable content.`);
        }
        console.log(`[AIService] ✅ Vision extraction succeeded with OpenRouter model: ${model}`, parsed);
        return parsed;
      } catch (err) {
        lastError = err;
        console.warn(`[AIService] OpenRouter model ${model} failed:`, err.message || err);
      }
    }

    throw lastError || new Error('OpenRouter vision unavailable.');
  },

  // Fourth vision provider: Cloudflare Workers AI through the proxy. Same
  // contract as the others; tries each WORKERS_AI_VISION_MODELS entry.
  async callWorkersAIVision(base64Data, mimeType, promptText) {
    const route = await this._route('workersai');
    let lastError = null;

    for (const model of this._healthyFirst(this.WORKERS_AI_VISION_MODELS, m => `workersai:${m}`)) {
      try {
        console.log(`[AIService] Attempting VISION extraction with Workers AI model: ${model}`);
        // 90 s, not the usual 60: these models took ~45 s on a full timetable,
        // and this leg only runs after Gemini and Groq have already failed.
        const response = await this._post(`workersai:${model}`, route.url, {
          method: 'POST',
          headers: route.headers,
          body: JSON.stringify({
            model,
            messages: [
              { role: 'user', content: [
                { type: 'text', text: promptText },
                { type: 'image_url', image_url: { url: `data:${mimeType};base64,${base64Data}` } }
              ] }
            ],
            temperature: 0.1,
            max_tokens: 4096,
            response_format: { type: 'json_object' },
            ...(this.WORKERS_AI_MODEL_OPTIONS[model] || {})
          })
        }, 90000);

        if (!response.ok) {
          const errObj = await response.json().catch(() => ({}));
          throw new Error(errObj.error?.message || `HTTP ${response.status} from Workers AI ${model}`);
        }

        const resData = await response.json();
        const parsed = safeParseGeminiJson(resData.choices?.[0]?.message?.content || '');
        if (!parsed) {
          throw new Error(`Workers AI model ${model} returned unparseable content.`);
        }
        console.log(`[AIService] ✅ Vision extraction succeeded with Workers AI model: ${model}`, parsed, resData.usage || '');
        return parsed;
      } catch (err) {
        lastError = err;
        console.warn(`[AIService] Workers AI model ${model} failed:`, err.message || err);
      }
    }

    throw lastError || new Error('Workers AI vision unavailable.');
  },

  // Rotates across every vision-capable provider the user has a key for, in
  // free-tier-friendliness order (Gemini's free tier is the most generous
  // per-provider today, Groq is fastest, OpenRouter has the widest model
  // selection to fall through). Stops at the first provider that returns a
  // non-empty schedule -- a provider being out of quota (429) or briefly
  // down no longer means the whole photo falls back to raw Tesseract text,
  // it just means the next configured provider gets tried instead.
  // onStep(providerName), optional, is called before each provider is tried
  // so the scan screen can say what it is waiting on.
  async extractStructuredFromImage(base64Data, mimeType, promptText, onStep) {
    let attempts = [];
    if (this.hasProvider('gemini')) attempts.push(['Gemini', () => this.generateContentFromImage(base64Data, mimeType, promptText), this.getModelsList().map(m => `gemini:${m}`)]);
    if (this.hasProvider('groq')) attempts.push(['Groq', () => this.callGroqVision(base64Data, mimeType, promptText), [`groq:${this.GROQ_VISION_MODEL}`]]);
    if (this.hasProvider('workersai')) attempts.push(['Workers AI', () => this.callWorkersAIVision(base64Data, mimeType, promptText), this.WORKERS_AI_VISION_MODELS.map(m => `workersai:${m}`)]);
    if (this.hasProvider('openrouter')) attempts.push(['OpenRouter', () => this.callOpenRouterVision(base64Data, mimeType, promptText), this.OPENROUTER_VISION_MODELS.map(m => `openrouter:${m}`)]);

    if (attempts.length === 0) {
      throw new Error('No vision-capable AI provider configured.');
    }

    // A provider whose every model just failed goes to the back of the line.
    attempts = this._healthyFirst(attempts, a => a[2].every(id => this._isCooling(id)) ? a[2][0] : '');

    let lastError = null;
    for (const [providerName, attempt] of attempts) {
      if (typeof onStep === 'function') { try { onStep(providerName); } catch (_) {} }
      try {
        const result = await attempt();
        if (result && Array.isArray(result.schedule) && result.schedule.length > 0) {
          return result;
        }
        lastError = new Error(`${providerName} vision returned an empty schedule.`);
      } catch (err) {
        lastError = err;
        console.warn(`[AIService] Vision provider ${providerName} failed, trying next:`, err.message || err);
      }
    }

    throw lastError || new Error('All configured vision providers failed.');
  }
};


// Strips markdown code fences (```json ... ```) that Gemini sometimes wraps around JSON responses,
// then safely attempts JSON.parse. Returns null (not throws) if content is unparseable.
// Every AI provider call goes through this. Without a timeout, one
// provider that accepts the connection but never answers (free endpoints
// under load do this) left the scan spinner running forever instead of
// moving on to the next provider/model. 45s is above every successful
// vision response measured on the kit images (5-40s, slowest a six-
// department sheet at ~34s) and below the 35-54s an overloaded model takes
// to refuse, so it only cuts off
// genuinely stuck calls; the abort surfaces as an ordinary error, which
// every caller's existing provider/model rotation already handles.
async function fetchWithTimeout(url, options = {}, ms = 45000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);
  try {
    return await fetch(url, { ...options, signal: controller.signal });
  } catch (err) {
    if (err && err.name === 'AbortError') throw new Error(`No response within ${Math.round(ms / 1000)}s`);
    throw err;
  } finally {
    clearTimeout(timer);
  }
}

function safeParseGeminiJson(text) {
  if (!text || typeof text !== 'string') return null;
  let cleaned = text.trim();

  // Remove leading ```json or ``` fence and trailing ```
  cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();

  // If still not starting with { or [, attempt to extract the first {...} block
  if (!cleaned.startsWith('{') && !cleaned.startsWith('[')) {
    console.warn('[safeParseGeminiJson] Response does not start with { or [. Attempting substring extraction.');
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (!match) return null;
    cleaned = match[0];
  }

  try {
    return JSON.parse(cleaned);
  } catch (e) {
    console.warn('[safeParseGeminiJson] JSON.parse failed after cleanup:', e.message, '| Snippet:', cleaned.slice(0, 120));
    return null;
  }
}

// Converts raw Gemini API error messages into short, user-friendly strings.
function friendlyGeminiError(httpStatus, rawMsg) {
  const m = (rawMsg || '').toLowerCase();
  if (httpStatus === 429 || m.includes('quota') || m.includes('rate') || m.includes('limit')) {
    return 'The AI extraction service has reached its usage limit for now. Please wait a few minutes and try again, or enter your timetable manually.';
  }
  if (httpStatus === 403 || m.includes('api key') || m.includes('permission') || m.includes('unauthorized')) {
    return 'AI service authentication error. The Gemini API key may be invalid or restricted.';
  }
  if (httpStatus === 404 || m.includes('not found') || m.includes('not supported')) {
    return 'The AI model is currently unavailable. Trying a fallback model…';
  }
  if (httpStatus >= 500 || m.includes('internal') || m.includes('server error')) {
    return 'Google AI service is temporarily unavailable. Please try again in a moment.';
  }
  // Truncate any other raw message at 160 chars
  return rawMsg.length > 160 ? rawMsg.slice(0, 157) + '…' : rawMsg;
}

function updateTimetableLoadingModal(msg) {
  const backdrop = document.getElementById('tt-loading-backdrop');
  if (backdrop) {
    const msgEl = backdrop.querySelector('.loading-msg');
    if (msgEl) msgEl.textContent = msg;
  } else {
    showTimetableLoadingModal(msg);
  }
}

function showTimetableLoadingModal(msg = "Analyzing photo...") {
  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop';
  backdrop.id = 'tt-loading-backdrop';
  backdrop.innerHTML = `
    <div class="modal" style="max-width:360px;text-align:center;padding:32px 24px">
      <div style="font-size:var(--text-hero);margin-bottom:12px;animation:spin 1.5s linear infinite">✨</div>
      <div style="font-weight:700;font-size:var(--text-md);margin-bottom:6px" class="loading-msg">${msg}</div>
      <div style="font-size:var(--text-sm);color:var(--text-muted)">Extracting weekly schedule...</div>
    </div>
  `;
  document.body.appendChild(backdrop);
}

// ── Lazy-Loaded OCR Engine & Worker Cache ─────────────────────
let _tesseractWorker = null;
let _tesseractWorkerPromise = null;
let _tesseractScriptPromise = null;
let _isOcrBusy = false;

function loadTesseractScriptOnDemand() {
  if (typeof window !== 'undefined' && window.Tesseract) {
    return Promise.resolve(window.Tesseract);
  }
  if (_tesseractScriptPromise) return _tesseractScriptPromise;

  _tesseractScriptPromise = new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';
    script.async = true;
    script.onload = () => {
      console.log('[TesseractLazy] Local OCR engine library loaded on-demand.');
      resolve(window.Tesseract);
    };
    script.onerror = (err) => {
      _tesseractScriptPromise = null;
      console.error('[TesseractLazy] Failed to fetch Tesseract library:', err);
      reject(new Error('Failed to load local OCR engine library. Check your network connection.'));
    };
    document.head.appendChild(script);
  });

  return _tesseractScriptPromise;
}

async function getTesseractWorker(onProgress = null) {
  if (_tesseractWorker) return _tesseractWorker;
  if (_tesseractWorkerPromise) return _tesseractWorkerPromise;

  _tesseractWorkerPromise = (async () => {
    try {
      await loadTesseractScriptOnDemand();
      console.log('[TesseractWorker] Initializing single reusable OCR worker (eng fast)...');
      
      const worker = await window.Tesseract.createWorker('eng', 1, {
        logger: m => {
          if (m.status === 'recognizing text') {
            const pct = Math.round((m.progress || 0) * 100);
            if (typeof onProgress === 'function') onProgress(pct);
            if (typeof updateAttendanceScanLoadingProgress === 'function') {
              updateAttendanceScanLoadingProgress(pct);
            }
            if (m.progress % 0.2 < 0.05) {
              console.log(`[TesseractWorker] OCR Progress: ${pct}%`);
            }
          }
        }
      });
      _tesseractWorker = worker;
      console.log('[TesseractWorker] ✅ Single reusable OCR worker ready and cached.');
      return _tesseractWorker;
    } catch (err) {
      _tesseractWorker = null;
      _tesseractWorkerPromise = null;
      console.error('[TesseractWorker] ❌ Worker init failed:', err);
      throw err;
    }
  })();

  return _tesseractWorkerPromise;
}

// ── Auto-Deskew (Rotation Correction) ──────────────────────────
// Detects small handheld-photo tilt via a projection-profile angle
// search: for each candidate angle, rotate a cheap downscaled copy of
// the photo and score how sharply text rows separate (variance of
// per-row ink density across the rotated image). The angle that produces
// the highest variance is the one where horizontal table/text lines are
// best aligned to the horizontal axis -- the standard "projection
// profile" deskew method. Bounded to +/-12 degrees: this corrects
// ordinary camera tilt, not gross 90/180-degree misorientation (already
// handled by the browser's own EXIF-orientation handling on image
// decode, well before this ever runs).
function detectSkewAngle(sourceCanvas) {
  const SEARCH_W = 320;
  const scale = Math.min(1, SEARCH_W / sourceCanvas.width);
  const searchW = Math.max(40, Math.round(sourceCanvas.width * scale));
  const searchH = Math.max(40, Math.round(sourceCanvas.height * scale));

  const smallCanvas = document.createElement('canvas');
  smallCanvas.width = searchW;
  smallCanvas.height = searchH;
  const sctx = smallCanvas.getContext('2d');
  sctx.drawImage(sourceCanvas, 0, 0, searchW, searchH);
  const { data } = sctx.getImageData(0, 0, searchW, searchH);
  smallCanvas.width = 1;
  smallCanvas.height = 1;

  // Scored on the coordinates of "ink" pixels only, projected at each
  // candidate angle -- NOT by rotating the image itself. The previous
  // version rotated the downscaled image onto a white-filled canvas and
  // scored row-darkness variance over the whole rotated canvas; on a real
  // scan the paper is light grey, not white, so the white corner triangles
  // that grow with every degree of rotation (and the canvas itself growing)
  // added fake variance that rose monotonically with |angle|. Verified on
  // the real SY-AIDS test-kit scan (tilted ~1deg): it returned the edge of
  // the search range (12deg) and the whole page went to Tesseract rotated
  // ~13deg, so day rows ran diagonally across each other -- the root cause
  // of garbled text, missing day labels, and one day's classes being filed
  // under another. Rotating a fixed set of points has no fill and no
  // changing canvas size, so nothing but real text/rule alignment affects
  // the score.
  //
  // Ink = pixels far from the dominant (median) background luminance in
  // either direction, so dark-on-light scans and light-on-dark screenshots
  // both work (skew detection runs before the auto-invert step).
  const lum = new Uint8Array(searchW * searchH);
  const hist = new Uint32Array(256);
  for (let i = 0, j = 0; j < lum.length; i += 4, j++) {
    const l = Math.round(0.299 * data[i] + 0.587 * data[i + 1] + 0.114 * data[i + 2]);
    lum[j] = l;
    hist[l]++;
  }
  let acc = 0, bg = 0;
  for (let v = 0; v < 256; v++) { acc += hist[v]; if (acc >= lum.length / 2) { bg = v; break; } }

  const xs = [], ys = [];
  const cx = searchW / 2, cy = searchH / 2;
  for (let y = 0; y < searchH; y++) {
    for (let x = 0; x < searchW; x++) {
      if (Math.abs(lum[y * searchW + x] - bg) > 60) { xs.push(x - cx); ys.push(y - cy); }
    }
  }
  if (xs.length < 50) return 0;

  const diag = Math.ceil(Math.hypot(searchW, searchH));
  const bins = new Float64Array(diag * 2 + 2);
  // Same convention as rotateCanvasByAngle (canvas ctx.rotate): a point's
  // row after rotating by `rad` is y' = x*sin(rad) + y*cos(rad).
  const scoreAt = (angleDeg) => {
    const rad = angleDeg * Math.PI / 180;
    const s = Math.sin(rad), c = Math.cos(rad);
    bins.fill(0);
    for (let k = 0; k < xs.length; k++) {
      bins[Math.round(xs[k] * s + ys[k] * c) + diag]++;
    }
    let energy = 0;
    for (let b = 0; b < bins.length; b++) energy += bins[b] * bins[b];
    return energy;
  };

  const straightScore = scoreAt(0);
  let bestAngle = 0;
  let bestScore = straightScore;
  for (let angleDeg = -12; angleDeg <= 12; angleDeg += 0.5) {
    const score = scoreAt(angleDeg);
    if (score > bestScore) { bestScore = score; bestAngle = angleDeg; }
  }
  // Refine to 0.1deg around the coarse winner.
  const coarse = bestAngle;
  for (let angleDeg = coarse - 0.4; angleDeg <= coarse + 0.4 + 1e-9; angleDeg += 0.1) {
    const a = Math.round(angleDeg * 10) / 10;
    const score = scoreAt(a);
    if (score > bestScore) { bestScore = score; bestAngle = a; }
  }

  // Never rotate an already-straight page on a marginal difference: the
  // chosen angle must beat "no rotation" by a real margin.
  if (bestScore < straightScore * 1.03) return 0;
  return bestAngle;
}

// Rotates a full-resolution canvas by the given angle (degrees) around
// its own center, returning a NEW canvas sized to fit the fully-rotated
// content against a white background (so no corner content is clipped
// and the added corners read as blank page, not noise, to the margin-trim
// step that runs later). A near-zero angle is a no-op -- returns the
// same canvas unchanged -- so the common case of an already-square photo
// pays no extra resample cost.
function rotateCanvasByAngle(sourceCanvas, angleDeg) {
  if (Math.abs(angleDeg) < 0.3) return sourceCanvas;

  const rad = angleDeg * Math.PI / 180;
  const w = sourceCanvas.width;
  const h = sourceCanvas.height;
  const absCos = Math.abs(Math.cos(rad));
  const absSin = Math.abs(Math.sin(rad));
  const newW = Math.max(1, Math.round(w * absCos + h * absSin));
  const newH = Math.max(1, Math.round(w * absSin + h * absCos));

  const out = document.createElement('canvas');
  out.width = newW;
  out.height = newH;
  const ctx = out.getContext('2d');
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, newW, newH);
  ctx.translate(newW / 2, newH / 2);
  ctx.rotate(rad);
  ctx.drawImage(sourceCanvas, -w / 2, -h / 2);

  return out;
}

// Threshold for the dark-dominant auto-invert decision in
// preprocessImageForOCR -- pulled out as a pure, named function so it's
// independently testable without a canvas/DOM. Ported from PR #33
// (claude/gifted-feynman-s1s33y): handles light-text-on-dark screenshots
// (e.g. a Notion-exported timetable) that the existing dark-text-on-light-
// tuned contrast stretch below was never tuned for.
function isDarkDominantForInvert(meanGrayValue) {
  return meanGrayValue < 100;
}

function preprocessImageForOCR(base64Data, mimeType) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      let canvas = document.createElement('canvas');
      let ctx = canvas.getContext('2d');
      
      let width = img.width;
      let height = img.height;

      // 1. Target upscaling: upscale narrow/low-res photos for crisp OCR character recognition
      const TARGET_MIN_WIDTH = 1400;
      if (width < TARGET_MIN_WIDTH) {
        const scale = Math.min(2.0, TARGET_MIN_WIDTH / width);
        width = Math.round(width * scale);
        height = Math.round(height * scale);
      }

      // Cap at reasonable max to keep memory low and local OCR fast
      const MAX_DIM = 2000;
      if (width > MAX_DIM || height > MAX_DIM) {
        const ratio = Math.min(MAX_DIM / width, MAX_DIM / height);
        width = Math.round(width * ratio);
        height = Math.round(height * ratio);
      }

      canvas.width = width;
      canvas.height = height;
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = 'high';
      ctx.drawImage(img, 0, 0, width, height);

      // 1b. Auto-deskew: correct small handheld-photo rotation before any
      // further processing, so both the margin-trim step below (which
      // assumes roughly horizontal table lines) and Tesseract itself see
      // an upright table. Scored on a cheap downscaled copy, applied once
      // to the full-resolution canvas.
      const skewAngle = detectSkewAngle(canvas);
      if (Math.abs(skewAngle) >= 0.3) {
        const rotated = rotateCanvasByAngle(canvas, skewAngle);
        if (rotated !== canvas) {
          canvas.width = 1;
          canvas.height = 1;
          canvas = rotated;
          ctx = canvas.getContext('2d');
          width = canvas.width;
          height = canvas.height;
        }
      }

      // 2. Grayscale & contrast enhancement with dynamic range expansion & soft S-curve
      const imageData = ctx.getImageData(0, 0, width, height);
      const data = imageData.data;

      let grayValues = new Uint8ClampedArray(data.length / 4);
      for (let i = 0, j = 0; i < data.length; i += 4, j++) {
        grayValues[j] = Math.round(0.299 * data[i] + 0.587 * data[i + 1] + 0.114 * data[i + 2]);
      }

      let minL = 255, maxL = 0;
      for (let j = 0; j < grayValues.length; j++) {
        if (grayValues[j] < minL) minL = grayValues[j];
        if (grayValues[j] > maxL) maxL = grayValues[j];
      }

      // 2a. Auto-invert dark-dominant images (e.g. dark-theme screenshots
      // with light text) so the light-text-on-dark case binarizes the same
      // way the light-background/dark-text case is tuned for below. A real
      // photo of a paper timetable is background-dominant (mostly light
      // pixels even under shadow), so this only fires on genuinely
      // dark-dominant images. Ported from PR #33.
      let sumGrayForInvert = 0;
      for (let j = 0; j < grayValues.length; j++) sumGrayForInvert += grayValues[j];
      const meanGrayForInvert = sumGrayForInvert / grayValues.length;
      if (isDarkDominantForInvert(meanGrayForInvert)) {
        minL = 255;
        maxL = 0;
        for (let j = 0; j < grayValues.length; j++) {
          grayValues[j] = 255 - grayValues[j];
          if (grayValues[j] < minL) minL = grayValues[j];
          if (grayValues[j] > maxL) maxL = grayValues[j];
        }
      }

      const range = Math.max(1, maxL - minL);
      for (let i = 0, j = 0; i < data.length; i += 4, j++) {
        const normalized = Math.min(255, Math.max(0, Math.round(((grayValues[j] - minL) / range) * 255)));
        // Soft S-curve boost to keep font edges anti-aliased while whitening light backgrounds
        const boosted = normalized < 130
          ? Math.round(Math.pow(normalized / 130, 1.35) * 115)
          : Math.min(255, Math.round(115 + Math.pow((normalized - 130) / 125, 0.75) * 140));
        data[i] = boosted;
        data[i + 1] = boosted;
        data[i + 2] = boosted;
      }

      // 2b. Local (tile-based) contrast normalization, blended with the
      // global S-curve above. A single global min/max stretch assumes
      // uniform lighting across the whole photo -- a real photographed
      // page commonly has a shadow across half the sheet or a glare
      // patch, which one curve can't equalize. Each tile is renormalized
      // against its OWN local min/max (from `grayValues`, captured before
      // the S-curve above overwrote `data`) and blended 50/50 with the
      // global result already written -- a full replacement risks
      // amplifying flat, near-blank tiles (pure background/margin) into
      // visible noise, so the global curve stays as a floor.
      const TILE = 48;
      const tilesX = Math.ceil(width / TILE);
      const tilesY = Math.ceil(height / TILE);
      const tileMin = new Float32Array(tilesX * tilesY).fill(255);
      const tileMax = new Float32Array(tilesX * tilesY).fill(0);
      for (let y = 0; y < height; y++) {
        const ty = Math.min(tilesY - 1, Math.floor(y / TILE));
        const rowBase = y * width;
        for (let x = 0; x < width; x++) {
          const tx = Math.min(tilesX - 1, Math.floor(x / TILE));
          const idx = ty * tilesX + tx;
          const g = grayValues[rowBase + x];
          if (g < tileMin[idx]) tileMin[idx] = g;
          if (g > tileMax[idx]) tileMax[idx] = g;
        }
      }
      for (let y = 0; y < height; y++) {
        const ty = Math.min(tilesY - 1, Math.floor(y / TILE));
        const rowBase = y * width;
        for (let x = 0; x < width; x++) {
          const tx = Math.min(tilesX - 1, Math.floor(x / TILE));
          const idx = ty * tilesX + tx;
          const localMin = tileMin[idx];
          const localMax = tileMax[idx];
          const localRange = localMax - localMin;
          // Skip near-flat tiles (pure background/margin) -- normalizing
          // them would only amplify sensor noise into visible speckling.
          if (localRange < 18) continue;
          const g = grayValues[rowBase + x];
          const localNorm = Math.min(255, Math.max(0, ((g - localMin) / localRange) * 255));
          const i = (rowBase + x) * 4;
          const blended = Math.round((data[i] + localNorm) / 2);
          data[i] = blended;
          data[i + 1] = blended;
          data[i + 2] = blended;
        }
      }

      // 2c. Light unsharp-mask sharpening to recover edge crispness lost
      // to smartphone camera softness/motion blur (and to the smoothing
      // upscale draw above). Deliberately mild -- a fast 3x3 box-blur
      // estimate rather than a true Gaussian, amount capped at 0.4 --
      // since OCR accuracy suffers more from over-sharpened halo
      // artifacts than from mild residual softness.
      const sharpenSrc = new Uint8ClampedArray(data.length);
      sharpenSrc.set(data);
      const SHARPEN_AMOUNT = 0.4;
      for (let y = 1; y < height - 1; y++) {
        for (let x = 1; x < width - 1; x++) {
          const i = (y * width + x) * 4;
          let sum = 0;
          for (let dy = -1; dy <= 1; dy++) {
            const rowOffset = (y + dy) * width;
            for (let dx = -1; dx <= 1; dx++) {
              sum += sharpenSrc[(rowOffset + (x + dx)) * 4];
            }
          }
          const blurVal = sum / 9;
          const orig = sharpenSrc[i];
          const sharpened = Math.min(255, Math.max(0, orig + (orig - blurVal) * SHARPEN_AMOUNT));
          data[i] = sharpened;
          data[i + 1] = sharpened;
          data[i + 2] = sharpened;
        }
      }

      ctx.putImageData(imageData, 0, 0);

      // 3. Margin & noise trimming (with safe 24px padding to prevent header clipping)
      let top = 0, bottom = height - 1, left = 0, right = width - 1;
      const darkPixelThreshold = 100;

      for (let y = 0; y < height; y++) {
        let darks = 0;
        for (let x = 0; x < width; x++) {
          if (data[(y * width + x) * 4] < darkPixelThreshold) darks++;
        }
        if (darks > width * 0.015) { top = y; break; }
      }

      for (let y = height - 1; y >= top; y--) {
        let darks = 0;
        for (let x = 0; x < width; x++) {
          if (data[(y * width + x) * 4] < darkPixelThreshold) darks++;
        }
        if (darks > width * 0.015) { bottom = y; break; }
      }

      for (let x = 0; x < width; x++) {
        let darks = 0;
        for (let y = top; y <= bottom; y++) {
          if (data[(y * width + x) * 4] < darkPixelThreshold) darks++;
        }
        if (darks > (bottom - top) * 0.015) { left = x; break; }
      }

      for (let x = width - 1; x >= left; x--) {
        let darks = 0;
        for (let y = top; y <= bottom; y++) {
          if (data[(y * width + x) * 4] < darkPixelThreshold) darks++;
        }
        if (darks > (bottom - top) * 0.015) { right = x; break; }
      }

      const pad = 24;
      top = Math.max(0, top - pad);
      bottom = Math.min(height - 1, bottom + pad);
      left = Math.max(0, left - pad);
      right = Math.min(width - 1, right + pad);

      const trimW = Math.max(10, right - left + 1);
      const trimH = Math.max(10, bottom - top + 1);

      const trimmedCanvas = document.createElement('canvas');
      trimmedCanvas.width = trimW;
      trimmedCanvas.height = trimH;
      const trimmedCtx = trimmedCanvas.getContext('2d');
      trimmedCtx.drawImage(canvas, left, top, trimW, trimH, 0, 0, trimW, trimH);

      // Always lossless PNG, never the upload's own format. This used to be
      // toDataURL(mimeType, 0.92): for a JPEG upload -- every phone photo
      // and WhatsApp image -- the freshly sharpened, contrast-boosted page
      // was re-compressed as a lossy JPEG right before Tesseract read it,
      // smearing thin strokes into ringing artifacts. Verified on the real
      // SY-AIDS test-kit scan: the same preprocessed pixels read the time
      // header cleanly as PNG ("12:45PM | 1:45PM |Rece| 3:00PM") but as
      // garbage after the JPEG round-trip ("rzasem | tase | soar]"),
      // dropping three period start times and shifting every column after
      // them. The cell re-OCR crops below already use PNG for this reason.
      // The vision-AI upload re-encodes this back to the original format
      // (see reencodeDataUrl), so its payload is unchanged.
      const resultDataUrl = trimmedCanvas.toDataURL('image/png');

      // Free buffers immediately to avoid memory leaks
      canvas.width = 1;
      canvas.height = 1;
      trimmedCanvas.width = 1;
      trimmedCanvas.height = 1;

      resolve(resultDataUrl);
    };
    img.onerror = () => reject(new Error("Failed to load image for timetable preprocessing"));
    img.src = `data:${mimeType};base64,${base64Data}`;
  });
}

// Re-encodes an image data URL into another format/quality. Used to turn
// the lossless PNG from preprocessImageForOCR back into the upload's own
// format for the vision-AI call, so that upload stays exactly as compact as
// it was before OCR input switched to PNG (PNG round-trip is lossless, so
// the resulting bytes match what the old direct toDataURL(mimeType) gave).
function reencodeDataUrl(dataUrl, mimeType, quality) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      const c = document.createElement('canvas');
      c.width = img.width;
      c.height = img.height;
      c.getContext('2d').drawImage(img, 0, 0);
      const out = c.toDataURL(mimeType, quality);
      c.width = 1;
      c.height = 1;
      resolve(out);
    };
    img.onerror = () => reject(new Error('Failed to re-encode preprocessed image'));
    img.src = dataUrl;
  });
}

// ── Robust Time Normalizer ──────────────────────────────────────
function normalizeTimetableTime(timeRaw, defaultEndHours = 1) {
  if (!timeRaw || typeof timeRaw !== 'string') return { time: '', end: '', isValid: false };
  let str = timeRaw.trim()
    // Only an O touching a digit or colon is a misread zero ("1O:OO").
    // The old rule also fired on an O before a space, which turned the
    // "to" in "9.00 to 10.55" into "t0" and broke every "X to Y" range.
    .replace(/[OoQ]+(?=\d|:)/g, m => '0'.repeat(m.length))
    .replace(/(?<=\d|:)[OoQ]+/g, m => '0'.repeat(m.length))
    .replace(/(?<=\s|^)[lI|i](?=\d|:)/g, '1')
    .replace(/\s+/g, ' ');

  // Range match e.g. "09:00 - 10:00", "9.00 to 10.30", "1:00 - 2:00 pm"
  const rangeMatch = str.match(/(\d{1,2})[:.]?(\d{2})?\s*(am|pm)?\s*(?:-|to|~|–|—)\s*(\d{1,2})[:.]?(\d{2})?\s*(am|pm)?/i);
  if (rangeMatch) {
    let h1 = parseInt(rangeMatch[1], 10);
    let m1 = parseInt(rangeMatch[2] || '00', 10);
    let mer1 = rangeMatch[3] ? rangeMatch[3].toLowerCase() : '';

    let h2 = parseInt(rangeMatch[4], 10);
    let m2 = parseInt(rangeMatch[5] || '00', 10);
    let mer2 = rangeMatch[6] ? rangeMatch[6].toLowerCase() : '';

    if (mer2 === 'pm' && !mer1 && h1 < 12 && h2 <= 12) {
      if (h1 < h2) h1 += 12;
      if (h2 < 12) h2 += 12;
    } else if (mer1 === 'pm' && h1 < 12) {
      h1 += 12;
    }
    if (mer2 === 'pm' && h2 < 12) {
      h2 += 12;
    }
    // 12-hour clock midnight rule: "12:00 AM" means hour 0, not 12.
    if (mer1 === 'am' && h1 === 12) h1 = 0;
    if (mer2 === 'am' && h2 === 12) h2 = 0;
    // No college class runs past midnight: "12.10am" printed on a day
    // timetable is a typo for 12:10 PM. Without this, "11:10 AM - 12:10 AM"
    // ended at midnight and "12:10 AM - 1:10 PM" started at 00:10.
    if (h1 === 0 && mer1 === 'am' && (mer2 === 'pm' || h2 > 0)) h1 = 12;
    if (h2 === 0 && mer2 === 'am' && h1 > 0) h2 = 12;

    // College afternoon heuristic for non-AM/PM timetables
    if (!mer1 && !mer2) {
      if (h1 >= 1 && h1 <= 6) h1 += 12;
      if (h2 >= 1 && h2 <= 7 && h2 < h1) h2 += 12;
      else if (h2 >= 1 && h2 <= 6 && h1 >= 12) h2 += 12;
    }

    if (h1 >= 0 && h1 <= 23 && m1 >= 0 && m1 <= 59 && h2 >= 0 && h2 <= 23 && m2 >= 0 && m2 <= 59) {
      const t1 = `${String(h1).padStart(2, '0')}:${String(m1).padStart(2, '0')}`;
      const t2 = `${String(h2).padStart(2, '0')}:${String(m2).padStart(2, '0')}`;
      return { time: t1, end: t2, isValid: true, isRangeMatch: true };
    }
  }

  // Single timestamp e.g. "09:00", "10:30 AM"
  const singleMatch = str.match(/(\d{1,2})[:.](\d{2})\s*(am|pm)?/i);
  if (singleMatch) {
    let h1 = parseInt(singleMatch[1], 10);
    let m1 = parseInt(singleMatch[2], 10);
    let mer = singleMatch[3] ? singleMatch[3].toLowerCase() : '';

    if (mer === 'pm' && h1 < 12) h1 += 12;
    if (mer === 'am' && h1 === 12) h1 = 0;
    if (!mer && h1 >= 1 && h1 <= 6) h1 += 12;

    if (h1 >= 0 && h1 <= 23 && m1 >= 0 && m1 <= 59) {
      const t1 = `${String(h1).padStart(2, '0')}:${String(m1).padStart(2, '0')}`;
      let endH = (h1 + defaultEndHours) % 24;
      const t2 = `${String(endH).padStart(2, '0')}:${String(m1).padStart(2, '0')}`;
      // isRangeMatch: false -- this end time is a SYNTHESIZED default (start
      // + defaultEndHours), not read from the image. Callers that can spot
      // this token's real end elsewhere (e.g. a timetable that prints a
      // period's start and end time on two separate header rows) should
      // prefer that over trusting this guess -- see mergeSplitHeaderTimeTokens.
      return { time: t1, end: t2, isValid: true, isRangeMatch: false };
    }
  }

  return { time: '', end: '', isValid: false, isRangeMatch: false };
}

// ── Day Standardizer ───────────────────────────────────────────
const DAY_ALIASES = {
  mon: 'Mon', monday: 'Mon', m0n: 'Mon', mo: 'Mon',
  tue: 'Tue', tuesday: 'Tue', tu: 'Tue', tues: 'Tue', tu3: 'Tue',
  wed: 'Wed', wednesday: 'Wed', we: 'Wed', w3d: 'Wed',
  thu: 'Thu', thursday: 'Thu', th: 'Thu', thur: 'Thu', thurs: 'Thu',
  fri: 'Fri', friday: 'Fri', fr: 'Fri', fr1: 'Fri',
  sat: 'Sat', saturday: 'Sat', sa: 'Sat'
};

function standardizeTimetableDay(rawDay) {
  if (!rawDay || typeof rawDay !== 'string') return '';
  const clean = rawDay.toLowerCase().replace(/[^a-z0-9]/g, '');
  for (const [alias, standard] of Object.entries(DAY_ALIASES)) {
    // Exact match always wins (covers legitimate short forms like "we").
    // Prefix/substring matches require alias.length >= 3 -- otherwise a
    // 2-letter alias (mo/tu/we/th/fr/sa) can false-positive-match the start
    // of a real word, e.g. "WEB" (as in "Web Development") -> "Wed".
    if (clean === alias || (alias.length >= 3 && (clean.startsWith(alias) || clean.includes(alias)))) {
      return standard;
    }
  }
  return '';
}

// ── Precision Timetable Cell Sanitizer & Canonical Subject Normalizer ─
const TIMETABLE_NON_CLASS_KEYWORDS = [
  'lunch', 'break', 'recess', 'tea break', 'interval',
  'free', 'library', 'sports', 'mentoring', 'assembly',
  'no class', 'holiday', 'gap', 'vacant', 'off period'
];

const TIMETABLE_JUNK_TOKENS = new Set([
  'timetable', 'time table', 'schedule', 'semester', 'sem', 'academic year',
  'class', 'period', 'room no', 'lecture', 'theory', 'lab', 'practical',
  'tutorial', 'batch', 'section', 'day', 'time', 'monday', 'tuesday',
  'wednesday', 'thursday', 'friday', 'saturday', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat',
  'slot', 'hours', 'hr', 'dept', 'department', 'college', 'university',
  'sr', 'no', 'code', 'subject', 'faculty', 'room', 'venue', 'timing'
]);

const BATCH_PATTERN = /\b(?:Batch(?:es)?|Sec(?:tion)?|Grp|Group)\s*[:\-\s]*\b([A-D][1-4]|[A-D](?![a-zA-Z])|[1-4](?![0-9]))\b|\b([A-D][1-4])\b/gi;
const BRACKETED_BATCH_PATTERN = /\((?:AI-)?([A-D][1-4](?:[\s,/-]+(?:AI-)?[A-D][1-4])*)\)/i;
const SUBJECT_CODE_PATTERN = /\b([A-Z]{2,8}[0-9]{1,4}[A-Z]{1,4}[0-9]{1,4}[A-Z]?|[A-Z]{2,6}[-\s]?[0-9]{2,5}[A-Z]?|[0-9]{2}[A-Z]{2,6}[0-9]{2,4})\b/i;
const FACULTY_TITLE_PATTERN = /\b(?:Prof\.?|Dr\.?|Mr\.?|Mrs\.?|Ms\.?|Adv\.?|Shri|Smt\.?)\s+[A-Za-z]+(?:\s+(?!LH|LT|CR|Room|Lab|Cabin|Hall|Batch|Sec)[A-Za-z]+)?/gi;
const ROOM_PATTERN = /\b(?:Room|LT|CR|LH|Cabin|Hall|SF|FF|GF|WS)[-.\s]*(?:\d+[A-Z]?|[A-D]\b)|\bLab[-.\s]*\d+[A-Z]?\b|\b(?:G|F|S|T)-\d{2,3}\b|\b[A-Z]{1,2}-\d{2,3}\b/i;

function getCanonicalSubjectName(rawText) {
  if (!rawText || typeof rawText !== 'string') return '';
  let text = rawText.trim().replace(/\r\n|\r/g, '\n');

  // 1. Remove bracketed expressions (e.g. "(AI-A2, B2)", "(Lab)", "(Theory)", "[Batch 1]")
  text = text.replace(/\([^)]*\)/g, ' ');
  text = text.replace(/\[[^\]]*\]/g, ' ');

  // 2. Remove Batch/Section/Group keywords and tags (e.g. "Batch A2", "Sec B", "Grp 1", "- A2", "- C2")
  text = text.replace(/\b(?:Batch(?:es)?|Sec(?:tion)?|Grp|Group)\s*[:\-\s]*[A-D0-9,\s/-]+\b/gi, ' ');
  text = text.replace(/[:\-\s]+\b[A-D][1-4]\b/gi, ' ');
  text = text.replace(/[:\-\s]+\b[A-D]\b(?![a-zA-Z])/gi, ' ');

  // 3. Remove Faculty Titles & Names
  const FACULTY_TITLE_PATTERN = /\b(?:Prof\.?|Dr\.?|Mr\.?|Mrs\.?|Ms\.?|Shri|Smt\.?)\s+[A-Za-z]+(?:\s+[A-Za-z]+)?/gi;
  text = text.replace(FACULTY_TITLE_PATTERN, ' ');

  // 4. Remove Room numbers
  const ROOM_PATTERN = /\b(?:Room|LT|CR|LH|Cabin|Hall|SF|FF|GF|WS)[-.\s]*(?:\d+[A-Z]?|[A-D]\b)|\bLab[-.\s]*\d+[A-Z]?\b|\b(?:G|F|S|T)-\d{2,3}\b|\b[A-Z]{1,2}-\d{2,3}\b/gi;
  text = text.replace(ROOM_PATTERN, ' ');

  // 5. Remove Subject Code patterns e.g. CS401, AID21PCL202
  const SUBJECT_CODE_PATTERN = /\b([A-Z]{2,8}[0-9]{1,4}[A-Z]{1,4}[0-9]{1,4}[A-Z]?|[A-Z]{2,6}[-\s]?[0-9]{2,5}[A-Z]?|[0-9]{2}[A-Z]{2,6}[0-9]{2,4})\b/gi;
  text = text.replace(SUBJECT_CODE_PATTERN, ' ');

  // 6. Remove Type keywords (lab, theory, practical, lecture, tutorial, workshop)
  text = text.replace(/\b(?:laboratory|lab|practical|tutorial|tut|lecture|theory|project|seminar|workshop)\b/gi, ' ');
  text = text.replace(/\b(?:credits?|hours?|hrs?|periods?|sem(?:ester)?\s*(?:[1-8]|i{1,3}|iv|v|vi{0,3})?)\b/gi, ' ');

  // 7. Clean punctuation and whitespace
  text = text.replace(/^\d+[\s.\-–)]+/, '');
  let clean = text.replace(/[^a-zA-Z0-9\s/&+-]/g, ' ').replace(/\s+/g, ' ').trim();

  const words = clean.split(' ').filter((w, idx, arr) => {
    const wLow = w.toLowerCase();
    if (w === '&') return true;
    if (/^\d+$/.test(w)) {
      // Keep a short trailing number ("Open Elective 1", "Group 2") --
      // it is the only thing distinguishing otherwise-identical subject
      // names. A bare digit anywhere else in the text is still OCR/format
      // noise (stray page numbers, leftover credit counts, etc.) and gets
      // dropped as before. Checked ahead of the generic length<=1 filter
      // below, which would otherwise reject a single trailing digit first.
      return idx === arr.length - 1 && w.length <= 2;
    }
    if (w.length <= 1 && !['c', 'r'].includes(wLow)) return false;
    if (TIMETABLE_JUNK_TOKENS.has(wLow)) return false;
    if (/^[A-D][1-4]$/i.test(w)) return false;
    return true;
  });

  clean = words.join(' ').trim();

  const CANONICAL_MAP = {
    'ds': 'Data Structures',
    'data structure': 'Data Structures',
    'data structures': 'Data Structures',
    'demp': 'Digital Electronics and Microprocessors',
    'digital electronics': 'Digital Electronics and Microprocessors',
    'digital electronics and microprocessor': 'Digital Electronics and Microprocessors',
    'digital electronics and microprocessors': 'Digital Electronics and Microprocessors',
    'pbst': 'Probability and Statistics',
    'probability statistics': 'Probability and Statistics',
    'probability & statistics': 'Probability and Statistics',
    'probability and statistics': 'Probability and Statistics',
    'bmfa': 'Business Management and Financial Accounting',
    'business management financial account': 'Business Management and Financial Accounting',
    'business management & financial account': 'Business Management and Financial Accounting',
    'business management': 'Business Management and Financial Accounting',
    'coi': 'Constitution of India',
    'ce': 'Community Engagement',
    'web dev': 'Web Development',
    'web development': 'Web Development',
    'wd': 'Web Development',
    'os': 'Operating Systems',
    'operating system': 'Operating Systems',
    'operating systems': 'Operating Systems',
    'dbms': 'Database Management Systems',
    'database management': 'Database Management Systems',
    'ai': 'Artificial Intelligence',
    'ml': 'Machine Learning',
    'cn': 'Computer Networks',
    'computer network': 'Computer Networks',
    'computer networks': 'Computer Networks',
    'mdm': 'Multi Disciplinary Minor',
    'oe-1': 'Open Elective 1',
    'oe-2': 'Open Elective 2'
  };

  const lower = clean.toLowerCase();
  if (CANONICAL_MAP[lower]) return CANONICAL_MAP[lower];
  return clean || rawText.trim();
}

// Timetable slots that are real periods but not academic subjects. Used
// only by the scan preview to pre-set such rows to "Off" (the student can
// switch any of them back to Lecture). Kept separate from
// TIMETABLE_NON_CLASS_KEYWORDS so the OCR parser's behaviour is unchanged.
const NON_SUBJECT_SLOT_PATTERN = /^(?:library|sports?|games|mentor(?:ing)?|assembly|t\s*&\s*p|tnp|training\s*(?:&|and)\s*placements?|placements?|counsel+ing|nss|ncc|free|break|short break|lunch|recess)(?:\s+(?:period|session|slot|time))?$/i;

function isNonSubjectSlotName(name) {
  if (!name || typeof name !== 'string') return false;
  return NON_SUBJECT_SLOT_PATTERN.test(name.trim().replace(/\s+/g, ' '));
}

function getCanonicalSubjectKey(rawText) {
  const name = getCanonicalSubjectName(rawText);
  return (name || '').toLowerCase().replace(/[^a-z0-9]/g, '');
}

// Detects a canonical subject NAME that is almost certainly OCR/scan
// garbage rather than a real course name, using cheap, conservative
// signals chosen to avoid flagging genuine (if unusual) subject names:
//  - a word with an internal capital-then-lowercase run that is neither
//    Title Case ("Data Structures") nor an all-caps acronym ("DBMS"),
//    e.g. "ADzeame" -- this pattern essentially never occurs in a
//    human-typed subject name.
//  - a 4+ letter word with no vowels at all -- essentially never a real
//    English word or subject fragment.
//  - a very short (<=2 char) name that isn't all-caps -- a genuine short
//    subject label is written in caps ("PE", "GK"); lowercase/mixed short
//    strings like "ee" are leftover OCR noise.
// This deliberately does NOT try to catch every garbled string (two real
// dictionary words mis-stitched together, or an all-caps blob that still
// contains a vowel) -- that would need a subject dictionary and risks
// flagging real subjects. Anything this misses stays reachable through
// the per-card delete ("X") on a Subject Hub card and through the
// "Declutter my desk" preview, both already safe/non-destructive.
function isLikelyGarbledSubjectName(name) {
  if (!name || typeof name !== 'string') return false;
  const clean = name.trim();
  if (!clean) return false;

  if (clean.length <= 2 && clean !== clean.toUpperCase()) return true;

  // Cells a scan sometimes reads as the subject even though they are only
  // the room, the teacher, the batch, or the time printed in that slot.
  // getCanonicalSubjectName falls back to the raw text when stripping
  // leaves nothing, so these arrive here unchanged. A code-only name
  // ("CS401") is a real subject and is deliberately not matched.
  if (!clean.replace(/\b[ap]\.?m\.?\b/gi, '').replace(/[^a-zA-Z]/g, '')) return true;
  if (/^(?:room|rm|lt|lh|cr|hall|cabin|class\s*room)\s*[-#.:]?\s*(?:no\.?\s*)?[a-z]?\d{1,4}[a-z]?$/i.test(clean)) return true;
  if (/^[A-Z]{1,2}-\d{2,4}$/.test(clean)) return true;
  if (/^(?:prof|dr|mr|mrs|shri|smt)\.?(?:\s|$)/i.test(clean)) return true;
  if (/^(?:(?:batch(?:es)?|all|[A-D][1-4])[\s,/&+-]*)+$/i.test(clean)) return true;
  // Only short scraps and no real word, e.g. "Rm l1 2x" (all-caps short
  // labels such as "OS" or "AI & DS" are real subjects and pass).
  if (!/[A-Za-z]{3,}/.test(clean) && clean !== clean.toUpperCase()) return true;

  const words = clean.split(/\s+/);
  for (const w of words) {
    const letters = w.replace(/[^a-zA-Z]/g, '');
    if (!letters) continue;
    if (/[A-Z]{2,}[a-z]/.test(letters)) return true;
    // An all-caps short word is an acronym ("DBMS", "CPPL"), not noise.
    if (letters.length >= 4 && !/[aeiouAEIOU]/.test(letters) && !(letters.length <= 6 && letters === letters.toUpperCase())) return true;
  }
  return false;
}

function getCanonicalSubjectCode(rawName, rawCode) {
  if (rawCode && rawCode.trim() && !/lab|theory|batch/i.test(rawCode)) {
    return rawCode.trim().toUpperCase();
  }
  const cleanName = getCanonicalSubjectName(rawName);
  const CODE_MAP = {
    'Data Structures': 'DS',
    'Digital Electronics and Microprocessors': 'DEMP',
    'Probability and Statistics': 'PBST',
    'Business Management and Financial Accounting': 'BMFA',
    'Constitution of India': 'COI',
    'Community Engagement': 'CE',
    'Web Development': 'WD',
    'Operating Systems': 'OS',
    'Database Management Systems': 'DBMS',
    'Artificial Intelligence': 'AI',
    'Machine Learning': 'ML',
    'Computer Networks': 'CN',
    'Multi Disciplinary Minor': 'MDM'
  };
  if (CODE_MAP[cleanName]) return CODE_MAP[cleanName];
  if (rawCode && rawCode.trim()) return rawCode.trim().toUpperCase();
  const words = cleanName.split(/\s+/).filter(Boolean);
  if (words.length > 1) {
    return words.map(w => w[0].toUpperCase()).join('');
  }
  return cleanName.slice(0, 4).toUpperCase();
}

function extractBatchTags(rawText) {
  if (!rawText || typeof rawText !== 'string') return [];
  const batches = new Set();

  // 1. Check all bracketed expressions e.g. (AI-A2, B2), (Sec B), (Batch D1)
  const bracketMatches = rawText.match(/\(([^)]+)\)/g);
  if (bracketMatches) {
    bracketMatches.forEach(bracket => {
      const inner = bracket.replace(/^\(|\)$/g, '').trim();
      const parts = inner.split(/[\s,/-]+/).map(p => p.replace(/^AI-/i, '').replace(/^(?:Sec|Section|Batch|Grp|Group)[:\-\s]*/i, '').trim().toUpperCase());
      parts.forEach(p => {
        if (/^[A-D][1-4]$|^[A-D]$/.test(p)) batches.add(p);
      });
    });
  }

  // 2. Check standalone batch markers e.g. "Batch A2", "Sec B", "Batch D1",
  // plus bare two-character batch codes like "A2"/"D1" outside brackets
  // (e.g. "DS-AI-A2 (VJM)"). Bare single-letter/single-digit tokens now
  // require an explicit Batch/Sec/Grp/Group keyword -- see BATCH_PATTERN.
  let match;
  const regex = new RegExp(BATCH_PATTERN.source, 'gi');
  while ((match = regex.exec(rawText)) !== null) {
    const tag = (match[1] || match[2] || '').toUpperCase();
    if (tag && (/^[A-D][1-4]$|^[A-D]$/.test(tag))) {
      batches.add(tag);
    }
  }

  return Array.from(batches);
}

// Renders a teacher/faculty value with exactly one "Prof. " title, never
// doubled. Several render sites used to hardcode 'Prof. ' + teacher, which
// double-prefixed any value that already carried a title -- data.js's own
// default timetable entries all store "Prof. VAK" etc. already, and the
// Add/Edit Class form's placeholder used to suggest typing the title too
// -- producing "Prof. Prof. VAK" on screen. A value that isn't actually a
// person's name (a not-yet-assigned placeholder like "Faculty", or an
// empty-marker like "—") is left untouched since there's no name to title.
const TEACHER_TITLE_PATTERN = /^(?:prof\.?|dr\.?|mr\.?|mrs\.?|ms\.?|adv\.?|shri|smt\.?)\s/i;
const TEACHER_NO_TITLE_VALUES = new Set(['faculty', 'staff', 'tba', '\u2014', '-']);
function formatTeacherName(teacher) {
  const t = (teacher || '').trim();
  if (!t) return '';
  if (TEACHER_NO_TITLE_VALUES.has(t.toLowerCase())) return t;
  if (TEACHER_TITLE_PATTERN.test(t)) return t;
  return `Prof. ${t}`;
}

// A class like an Open Elective ("OE-1", "OE-2") often has no separate
// catalogued full name -- the raw code IS the subject name, so
// normalizeSubjectIdentity ends up setting both `subject` and `code` to the
// identical string. Any "{subject} · {code}" display then shows the exact
// same text twice ("OE-2 · OE-2"), which reads as a glitch even though both
// fields are individually correct. This only suppresses the code suffix
// when it adds no new information; a genuinely different code (e.g. "Data
// Structures · DS") still displays normally.
function subjectCodeSuffix(subject, code) {
  const c = (code || '').trim();
  if (!c) return '';
  const s = (subject || '').trim();
  if (c.toLowerCase() === s.toLowerCase()) return '';
  return '· ' + c;
}

// ── Bounded Fuzzy Matching for Existing-Subject Reconciliation ──
// Conservative, name-only (never applied to codes -- codes are short
// structured tokens where ratio-based fuzzing is dangerous). Used solely to
// catch small OCR/typo variants of an already-known subject. Below
// threshold, callers fall through to the existing "no match" behavior
// completely unchanged -- this never partially merges anything.
function levenshteinDistance(a, b) {
  if (a === b) return 0;
  const aLen = a.length, bLen = b.length;
  if (aLen === 0) return bLen;
  if (bLen === 0) return aLen;
  let prevRow = new Array(bLen + 1);
  let currRow = new Array(bLen + 1);
  for (let j = 0; j <= bLen; j++) prevRow[j] = j;
  for (let i = 1; i <= aLen; i++) {
    currRow[0] = i;
    for (let j = 1; j <= bLen; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      currRow[j] = Math.min(
        prevRow[j] + 1,
        currRow[j - 1] + 1,
        prevRow[j - 1] + cost
      );
    }
    const tmp = prevRow; prevRow = currRow; currRow = tmp;
  }
  return prevRow[bLen];
}

// Requires BOTH a high similarity ratio AND a small absolute edit distance,
// and refuses to run on short strings where a single edit would otherwise
// cross the ratio threshold. This is what keeps it conservative (few false
// positives) at the deliberate cost of more false negatives.
const FUZZY_MIN_LENGTH = 6;
const FUZZY_MAX_EDIT_DISTANCE = 3;
const FUZZY_MIN_SIMILARITY = 0.90;

function subjectNameFuzzyMatch(a, b) {
  if (!a || !b) return { isMatch: false, similarity: 0 };
  if (a === b) return { isMatch: true, similarity: 1 };
  if (a.length < FUZZY_MIN_LENGTH || b.length < FUZZY_MIN_LENGTH) {
    return { isMatch: false, similarity: 0 };
  }
  const dist = levenshteinDistance(a, b);
  if (dist > FUZZY_MAX_EDIT_DISTANCE) return { isMatch: false, similarity: 0 };
  const maxLen = Math.max(a.length, b.length);
  const similarity = maxLen === 0 ? 1 : 1 - (dist / maxLen);
  return { isMatch: similarity >= FUZZY_MIN_SIMILARITY, similarity };
}

// ── Faculty-Initials Legend Parser (auto name resolution) ───────────
// Many real timetables print a small legend below the grid mapping the
// short initials used inside cells (e.g. "VAK") to the actual faculty
// member's full name (e.g. "Prof. V. A. Kulkarni"). This detects that
// legend section via a distinctive header marker ("...faculty..."), then
// reads each physical line below it as one <INITIALS> <Title Name...>
// row. Returns a plain { INITIALS: 'Full Name' } map (empty when no such
// legend is found or nothing in it parses cleanly) -- deliberately
// conservative: an entry is only ever added when a line's first word is a
// short (2-4 letter) all-caps token immediately followed by text
// containing a recognizable title (Prof./Dr./etc), so a mis-detected
// boundary or a stray noise line just yields fewer entries, never a wrong
// one. Runs once per scan against the ORIGINAL, unfiltered word list --
// independent of reconstructTimetable2DGrid's own legend-boundary guard,
// which only concerns the grid side of that same boundary.
function parseFacultyLegend(rawWords) {
  const legend = {};
  if (!rawWords || rawWords.length === 0) return legend;

  const mapped = mapRawOcrWordsForDetection(rawWords);
  const lines = groupWordsIntoLines(mapped);

  // Detect the legend's header line by looking at each physical line's
  // words left-to-right -- covers both a single fused "FacultyName" token
  // (common on tight, small-column screenshots) and the more common
  // "Name of the faculty" multi-word phrasing (each word its own OCR
  // token). A per-word substring check alone would miss the multi-word
  // case entirely, since no single word contains "facultyname".
  // groupWordsIntoLines already returns lines sorted top-to-bottom (by
  // each line's own first word's y0), so the header's ORDINAL position is
  // used to separate it from the content rows below it, rather than an
  // absolute Y-pixel cutoff -- a real photo's row spacing is uneven
  // enough that the header's own text can visually overlap the very next
  // content row's vertical span (real evidence: a header row spanning
  // y0-y1 1122-1149 sitting right against a content row starting at
  // y0=1144), which made a Y-threshold comparison wrongly swallow the
  // first legend entry.
  let headerIndex = -1;
  lines.forEach((line, idx) => {
    if (headerIndex !== -1) return;
    const sorted = [...line].sort((a, b) => a.bbox.x0 - b.bbox.x0);
    const cleanWords = sorted.map(w => w.text.toLowerCase().replace(/[^a-z]/g, ''));
    const joined = cleanWords.join('');
    // Truncated prefixes ("facu" not "faculty") because a blurry real
    // photo's OCR commonly clips the tail off "faculty" -- real evidence:
    // "Name of the facul" (missing "ty") on an otherwise clean real scan.
    const hasFusedMarker = joined.includes('nameofthefacu') || joined.includes('facultynam');
    const hasWordSequence = cleanWords.some((cw, i) => cw === 'name' && cleanWords.slice(i + 1, i + 4).some(w2 => w2.length >= 4 && w2.startsWith('facu')));
    if (hasFusedMarker || hasWordSequence) {
      headerIndex = idx;
    }
  });
  if (headerIndex === -1) return legend;

  const legendTitlePattern = /\b(?:Prof\.?|Dr\.?|Mr\.?|Mrs\.?|Ms\.?|Adv\.?|Shri|Smt\.?)\b/i;
  // A real faculty name is short and title-only-once; a garbled multi-
  // column table read out of order (subject name + faculty name + a
  // student roll-number range all bleeding onto one detected "line") is
  // what real evidence on a compact layout actually produced -- reject it
  // outright rather than accept a wrong mapping. Better no entry than a
  // wrong one.
  const MAX_NAME_LENGTH = 45;

  lines.slice(headerIndex + 1).forEach(line => {
    const sorted = [...line].sort((a, b) => a.bbox.x0 - b.bbox.x0);
    if (sorted.length < 2) return;

    const cleanInitials = (sorted[0].text || '').toUpperCase().replace(/[^A-Z]/g, '');
    if (!/^[A-Z]{2,4}$/.test(cleanInitials)) return;

    // Strip stray leading/trailing punctuation a real photo's OCR often
    // picks up from adjacent table borders (e.g. a leading "[" or "|").
    let restText = sorted.slice(1).map(w => w.text).join(' ')
      .replace(/^[^A-Za-z0-9]+/, '').replace(/[^A-Za-z0-9.]+$/, '').trim();

    // A combined "code | subject name | faculty name" legend layout (real
    // evidence: an FY-AIDS timetable) also glues on a 4th, unrelated
    // column -- a student roll-number range, e.g. "...Prof. A. B. Nale
    // 12506051-12506075". A run of 6+ digits (optionally a hyphenated
    // pair of them) is never really part of a subject/faculty name, so
    // strip it before validating instead of rejecting the whole row.
    restText = restText.replace(/\s*\b\d{6,}(?:-\d{6,})?\b\s*$/, '').trim();
    if (!legendTitlePattern.test(restText)) return;

    // On that same combined layout the title sits partway through the
    // row, after the subject-name prose, not at the start -- keep only
    // from the title onward so that prose doesn't end up inside what's
    // supposed to be just the teacher's name.
    const titleMatch = restText.match(legendTitlePattern);
    const fullName = (titleMatch.index > 0 ? restText.slice(titleMatch.index) : restText)
      .replace(/\s{2,}/g, ' ').trim();
    const titleOccurrences = (fullName.match(/\b(?:Prof|Dr|Mr|Mrs|Ms|Adv|Shri|Smt)\b\.?/gi) || []).length;
    if (fullName.length < 5 || fullName.length > MAX_NAME_LENGTH) return;
    // A real name can still carry a single stray digit from a letter/
    // digit OCR mix-up (real evidence: "S.D." misread as "5.0.", "S."
    // misread as "8."), but genuine contamination (a roll-number range,
    // or noise glued into the middle of the row) always shows up as a
    // RUN of several digits together -- reject on that shape instead of
    // any digit at all, so one isolated-digit typo doesn't cost the
    // whole entry.
    if (/\d{2,}/.test(fullName)) return;
    if (titleOccurrences > 1) return;
    if (!legend[cleanInitials]) {
      legend[cleanInitials] = fullName;
    }
  });

  return legend;
}

// Mirrors parseFacultyLegend's shape/approach for the other common legend
// table printed below a timetable grid: "Subject | Abbreviation | Lab | Hall
// No.". Lets a scan resolve abbreviations that aren't in the hardcoded
// CANONICAL_SUBJECT_MAP below (i.e. any institution's own subject list, not
// just the one this map was authored against), straight from that scan's
// own legend rather than requiring the map to be extended per-college.
// Ported from PR #33 (claude/gifted-feynman-s1s33y), unchanged.
function parseSubjectAbbreviationLegend(rawWords) {
  const legend = {};
  if (!rawWords || rawWords.length === 0) return legend;

  const mapped = mapRawOcrWordsForDetection(rawWords);
  const lines = groupWordsIntoLines(mapped);

  let headerIndex = -1;
  lines.forEach((line, idx) => {
    if (headerIndex !== -1) return;
    const sorted = [...line].sort((a, b) => a.bbox.x0 - b.bbox.x0);
    const cleanWords = sorted.map(w => w.text.toLowerCase().replace(/[^a-z]/g, ''));
    const hasSubjectWord = cleanWords.some(w => w.startsWith('subject'));
    // "abbrivat" (not "abbreviat") covers the common real-world misspelling
    // printed on the source document itself, not just an OCR misread.
    const hasAbbrevWord = cleanWords.some(w => w.startsWith('abbrev') || w.startsWith('abbriv'));
    if (hasSubjectWord && hasAbbrevWord) headerIndex = idx;
  });
  if (headerIndex === -1) return legend;

  lines.slice(headerIndex + 1).forEach(line => {
    const sorted = [...line].sort((a, b) => a.bbox.x0 - b.bbox.x0);
    if (sorted.length < 2) return;

    const nameWords = [];
    let abbrev = null;
    for (const w of sorted) {
      const raw = (w.text || '').trim();
      if (!raw) continue;
      const alphaOnly = raw.replace(/[^A-Za-z0-9-]/g, '');
      // Only accept an all-caps short token as the abbreviation once at
      // least one name word already precedes it -- a faculty-legend row
      // (e.g. "VAK  Prof. V. A. Kulkarni") starts with its all-caps token
      // immediately, so this naturally skips that table instead of misreading
      // it as this one.
      if (!abbrev && nameWords.length > 0 && /^[A-Z]{2,6}$/.test(alphaOnly)) {
        abbrev = alphaOnly;
        break;
      }
      nameWords.push(raw);
    }
    if (!abbrev) return;

    const subjectName = nameWords.join(' ')
      .replace(/[^A-Za-z0-9\s&/.-]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    if (subjectName.length < 3 || subjectName.length > 60) return;
    if (!legend[abbrev]) legend[abbrev] = subjectName;
  });

  return legend;
}

function normalizeSubjectIdentity(rawText, existingSubjects = [], forceType = null, facultyLegend = {}, subjectLegend = {}) {
  if (!rawText || typeof rawText !== 'string') {
    return {
      canonicalName: '',
      canonicalCode: '',
      classType: 'lecture',
      batches: [],
      room: '',
      teacher: '',
      isLab: false
    };
  }

  let text = rawText.trim().replace(/\r\n|\r/g, '\n');

  // 1. Extract Batch tags
  const batches = extractBatchTags(text);

  // 2. Extract Faculty
  let teacher = '';
  const teacherMatch = text.match(FACULTY_TITLE_PATTERN);
  if (teacherMatch) {
    teacher = teacherMatch[0].trim();
    text = text.replace(teacherMatch[0], ' ');
  }

  // 2b. Resolve bare faculty initials (e.g. "VAK") via a per-scan legend
  // parsed from this image's own "Name of the faculty" table, for the
  // common case where a raw cell only prints the initials with no title
  // prefix (so step 2's FACULTY_TITLE_PATTERN never finds them). Scans
  // every short all-caps token in reading order and stops at the first
  // one that's an actual legend match -- e.g. "DEMP VAK" tries "DEMP"
  // first (no match, since that's a subject abbreviation, not a faculty
  // legend entry) before matching "VAK". Only ever fires when no teacher
  // was already resolved, so it can only add information, never override
  // an already-confident result.
  if (!teacher && facultyLegend && Object.keys(facultyLegend).length > 0) {
    const candidateTokens = text.match(/\b[A-Z]{2,4}\b/g) || [];
    for (const tok of candidateTokens) {
      if (facultyLegend[tok]) {
        teacher = facultyLegend[tok];
        text = text.replace(new RegExp(`\\b${tok}\\b`), ' ');
        break;
      }
    }
  }

  // 3. Extract Room
  let room = '';
  const roomMatch = text.match(ROOM_PATTERN);
  if (roomMatch && !/^(19|20)\d\d$/.test(roomMatch[0])) {
    room = roomMatch[0].trim().replace(/\s+/g, '-');
    text = text.replace(roomMatch[0], ' ');
  }

  // 4. Extract Course Code (including inside parentheses like (CS401) or (AID21PCL202))
  let code = '';
  const codeMatch = text.match(SUBJECT_CODE_PATTERN);
  if (codeMatch && codeMatch[1].length >= 3) {
    const candidateCode = codeMatch[1].replace(/\s+/g, '').toUpperCase();
    if (/[0-9]/.test(candidateCode) || candidateCode.length <= 5) {
      code = candidateCode;
      text = text.replace(codeMatch[0], ' ');
    }
  }

  // Strip all remaining bracketed expressions e.g. (AI-A2, B2) or (CE) or (Batch 1)
  text = text.replace(/\([^)]*\)/g, ' ');
  text = text.replace(/\[[^\]]*\]/g, ' ');
  text = text.replace(/\b(?:Batch(?:es)?|Sec(?:tion)?)\s*[:\-\s]*[A-D0-9,\s/-]+\b/gi, ' ');

  // Strip an inline, unbracketed branch/batch qualifier appended directly
  // to a subject abbreviation with a hyphen -- e.g. "DS-AI-A2", "DEMP-AI-B2",
  // "WEB DEV.-AI- C2" -- the same "(AI-)?[A-D][1-4]" shape
  // BRACKETED_BATCH_PATTERN already recognizes inside parentheses, just
  // without the parens. Real evidence: on a clean real-photo scan, cells
  // like "DS-AI-A2" were left as an unresolved raw code (never matching
  // CANONICAL_SUBJECT_MAP's plain "ds" key) purely because this suffix was
  // never separated from the subject abbreviation before the lookup. The
  // batch itself is already captured independently via extractBatchTags
  // (BATCH_PATTERN's bare "[A-D][1-4]" alternative matches regardless of
  // brackets), so this only needs to remove it from the text used to
  // derive the subject NAME, not re-extract it.
  //
  // "A[IL]" (not just "AI") because the same real photos show Tesseract
  // inconsistently misreading the "I" in this exact qualifier as a
  // lowercase "l" -- "WEB DEV.-Al- C2" right next to a correctly-read
  // "DEMP-AI- D2" on the very same line. The /gi flag already makes each
  // matched letter case-insensitive, so "A[IL]" alone covers all of
  // AI/Ai/aI/ai/AL/Al/aL/al without needing separate alternatives.
  text = text.replace(/[-\s]+(?:A[IL][-\s]*)?[A-D][1-4]\b/gi, ' ');

  // 5. Detect Class Type & Lab markers
  let classType = forceType || 'lecture';
  const isLabExplicit = /\b(?:lab|practical|workshop|hands-on|pr)\b/i.test(text) || /\b(?:lab|ws)\b/i.test(room);
  const isTutorial = /\b(?:tutorial|tut)\b/i.test(text);
  const isProject = /\b(?:project|seminar|viva)\b/i.test(text);

  if (forceType) {
    classType = forceType;
  } else if (isLabExplicit) {
    classType = 'lab';
  } else if (isTutorial) {
    classType = 'tutorial';
  } else if (isProject) {
    classType = 'project';
  }

  // Strip type keywords from title candidate
  text = text
    .replace(/\b(?:laboratory|lab|practical|tutorial|tut|lecture|theory|project|seminar|workshop)\b/gi, ' ')
    .replace(/\b(?:credits?|hours?|hrs?|periods?|sem(?:ester)?\s*(?:[1-8]|i{1,3}|iv|v|vi{0,3})?)\b/gi, ' ');

  // If code was not found earlier, try again on cleaned text
  if (!code) {
    const codeMatch2 = text.match(SUBJECT_CODE_PATTERN);
    if (codeMatch2 && codeMatch2[1].length >= 3) {
      const candidateCode = codeMatch2[1].replace(/\s+/g, '').toUpperCase();
      if (/[0-9]/.test(candidateCode) || candidateCode.length <= 5) {
        code = candidateCode;
        text = text.replace(codeMatch2[0], ' ');
      }
    }
  }

  // 6. Clean Subject Name words
  text = text.replace(/^\d+[\s.\-–)]+/, '');
  let cleanName = text
    .replace(/[^a-zA-Z0-9\s/&+-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const words = cleanName.split(' ').filter((w, idx, arr) => {
    const wLow = w.toLowerCase();
    if (w === '&') return true;
    if (/^\d+$/.test(w)) {
      // Keep a short trailing number ("Open Elective 1", "Group 2") --
      // it is the only thing distinguishing otherwise-identical subject
      // names. A bare digit anywhere else in the text is still OCR/format
      // noise (stray page numbers, leftover credit counts, etc.) and gets
      // dropped as before. Checked ahead of the generic length<=1 filter
      // below, which would otherwise reject a single trailing digit first.
      return idx === arr.length - 1 && w.length <= 2;
    }
    if (w.length <= 1 && !['c', 'r'].includes(wLow)) return false;
    if (TIMETABLE_JUNK_TOKENS.has(wLow)) return false;
    if (/^[A-D][1-4]$/i.test(w)) return false;
    return true;
  });

  cleanName = words.join(' ').trim();

  // Normalize common subject abbreviations / names
  const CANONICAL_SUBJECT_MAP = {
    'ds': 'Data Structures',
    'data structure': 'Data Structures',
    'demp': 'Digital Electronics and Microprocessors',
    'digital electronics': 'Digital Electronics and Microprocessors',
    'digital electronics and microprocessor': 'Digital Electronics and Microprocessors',
    'pbst': 'Probability and Statistics',
    'probability statistics': 'Probability and Statistics',
    'probability & statistics': 'Probability and Statistics',
    'probability and statistic': 'Probability and Statistics',
    'bmfa': 'Business Management and Financial Accounting',
    'business management financial account': 'Business Management and Financial Accounting',
    'business management & financial account': 'Business Management and Financial Accounting',
    'business management': 'Business Management and Financial Accounting',
    'coi': 'Constitution of India',
    'ce': 'Community Engagement',
    'web dev': 'Web Development',
    'web development': 'Web Development',
    'os': 'Operating Systems',
    'operating system': 'Operating Systems',
    'dbms': 'Database Management Systems',
    'database management': 'Database Management Systems',
    'ai': 'Artificial Intelligence',
    'ml': 'Machine Learning',
    'cn': 'Computer Networks',
    'computer network': 'Computer Networks'
  };

  const lowerClean = cleanName.toLowerCase();
  let resolvedFromScanLegend = false;
  let digitConfusionCorrected = false;
  if (CANONICAL_SUBJECT_MAP[lowerClean]) {
    cleanName = CANONICAL_SUBJECT_MAP[lowerClean];
  } else if (subjectLegend && subjectLegend[cleanName.toUpperCase()]) {
    // Not a subject this app already knows about, but this exact scan's own
    // "Subject | Abbreviation" legend table resolves it -- use that instead
    // of leaving the bare code as the display name.
    cleanName = subjectLegend[cleanName.toUpperCase()];
    resolvedFromScanLegend = true;
  } else {
    const corrected = correctDigitLetterConfusion(cleanName.toUpperCase());
    if (corrected) {
      if (CANONICAL_SUBJECT_MAP[corrected.toLowerCase()]) {
        cleanName = CANONICAL_SUBJECT_MAP[corrected.toLowerCase()];
        digitConfusionCorrected = true;
      } else if (subjectLegend && subjectLegend[corrected]) {
        cleanName = subjectLegend[corrected];
        resolvedFromScanLegend = true;
        digitConfusionCorrected = true;
      }
    }
  }

  // If Lab variant, standardize name with 'Lab' suffix
  if (classType === 'lab' && cleanName && !/\blab\b/i.test(cleanName)) {
    cleanName = `${cleanName} Lab`;
    if (code && !code.endsWith('-LAB') && !code.endsWith('LAB') && !code.endsWith('P')) {
      code = `${code}-LAB`;
    }
  }

  // Match against existing subjects
  let fuzzyMatchApplied = false;
  if (existingSubjects && existingSubjects.length > 0) {
    const cleanNoSpaces = cleanName.toLowerCase().replace(/[^a-z0-9]/g, '');
    const cleanCodeNoSpaces = code.toLowerCase().replace(/[^a-z0-9]/g, '');

    let exactMatchFound = false;
    for (const ex of existingSubjects) {
      const exName = (ex.name || ex.subject || '').trim();
      const exCode = (ex.code || '').trim();
      const exNameClean = exName.toLowerCase().replace(/[^a-z0-9]/g, '');
      const exCodeClean = exCode.toLowerCase().replace(/[^a-z0-9]/g, '');

      const exIsLab = /\blab\b/i.test(exName) || (ex.type === 'lab');
      if (exIsLab !== (classType === 'lab')) continue;

      if (cleanCodeNoSpaces && exCodeClean && cleanCodeNoSpaces === exCodeClean) {
        cleanName = exName;
        code = exCode;
        exactMatchFound = true;
        break;
      }
      if (cleanNoSpaces && exNameClean && cleanNoSpaces === exNameClean) {
        cleanName = exName;
        code = exCode || code;
        exactMatchFound = true;
        break;
      }
    }

    // Conservative fuzzy fallback: only runs when no exact code/name match was
    // found above. Anything below subjectNameFuzzyMatch's threshold is left
    // exactly as-is -- treated as a new/unmatched subject, unchanged from
    // prior behavior. Never partially merged, never silently glued on.
    if (!exactMatchFound && cleanNoSpaces) {
      let bestFuzzy = null;
      for (const ex of existingSubjects) {
        const exName = (ex.name || ex.subject || '').trim();
        if (!exName) continue;
        const exNameClean = exName.toLowerCase().replace(/[^a-z0-9]/g, '');
        const exIsLab = /\blab\b/i.test(exName) || (ex.type === 'lab');
        if (exIsLab !== (classType === 'lab')) continue;

        const result = subjectNameFuzzyMatch(cleanNoSpaces, exNameClean);
        if (result.isMatch && (!bestFuzzy || result.similarity > bestFuzzy.similarity)) {
          bestFuzzy = { exName, exCode: (ex.code || '').trim(), similarity: result.similarity };
        }
      }
      if (bestFuzzy) {
        cleanName = bestFuzzy.exName;
        code = bestFuzzy.exCode || code;
        fuzzyMatchApplied = true;
      }
    }
  }

  const confidence = fuzzyMatchApplied
    ? 82
    : (cleanName && cleanName !== 'General Subject') ? (code ? 95 : 85) : (code ? 80 : 50);

  return {
    raw_label: rawText,
    normalized_subject_name: cleanName || code || 'General Subject',
    canonicalName: cleanName || code || 'General Subject',
    canonicalCode: code || '',
    code: code || '',
    subject_kind: classType,
    classType,
    batch_tags: batches,
    batches,
    room,
    faculty: teacher,
    teacher,
    isLab: classType === 'lab',
    normalization_confidence: confidence,
    resolvedFromScanLegend,
    digitConfusionCorrected,
    fuzzyMatchApplied
  };
}

function shouldKeepClassForUserBatch(classItem, userBatch = 'all') {
  if (!userBatch || userBatch.toLowerCase() === 'all') return true;

  const itemBatches = classItem.batches || extractBatchTags(classItem.subject || '');
  if (!itemBatches || itemBatches.length === 0) return true;

  const cleanUserBatch = userBatch.toUpperCase().trim();
  if (itemBatches.includes(cleanUserBatch)) return true;

  const userLetter = cleanUserBatch.charAt(0);
  if (itemBatches.includes(userLetter)) return true;

  return false;
}

// Splits a combined multi-batch timetable row -- data.js's "A + B" lab-slot
// shorthand, e.g. "DS-AI-A2 (VJM) + WEB DEV.-AI-C2 (MKP)", where several
// batches share one time slot but each does a DIFFERENT subject in a
// different room -- into one entry per batch. Verified against every
// combined row in TIMETABLE: `subject` segments split on "+" and `room`
// segments split on "/" list the same batches in the same order, so they
// pair up by index; each segment's own trailing "(INITIALS)" is pulled out
// as that segment's teacher, since the row's shared `teacher` field is not
// reliably parallel (only the first name in it carries a title). Rows that
// aren't combined (the vast majority -- ordinary lectures, single-batch
// labs, recess) pass through unchanged.
function expandCombinedTimetableRow(item) {
  const subj = item.subject || '';
  if (!subj.includes('+')) return [item];

  const subjParts = subj.split(/\s*\+\s*/).map(s => s.trim()).filter(Boolean);
  if (subjParts.length < 2) return [item];

  const roomParts = (item.room || '').split(/\s*\/\s*/).map(s => s.trim());
  const roomsAlign = roomParts.length === subjParts.length;

  return subjParts.map((part, i) => {
    const teacherMatch = part.match(/\(([^)]+)\)\s*$/);
    return {
      ...item,
      subject: part,
      room: roomsAlign ? roomParts[i] : (item.room || ''),
      teacher: teacherMatch ? teacherMatch[1].trim() : (item.teacher || ''),
      code: '',
    };
  });
}

// Flattens data.js's TIMETABLE (keyed 0=Sun..6=Sat) into the flat
// {day, time, end, subject, room, teacher, type, ...} shape the timetable
// preview pipeline (showTimetablePreviewModal) already expects, expanding
// combined multi-batch rows first via expandCombinedTimetableRow() so each
// entry describes exactly one batch's class rather than several batches
// glued into one row.
function buildSampleTimetableSchedule() {
  const DAY_NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const out = [];
  Object.keys(TIMETABLE).forEach(dayKey => {
    const dayName = DAY_NAMES[parseInt(dayKey, 10)] || 'Mon';
    (TIMETABLE[dayKey] || []).forEach(item => {
      expandCombinedTimetableRow(item).forEach(entry => {
        out.push({ ...entry, day: dayName });
      });
    });
  });
  return out;
}

// Headless counterpart to showTimetablePreviewModal()'s per-item
// normalization step, used only where popping the interactive preview
// modal would be disruptive (mid-onboarding). Mirrors that modal's
// normalize-and-fallback logic exactly, so a class looks identical
// whether it was loaded via onboarding or the standalone "Load sample
// timetable" button, then keeps only the rows relevant to userBatch
// (shouldKeepClassForUserBatch already keeps batch-less rows -- lectures,
// recess -- for everyone).
function buildFilteredAidsTimetable(userBatch) {
  const existingSubjects = getSubjectList();
  const grouped = getEmptyTimetable();
  buildSampleTimetableSchedule().forEach(item => {
    const norm = normalizeSubjectIdentity(item.subject || '', existingSubjects, item.type);
    const batches = (norm.batches && norm.batches.length > 0) ? norm.batches : (item.batches || []);
    const entry = {
      time: item.time || '10:00',
      end: item.end || '11:00',
      subject: norm.canonicalName || item.subject || '',
      code: norm.canonicalCode || item.code || '',
      room: norm.room || item.room || '',
      teacher: norm.teacher || item.teacher || '',
      type: norm.classType || item.type || 'lecture',
      batches,
    };
    if (!shouldKeepClassForUserBatch(entry, userBatch)) return;
    const dayIdx = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(item.day);
    if (dayIdx === -1) return;
    grouped[dayIdx].push(entry);
  });
  Object.keys(grouped).forEach(d => {
    grouped[d].sort((a, b) => timeToMinutes(a.time) - timeToMinutes(b.time));
  });
  return grouped;
}

function cleanupTimetableDomain(rawText, existingSubjects = []) {
  if (!rawText || typeof rawText !== 'string') {
    return { subject: '', code: '', room: '', teacher: '', type: 'lecture', batches: [], isOff: false, isUncertain: true };
  }

  let text = rawText.trim().replace(/\r\n|\r/g, '\n');
  const lower = text.toLowerCase();

  // Check if non-class / break period
  for (const kw of TIMETABLE_NON_CLASS_KEYWORDS) {
    if (new RegExp(`\\b${kw}\\b`, 'i').test(lower)) {
      return {
        subject: kw.toUpperCase(),
        code: '',
        room: '',
        teacher: '',
        type: 'off',
        batches: [],
        isOff: true,
        isUncertain: false
      };
    }
  }

  // Strip time strings so times never pollute room numbers, batch tokens, or codes
  text = text
    .replace(/\b([0-1]?[0-9]|2[0-3])[:.]([0-5][0-9])\s*(?:am|pm)?\s*(?:-|to|~|–|—)\s*([0-1]?[0-9]|2[0-3])[:.]([0-5][0-9])\s*(?:am|pm)?\b/gi, ' ')
    .replace(/\b([0-1]?[0-9]|2[0-3])[:.]([0-5][0-9])\s*(?:am|pm)?\b/gi, ' ')
    .replace(/\b\d{1,2}\s*(?:am|pm)\b/gi, ' ');

  const norm = normalizeSubjectIdentity(text, existingSubjects);

  return {
    subject: norm.canonicalName,
    code: norm.canonicalCode,
    room: norm.room,
    teacher: norm.teacher,
    type: norm.classType,
    batches: norm.batches,
    isOff: false,
    isUncertain: !norm.canonicalName
  };
}

// ── OCR Cell Clustering Helpers (Stage 2A: structure-aware timetable parsing) ──
// Groups words into physical text lines by vertical bbox overlap -- this is
// orientation-independent (text always reads top-to-bottom regardless of
// whether the table has days-as-rows or days-as-columns), so it is reused
// unchanged for both Layout A and Layout B below. Same 0.42 overlap ratio
// already used by the existing visual-line clusterer (Strategy 2), kept
// consistent rather than inventing a new constant.
function groupWordsIntoLines(words, overlapThreshold = 0.42) {
  const sorted = [...words].sort((a, b) => a.bbox.y0 - b.bbox.y0);
  const lines = [];
  for (const w of sorted) {
    let placed = false;
    for (const line of lines) {
      const avgY0 = line.reduce((s, x) => s + x.bbox.y0, 0) / line.length;
      const avgY1 = line.reduce((s, x) => s + x.bbox.y1, 0) / line.length;
      const wH = w.bbox.y1 - w.bbox.y0;
      const overlap = Math.max(0, Math.min(w.bbox.y1, avgY1) - Math.max(w.bbox.y0, avgY0));
      if (wH > 0 && (overlap / wH) > overlapThreshold) {
        line.push(w);
        placed = true;
        break;
      }
    }
    if (!placed) lines.push([w]);
  }
  lines.forEach(l => l.sort((a, b) => a.bbox.x0 - b.bbox.x0));
  lines.sort((a, b) => a[0].bbox.y0 - b[0].bbox.y0);
  return lines;
}

function bboxOfWords(wordsArr) {
  return {
    x0: Math.min(...wordsArr.map(w => w.bbox.x0)),
    x1: Math.max(...wordsArr.map(w => w.bbox.x1)),
    y0: Math.min(...wordsArr.map(w => w.bbox.y0)),
    y1: Math.max(...wordsArr.map(w => w.bbox.y1))
  };
}

// Splits one physical text line into horizontal segments wherever the gap
// between consecutive words exceeds gapPx. Used only when the time axis
// runs horizontally (Layout A), to separate genuinely distinct side-by-side
// cells that share one day-row's Y-band without breaking apart a single
// label's own normal word spacing.
function splitLineByXGap(line, gapPx) {
  const sorted = [...line].sort((a, b) => a.bbox.x0 - b.bbox.x0);
  const segments = [];
  let current = [sorted[0]];
  for (let i = 1; i < sorted.length; i++) {
    const prev = sorted[i - 1];
    const w = sorted[i];
    const gap = w.bbox.x0 - prev.bbox.x1;
    if (gap > gapPx) {
      segments.push(current);
      current = [w];
    } else {
      current.push(w);
    }
  }
  segments.push(current);
  return segments;
}

function axisOverlapFraction(bboxA, bboxB, axis) {
  const aMin = axis === 'x' ? bboxA.x0 : bboxA.y0;
  const aMax = axis === 'x' ? bboxA.x1 : bboxA.y1;
  const bMin = axis === 'x' ? bboxB.x0 : bboxB.y0;
  const bMax = axis === 'x' ? bboxB.x1 : bboxB.y1;
  const overlap = Math.max(0, Math.min(aMax, bMax) - Math.max(aMin, bMin));
  const narrower = Math.min(aMax - aMin, bMax - bMin);
  if (narrower <= 0) return 0;
  return overlap / narrower;
}

// Merges a flat list of word-segments into cell clusters by testing overlap
// on the given axis between each pair's combined bbox extent. Used by
// Layout A to re-stitch a single label's stacked subject/teacher/room lines
// (or a spanned cell's own wrapped text) back into one cluster after the
// per-line X-gap split above.
function mergeSegmentsByAxisOverlap(segments, axis, overlapFrac) {
  const items = segments.map(s => ({ words: s, bbox: bboxOfWords(s) }));
  const used = new Array(items.length).fill(false);
  const merged = [];

  for (let i = 0; i < items.length; i++) {
    if (used[i]) continue;
    const group = [items[i]];
    used[i] = true;
    let changed = true;
    while (changed) {
      changed = false;
      for (let j = 0; j < items.length; j++) {
        if (used[j]) continue;
        const overlapsAny = group.some(g => axisOverlapFraction(g.bbox, items[j].bbox, axis) >= overlapFrac);
        if (overlapsAny) {
          group.push(items[j]);
          used[j] = true;
          changed = true;
        }
      }
    }
    const allWords = group.flatMap(g => g.words);
    merged.push({ words: allWords, bbox: bboxOfWords(allWords) });
  }
  return merged;
}

// Merges consecutive physical text lines into one cell cluster when the
// vertical gap between them is small (stacked lines of one session). Used
// when the time axis runs vertically (Layout B): a day-band there is
// already a narrow column, so distinct cells are separated by vertical
// proximity rather than by any horizontal gap.
function mergeLinesByYGap(lines, gapPx) {
  const clusters = [];
  let current = null;
  for (const line of lines) {
    const bbox = bboxOfWords(line);
    if (current && (bbox.y0 - current.bbox.y1) <= gapPx) {
      current.words.push(...line);
      current.bbox = bboxOfWords(current.words);
    } else {
      current = { words: [...line], bbox };
      clusters.push(current);
    }
  }
  return clusters;
}

// Determines which time intervals a cluster's bbox spans on the given axis.
// An interval counts as "covered" when the overlap between the cluster's
// extent and that interval is at least overlapFrac of the interval's own
// width/height -- this is what lets one merged cell correctly claim 2
// adjacent time columns/rows instead of being force-assigned to whichever
// one its center point happens to fall in. A weak-but-passing overlap on
// any covered interval is flagged borderline for human review.
function computeIntervalSpan(clusterBBox, intervals, axis, overlapFrac = 0.35) {
  const cMin = axis === 'x' ? clusterBBox.x0 : clusterBBox.y0;
  const cMax = axis === 'x' ? clusterBBox.x1 : clusterBBox.y1;
  const clusterSize = cMax - cMin;
  const covered = [];
  intervals.forEach((iv, idx) => {
    const ivMin = axis === 'x' ? iv.minX : iv.minY;
    const ivMax = axis === 'x' ? iv.maxX : iv.maxY;
    const overlap = Math.max(0, Math.min(cMax, ivMax) - Math.max(cMin, ivMin));
    const ivSize = ivMax - ivMin;
    const ivFrac = ivSize > 0 ? overlap / ivSize : 0;
    const clusterFrac = clusterSize > 0 ? overlap / clusterSize : 0;
    // An interval counts as covered if the overlap is a substantial share of
    // EITHER the interval's own width/height (catches a cell that spans
    // multiple columns/rows) OR the cluster's own extent (catches a short,
    // narrow label -- e.g. a bare 2-letter abbreviation -- sitting inside
    // one much wider column, which would otherwise never clear an
    // interval-relative threshold). Coverage via the interval-relative
    // share is the stronger signal; when neither measure is confident the
    // interval is flagged as weak evidence for the caller.
    if (ivFrac >= overlapFrac || clusterFrac >= overlapFrac) {
      covered.push({ idx, iv, ivFrac, clusterFrac, weak: ivFrac < 0.5 && clusterFrac < 0.5 });
    }
  });
  if (covered.length === 0) return null;
  covered.sort((a, b) => a.idx - b.idx);
  const borderline = covered.some(c => c.weak);
  return {
    startIdx: covered[0].idx,
    endIdx: covered[covered.length - 1].idx,
    startInterval: covered[0].iv,
    endInterval: covered[covered.length - 1].iv,
    durationInSlots: covered[covered.length - 1].idx - covered[0].idx + 1,
    borderline
  };
}

// Conservative pre-normalization split for a clustered cell's raw text: only
// splits on a '+' that looks like a real parallel-session separator (real
// production timetable data in this codebase already uses "+" to join
// grouped multi-batch lab cells, e.g. "DS-AI-A2 (VJM) + WEB DEV.-AI-C2
// (MKP)"). Requires 2-4 fragments, each with a real minimum of readable
// text, and refuses to partially split -- an ambiguous or over-long split
// falls back to the original single-string behavior unchanged, leaving the
// caller to flag it uncertain instead.
function splitMultiSessionCellText(rawText) {
  if (!rawText || typeof rawText !== 'string') return { fragments: [rawText || ''], wasSplit: false };
  if (rawText.indexOf('+') === -1) return { fragments: [rawText], wasSplit: false };

  const MAX_FRAGMENTS = 4;
  const MIN_FRAGMENT_CHARS = 3;

  const trimmed = rawText.split(/\s*\+\s*/).map(p => p.trim());

  if (trimmed.length < 2 || trimmed.length > MAX_FRAGMENTS) {
    return { fragments: [rawText], wasSplit: false };
  }
  if (trimmed.some(f => f.replace(/[^a-zA-Z0-9]/g, '').length < MIN_FRAGMENT_CHARS)) {
    return { fragments: [rawText], wasSplit: false };
  }
  return { fragments: trimmed, wasSplit: true };
}

// Fallback split for a clustered cell with NO literal '+' separator. Real
// timetable data can show two distinct parallel sessions stacked as two
// physical lines within one cell with no connecting character at all --
// but splitting on line count alone is unsafe, since a single subject's
// own label commonly wraps across two lines too. This only splits when
// each line, run independently through the exact same subject-matching
// used everywhere else in this file, resolves to its own confident
// (non-residue) canonical subject, and the two resolved subjects differ.
// Any weaker signal declines the split and returns wasSplit:false, the
// same refuse-if-ambiguous behavior as splitMultiSessionCellText's '+'
// path. Callers must flag a resulting split uncertain -- unlike an
// explicit '+' separator, this is inferred from ambiguous input.
function trySplitByIndependentLines(clusterWords, existingSubjects) {
  if (!clusterWords || clusterWords.length === 0) return { fragments: null, wasSplit: false };

  const lines = groupWordsIntoLines(clusterWords);
  // Originally capped at exactly 2 lines; generalized to up to 4 after real
  // evidence showed a genuinely-independent 3-subject stacked cell (three
  // distinct classes crammed into one merged multi-hour cell) on a real
  // photo. Capped at 4 to keep this a targeted heuristic, not an open-ended
  // one -- more stacked lines than that is far more likely to be OCR line
  // fragmentation noise than a real 4+-subject cell.
  if (lines.length < 2 || lines.length > 4) return { fragments: null, wasSplit: false };

  const lineTexts = lines.map(line =>
    [...line].sort((a, b) => a.bbox.x0 - b.bbox.x0).map(w => w.text).join(' ').trim()
  );
  if (lineTexts.some(t => t.replace(/[^a-zA-Z0-9]/g, '').length < 3)) {
    return { fragments: null, wasSplit: false };
  }

  const norms = lineTexts.map(t => normalizeSubjectIdentity(t, existingSubjects));
  // 'General Subject' is normalizeSubjectIdentity's own explicit fallback
  // sentinel for "nothing meaningful resolved" (e.g. a line that's entirely
  // a teacher name, like "Prof. Rao") -- it must never count as a real,
  // confidently-distinct subject, or a lone teacher-name line would look
  // like a second session and trigger a false split.
  const allConfident = norms.every(n => n.canonicalName && n.canonicalName !== 'General Subject' && !looksLikeUnresolvedCodeResidue(n.canonicalName));
  const uniqueNames = new Set(norms.map(n => n.canonicalName.toLowerCase()));
  const allDistinct = allConfident && uniqueNames.size === norms.length;

  if (!allConfident || !allDistinct) return { fragments: null, wasSplit: false };
  return { fragments: lineTexts, wasSplit: true };
}

// A canonical name that never resolved past raw codes/branch-qualifiers
// (e.g. an unresolved "DS-AI", or a bare "AI") is a real, observed failure
// mode found against this codebase's own reference timetable data ("AI"
// aliases to the real subject "Artificial Intelligence" in
// CANONICAL_SUBJECT_MAP, but also appears as a branch qualifier inside
// codes like "DS-AI-A2") -- flag it for review instead of silently trusting
// a guess either way.
function looksLikeUnresolvedCodeResidue(canonicalName) {
  if (!canonicalName) return true;
  const trimmed = canonicalName.trim();
  return /^[A-Z0-9]+([\s-]+[A-Z0-9]+)*$/.test(trimmed);
}

// Reuses the attendance-scan pipeline's digit/letter OCR-confusion pattern
// (0/O, 1/I, 5/S, 8/B) for the timetable path, where it wasn't previously
// applied. Only ever called on a token that already failed both the
// canonical-subject map and the per-scan legend lookup, and only kept if the
// corrected version then resolves against one of them -- so it can never
// invent a subject name, only recover one that a single misread character
// was hiding. Ported from PR #33 (claude/gifted-feynman-s1s33y), unchanged.
function correctDigitLetterConfusion(token) {
  if (!token || !/\d/.test(token)) return null;
  const DIGIT_TO_LETTER = { '0': 'O', '1': 'I', '5': 'S', '8': 'B' };
  let changed = false;
  const corrected = token.replace(/[0158]/g, (d) => { changed = true; return DIGIT_TO_LETTER[d]; });
  return changed ? corrected : null;
}

// True when two words' vertical centers are close enough to plausibly be on
// the same physical text line -- scaled to each word's own bbox height
// rather than a fixed pixel guess. Guards detectDayAndTimeTokens's
// pairText/tripText lookahead against fusing the trailing word of one
// header line with the leading word of the NEXT line into a bogus token
// (real risk on a tightly-packed multi-row header, e.g. a period's start
// time on one line and its end time directly below it -- Tesseract's word
// array need not be grouped by line, so words[i+1] is not guaranteed to be
// on the same line as words[i]).
function wordsOnSameLine(a, b) {
  const heightA = (a.bbox?.y1 ?? a.cy) - (a.bbox?.y0 ?? a.cy);
  const heightB = (b.bbox?.y1 ?? b.cy) - (b.bbox?.y0 ?? b.cy);
  const tolerance = Math.max(8, Math.max(heightA, heightB) * 0.7);
  return Math.abs(a.cy - b.cy) < tolerance;
}

// ── OCR Header-Band Robustness Helpers (Stage A) ─────────────────
// Pure extraction of the day/time-token detection loop that
// reconstructTimetable2DGrid already used inline. Identical behavior --
// operates on whatever already-mapped `words` array the caller passes in,
// so reference-equality against that same array (used later for
// headerWordSet exclusion) is preserved when called from
// reconstructTimetable2DGrid itself.
function detectDayAndTimeTokens(words) {
  const dayTokens = [];
  const timeTokens = [];

  for (let i = 0; i < words.length; i++) {
    const w = words[i];
    const cleanWord = w.text.toLowerCase().replace(/[^a-z]/g, '');
    const stdDay = standardizeTimetableDay(cleanWord);
    if (stdDay && (cleanWord.length >= 3 || ['mon','tue','wed','thu','fri','sat'].includes(cleanWord))) {
      dayTokens.push({ word: w, stdDay, cx: w.cx, cy: w.cy });
      continue;
    }

    // Check single word or multi-word window for time range
    const timeWin1 = normalizeTimetableTime(w.text);
    if (timeWin1.isValid) {
      // A number that's already valid alone (e.g. "10:00") still commonly
      // has its own trailing "AM"/"PM" as a SEPARATE OCR word right after
      // it. If left dangling here, that bare meridiem word would fall
      // through to the NEXT loop iteration and could wrongly pair forward
      // with an unrelated neighboring column's number instead (real risk on
      // a tightly-packed multi-column header row: "10:00" "AM" "11:00" "AM"
      // side by side, where "AM" belongs to "10:00", not to "11:00").
      // Consume it now as this token's own meridiem suffix whenever it's
      // genuinely just "am"/"pm" on the same line, so nothing is left for
      // a later column to accidentally absorb.
      let token = { words: [w], timeNorm: timeWin1, cx: w.cx, cy: w.cy };
      if (i < words.length - 1 && wordsOnSameLine(w, words[i+1]) && /^(am|pm)$/i.test(words[i+1].text.trim())) {
        const paired = normalizeTimetableTime(`${w.text} ${words[i+1].text}`);
        if (paired.isValid) {
          token = {
            words: [w, words[i+1]],
            timeNorm: paired,
            cx: (w.cx + words[i+1].cx) / 2,
            cy: (w.cy + words[i+1].cy) / 2
          };
          i++;
        }
      }
      timeTokens.push(token);
    } else if (i < words.length - 1 && wordsOnSameLine(w, words[i+1])) {
      const pairText = `${w.text} ${words[i+1].text}`;
      const timeWin2 = normalizeTimetableTime(pairText);
      if (timeWin2.isValid) {
        const cx = (w.cx + words[i+1].cx) / 2;
        const cy = (w.cy + words[i+1].cy) / 2;
        timeTokens.push({ words: [w, words[i+1]], timeNorm: timeWin2, cx, cy });
        i++;
      } else if (i < words.length - 2 && wordsOnSameLine(w, words[i+2])) {
        const tripText = `${w.text} ${words[i+1].text} ${words[i+2].text}`;
        const timeWin3 = normalizeTimetableTime(tripText);
        if (timeWin3.isValid) {
          const cx = (w.cx + words[i+2].cx) / 2;
          const cy = (w.cy + words[i+2].cy) / 2;
          timeTokens.push({ words: [w, words[i+1], words[i+2]], timeNorm: timeWin3, cx, cy });
          i += 2;
        }
      }
    }
  }

  return { dayTokens, timeTokens };
}

// Real printed timetables commonly split a single period's start and end
// time across two separate physical header rows/lines instead of one
// "10:00 - 11:00" range on a single line (real evidence: an MGM University-
// style grid printing "10:00 AM" then "11:00 AM" as two stacked rows under
// the same period-number column). detectDayAndTimeTokens's single-timestamp
// branch treats EACH of those independently, synthesizing its own
// default-duration end time for both -- so a 6-period timetable like that
// produces ~12 bogus, overlapping "columns" instead of 6 real ones, which
// then corrupts every downstream cell-to-time-slot mapping.
//
// This merges pairs of such not-yet-a-real-range tokens (isRangeMatch ===
// false) that sit in the same column/row of the header (close together on
// the axis perpendicular to `primaryAxis`) but on two different header
// lines (spread apart along `primaryAxis`) into one token carrying the
// EARLIER one's start time and the LATER one's start time as the real end
// -- not either token's own synthesized default. Already-valid range
// tokens (isRangeMatch === true, e.g. a clean single-line "10:00 - 11:00")
// are never touched. `primaryAxis` is 'y' for Layout A (times spread
// horizontally as columns, so a split pair is stacked vertically) and 'x'
// for Layout B (times spread vertically as rows, so a split pair sits
// side-by-side horizontally).
function mergeSplitHeaderTimeTokens(timeTokens, primaryAxis) {
  if (!timeTokens || timeTokens.length < 2) return timeTokens || [];

  const primaryOf = (t) => primaryAxis === 'y' ? t.cy : t.cx;
  const crossOf = (t) => primaryAxis === 'y' ? t.cx : t.cy;
  const tokenExtent = (t) => {
    const vals = t.words.flatMap(w => primaryAxis === 'y' ? [w.bbox.y0, w.bbox.y1] : [w.bbox.x0, w.bbox.x1]);
    return Math.max(...vals) - Math.min(...vals);
  };

  const candidates = timeTokens.filter(t => t.timeNorm && t.timeNorm.isRangeMatch === false);
  if (candidates.length < 2) return timeTokens;

  const medianExtent = candidates
    .map(tokenExtent)
    .sort((a, b) => a - b)[Math.floor(candidates.length / 2)] || 20;

  const used = new Set();
  const merged = [];

  for (let i = 0; i < timeTokens.length; i++) {
    if (used.has(i)) continue;
    const a = timeTokens[i];
    if (!a.timeNorm || a.timeNorm.isRangeMatch !== false) { merged.push(a); continue; }

    let bestJ = -1, bestPrimaryGap = Infinity;
    for (let j = 0; j < timeTokens.length; j++) {
      if (j === i || used.has(j)) continue;
      const b = timeTokens[j];
      if (!b.timeNorm || b.timeNorm.isRangeMatch !== false) continue;
      const crossGap = Math.abs(crossOf(a) - crossOf(b));
      const primaryGap = Math.abs(primaryOf(a) - primaryOf(b));
      // Same column/row (tight cross-axis alignment), different header
      // line (a real but small gap along the primary axis) -- both scaled
      // to this header's own text size rather than a fixed pixel guess.
      if (crossGap < medianExtent * 1.5 && primaryGap > 0 && primaryGap < medianExtent * 4) {
        if (primaryGap < bestPrimaryGap) { bestPrimaryGap = primaryGap; bestJ = j; }
      }
    }

    if (bestJ !== -1) {
      const b = timeTokens[bestJ];
      const [earlier, later] = primaryOf(a) <= primaryOf(b) ? [a, b] : [b, a];
      merged.push({
        words: [...earlier.words, ...later.words],
        timeNorm: { time: earlier.timeNorm.time, end: later.timeNorm.time, isValid: true, isRangeMatch: true },
        cx: (earlier.cx + later.cx) / 2,
        cy: (earlier.cy + later.cy) / 2
      });
      used.add(i);
      used.add(bestJ);
    } else {
      merged.push(a);
      used.add(i);
    }
  }

  return merged;
}

// Maps raw Tesseract word entries {text, bbox, confidence} into the
// {text, bbox, conf, cx, cy} shape detectDayAndTimeTokens expects. Kept
// separate from reconstructTimetable2DGrid's own copy of this mapping
// (that one must stay untouched -- see note above) since this one feeds
// a completely independent word array (first-pass trigger check, and the
// header-crop re-OCR pass), with no reference-identity requirements.
function mapRawOcrWordsForDetection(rawWords) {
  return (rawWords || []).map(w => ({
    text: (w.text || '').trim(),
    bbox: w.bbox || { x0: 0, y0: 0, x1: 0, y1: 0 },
    conf: w.confidence || 0,
    cx: ((w.bbox?.x0 || 0) + (w.bbox?.x1 || 0)) / 2,
    cy: ((w.bbox?.y0 || 0) + (w.bbox?.y1 || 0)) / 2
  })).filter(w => w.text.length > 0);
}

// Crops the header band (day/time label row) out of the already-
// preprocessed image, using the topmost detected day token as the lower
// bound, upscales it, and runs one additional, isolated OCR pass over
// just that crop with PSM 6 (uniform block) -- restoring the worker's
// default PSM afterward no matter what happens. Returns recovered word
// entries (raw Tesseract shape) remapped into full-image coordinates, for
// the caller to merge onto the first pass's word list. Does not touch or
// depend on reconstructTimetable2DGrid in any way.
async function reOcrHeaderBandForTimeTokens(preprocessedDataUrl, worker, dayTokens) {
  if (!dayTokens || dayTokens.length === 0) return [];

  const topmostY0 = Math.min(...dayTokens.map(d => d.word.bbox.y0 ?? d.word.bbox?.y0 ?? Infinity));
  if (!isFinite(topmostY0)) return [];

  const cropSlackPx = 6;
  const cropBottomY = Math.round(topmostY0 + cropSlackPx);
  if (cropBottomY < 20) return [];

  const img = await new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error("Failed to load preprocessed image for header-band re-OCR"));
    image.src = preprocessedDataUrl;
  });

  const clampedBottom = Math.min(img.height, cropBottomY);
  const scale = 3;
  const canvas = document.createElement('canvas');
  canvas.width = img.width * scale;
  canvas.height = clampedBottom * scale;
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(img, 0, 0, img.width, clampedBottom, 0, 0, canvas.width, canvas.height);
  const cropDataUrl = canvas.toDataURL('image/png', 0.92);
  canvas.width = 1;
  canvas.height = 1;

  let cropResult;
  try {
    await worker.setParameters({ tessedit_pageseg_mode: '6' });
    cropResult = await worker.recognize(cropDataUrl);
  } finally {
    // Always restore the default segmentation mode so nothing leaks into
    // later scans, even if the crop recognize() call above threw.
    // Tesseract.js's own default is '6' (SINGLE_BLOCK), not native
    // Tesseract's '3' -- verified: an untouched worker's output is
    // byte-identical to PSM 6 on the test-kit scans. Restoring '3' left the
    // shared, cached worker in a different, worse mode for every later scan
    // in the session (re-scans, attendance scans): on the SY-AIDS scan PSM 3
    // found 4 time labels vs 12 at PSM 6.
    await worker.setParameters({ tessedit_pageseg_mode: '6' });
  }

  const cropWords = mapRawOcrWordsForDetection(cropResult?.data?.words);
  const { timeTokens: cropTimeTokens } = detectDayAndTimeTokens(cropWords);

  // Re-express each recovered token as ONE clean, self-contained range
  // string (e.g. "10:00 - 11:00"), not its raw constituent word(s). This
  // matters: detectDayAndTimeTokens's windowing checks a word's own text
  // first and only looks ahead at neighbors if that fails. A clean,
  // already-valid single token always matches on that first check and
  // never triggers a lookahead into whatever real word ends up next to
  // it once merged -- so it can't get accidentally absorbed into (or
  // accidentally absorb) unrelated neighboring content the way raw,
  // fragment-level words could.
  const recovered = [];
  cropTimeTokens.forEach(t => {
    const x0 = Math.min(...t.words.map(cw => cw.bbox.x0)) / scale;
    const y0 = Math.min(...t.words.map(cw => cw.bbox.y0)) / scale;
    const x1 = Math.max(...t.words.map(cw => cw.bbox.x1)) / scale;
    const y1 = Math.max(...t.words.map(cw => cw.bbox.y1)) / scale;
    const avgConf = t.words.reduce((sum, cw) => sum + cw.conf, 0) / t.words.length;
    recovered.push({
      text: `${t.timeNorm.time} - ${t.timeNorm.end}`,
      bbox: { x0, y0, x1, y1 },
      confidence: avgConf
    });
  });
  return recovered;
}

// True when a word's own center point falls inside a region's bbox --
// used to remove exactly the original (low-confidence) words a targeted
// cell re-OCR is about to replace, without relying on object identity
// (the reconstructor maps OCR words into its own new objects, so
// reference equality against the raw ocrResult.data.words array doesn't
// hold).
function isBboxInsideRegion(wordBbox, regionBbox) {
  if (!wordBbox || !regionBbox) return false;
  const cx = (wordBbox.x0 + wordBbox.x1) / 2;
  const cy = (wordBbox.y0 + wordBbox.y1) / 2;
  return cx >= regionBbox.x0 && cx <= regionBbox.x1 && cy >= regionBbox.y0 && cy <= regionBbox.y1;
}

// Generic targeted re-OCR of an arbitrary, already-known cell region.
// Unlike a naive whole-row or whole-line crop, the region here always
// comes from the real 2D grid clustering itself (reconstructTimetable2DGrid's
// own cluster.bbox), so it's already properly bounded to ONE cell and
// never spans multiple side-by-side columns -- empirically, cropping
// across column borders badly confuses OCR (border strokes read as
// garbage text, columns' text interleaved), while a single cell-sized
// crop upscaled 2x with PSM 6 (uniform block) reliably recovers dense,
// multi-line body text that a whole-image single pass garbles. Always
// restores the worker's default PSM afterward even if recognize() itself
// throws. Returns recovered words remapped into full-image coordinates.
async function reOcrCellRegion(preprocessedDataUrl, worker, bboxFullImage) {
  const PAD = 6;
  const SCALE = 2;

  const img = await new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error("Failed to load preprocessed image for cell re-OCR"));
    image.src = preprocessedDataUrl;
  });

  const x0 = Math.max(0, Math.floor(bboxFullImage.x0 - PAD));
  const y0 = Math.max(0, Math.floor(bboxFullImage.y0 - PAD));
  const x1 = Math.min(img.width, Math.ceil(bboxFullImage.x1 + PAD));
  const y1 = Math.min(img.height, Math.ceil(bboxFullImage.y1 + PAD));
  const cropW = x1 - x0;
  const cropH = y1 - y0;
  if (cropW < 10 || cropH < 10) return [];

  const canvas = document.createElement('canvas');
  canvas.width = cropW * SCALE;
  canvas.height = cropH * SCALE;
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(img, x0, y0, cropW, cropH, 0, 0, canvas.width, canvas.height);
  const cropDataUrl = canvas.toDataURL('image/png', 0.92);
  canvas.width = 1;
  canvas.height = 1;

  let cropResult;
  try {
    await worker.setParameters({ tessedit_pageseg_mode: '6' });
    cropResult = await worker.recognize(cropDataUrl);
  } finally {
    // Always restore the default segmentation mode so nothing leaks into
    // later scans, even if the crop recognize() call above threw.
    // Tesseract.js's own default is '6' (SINGLE_BLOCK), not native
    // Tesseract's '3' -- verified: an untouched worker's output is
    // byte-identical to PSM 6 on the test-kit scans. Restoring '3' left the
    // shared, cached worker in a different, worse mode for every later scan
    // in the session (re-scans, attendance scans): on the SY-AIDS scan PSM 3
    // found 4 time labels vs 12 at PSM 6.
    await worker.setParameters({ tessedit_pageseg_mode: '6' });
  }

  return (cropResult?.data?.words || [])
    .map(w => ({
      text: w.text,
      bbox: {
        x0: (w.bbox.x0 / SCALE) + x0,
        y0: (w.bbox.y0 / SCALE) + y0,
        x1: (w.bbox.x1 / SCALE) + x0,
        y1: (w.bbox.y1 / SCALE) + y0
      },
      confidence: w.confidence
    }))
    .filter(w => (w.text || '').trim().length > 0);
}

// A real printed timetable sometimes has one cell visually merged across
// two (or more) consecutive period columns -- e.g. a single "Community
// Engagement" block spanning periods 3 and 4 with no divider inside it.
// When that merged cell's text is unusually dense (several batch codes and
// a teacher code crammed together), the column-splitting heuristics above
// can occasionally cut it into two side-by-side clusters instead of
// recognizing it as one span, and each half independently resolves through
// the SAME normalization step -- so a single real class can come out as
// two adjacent rows that agree on subject/teacher/room/batches but each
// only cover one period. This collapses exactly that shape back into one
// row per day, spanning the full contiguous time range, rather than
// leaving a real class duplicated across periods. It never touches rows
// that differ in subject, teacher, room, type, or batches -- including two
// genuinely separate classes that happen to share a subject name but have
// a different teacher/room -- so it only ever removes a duplicate, never a
// real distinct class.
function mergeAdjacentDuplicatePeriods(schedule) {
  if (!schedule || schedule.length < 2) return schedule || [];

  const sameCell = (a, b) => {
    const norm = s => (s || '').trim().toLowerCase();
    if (norm(a.subject) !== norm(b.subject)) return false;
    if (norm(a.teacher) !== norm(b.teacher)) return false;
    if (norm(a.room) !== norm(b.room)) return false;
    if ((a.type || 'lecture') !== (b.type || 'lecture')) return false;
    const batchKey = item => (item.batches || []).slice().sort().join(',');
    return batchKey(a) === batchKey(b);
  };

  const dayOrder = [];
  const byDay = new Map();
  schedule.forEach(item => {
    if (!byDay.has(item.day)) { byDay.set(item.day, []); dayOrder.push(item.day); }
    byDay.get(item.day).push(item);
  });

  const merged = [];
  dayOrder.forEach(day => {
    const items = byDay.get(day).slice().sort((a, b) => timeToMinutes(a.time) - timeToMinutes(b.time));
    let i = 0;
    while (i < items.length) {
      let curr = items[i];
      let j = i + 1;
      while (j < items.length && items[j].time === curr.end && sameCell(curr, items[j])) {
        curr = {
          ...curr,
          end: items[j].end,
          endSlot: items[j].endSlot !== undefined ? items[j].endSlot : curr.endSlot,
          isUncertain: !!(curr.isUncertain || items[j].isUncertain),
          subjectInferred: !!(curr.subjectInferred || items[j].subjectInferred)
        };
        j++;
      }
      merged.push(curr);
      i = j;
    }
  });
  return merged;
}

// ── Table-Aware 2D Grid Reconstructor ────────────────────────────
function reconstructTimetable2DGrid(ocrData, existingSubjects = [], facultyLegend = {}, subjectLegend = {}) {
  if (!ocrData || !ocrData.words || ocrData.words.length === 0) {
    return { schedule: [], confidence: 0, ambiguous: true };
  }

  let words = ocrData.words.map(w => ({
    text: (w.text || '').trim(),
    bbox: w.bbox || { x0: 0, y0: 0, x1: 0, y1: 0 },
    conf: w.confidence || 0,
    cx: ((w.bbox?.x0 || 0) + (w.bbox?.x1 || 0)) / 2,
    cy: ((w.bbox?.y0 || 0) + (w.bbox?.y1 || 0)) / 2
  })).filter(w => w.text.length > 0);

  // Guard against footer/legend-table content (e.g. a "Subject /
  // Abbrivation / Lab / Hall No." or "Name of the faculty" key printed
  // below the grid) bleeding into whichever day happens to sit physically
  // last. Real evidence: on a compact layout, such a table can sit close
  // enough beneath the grid that its header row falls inside the last
  // day's otherwise-unbounded lower band (which only extends a fixed
  // +70px past that day's own row), fabricating a "row" out of words that
  // are actually legend/footer text. This only ever removes words when at
  // least one distinctive legend-header marker is legible in the OCR
  // output, and never touches anything above it.
  const LEGEND_BOUNDARY_MARKERS = ['abbrivat', 'abbreviat', 'facultyname', 'subjectname', 'nameofthefacult', 'nameoffacult'];
  let legendBoundaryY = Infinity;
  words.forEach(w => {
    const cleanW = w.text.toLowerCase().replace(/[^a-z]/g, '');
    if (cleanW.length >= 6 && LEGEND_BOUNDARY_MARKERS.some(m => cleanW.includes(m))) {
      legendBoundaryY = Math.min(legendBoundaryY, w.bbox.y0);
    }
  });
  // Also catch the marker when it's spread across separate words on one
  // line (e.g. "Name of the facul[ty]", OCR-truncated on a real photo) --
  // the per-word check above only matches a single fused token, but a
  // less-compact layout OCRs each word of the legend header separately.
  const legendGuardLines = groupWordsIntoLines(words);
  legendGuardLines.forEach(line => {
    const sorted = [...line].sort((a, b) => a.bbox.x0 - b.bbox.x0);
    const cleanWords = sorted.map(w => w.text.toLowerCase().replace(/[^a-z]/g, ''));
    const nameIdx = cleanWords.findIndex((cw, i) => cw === 'name' && cleanWords.slice(i + 1, i + 4).some(w2 => w2.length >= 4 && w2.startsWith('facu')));
    if (nameIdx !== -1) {
      legendBoundaryY = Math.min(legendBoundaryY, sorted[nameIdx].bbox.y0);
    }
  });
  if (isFinite(legendBoundaryY)) {
    words = words.filter(w => w.cy < legendBoundaryY);
  }

  // 1. Identify Day Tokens and Time Tokens with coordinates
  const tokenDetection = detectDayAndTimeTokens(words);
  let { timeTokens } = tokenDetection;

  // De-duplicate and confidence-gate day tokens before anything below uses
  // them. detectDayAndTimeTokens matches ANY word in the whole photo that
  // reads as a day abbreviation, with no requirement that it actually sits
  // in the header row/column -- so a garbled body-cell word (a room code,
  // a teacher's initials, anything OCR misreads as e.g. "Tue" under
  // real-world lighting/glare/skew) is indistinguishable from a genuine
  // header label at this point. Left unfiltered, that spurious extra token
  // gets its own day-band interval below and either splits a real day's
  // row/column in two or pulls a neighboring day's content under the wrong
  // label -- this is the "Tuesday shows Monday's classes plus random other
  // classes" bug. A genuinely printed day header should read with
  // reasonable confidence (40 is the same floor Stage D above already
  // trusts for a recovered day label), and a real timetable prints each
  // day exactly once, so keeping only the single highest-confidence
  // candidate per weekday removes both a stray low-confidence misread and
  // a rarer same-day double-read, without needing to know the grid's
  // orientation yet.
  const bestDayTokenByDay = new Map();
  tokenDetection.dayTokens.forEach(t => {
    if ((t.word.conf || 0) <= 40) return;
    const existing = bestDayTokenByDay.get(t.stdDay);
    if (!existing || (t.word.conf || 0) > (existing.word.conf || 0)) {
      bestDayTokenByDay.set(t.stdDay, t);
    }
  });
  const dayTokens = Array.from(bestDayTokenByDay.values());

  // 2. Detect Orientation:
  // Layout A: Rows = Days (stacked vertically), Columns = Times (spread horizontally)
  // Layout B: Rows = Times (stacked vertically), Columns = Days (spread horizontally)
  const dayXSpread = dayTokens.length > 1 ? Math.max(...dayTokens.map(d => d.cx)) - Math.min(...dayTokens.map(d => d.cx)) : 0;
  const dayYSpread = dayTokens.length > 1 ? Math.max(...dayTokens.map(d => d.cy)) - Math.min(...dayTokens.map(d => d.cy)) : 0;
  const timeXSpread = timeTokens.length > 1 ? Math.max(...timeTokens.map(t => t.cx)) - Math.min(...timeTokens.map(t => t.cx)) : 0;
  const timeYSpread = timeTokens.length > 1 ? Math.max(...timeTokens.map(t => t.cy)) - Math.min(...timeTokens.map(t => t.cy)) : 0;

  let isLayoutA = true;
  let isLayoutB = false;

  if (dayXSpread > dayYSpread * 1.5 && timeYSpread >= timeXSpread) {
    isLayoutA = false;
    isLayoutB = true;
  } else if (dayYSpread >= dayXSpread) {
    isLayoutA = true;
    isLayoutB = false;
  }

  const schedule = [];
  const lowConfidenceClusters = [];
  // Below this average per-cluster OCR confidence, a cell is more likely
  // garbled than genuinely simple -- flagged for a later targeted re-OCR
  // retry (see reOcrCellRegion / extractTimetableFromImage) rather than
  // silently trusted or silently dropped.
  const CELL_RETRY_CONFIDENCE_THRESHOLD = 55;

  if (isLayoutA && dayTokens.length >= 1 && timeTokens.length >= 1) {
    // Layout A: Days are row headers along left, Times are column headers along top
    dayTokens.sort((a, b) => a.cy - b.cy);
    timeTokens = mergeSplitHeaderTimeTokens(timeTokens, 'y');
    timeTokens.sort((a, b) => a.cx - b.cx);

    const dayIntervals = [];
    for (let i = 0; i < dayTokens.length; i++) {
      const curr = dayTokens[i];
      const prevY = i > 0 ? (dayTokens[i - 1].cy + curr.cy) / 2 : curr.cy - 40;
      const nextY = i < dayTokens.length - 1 ? (curr.cy + dayTokens[i + 1].cy) / 2 : curr.cy + 70;
      dayIntervals.push({ day: curr.stdDay, minY: prevY, maxY: nextY });
    }

    const timeIntervals = [];
    for (let i = 0; i < timeTokens.length; i++) {
      const curr = timeTokens[i];
      const prevX = i > 0 ? (timeTokens[i - 1].cx + curr.cx) / 2 : curr.cx - 60;
      const nextX = i < timeTokens.length - 1 ? (curr.cx + timeTokens[i + 1].cx) / 2 : curr.cx + 90;
      timeIntervals.push({ timeNorm: curr.timeNorm, minX: prevX, maxX: nextX });
    }

    const headerWordSet = new Set([...dayTokens.map(d => d.word), ...timeTokens.flatMap(t => t.words)]);

    // Narrowest column width sizes the horizontal gap threshold that
    // separates genuinely distinct side-by-side cells from a single
    // label's own word spacing -- scales with the actual scanned table
    // instead of a fixed pixel guess. Uses the MINIMUM (not median/average)
    // column width deliberately: a real timetable's Recess columns make
    // period-to-period spacing uneven across one header row (adjacent
    // periods sit close together; a period separated from its neighbor by
    // a Recess column sits much farther apart), so a median/average width
    // gets pulled up by those wider Recess-adjacent gaps and ends up too
    // generous for the genuinely-adjacent, no-recess-between-them columns
    // -- letting two short, centered labels like "DEMP" and "DS" in
    // neighboring narrow columns wrongly merge into one cell.
    const colWidthsA = timeIntervals.map(t => t.maxX - t.minX).filter(w => w > 0);
    const narrowestColWidthA = colWidthsA.length ? Math.min(...colWidthsA) : 80;
    const xGapThresholdA = Math.max(18, narrowestColWidthA * 0.55);

    dayIntervals.forEach(dInt => {
      const dayBandWords = words.filter(w => {
        if (headerWordSet.has(w)) return false;
        return w.cy >= dInt.minY && w.cy < dInt.maxY;
      });
      if (dayBandWords.length === 0) return;

      // 1. Group into physical text lines (orientation-independent).
      const linesA = groupWordsIntoLines(dayBandWords);
      // 2. Split each line into horizontal segments on a real gap.
      const segmentsA = linesA.flatMap(line => splitLineByXGap(line, xGapThresholdA));
      // 3. Merge segments across lines into full cell clusters when their
      //    X-ranges substantially overlap.
      const clustersA = mergeSegmentsByAxisOverlap(segmentsA, 'x', 0.4);

      clustersA.forEach(cluster => {
        const cellWords = [...cluster.words].sort((a, b) => a.bbox.y0 === b.bbox.y0 ? a.bbox.x0 - b.bbox.x0 : a.bbox.y0 - b.bbox.y0);
        const cellRaw = cellWords.map(w => w.text).join(' ');
        if (cellRaw.length < 2 || /^(break|lunch|recess|tea|interval)$/i.test(cellRaw.trim())) return;

        const avgConfA = cellWords.reduce((sum, w) => sum + w.conf, 0) / cellWords.length;
        if (avgConfA < CELL_RETRY_CONFIDENCE_THRESHOLD) {
          lowConfidenceClusters.push({ day: dInt.day, bbox: cluster.bbox });
        }

        const span = computeIntervalSpan(cluster.bbox, timeIntervals, 'x', 0.35);
        if (!span) return;

        const { fragments: plusFragments, wasSplit: plusWasSplit } = splitMultiSessionCellText(cellRaw);
        let fragments = plusFragments;
        let lineSplitFallback = false;
        if (!plusWasSplit && !cellRaw.includes('+')) {
          const lineSplit = trySplitByIndependentLines(cluster.words, existingSubjects);
          if (lineSplit.wasSplit) {
            fragments = lineSplit.fragments;
            lineSplitFallback = true;
          }
        }
        const guardrailDeclinedSplit = cellRaw.includes('+') && !plusWasSplit;

        fragments.forEach(fragmentText => {
          const norm = normalizeSubjectIdentity(fragmentText, existingSubjects, null, facultyLegend, subjectLegend);
          if (!norm.canonicalName || TIMETABLE_JUNK_TOKENS.has(norm.canonicalName.toLowerCase())) return;

          const isUncertainRow = !norm.canonicalName
            || span.borderline
            || guardrailDeclinedSplit
            || lineSplitFallback
            || looksLikeUnresolvedCodeResidue(norm.canonicalName)
            // A fuzzy match means the raw OCR text didn't cleanly resolve to
            // any known subject and normalizeSubjectIdentity substituted the
            // closest EXISTING subject name it could find instead -- a real
            // college timetable's dense, multi-batch cells (e.g. "Community
            // Engagement- AI-A2,B2,C2,D2(SDJ)") are exactly the kind of text
            // that garbles under real-world OCR, and a garbled fragment can
            // land closest to a totally unrelated existing subject. That
            // guess was previously trusted at the same confidence as a clean
            // exact match, so a wrong substitution could sail straight into
            // the saved timetable unflagged. Now it's always surfaced in the
            // preview modal for the student to confirm or fix before saving.
            || !!norm.fuzzyMatchApplied;

          schedule.push({
            day: dInt.day,
            time: span.startInterval.timeNorm.time,
            end: span.endInterval.timeNorm.end,
            startSlot: span.startIdx,
            endSlot: span.endIdx,
            durationInSlots: span.durationInSlots,
            subject: norm.canonicalName,
            code: norm.canonicalCode,
            room: norm.room,
            teacher: norm.teacher,
            type: norm.classType,
            batches: norm.batches,
            isUncertain: isUncertainRow,
            subjectInferred: !!(norm.resolvedFromScanLegend || norm.digitConfusionCorrected)
          });
        });
      });
    });
  } else if (isLayoutB && dayTokens.length >= 1 && timeTokens.length >= 1) {
    // Layout B: Days are column headers along top, Times are row headers along left
    dayTokens.sort((a, b) => a.cx - b.cx);
    timeTokens = mergeSplitHeaderTimeTokens(timeTokens, 'x');
    timeTokens.sort((a, b) => a.cy - b.cy);

    const dayIntervals = [];
    for (let i = 0; i < dayTokens.length; i++) {
      const curr = dayTokens[i];
      const prevX = i > 0 ? (dayTokens[i - 1].cx + curr.cx) / 2 : curr.cx - 60;
      const nextX = i < dayTokens.length - 1 ? (curr.cx + dayTokens[i + 1].cx) / 2 : curr.cx + 90;
      dayIntervals.push({ day: curr.stdDay, minX: prevX, maxX: nextX });
    }

    const timeIntervals = [];
    for (let i = 0; i < timeTokens.length; i++) {
      const curr = timeTokens[i];
      const prevY = i > 0 ? (timeTokens[i - 1].cy + curr.cy) / 2 : curr.cy - 40;
      const nextY = i < timeTokens.length - 1 ? (curr.cy + timeTokens[i + 1].cy) / 2 : curr.cy + 70;
      timeIntervals.push({ timeNorm: curr.timeNorm, minY: prevY, maxY: nextY });
    }

    const headerWordSet = new Set([...dayTokens.map(d => d.word), ...timeTokens.flatMap(t => t.words)]);

    // Narrowest row height sizes the vertical gap threshold that separates
    // genuinely distinct stacked cells from one session's own stacked
    // subject/teacher/room lines. Uses the MINIMUM (not median) row height
    // for the same reason as Layout A's xGapThresholdA above: a Recess row
    // makes period-to-period spacing uneven, so a median gets pulled up by
    // the wider Recess-adjacent gaps and becomes too generous for
    // genuinely-adjacent rows.
    const rowHeightsB = timeIntervals.map(t => t.maxY - t.minY).filter(h => h > 0);
    const narrowestRowHeightB = rowHeightsB.length ? Math.min(...rowHeightsB) : 60;
    const yGapThresholdB = Math.max(14, narrowestRowHeightB * 0.5);

    dayIntervals.forEach(dInt => {
      const dayBandWords = words.filter(w => {
        if (headerWordSet.has(w)) return false;
        return w.cx >= dInt.minX && w.cx < dInt.maxX;
      });
      if (dayBandWords.length === 0) return;

      // Physical text lines (same orientation-independent grouping as
      // Layout A above). In this orientation the day-band is already a
      // narrow column, so distinct cells are separated vertically, not
      // horizontally: merge consecutive lines into one cluster when the
      // gap between them is small, start a new cluster otherwise.
      const linesB = groupWordsIntoLines(dayBandWords);
      const clustersB = mergeLinesByYGap(linesB, yGapThresholdB);

      clustersB.forEach(cluster => {
        const cellWords = [...cluster.words].sort((a, b) => a.bbox.y0 === b.bbox.y0 ? a.bbox.x0 - b.bbox.x0 : a.bbox.y0 - b.bbox.y0);
        const cellRaw = cellWords.map(w => w.text).join(' ');
        if (cellRaw.length < 2 || /^(break|lunch|recess|tea|interval)$/i.test(cellRaw.trim())) return;

        const avgConfB = cellWords.reduce((sum, w) => sum + w.conf, 0) / cellWords.length;
        if (avgConfB < CELL_RETRY_CONFIDENCE_THRESHOLD) {
          lowConfidenceClusters.push({ day: dInt.day, bbox: cluster.bbox });
        }

        const span = computeIntervalSpan(cluster.bbox, timeIntervals, 'y', 0.35);
        if (!span) return;

        const { fragments: plusFragments, wasSplit: plusWasSplit } = splitMultiSessionCellText(cellRaw);
        let fragments = plusFragments;
        let lineSplitFallback = false;
        if (!plusWasSplit && !cellRaw.includes('+')) {
          const lineSplit = trySplitByIndependentLines(cluster.words, existingSubjects);
          if (lineSplit.wasSplit) {
            fragments = lineSplit.fragments;
            lineSplitFallback = true;
          }
        }
        const guardrailDeclinedSplit = cellRaw.includes('+') && !plusWasSplit;

        fragments.forEach(fragmentText => {
          const norm = normalizeSubjectIdentity(fragmentText, existingSubjects, null, facultyLegend, subjectLegend);
          if (!norm.canonicalName || TIMETABLE_JUNK_TOKENS.has(norm.canonicalName.toLowerCase())) return;

          const isUncertainRow = !norm.canonicalName
            || span.borderline
            || guardrailDeclinedSplit
            || lineSplitFallback
            || looksLikeUnresolvedCodeResidue(norm.canonicalName)
            // A fuzzy match means the raw OCR text didn't cleanly resolve to
            // any known subject and normalizeSubjectIdentity substituted the
            // closest EXISTING subject name it could find instead -- a real
            // college timetable's dense, multi-batch cells (e.g. "Community
            // Engagement- AI-A2,B2,C2,D2(SDJ)") are exactly the kind of text
            // that garbles under real-world OCR, and a garbled fragment can
            // land closest to a totally unrelated existing subject. That
            // guess was previously trusted at the same confidence as a clean
            // exact match, so a wrong substitution could sail straight into
            // the saved timetable unflagged. Now it's always surfaced in the
            // preview modal for the student to confirm or fix before saving.
            || !!norm.fuzzyMatchApplied;

          schedule.push({
            day: dInt.day,
            time: span.startInterval.timeNorm.time,
            end: span.endInterval.timeNorm.end,
            startSlot: span.startIdx,
            endSlot: span.endIdx,
            durationInSlots: span.durationInSlots,
            subject: norm.canonicalName,
            code: norm.canonicalCode,
            room: norm.room,
            teacher: norm.teacher,
            type: norm.classType,
            batches: norm.batches,
            isUncertain: isUncertainRow,
            subjectInferred: !!(norm.resolvedFromScanLegend || norm.digitConfusionCorrected)
          });
        });
      });
    });
  }

  const dedupedSchedule = mergeAdjacentDuplicatePeriods(schedule);
  const confidence = Math.min(98, 75 + dedupedSchedule.length * 5);
  return { schedule: dedupedSchedule, confidence, ambiguous: dedupedSchedule.length === 0, lowConfidenceClusters };
}

// ── Multi-Strategy Timetable Parser (2D Grid + Geometric Rows + Text Stream) ───
function parseTimetableFromGrid(ocrData, existingSubjects = [], facultyLegend = {}, subjectLegend = {}) {
  if (!ocrData || !ocrData.words || ocrData.words.length === 0) {
    if (ocrData?.text) {
      const textFallback = parseTimetableFromTextStream(ocrData.text, existingSubjects);
      return { schedule: textFallback, confidence: textFallback.length ? 60 : 0, ambiguous: textFallback.length === 0 };
    }
    return { schedule: [], confidence: 0, ambiguous: true };
  }

  // Strategy 1: Table-Aware 2D Grid Reconstructor (Layout A & Layout B)
  try {
    const gridResult = reconstructTimetable2DGrid(ocrData, existingSubjects, facultyLegend, subjectLegend);
    if (gridResult.schedule && gridResult.schedule.length > 0) {
      return gridResult;
    }
  } catch (err) {
    console.warn("[TimetableParser] 2D grid reconstructor error, falling back to visual line clusterer:", err);
  }

  // Strategy 2: Visual Line / Card Clusterer (for list/card-based schedules)
  const words = ocrData.words.map(w => ({
    text: (w.text || '').trim(),
    bbox: w.bbox || { x0: 0, y0: 0, x1: 0, y1: 0 },
    conf: w.confidence || 0,
    cx: ((w.bbox?.x0 || 0) + (w.bbox?.x1 || 0)) / 2,
    cy: ((w.bbox?.y0 || 0) + (w.bbox?.y1 || 0)) / 2
  })).filter(w => w.text.length > 0);

  words.sort((a, b) => a.bbox.y0 - b.bbox.y0);
  const visualLines = [];
  for (const word of words) {
    let added = false;
    for (const line of visualLines) {
      const avgY0 = line.reduce((sum, w) => sum + w.bbox.y0, 0) / line.length;
      const avgY1 = line.reduce((sum, w) => sum + w.bbox.y1, 0) / line.length;
      const wordH = word.bbox.y1 - word.bbox.y0;
      const overlap = Math.max(0, Math.min(word.bbox.y1, avgY1) - Math.max(word.bbox.y0, avgY0));
      if (wordH > 0 && (overlap / wordH) > 0.42) {
        line.push(word);
        added = true;
        break;
      }
    }
    if (!added) visualLines.push([word]);
  }
  visualLines.forEach(l => l.sort((a, b) => a.bbox.x0 - b.bbox.x0));

  const dayNames = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
  const schedule = [];
  let currentDay = '';
  let foundCount = 0;

  for (const line of visualLines) {
    const lineStr = line.map(w => w.text).join(' ');
    const firstWord = (line[0]?.text || '').toLowerCase().replace(/[^a-z]/g, '');
    const matchedDay = dayNames.find(d => firstWord === d || firstWord.startsWith(d) || lineStr.toLowerCase().startsWith(d));

    if (matchedDay) {
      currentDay = standardizeTimetableDay(matchedDay);
    }

    const timeNorm = normalizeTimetableTime(lineStr);
    if (timeNorm.isValid) {
      let lineDay = currentDay;
      if (matchedDay) lineDay = standardizeTimetableDay(matchedDay);
      if (!lineDay) lineDay = 'Mon';

      const cell = cleanupTimetableDomain(lineStr, existingSubjects);
      if (!cell.isOff && cell.subject) {
        schedule.push({
          day: lineDay,
          time: timeNorm.time,
          end: timeNorm.end,
          subject: cell.subject,
          code: cell.code || '',
          room: cell.room || '',
          teacher: cell.teacher || '',
          type: cell.type || 'lecture',
          batches: cell.batches || [],
          isUncertain: cell.isUncertain
        });
        foundCount++;
      }
    }
  }

  // Strategy 3: Text stream linear extractor fallback
  if (schedule.length === 0 && ocrData.text) {
    const streamSchedule = parseTimetableFromTextStream(ocrData.text, existingSubjects);
    if (streamSchedule.length > 0) {
      return {
        schedule: streamSchedule,
        confidence: Math.min(90, 35 + streamSchedule.length * 10),
        ambiguous: false
      };
    }
  }

  const confidence = Math.min(95, 30 + foundCount * 12);
  return {
    schedule,
    confidence,
    ambiguous: schedule.length === 0 || confidence < 40
  };
}

// ── Text-Stream / Linear Schedule Extractor ────────────────────
function parseTimetableFromTextStream(rawText, existingSubjects = []) {
  if (!rawText || typeof rawText !== 'string') return [];
  const lines = rawText.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  const schedule = [];

  let currentDay = '';
  const dayRegex = /\b(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Mon|Tue|Wed|Thu|Fri|Sat)\b/i;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const dayMatch = line.match(dayRegex);

    if (dayMatch && (line.length < 25 || /^(?:day|daily|schedule)?\s*[:\-\s]*[A-Za-z]+\s*$/i.test(line))) {
      currentDay = standardizeTimetableDay(dayMatch[1]);
      continue;
    }

    const timeNorm = normalizeTimetableTime(line);
    if (timeNorm.isValid) {
      let lineDay = currentDay;
      if (dayMatch) {
        lineDay = standardizeTimetableDay(dayMatch[1]);
      }
      if (!lineDay) lineDay = 'Mon';

      const cellInfo = cleanupTimetableDomain(line, existingSubjects);
      if (cellInfo.isOff) continue;

      if (cellInfo.subject) {
        schedule.push({
          day: lineDay,
          time: timeNorm.time,
          end: timeNorm.end,
          subject: cellInfo.subject,
          code: cellInfo.code || '',
          room: cellInfo.room || '',
          teacher: cellInfo.teacher || '',
          type: cellInfo.type || 'lecture',
          batches: cellInfo.batches || [],
          isUncertain: cellInfo.isUncertain
        });
      }
    }
  }
  return schedule;
}

// True when an on-device (Tesseract) timetable row is evidently misread.
// Measured on scanner-practice-kit samples 07 and 11: rows like "c", "R R",
// "General Subject", "6102CR 6201LA CT 6103CR" (only room codes), a whole
// day's cells glued into one 25-word row, and classes at 00:10 all reached
// review unflagged. Short real codes ("DT", "OS", "MA", "OE-1") pass.
function looksLikeJunkTimetableRow(row) {
  const subject = String(row?.subject || '').trim();
  if (!subject || /^general subject$/i.test(subject)) return true;
  const hm = String(row.time || '').match(/^(\d{1,2}):(\d{2})/);
  if (hm && Number(hm[1]) < 6) return true;                                 // no classes between midnight and 6 AM
  const tokens = subject.split(/[\s,/|]+/).filter(Boolean);
  if (tokens.length > 8) return true;                                       // several cells glued together
  // Room / batch codes: 6102CR, W101, A1043, B212A, B1 (not OE-1 or EM-I).
  const isCode = t => /^(?:[A-Za-z]{0,3}\d{2,}[A-Za-z]{0,3}|[A-Za-z]\d)$/.test(t);
  const words = tokens.filter(t => !isCode(t) && /[A-Za-z]/.test(t));
  const codes = tokens.filter(isCode).length;
  if (words.join('').replace(/[^A-Za-z]/g, '').length < 2) return true;     // "c", "T1", nothing but codes
  if (codes >= 2 && codes > words.length) return true;                      // mostly room numbers
  if (words.length >= 2 && words.every(w => w.replace(/[^A-Za-z]/g, '').length === 1)) return true; // "R R"
  return false;
}

async function extractTimetableFromImage(base64Data, mimeType) {
  const existingSubjects = getSubjectList();

  updateTimetableLoadingModal("Preprocessing timetable image (adaptive contrast, scaling)...");
  const preprocessedDataUrl = await preprocessImageForOCR(base64Data, mimeType);
  
  updateTimetableLoadingModal("Scanning timetable text with local OCR...");
  const worker = await getTesseractWorker();
  const ocrResult = await worker.recognize(preprocessedDataUrl);

  // Diagnostic-only: surfaces exactly what Tesseract itself read off this
  // image, before any grid/parsing logic touches it -- the single fastest
  // way to tell "OCR read the photo badly" apart from "OCR read it fine but
  // parsing/mapping mangled it after". Cheap, console-only, no UI/behavior
  // impact; safe to leave in permanently the way the existing
  // [TesseractWorker]/[TimetableUpload] logs already are.
  console.log('[TimetableOCR] Raw Tesseract text:\n' + (ocrResult.data?.text || '(empty)'));
  console.log('[TimetableOCR] Raw word list (text @ confidence):',
    (ocrResult.data?.words || []).map(w => `"${w.text}"@${Math.round(w.confidence)}`).join('  '));

  // Parsed once, up front, from the first pass's own word list: many real
  // timetables print a "Name of the faculty" legend below the grid mapping
  // short initials (e.g. "VAK") used inside cells to the actual faculty
  // member's full name. See parseFacultyLegend's own comment for the
  // detection/parsing details -- this is deliberately independent of
  // Stage A/C/D's retries below, since the legend's physical position
  // never depends on how the grid itself gets recovered.
  const facultyLegend = parseFacultyLegend(ocrResult.data?.words);
  const subjectLegend = parseSubjectAbbreviationLegend(ocrResult.data?.words);

  // Stage A: if the first pass found day labels but essentially no usable
  // time-range tokens, retry OCR on just the header band (cropped +
  // upscaled) before handing off to the deterministic parser. Only
  // triggers on an already-failing first pass, so a normal/clean scan is
  // completely unaffected.
  try {
    const firstPassWords = mapRawOcrWordsForDetection(ocrResult.data?.words);
    const { dayTokens: firstPassDayTokens, timeTokens: firstPassTimeTokens } = detectDayAndTimeTokens(firstPassWords);
    if (firstPassDayTokens.length >= 1 && firstPassTimeTokens.length <= 1) {
      updateTimetableLoadingModal("Re-scanning header row for class times...");
      const recoveredWords = await reOcrHeaderBandForTimeTokens(preprocessedDataUrl, worker, firstPassDayTokens);
      if (recoveredWords.length > 0) {
        // Prepended, not appended: a clean recovered token never looks
        // ahead past itself once it self-validates (see note above), so
        // placing it before the rest of the words means nothing already
        // in the array can accidentally window-match into it either.
        ocrResult.data.words = [...recoveredWords, ...(ocrResult.data.words || [])];
      }
    }
  } catch (err) {
    console.warn("[TimetableParser] Header-band retry OCR failed, continuing with first-pass data:", err);
  }

  // Stage D: if at least two day labels were found but the topmost one
  // isn't Monday and no Monday token exists anywhere yet, a leading row
  // may have been swallowed entirely -- this happens on real photos where
  // Monday's row sits with no visual gap against the header band above it.
  // A full-width crop of that band (like Stage A's) drags in the whole
  // multi-column numeric header table alongside the lone day label and
  // confuses PSM 6 into producing nothing usable there (verified
  // empirically); cropping just the day-label column's own width for an
  // estimated one-row-height band above the topmost known day avoids that
  // and reliably recovers the label. Requires >=2 day tokens so a row
  // spacing can be estimated; degrades to a no-op otherwise.
  //
  // Generalized from "missing Monday only": the first pass can drop ANY
  // day label, not just a leading one. Verified on the real SY-AIDS
  // test-kit scan: PSM 6 read WEDNESD/THURSDAY/FRIDAY/SATURDAY but dropped
  // both MONDAY and TUESDAY (each sits vertically centred between two
  // lines of cell text), so the old one-row band above Wednesday only ever
  // saw TUESDAY -- which it ignored for not being Monday -- and both rows'
  // classes were lost. Now the whole day-label column is re-read, spanning
  // as many rows above the topmost / below the bottommost known day as
  // weekdays could be missing there, and every weekday not already found is
  // added back, subject to the same >40 confidence bar plus a weekday-order
  // check against the days already found (so a stray substring match in
  // the wrong place can't be adopted).
  try {
    const WEEK = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const postHeaderWords = mapRawOcrWordsForDetection(ocrResult.data?.words);
    const { dayTokens: postHeaderDayTokens } = detectDayAndTimeTokens(postHeaderWords);
    const known = new Map();
    postHeaderDayTokens.forEach(d => {
      const prev = known.get(d.stdDay);
      if (!prev || (d.word.conf || 0) > (prev.word.conf || 0)) known.set(d.stdDay, d);
    });
    // Only days missing BEFORE the last day found (leading or middle gaps)
    // trigger this. A missing trailing day (e.g. Saturday on a Mon-Fri
    // timetable) is ambiguous and never guessed at, so a normal scan pays
    // no extra OCR pass.
    const bottomIdx = Math.max(...[...known.keys()].map(d => WEEK.indexOf(d)));
    const missingDays = WEEK.filter((d, i) => !known.has(d) && i < bottomIdx);
    if (known.size >= 2 && missingDays.length > 0) {
      const sortedDays = [...known.values()].sort((a, b) => a.cy - b.cy);
      const ySpread = sortedDays[sortedDays.length - 1].cy - sortedDays[0].cy;
      const xSpread = Math.max(...sortedDays.map(d => d.cx)) - Math.min(...sortedDays.map(d => d.cx));
      const gaps = sortedDays.slice(1).map((d, i) => d.cy - sortedDays[i].cy).filter(g => g > 10);
      const rowSpacing = gaps.length ? Math.min(...gaps) : 0;
      // Days stacked vertically (Layout A) only -- same effective condition
      // the old version had via its rowSpacing > 10 guard.
      if (rowSpacing > 10 && ySpread > xSpread) {
        const topmost = sortedDays[0];
        const bottommost = sortedDays[sortedDays.length - 1];
        const rowsAbove = Math.max(0, WEEK.indexOf(topmost.stdDay));
        const dayLabelWidth = Math.max(...sortedDays.map(d => d.word.bbox.x1));
        const candidateBbox = {
          x0: 0,
          y0: Math.max(0, topmost.word.bbox.y0 - rowsAbove * rowSpacing - 20),
          x1: dayLabelWidth + 40,
          y1: bottommost.word.bbox.y1 + 20
        };
        if (candidateBbox.y1 > candidateBbox.y0) {
          updateTimetableLoadingModal("Re-scanning the day column for missing day rows...");
          // A full-page sparse-text (PSM 11) pass, filtered to the day-label
          // column window below -- NOT a cropped re-OCR. Verified on the
          // real SY-AIDS scan: a crop of that column, at any bounds or PSM,
          // read only "SATURDAY" (the boxed cells read as non-text once
          // isolated and upscaled), while the full-page PSM 11 pass read all
          // six labels at their true positions (MONDAY@96, TUESDAY@96...).
          let sparseWords = [];
          try {
            await worker.setParameters({ tessedit_pageseg_mode: '11' });
            const sparse = await worker.recognize(preprocessedDataUrl);
            sparseWords = sparse?.data?.words || [];
          } finally {
            await worker.setParameters({ tessedit_pageseg_mode: '6' });
          }
          const recoveredDayWords = sparseWords
            .map(w => ({ text: w.text, bbox: w.bbox, confidence: w.confidence }))
            .filter(w => w.bbox && isBboxInsideRegion(w.bbox, candidateBbox));
          const bestRecovered = new Map();
          recoveredDayWords.forEach(w => {
            const cleanWord = (w.text || '').toLowerCase().replace(/[^a-z]/g, '');
            const std = cleanWord.length >= 3 ? standardizeTimetableDay(cleanWord) : '';
            if (!std || !missingDays.includes(std) || (w.confidence || 0) <= 40) return;
            const cy = ((w.bbox?.y0 || 0) + (w.bbox?.y1 || 0)) / 2;
            const orderOk = [...known.values()].every(k => {
              const ki = WEEK.indexOf(k.stdDay), si = WEEK.indexOf(std);
              return ki < si ? k.cy < cy : k.cy > cy;
            });
            if (!orderOk) return;
            const prev = bestRecovered.get(std);
            if (!prev || (w.confidence || 0) > (prev.confidence || 0)) bestRecovered.set(std, w);
          });
          if (bestRecovered.size > 0) {
            // Prepended for the same reason Stage A prepends recovered
            // time tokens: a clean, self-validating recovered word
            // should never be at risk of an unrelated neighbor's
            // lookahead window absorbing it.
            ocrResult.data.words = [...bestRecovered.values(), ...(ocrResult.data.words || [])];
          }
        }
      }
    }
  } catch (err) {
    console.warn("[TimetableParser] Day-column retry OCR failed, continuing with prior data:", err);
  }

  updateTimetableLoadingModal("Reconstructing schedule rows and matching subjects...");
  let deterministicResult;
  try {
    deterministicResult = parseTimetableFromGrid(ocrResult.data, existingSubjects, facultyLegend, subjectLegend);
  } catch (err) {
    console.error("[TimetableParser] Error in grid parser, falling back to text stream:", err);
    try {
      const streamFallback = parseTimetableFromTextStream(ocrResult.data?.text || '', existingSubjects);
      deterministicResult = { schedule: streamFallback, confidence: streamFallback.length ? 50 : 0, ambiguous: streamFallback.length === 0 };
    } catch {
      deterministicResult = { schedule: [], confidence: 0, ambiguous: true };
    }
  }

  // Stage C: the 2D grid reconstructor flags any cell cluster whose OCR
  // confidence was too low to trust (dense multi-line body cells can hit
  // the same kind of OCR breakdown Stage A fixed for header numerals).
  // Each flagged region is already properly bounded to ONE cell by the
  // real clustering (never spans multiple side-by-side columns the way a
  // naive whole-row crop would), so a targeted crop + upscale + isolated
  // OCR pass can retry just that region safely. Only runs when something
  // was actually flagged, so a clean scan pays no extra cost, and the
  // retry result is only adopted if it doesn't produce fewer rows than
  // the first pass already found.
  if (deterministicResult?.lowConfidenceClusters?.length > 0) {
    try {
      updateTimetableLoadingModal("Re-scanning unclear cells for better accuracy...");
      let improvedWords = ocrResult.data.words || [];
      for (const region of deterministicResult.lowConfidenceClusters) {
        const recovered = await reOcrCellRegion(preprocessedDataUrl, worker, region.bbox);
        if (recovered.length > 0) {
          improvedWords = improvedWords.filter(w => !isBboxInsideRegion(w.bbox, region.bbox));
          improvedWords = [...improvedWords, ...recovered];
        }
      }
      const retryResult = parseTimetableFromGrid({ ...ocrResult.data, words: improvedWords }, existingSubjects, facultyLegend, subjectLegend);
      if ((retryResult?.schedule?.length || 0) >= (deterministicResult.schedule?.length || 0)) {
        deterministicResult = retryResult;
      }
    } catch (err) {
      console.warn("[TimetableParser] Cell-region retry OCR failed, continuing with prior result:", err);
    }
  }

  // Flag rows the on-device read clearly got wrong, BEFORE the confidence
  // gate below, so junk can't make a bad read look confident (which skipped
  // the AI) and the review screen highlights it. Flags only, never drops.
  (deterministicResult?.schedule || []).forEach(row => {
    if (!row.isUncertain && looksLikeJunkTimetableRow(row)) row.isUncertain = true;
  });

  // If the deterministic parser found a confident result, return
  // immediately -- "confident" now means non-empty, not mostly flagged
  // uncertain, AND covering a plausible chunk of a real week, so a photo
  // that produced a few rows but garbled most of them still gets a chance
  // at AI help below instead of being silently accepted as-is.
  //
  // The distinct-day and row-count floors below exist because per-row
  // uncertainty alone let a badly under-extracted result masquerade as
  // "confident": if the grid parser recovered only 2 rows out of a full
  // week and neither happened to be individually flagged, uncertainRatio
  // was 0/2 = 0, which passed the old < 0.4 check and returned those 2 rows
  // immediately -- AI extraction never even ran. That's the root cause a
  // real-device test surfaced as "0-2 entries from a full weekly
  // timetable" even though the vision fallback below already existed. A
  // week with real classes realistically has entries on 3+ days and more
  // than a handful of rows; anything less is itself a strong signal the
  // grid reconstruction missed most of the photo, regardless of whether
  // Tesseract felt confident about the few rows it did produce.
  const uncertainRowCount = (deterministicResult.schedule || []).filter(r => r.isUncertain).length;
  const uncertainRatio = deterministicResult.schedule?.length
    ? uncertainRowCount / deterministicResult.schedule.length
    : 1;
  const distinctDaysFound = new Set((deterministicResult.schedule || []).map(r => r.day)).size;
  const deterministicIsConfident = deterministicResult.schedule
    && deterministicResult.schedule.length >= 6
    && uncertainRatio < 0.4
    && distinctDaysFound >= 3;

  if (deterministicIsConfident) {
    return { schedule: deterministicResult.schedule, confidence: Math.max(70, deterministicResult.confidence) };
  }

  // AI structured repair fallback (only if user has configured an API key
  // for at least one vision/text provider)
  const hasGroqKey = AIService.hasProvider('groq');
  const hasGeminiKey = AIService.hasProvider('gemini');
  const hasOpenRouterKey = AIService.hasProvider('openrouter');

  if (!hasGroqKey && !hasGeminiKey && !hasOpenRouterKey) {
    console.log("[ExtractionPipeline] AI Repair skipped (no API key). Using deterministic output.");
    // No AI provider to cross-check against, and this result already failed
    // the confidence gate above -- flagged so the preview modal can warn
    // the user to check it row-by-row instead of presenting it as reliable.
    return { ...deterministicResult, needsReview: true };
  }

  updateTimetableLoadingModal("Refining ambiguous timetable entries with AI...");
  const schemaInstruction = `Extract all weekly college class timetable entries from this raw OCR text.
Return JSON matching this exact structure:
{
  "schedule": [
    {
      "day": "Mon" | "Tue" | "Wed" | "Thu" | "Fri" | "Sat",
      "time": "10:00",
      "end": "11:00",
      "subject": "Data Structures",
      "code": "DS",
      "room": "LT-2",
      "teacher": "Prof. Name",
      "type": "lecture" | "lab" | "project",
      "isUncertain": false
    }
  ]
}

Rules:
1. Day must be one of: Mon, Tue, Wed, Thu, Fri, Sat.
2. time and end must be 24-hour HH:MM format (e.g. 09:00, 10:30, 14:00).
3. Do not invent fake subjects or rooms if not present in text.
4. If an entry is ambiguous, mark isUncertain: true.
5. Merged cells: if one cell visually spans multiple consecutive periods (e.g.
   a single "OE-1" block covering periods 3 and 4), emit ONE row whose time
   is period 3's start and whose end is period 4's end -- do not duplicate
   the same subject into two separate rows for the two periods.
6. Stacked cells: if one time slot lists multiple different classes together
   (e.g. different batches sharing the same period, printed as separate
   lines in the same box), emit ONE row PER entry, all sharing that same
   day/time/end, differentiated by subject/code/teacher/room. Never merge
   them into a single row or drop all but one.
7. Legend expansion: if a subject/faculty legend is provided below, use it to
   expand abbreviations in the grid to their full names in "subject", and
   keep the short form in "code". Abbreviations sometimes appear in the grid
   in a slightly different form than the legend lists them (e.g. grid says
   "WEB DEV." while the legend lists "WD") -- match them by meaning, not
   exact string equality.
8. Inferred times: many timetables print only a period number or a shared
   duration label (e.g. "Lectures = 40 Min.") instead of a start/end time on
   every row. When that happens, compute each period's time from whatever IS
   printed -- an anchor time on one row, the stated duration, a recess
   position -- and fill time/end normally. Computing a time this way is NOT
   by itself a reason to set isUncertain: true; isUncertain is for when the
   subject, day, or which period a cell belongs to is genuinely unclear from
   the image, not for a time you derived rather than read verbatim.

This is an EXAMPLE of the clean formatting style to aim for (a DIFFERENT college's timetable -- copy the STYLE and STRUCTURE below, never this content, into whatever subjects/rooms/teachers this specific photo actually shows):
{ "day": "Mon", "time": "10:00", "end": "11:00", "subject": "Data Structures (DS)", "code": "DS", "room": "SF-31", "teacher": "Prof. VJM", "type": "lecture", "isUncertain": false }
{ "day": "Mon", "time": "12:00", "end": "12:45", "subject": "Recess", "code": "REC", "room": "—", "teacher": "—", "type": "off", "isUncertain": false }
{ "day": "Tue", "time": "10:00", "end": "12:00", "subject": "Web Development Lab", "code": "WEB DEV", "room": "FF-40", "teacher": "Prof. MKP", "type": "lab", "isUncertain": false }
Notice: full subject name with its short code in parentheses, "Prof. <initials>" for teacher when the photo only gives initials, "—" (em dash) for an unlisted room/teacher, and breaks/recess given their own row with type "off" rather than skipped.`;

  // Legends were already parsed from this same image by the Tesseract pass
  // above (facultyLegend/subjectLegend) -- hand them to the AI as a hint
  // instead of making it re-derive every abbreviation from pixels alone.
  // Deliberately phrased as "may be incomplete" since this first-pass OCR
  // read can itself be wrong; the model should verify against the photo,
  // not trust it blindly.
  const legendHint = (subjectLegend?.length || facultyLegend?.length)
    ? `\n\nA prior OCR pass already read a legend from this same image (may be incomplete or contain misreads -- verify against the photo, don't trust it blindly):\nSubject abbreviations: ${JSON.stringify(subjectLegend || [])}\nFaculty codes: ${JSON.stringify(facultyLegend || [])}`
    : '';

  // Vision-first: send the actual photo to a multimodal model when any
  // vision-capable provider is configured -- this is the only path that can
  // recover information Tesseract lost at the pixel level (heavy skew, poor
  // lighting, handwriting), which text-only repair structurally cannot do
  // since it never sees the picture. extractStructuredFromImage rotates
  // across every configured provider (Gemini -> Groq -> OpenRouter) so one
  // provider being rate-limited no longer drops all the way down to
  // text-only repair or raw Tesseract -- it just tries the next one. Falls
  // through to text-only repair below only if no vision provider is
  // configured, or all configured ones failed/were empty.
  if (hasGeminiKey || hasGroqKey || hasOpenRouterKey) {
    try {
      // The vision call asks for the GRID (which header columns each cell
      // covers), not clock times per row: the app computes times itself from
      // the printed header (expandGridCellsToScheduleRows). Measured on the
      // real SY-AIDS test-kit scan with the same model: the flat "time/end per
      // row" format read every cell correctly but cut most two-period merged
      // cells (MDM 3-5, the 10-12 lab blocks) to their first hour -- 74%
      // recall -- because the model had to derive each merged cell's end
      // time itself. The text-only repair path below keeps the flat format.
      const visionPrompt = VISION_GRID_INSTRUCTION + legendHint + `

The attached image is a photo of the same college timetable the OCR text below was read from. Use the image as the primary source of truth -- the OCR text is only a rough, possibly-garbled hint of what it contains, since it came from a classical OCR engine that may have misread skewed, poorly-lit, or handwritten text.

Rough OCR text (may be inaccurate):
${ocrResult.data.text || ''}`;
      // Reuse the already-preprocessed image (deskewed, contrast-enhanced,
      // capped at 2000px -- see preprocessImageForOCR above) instead of the
      // raw camera upload. Phone photos are routinely 3-8MB before this;
      // that full-size file was being base64-uploaded, unmodified, to every
      // vision provider on every scan. Smaller payload = faster network
      // transfer + faster model-side image processing, with no accuracy
      // loss since it's the exact same image Tesseract itself already reads.
      const visionDataUrl = await reencodeDataUrl(preprocessedDataUrl, mimeType, 0.92);
      const preprocessedBase64 = visionDataUrl.split(',')[1];
      const visionResult = await AIService.extractStructuredFromImage(preprocessedBase64, mimeType, visionPrompt,
        name => updateTimetableLoadingModal(`Reading the photo with AI (${name})...`));
      if (visionResult && Array.isArray(visionResult.schedule) && visionResult.schedule.length > 0) {
        // Grid-cell response (the requested format) -> rows with times from
        // the header; a model that ignored it and returned flat rows is
        // still accepted exactly as before.
        const isGridCells = Array.isArray(visionResult.periods)
          && visionResult.schedule.some(c => c && Array.isArray(c.periods) && Array.isArray(c.entries));
        const visionRows = isGridCells
          ? expandGridCellsToScheduleRows(visionResult.periods, visionResult.schedule)
          : visionResult.schedule;
        // Same back-to-back duplicate merge the on-device grid path already
        // applies (v156) -- e.g. two printed PBST periods become one 2-hour
        // block. Previously only the on-device path got this, so it never
        // reached AI-path scans, which is what real scans use.
        const sanitized = mergeAdjacentDuplicatePeriods(sanitizeAiScheduleRows(visionRows));
        if (sanitized.length > 0) {
          return { schedule: sanitized, confidence: 88 };
        }
      }
    } catch (err) {
      console.warn("[ExtractionPipeline] Vision AI Repair failed on every configured provider, falling back to text-only repair:", err);
    }
  }

  try {
    const rawOcrText = ocrResult.data.text;
    const aiResult = await AIService.generateContentFromText(rawOcrText, schemaInstruction + legendHint);
    if (aiResult && Array.isArray(aiResult.schedule) && aiResult.schedule.length > 0) {
      const sanitized = sanitizeAiScheduleRows(aiResult.schedule);
      // sanitized.length === 0 here means the text-repair call returned
      // *something* but every row got rejected by sanitizeAiScheduleRows --
      // that's a raw, un-repaired deterministic result reaching the user
      // exactly like the no-key path above, so it's flagged the same way
      // instead of wearing the AI path's confidence: 85 it didn't earn.
      if (sanitized.length > 0) {
        return { schedule: sanitized, confidence: 85 };
      }
      return { ...deterministicResult, needsReview: true };
    }
    return { ...deterministicResult, needsReview: true };
  } catch (err) {
    console.warn("[ExtractionPipeline] AI Repair failed:", err);
    return { ...deterministicResult, needsReview: true };
  }
}

// Shared sanitizer for AI-returned schedule rows (both the vision path and
// the text-only repair path), extracted so the two never drift apart.
// Rejects hallucinated rows with no subject, and re-runs each time value
// through the same normalizeTimetableTime used everywhere else so an AI
// model's own time formatting quirks don't bypass the app's own validation.
function sanitizeAiScheduleRows(rawRows) {
  return (rawRows || []).map(item => {
    const timeNorm = normalizeTimetableTime(`${item.time || '10:00'} - ${item.end || '11:00'}`);
    return {
      day: standardizeTimetableDay(item.day) || 'Mon',
      time: timeNorm.time || item.time || '10:00',
      end: timeNorm.end || item.end || '11:00',
      subject: (item.subject || '').trim(),
      code: (item.code || '').trim(),
      room: (item.room || '').trim(),
      teacher: (item.teacher || '').trim(),
      type: item.type || 'lecture',
      isUncertain: !!item.isUncertain || !item.subject
    };
  }).filter(r => r.subject.length > 0);
}

// Vision-AI prompt: asks for the table's structure (which header columns
// each cell spans) instead of per-row clock times. See the comment at the
// vision call in extractTimetableFromImage for the measured reason.
// `schedule` holds CELLS so AIService.extractStructuredFromImage's existing
// "non-empty schedule" acceptance check works unchanged.
const VISION_GRID_INSTRUCTION = `Read the weekly college class timetable in the attached image and return its GRID STRUCTURE as JSON matching exactly:
{
  "periods": [ { "n": 1, "start": "10:00 AM", "end": "11:00 AM" } ],
  "schedule": [
    { "day": "Mon", "periods": [1], "entries": [
      { "subject": "Data Structures", "code": "DS", "teacher": "Prof. VJM", "room": "", "batch": "", "type": "lecture", "isUncertain": false }
    ] }
  ]
}

Rules:
1. "periods" = the CLASS columns of the header, numbered 1, 2, 3... from left to right (use the column numbers printed in the header when there are any), each with its start and end time exactly as printed. Do NOT include recess/break/lunch columns and do not give them a number.
2. "schedule" = one object per non-empty class cell, for every day row, left to right. "day" is one of Mon, Tue, Wed, Thu, Fri, Sat.
3. "periods" on a cell = EVERY class-column number that cell covers. A cell merged across two or more columns (no vertical line between them) lists all of them, e.g. [3, 4] or [5, 6]; a single-column cell lists one number. Look at the column borders of every cell, especially lab blocks, cells in the last columns of the day, and cells directly after a recess column.
4. A cell listing several classes (different batches sharing the slot, one per line) gets one entry per class, all in that one cell object.
5. Skip empty cells and recess/break cells entirely.
6. "subject": the full subject name, expanded from the legend table when the grid uses an abbreviation (match by meaning -- the grid may write "WEB DEV." where the legend says "WD"). "code": the short form as printed. "batch": the batch/division exactly as printed in the cell (e.g. "AI-B2" or "A2,B2,C2,D2"), or "" if none. "teacher": "Prof. <initials>" when only initials are printed, or "". "room": the room printed in that cell, or "".
7. "type": "lab" for labs/practicals, "project" for projects/community work, otherwise "lecture".
8. Never invent subjects, rooms or teachers that are not in the image. Set "isUncertain": true only when a cell's subject, day or column span is genuinely unclear.
9. If the header prints only period numbers or a shared duration instead of times, compute each period's start/end from what IS printed.

Example of the shape only (a DIFFERENT college -- never copy this content):
{ "periods": [ { "n": 1, "start": "9:00 AM", "end": "10:00 AM" }, { "n": 2, "start": "10:00 AM", "end": "11:00 AM" }, { "n": 3, "start": "11:15 AM", "end": "12:15 PM" }, { "n": 4, "start": "12:15 PM", "end": "1:15 PM" } ],
  "schedule": [
    { "day": "Mon", "periods": [1], "entries": [ { "subject": "Operating Systems", "code": "OS", "teacher": "Prof. RKS", "room": "", "batch": "", "type": "lecture", "isUncertain": false } ] },
    { "day": "Mon", "periods": [3, 4], "entries": [
      { "subject": "Computer Networks Lab", "code": "CN", "teacher": "Prof. ABM", "room": "L-2", "batch": "B1", "type": "lab", "isUncertain": false },
      { "subject": "Operating Systems Lab", "code": "OS", "teacher": "Prof. RKS", "room": "L-3", "batch": "B2", "type": "lab", "isUncertain": false } ] }
  ] }`;

// Converts the grid-cell vision response into the flat rows the rest of the
// app uses. Each cell's time is derived from the header: start of its first
// covered period, end of its last -- so a merged cell always gets its full
// span. Recess rows are added for gaps between consecutive header periods
// that fall inside a day's classes (the flat format used to return these as
// rows too). The batch is appended in brackets so the existing batch filter
// (extractBatchTags) picks it up exactly as it does for on-device scans.
function expandGridCellsToScheduleRows(periodsHeader, cells) {
  const header = (periodsHeader || [])
    .map(p => {
      const n = parseInt(p && p.n, 10);
      const t = normalizeTimetableTime(`${(p && p.start) || ''} - ${(p && p.end) || ''}`);
      return { n, time: t.isValid ? t.time : '', end: t.isValid && t.isRangeMatch ? t.end : '' };
    })
    .filter(p => Number.isFinite(p.n) && p.time)
    .sort((a, b) => a.n - b.n);
  header.forEach((p, i) => {
    if (!p.end) p.end = header[i + 1] ? header[i + 1].time : '';
  });
  const byNum = new Map(header.filter(p => p.end).map(p => [p.n, p]));
  if (byNum.size === 0) return [];

  const rows = [];
  const dayBounds = new Map();
  (cells || []).forEach(cell => {
    const nums = (Array.isArray(cell && cell.periods) ? cell.periods : [])
      .map(x => parseInt(x, 10))
      .filter(x => byNum.has(x));
    if (!nums.length || !Array.isArray(cell.entries)) return;
    const first = byNum.get(Math.min(...nums));
    const last = byNum.get(Math.max(...nums));
    cell.entries.forEach(e => {
      if (!e || !(e.subject || e.code)) return;
      const batch = (e.batch || '').trim();
      rows.push({
        day: cell.day,
        time: first.time,
        end: last.end,
        subject: `${(e.subject || e.code || '').trim()}${batch ? ` (${batch})` : ''}`,
        code: e.code || '',
        room: e.room || '',
        teacher: e.teacher || '',
        type: e.type || 'lecture',
        isUncertain: !!e.isUncertain
      });
    });
    const b = dayBounds.get(cell.day) || { start: Infinity, end: -Infinity };
    b.start = Math.min(b.start, timeToMinutes(first.time));
    b.end = Math.max(b.end, timeToMinutes(last.end));
    dayBounds.set(cell.day, b);
  });

  const gaps = [];
  for (let i = 0; i + 1 < header.length; i++) {
    if (header[i].end && timeToMinutes(header[i + 1].time) - timeToMinutes(header[i].end) >= 5) {
      gaps.push({ time: header[i].end, end: header[i + 1].time });
    }
  }
  dayBounds.forEach((b, day) => {
    gaps.forEach(g => {
      if (timeToMinutes(g.time) >= b.start && timeToMinutes(g.end) <= b.end) {
        rows.push({ day, time: g.time, end: g.end, subject: 'Recess', code: 'REC', room: '—', teacher: '—', type: 'off', isUncertain: false });
      }
    });
  });
  return rows;
}

function triggerTimetableImport() {
  selectTimetableFile();
}

function selectTimetableFile() {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = 'image/*';
  // Hints mobile browsers to offer the rear camera directly rather than
  // defaulting straight to the photo library -- most mobile browsers still
  // also offer a gallery/file option alongside it, so this only speeds up
  // the common case without removing any existing choice.
  input.capture = 'environment';
  input.onchange = handleTimetableImageUpload;
  input.click();
}

function handleTimetableImageUpload(event) {
  const file = event.target.files?.[0];
  if (!file) return;

  // Validate file type & size (< 12 MB)
  if (!file.type.startsWith('image/')) {
    alert('Please upload an image file (JPG, PNG, WEBP, etc.)');
    return;
  }
  if (file.size > 12 * 1024 * 1024) {
    alert('Image is too large (max 12 MB). Please compress or crop it first.');
    return;
  }

  _scanStartedAt = Date.now();
  trackUsage('scan_started');
  showTimetableLoadingModal('Scanning timetable photo…');

  const reader = new FileReader();
  reader.onload = async (e) => {
    let mimeType, base64Data;
    try {
      const resultUrl = e.target.result;
      mimeType   = resultUrl.split(';')[0].split(':')[1] || 'image/jpeg';
      base64Data = resultUrl.split(',')[1];
    } catch {
      document.getElementById('tt-loading-backdrop')?.remove();
      showTimetableUploadErrorModal('Could not read the image file. Please try a different photo.');
      return;
    }

    try {
      const result = await extractTimetableFromImage(base64Data, mimeType);
      document.getElementById('tt-loading-backdrop')?.remove();

      const schedule = result?.schedule || [];

      if (schedule.length === 0) {
        // Extraction found no valid classes
        showTimetableUploadErrorModal(
          'No timetable entries could be extracted from this photo. The image may be blurry, low-contrast, or not a timetable.',
          base64Data, mimeType
        );
        return;
      }

      // ✅ SUCCESS → ALWAYS show preview/edit modal with extracted entries and batch filter
      console.log('[TimetableUpload] Extraction successful. UI transitioning to showTimetablePreviewModal with', schedule.length, 'classes.');
      pendingExtractionNeedsReview = !!result?.needsReview;
      showTimetablePreviewModal(schedule);

    } catch (err) {
      document.getElementById('tt-loading-backdrop')?.remove();
      console.warn('[TimetableUpload] Extraction error:', err);
      const reason = err?.message || 'Timetable extraction failed.';
      showTimetableUploadErrorModal(reason, base64Data, mimeType);
    }
  };

  reader.onerror = () => {
    document.getElementById('tt-loading-backdrop')?.remove();
    showTimetableUploadErrorModal('File could not be read. Please try again with a different image.');
  };

  reader.readAsDataURL(file);
}

// Non-blocking error dialog with Retry, Upload Again, and Enter Manually options.
function showTimetableUploadErrorModal(reason, base64Data, mimeType) {
  if (_scanStartedAt) trackUsage('scan_failed', usageScanBucket());
  document.getElementById('tt-upload-error-backdrop')?.remove();
  const canRetry = !!(base64Data && mimeType);
  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop';
  backdrop.id = 'tt-upload-error-backdrop';
  backdrop.innerHTML = `
    <div class="modal" style="max-width:400px;text-align:center;padding:28px 24px">
      <div style="font-size:var(--text-hero);margin-bottom:12px">${icons.alert()}</div>
      <div style="font-weight:700;font-size:var(--text-md);margin-bottom:8px">Timetable Extraction Failed</div>
      <div style="font-size:var(--text-base);color:var(--text-muted);margin-bottom:20px;line-height:1.5">${reason}</div>
      <div style="display:flex;flex-direction:column;gap:10px">
        ${canRetry ? `<button class="btn-primary" id="tt-error-retry-btn">🔄 Retry with Same Image</button>` : ''}
        <button class="btn-secondary" id="tt-error-upload-btn">${icons.camera()} Upload a Different Image</button>
        <button class="btn-secondary" id="tt-error-manual-btn">${icons.edit()} Enter Timetable Manually</button>
        <button style="background:none;border:none;color:var(--text-muted);cursor:pointer;font-size:var(--text-sm);margin-top:4px"
                onclick="document.getElementById('tt-upload-error-backdrop')?.remove()">Dismiss</button>
      </div>
    </div>
  `;
  document.body.appendChild(backdrop);

  if (canRetry) {
    document.getElementById('tt-error-retry-btn').onclick = async () => {
      backdrop.remove();
      showTimetableLoadingModal('Retrying extraction…');
      try {
        const result = await extractTimetableFromImage(base64Data, mimeType);
        document.getElementById('tt-loading-backdrop')?.remove();
        const schedule = result?.schedule;
        if (!Array.isArray(schedule) || schedule.length === 0) {
          showTimetableUploadErrorModal('Still no entries found. Try a clearer photo or enter manually.', base64Data, mimeType);
        } else {
          pendingExtractionNeedsReview = !!result?.needsReview;
          showTimetablePreviewModal(schedule);
        }
      } catch (err2) {
        document.getElementById('tt-loading-backdrop')?.remove();
        showTimetableUploadErrorModal(err2?.message || 'Retry also failed.', base64Data, mimeType);
      }
    };
  }

  document.getElementById('tt-error-upload-btn').onclick = () => {
    backdrop.remove();
    selectTimetableFile();
  };

  document.getElementById('tt-error-manual-btn').onclick = () => {
    console.log('[TimetableUpload] User explicitly clicked "Enter Timetable Manually" from Error Modal.');
    backdrop.remove();
    showTimetableEntryModal(state.ttDay, null);
  };
}

let pendingExtractedSchedule = [];
let selectedTimetablePreviewBatch = 'all';
// True when the schedule about to be previewed is a raw, un-repaired
// deterministic OCR result that no AI provider ever got to check (no key
// configured, or every configured provider failed/returned nothing usable).
// Distinct from per-row isUncertain: that flags individual rows Tesseract
// itself wasn't sure about, this flags the whole scan as never having had a
// second opinion at all -- see extractTimetableFromImage's needsReview.
let pendingExtractionNeedsReview = false;

function showTimetablePreviewModal(schedule) {
  if (_scanStartedAt) { trackUsage('scan_review_shown', usageScanBucket()); _scanStartedAt = 0; }
  const currentProfileBatch = (liveProfile?.batch || '').trim().toUpperCase();

  // Real existing-subject list (not []) so re-normalization here can
  // actually reconcile against subjects the user already has -- previously
  // this discarded the match context established at scan time.
  const existingSubjectsForPreview = getSubjectList();

  // Normalize each row through canonical normalization layer
  pendingExtractedSchedule = (schedule || []).map(item => {
    const norm = normalizeSubjectIdentity(item.subject || '', existingSubjectsForPreview, item.type);
    const batches = (norm.batches && norm.batches.length > 0) ? norm.batches : (item.batches || []);
    return {
      day: standardizeTimetableDay(item.day) || 'Mon',
      time: item.time || '10:00',
      end: item.end || '11:00',
      subject: norm.canonicalName || item.subject || '',
      code: norm.canonicalCode || item.code || '',
      room: norm.room || item.room || '',
      teacher: norm.teacher || item.teacher || '',
      type: norm.classType || item.type || 'lecture',
      batches,
      isUncertain: !norm.canonicalName || !!item.isUncertain,
      // Carries forward (not recomputed here -- this re-normalization pass
      // has no legend context) whether the OCR extraction step resolved
      // this subject via the scan's own legend table or an OCR digit/letter
      // correction, rather than reading it directly off the grid.
      subjectInferred: !!item.subjectInferred,
      rawSubject: (item.subject || '').trim()
    };
  }).map(row => {
    // A row whose "subject" is really a room, a teacher, a batch, a time,
    // or a non-academic slot (Library, Sports, T&P...) starts as Off so it
    // never becomes a Subject Hub card or a Study Vault folder. The Type
    // dropdown still lets the student turn it back into a Lecture.
    // normalizeSubjectIdentity answers "General Subject" when it found no
    // subject text at all, so that placeholder counts too, and the row then
    // shows what was actually read ("Room 304") instead of the placeholder.
    const { rawSubject, ...rest } = row;
    const subj = (rest.subject || '').trim();
    const placeholder = subj === 'General Subject';
    if (subj && rest.type !== 'off' && (placeholder || isNonSubjectSlotName(subj) || isLikelyGarbledSubjectName(subj) || isNonSubjectSlotName(rawSubject))) {
      return { ...rest, subject: placeholder && rawSubject ? rawSubject : rest.subject, type: 'off', autoOff: true };
    }
    return rest;
  });

  // Collect all discovered batches across schedule
  const discoveredBatches = new Set();
  pendingExtractedSchedule.forEach(item => {
    (item.batches || []).forEach(b => discoveredBatches.add(b));
  });

  if (currentProfileBatch && (discoveredBatches.has(currentProfileBatch) || discoveredBatches.size > 0)) {
    selectedTimetablePreviewBatch = currentProfileBatch;
  } else {
    selectedTimetablePreviewBatch = 'all';
  }

  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop';
  backdrop.id = 'tt-preview-backdrop';

  renderTimetablePreviewModalContent(backdrop);
  document.body.appendChild(backdrop);
}

function renderTimetablePreviewModalContent(backdrop) {
  const discoveredBatches = new Set();
  pendingExtractedSchedule.forEach(item => {
    (item.batches || []).forEach(b => discoveredBatches.add(b));
  });
  const batchList = Array.from(discoveredBatches).sort();

  const visibleSchedule = pendingExtractedSchedule
    .map((item, originalIdx) => ({ item, originalIdx }))
    .filter(({ item }) => shouldKeepClassForUserBatch(item, selectedTimetablePreviewBatch));

  const uncertainCount = visibleSchedule.filter(({ item }) => item.isUncertain || !item.subject).length;
  const autoOffCount = visibleSchedule.filter(({ item }) => item.autoOff && item.type === 'off').length;

  const rowsHtml = visibleSchedule.map(({ item, originalIdx }) => {
    const isRowUncertain = item.isUncertain || !item.subject;
    const batchLabel = (item.batches && item.batches.length > 0)
      ? `<span class="type-badge" style="font-size:var(--text-xs);padding:2px 6px;background:var(--accent-dim);color:var(--brand-primary)">${item.batches.join(', ')}</span>`
      : `<span style="font-size:var(--text-xs);color:var(--text-muted)">General</span>`;

    return `
    <tr class="${isRowUncertain ? 'preview-row-uncertain' : ''}" id="preview-row-${originalIdx}">
      <td>
        <select class="form-select" style="padding:4px 6px;font-size:var(--text-sm)" onchange="updatePreviewEntry(${originalIdx}, 'day', this.value)">
          ${['Mon','Tue','Wed','Thu','Fri','Sat'].map(d => `<option value="${d}" ${item.day===d?'selected':''}>${d}</option>`).join('')}
        </select>
      </td>
      <td>
        <div style="display:flex;align-items:center;gap:3px">
          <input type="text" class="form-input" style="padding:4px 4px;font-size:var(--text-sm);width:64px;font-family:var(--font-mono)" value="${formatDisplayTime(item.time || '10:00')}" placeholder="10:00 AM" onchange="updatePreviewEntry(${originalIdx}, 'time', this.value)">
          <span style="color:var(--text-muted)">-</span>
          <input type="text" class="form-input" style="padding:4px 4px;font-size:var(--text-sm);width:64px;font-family:var(--font-mono)" value="${formatDisplayTime(item.end || '11:00')}" placeholder="11:00 AM" onchange="updatePreviewEntry(${originalIdx}, 'end', this.value)">
        </div>
      </td>
      <td>
        <div style="display:flex;align-items:center;gap:4px">
          <input type="text" class="form-input ${!item.subject ? 'error' : ''}" id="preview-subject-${originalIdx}" style="padding:4px 6px;font-size:var(--text-sm);width:100%" value="${(item.subject || '').replace(/"/g, '&quot;')}" placeholder="Subject name *" onchange="updatePreviewEntry(${originalIdx}, 'subject', this.value)">
          ${item.subjectInferred ? '<span title="Resolved from this scan\'s legend/OCR-correction, not read directly off the grid. Please double-check it." style="font-size:var(--text-xs);color:var(--text-muted);white-space:nowrap">✨ inferred</span>' : ''}
        </div>
      </td>
      <td>
        <select class="form-select" style="padding:4px 6px;font-size:var(--text-sm);width:82px" onchange="updatePreviewEntry(${originalIdx}, 'type', this.value)">
          <option value="lecture" ${item.type==='lecture'?'selected':''}>Lecture</option>
          <option value="lab" ${item.type==='lab'?'selected':''}>Lab</option>
          <option value="tutorial" ${item.type==='tutorial'?'selected':''}>Tutorial</option>
          <option value="project" ${item.type==='project'?'selected':''}>Project</option>
          <option value="off" ${item.type==='off'?'selected':''}>Off</option>
        </select>
      </td>
      <td style="text-align:center">
        ${batchLabel}
      </td>
      <td>
        <input type="text" class="form-input" style="padding:4px 6px;font-size:var(--text-sm);width:68px" value="${(item.code || '').replace(/"/g, '&quot;')}" placeholder="Code" onchange="updatePreviewEntry(${originalIdx}, 'code', this.value)">
      </td>
      <td>
        <input type="text" class="form-input" style="padding:4px 6px;font-size:var(--text-sm);width:68px" value="${(item.room || '').replace(/"/g, '&quot;')}" placeholder="Room" onchange="updatePreviewEntry(${originalIdx}, 'room', this.value)">
      </td>
      <td>
        <input type="text" class="form-input" style="padding:4px 6px;font-size:var(--text-sm);width:85px" value="${(item.teacher || '').replace(/"/g, '&quot;')}" placeholder="Faculty" onchange="updatePreviewEntry(${originalIdx}, 'teacher', this.value)">
      </td>
      <td style="text-align:center">
        ${item.type === 'off' && item.subject ? '<span class="not-subject-badge" title="Saved as a free slot. It will not become a subject.">Not a subject</span>' : isRowUncertain ? '<span class="uncertain-badge" title="Please review or edit missing details">⚠️ Review</span>' : '<span style="color:var(--green);font-size:var(--text-sm);font-weight:600">✓ Ready</span>'}
      </td>
      <td style="text-align:center">
        <button class="task-delete-btn" onclick="removePreviewEntry(${originalIdx})" title="Remove class entry">${icons.trash()}</button>
      </td>
    </tr>`;
  }).join('');

  backdrop.innerHTML = `
    <div class="modal" onclick="event.stopPropagation()" style="max-width:860px;width:95%">
      <div class="modal-header">
        <div>
          <h2 class="modal-title">Extracted Timetable Preview</h2>
          <div style="font-size:var(--text-sm);color:var(--text-muted);margin-top:2px">
            ${visibleSchedule.length} class${visibleSchedule.length !== 1 ? 'es' : ''} shown ${selectedTimetablePreviewBatch !== 'all' ? `(Filtered for Batch ${selectedTimetablePreviewBatch})` : ''} ${pendingExtractionNeedsReview ? '· <span style="color:var(--yellow);font-weight:600">Check every row</span>' : uncertainCount > 0 ? `· <span style="color:var(--yellow);font-weight:600">${uncertainCount} ${uncertainCount !== 1 ? 'rows need' : 'row needs'} a check</span>` : '· <span style="color:var(--green);font-weight:600">All rows read clearly</span>'}
          </div>
        </div>
        <button class="modal-close" onclick="document.getElementById('tt-preview-backdrop').remove()">${icons.x()}</button>
      </div>

      ${pendingExtractionNeedsReview ? `
      <!-- Whole-scan warning: unlike the per-row ⚠️ Review badges below (which
           flag individual rows Tesseract itself was unsure about), this means
           NO AI provider ever got a chance to cross-check this scan against
           the photo -- either no Gemini/Groq/OpenRouter key is configured, or
           every configured one failed or returned nothing usable. Read as
           "this is a raw, unverified OCR guess", not "some fields are fuzzy". -->
      <div style="display:flex;align-items:flex-start;gap:10px;background:color-mix(in srgb, var(--yellow) 12%, var(--surface-2));border:1px solid var(--yellow);border-radius:var(--radius-sm);padding:10px 14px;margin-bottom:14px">
        <span style="font-size:var(--text-md);line-height:1">⚠️</span>
        <div style="font-size:var(--text-sm);line-height:1.4">
          <strong>Unverified scan.</strong> The AI that double-checks photos couldn't be reached, so your phone read this one alone and it may have mistakes. Check every row before saving, or cancel and scan again in a few minutes.
        </div>
      </div>
      ` : ''}

      <!-- Batch Filter & Normalization Controls -->
      <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;background:var(--surface-2);padding:10px 14px;border-radius:var(--radius-sm);margin-bottom:14px;flex-wrap:wrap">
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
          <span style="font-size:var(--text-base);font-weight:600;color:var(--text-primary)">Your Practical Batch / Section:</span>
          <select class="form-select" id="tt-preview-batch-select" style="padding:4px 8px;font-size:var(--text-base);max-width:160px" onchange="onTimetablePreviewBatchChange(this.value)">
            <option value="all" ${selectedTimetablePreviewBatch === 'all' ? 'selected' : ''}>All Batches (No Filter)</option>
            ${batchList.map(b => `<option value="${b}" ${selectedTimetablePreviewBatch === b ? 'selected' : ''}>Batch ${b}</option>`).join('')}
            ${!batchList.includes('A1') ? '<option value="A1"' + (selectedTimetablePreviewBatch === 'A1' ? ' selected' : '') + '>Batch A1</option>' : ''}
            ${!batchList.includes('A2') ? '<option value="A2"' + (selectedTimetablePreviewBatch === 'A2' ? ' selected' : '') + '>Batch A2</option>' : ''}
            ${!batchList.includes('B1') ? '<option value="B1"' + (selectedTimetablePreviewBatch === 'B1' ? ' selected' : '') + '>Batch B1</option>' : ''}
            ${!batchList.includes('B2') ? '<option value="B2"' + (selectedTimetablePreviewBatch === 'B2' ? ' selected' : '') + '>Batch B2</option>' : ''}
            ${!batchList.includes('C1') ? '<option value="C1"' + (selectedTimetablePreviewBatch === 'C1' ? ' selected' : '') + '>Batch C1</option>' : ''}
            ${!batchList.includes('C2') ? '<option value="C2"' + (selectedTimetablePreviewBatch === 'C2' ? ' selected' : '') + '>Batch C2</option>' : ''}
            ${!batchList.includes('D1') ? '<option value="D1"' + (selectedTimetablePreviewBatch === 'D1' ? ' selected' : '') + '>Batch D1</option>' : ''}
            ${!batchList.includes('D2') ? '<option value="D2"' + (selectedTimetablePreviewBatch === 'D2' ? ' selected' : '') + '>Batch D2</option>' : ''}
          </select>
        </div>
        <div style="font-size:var(--text-sm);color:var(--text-muted)">
          Hides other batch practicals so you only save classes for your section.
        </div>
        ${batchList.length && selectedTimetablePreviewBatch === 'all' ? `
        <div style="flex-basis:100%;font-size:var(--text-sm);font-weight:600;color:var(--accent)">
          We found lab groups ${batchList.map(escHtml_cd).join(', ')}. Pick yours so you only see your own labs.
        </div>` : ''}
      </div>

      ${autoOffCount > 0 ? `
      <div style="font-size:var(--text-sm);color:var(--text-muted);margin-bottom:10px;line-height:1.4">
        ${autoOffCount} ${autoOffCount !== 1 ? 'rows look' : 'row looks'} like a room, teacher, batch or free period, so ${autoOffCount !== 1 ? 'they are' : 'it is'} marked <strong style="color:var(--text-primary)">Not a subject</strong>. If one is a real credited subject, set its Type to Lecture.
      </div>` : ''}

      <div style="overflow-x:auto;max-height:380px;margin-bottom:16px;border:1px solid var(--border);border-radius:var(--radius-sm)">
        <table class="preview-table">
          <thead>
            <tr>
              <th style="width:75px">Day</th>
              <th style="width:125px">Time</th>
              <th>Subject Name *</th>
              <th style="width:85px">Type</th>
              <th style="width:70px;text-align:center">Batch</th>
              <th style="width:70px">Code</th>
              <th style="width:70px">Room</th>
              <th style="width:90px">Faculty</th>
              <th style="width:75px;text-align:center">Status</th>
              <th style="width:36px"></th>
            </tr>
          </thead>
          <tbody>
            ${rowsHtml.length > 0 ? rowsHtml : `
              <tr>
                <td colspan="10" style="text-align:center;padding:24px;color:var(--text-muted)">
                  No timetable rows matched the chosen batch (${selectedTimetablePreviewBatch}). Change batch or click "Add Class Row" below.
                </td>
              </tr>
            `}
          </tbody>
        </table>
      </div>

      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px">
        <button class="btn-secondary" onclick="addPreviewEntry()" style="font-size:var(--text-sm);display:flex;align-items:center;gap:5px">
          ${icons.plus()} Add Class Row
        </button>

        <div style="display:flex;gap:10px">
          <button class="btn-secondary" onclick="document.getElementById('tt-preview-backdrop').remove()">Cancel</button>
          <button class="btn-primary" onclick="confirmSaveExtractedTimetable()">Confirm &amp; Save Schedule</button>
        </div>
      </div>
    </div>
  `;
}

window.onTimetablePreviewBatchChange = function(val) {
  selectedTimetablePreviewBatch = val;
  const backdrop = document.getElementById('tt-preview-backdrop');
  if (backdrop) renderTimetablePreviewModalContent(backdrop);
};

window.updatePreviewEntry = function(idx, key, val) {
  if (pendingExtractedSchedule[idx]) {
    if (key === 'time' || key === 'end') {
      // The input displays/accepts 12-hour AM/PM (formatDisplayTime, matching
      // the rest of the app's display convention), but the stored shape
      // (cos_custom_timetable's time/end fields) stays 24-hour "HH:MM" --
      // reuse the same parser the OCR extraction itself already relies on
      // rather than inventing a second one. An unparseable edit is kept as
      // typed (never silently discarded) so the user can see and fix it.
      const parsed = normalizeTimetableTime(val);
      pendingExtractedSchedule[idx][key] = parsed.isValid ? parsed.time : val;
    } else {
      pendingExtractedSchedule[idx][key] = val;
    }
    if (key === 'subject' && val.trim().length > 0) {
      pendingExtractedSchedule[idx].isUncertain = false;
      pendingExtractedSchedule[idx].subjectInferred = false;
      const subjEl = document.getElementById(`preview-subject-${idx}`);
      if (subjEl) subjEl.classList.remove('error');
    }
    if (key === 'type') {
      // The student decided, so drop the automatic flag, then redraw so
      // the Status column matches the new Type.
      pendingExtractedSchedule[idx].autoOff = false;
      const backdrop = document.getElementById('tt-preview-backdrop');
      if (backdrop) renderTimetablePreviewModalContent(backdrop);
    }
  }
};

window.removePreviewEntry = function(idx) {
  pendingExtractedSchedule.splice(idx, 1);
  const backdrop = document.getElementById('tt-preview-backdrop');
  if (backdrop) renderTimetablePreviewModalContent(backdrop);
};

window.addPreviewEntry = function() {
  pendingExtractedSchedule.push({
    day: 'Mon',
    time: '10:00',
    end: '11:00',
    subject: '',
    code: '',
    room: '',
    teacher: '',
    type: 'lecture',
    batches: selectedTimetablePreviewBatch !== 'all' ? [selectedTimetablePreviewBatch] : [],
    isUncertain: true
  });
  const backdrop = document.getElementById('tt-preview-backdrop');
  if (backdrop) renderTimetablePreviewModalContent(backdrop);
};

window.confirmSaveExtractedTimetable = function() {
  const toSave = pendingExtractedSchedule.filter(item => shouldKeepClassForUserBatch(item, selectedTimetablePreviewBatch));

  if (!toSave.length) {
    showToast("No classes to save for the selected batch. Add at least one class row or select 'All Batches'.", "info");
    return;
  }

  // 1. Validate that all kept entries have valid subject names
  for (let i = 0; i < toSave.length; i++) {
    const item = toSave[i];
    const subj = (item.subject || '').trim();
    if (!subj && item.type !== 'off') {
      showToast(`A class on ${item.day} at ${formatDisplayTime(item.time)} is missing a Subject name. Please fill it in or delete the row.`, "error");
      return;
    }

    // Validate times
    const timeNorm = normalizeTimetableTime(`${item.time || '10:00'} - ${item.end || '11:00'}`);
    if (!timeNorm.isValid) {
      showToast(`Class "${subj || 'Class'}" on ${item.day} has an invalid time format. Use HH:MM.`, "error");
      return;
    }
  }

  const hadClasses = hasAnyTimetable();
  const dayMap = { "Mon": 1, "Tue": 2, "Wed": 3, "Thu": 4, "Fri": 5, "Sat": 6 };
  const newTT = { 1: [], 2: [], 3: [], 4: [], 5: [], 6: [], 0: [] };

  toSave.forEach(item => {
    const dayNum = dayMap[item.day] || 1;
    const timeNorm = normalizeTimetableTime(`${item.time || '10:00'} - ${item.end || '11:00'}`);

    newTT[dayNum].push({
      time:    timeNorm.time || item.time || '10:00',
      end:     timeNorm.end || item.end || '11:00',
      subject: (item.subject || (item.type === 'off' ? 'Off' : 'Class')).trim(),
      code:    (item.code || '').trim(),
      room:    (item.room || '').trim(),
      teacher: (item.teacher || '').trim(),
      type:    item.type || 'lecture',
      batches: Array.isArray(item.batches) ? item.batches : [],
    });
  });

  Object.keys(newTT).forEach(d => {
    newTT[d].sort((a,b) => timeToMinutes(a.time) - timeToMinutes(b.time));
  });

  saveTimetable(newTT);

  // Bug fix: attendance is stored per (calendar date, code+time) so the
  // SAME recurring slot keeps its attendance history across weeks -- that's
  // intentional. But a fresh scan/import can put a DIFFERENT class into a
  // slot that previously had an attendance mark (e.g. an earlier scan/test,
  // or a corrected timetable), and that old mark would silently reappear as
  // already-answered on the new class with no way for the student to tell.
  // Clear it so present/absent is always the student's own choice on a
  // freshly confirmed schedule. Only future-facing (tomorrow onward) so
  // real, already-happened attendance history is never touched.
  clearUpcomingAttendanceForNewSchedule(newTT);

  // If user chose a specific batch during preview, update profile batch
  if (selectedTimetablePreviewBatch && selectedTimetablePreviewBatch !== 'all') {
    liveProfile.batch = selectedTimetablePreviewBatch;
    safeSetStorage(KEY_PROFILE, liveProfile);
    syncToCloud();
  }

  const subjectSync = syncSubjectsAfterTimetableSave(newTT);

  document.getElementById('tt-preview-backdrop')?.remove();
  showToast(`Timetable saved! ${toSave.length} classes loaded${selectedTimetablePreviewBatch !== 'all' ? ` for Batch ${selectedTimetablePreviewBatch}` : ''}.`, "success");
  renderPage(state.currentPage);
  if (subjectSync.stale.length) showStaleSubjectsModal(subjectSync.stale);
  if (!hadClasses && hasAnyTimetable()) maybeOfferClosedAppReminders();
};

// The subjects a saved timetable actually teaches, keyed by canonical key.
// Free/break slots and names that are only a room, teacher, batch or OCR
// scrap are left out, matching what getSubjectList would show.
function getTimetableSubjectMap(tt) {
  const map = new Map();
  Object.values(tt || {}).forEach(day => {
    (day || []).forEach(c => {
      if (!isTeachingClass(c) || !c.subject) return;
      const name = getCanonicalSubjectName(c.subject);
      // "General" is what the "General Subject" scan placeholder normalizes to.
      if (!name || isLikelyGarbledSubjectName(name) || name.toLowerCase() === 'general') return;
      const key = getCanonicalSubjectKey(name);
      if (!key || map.has(key)) return;
      map.set(key, { key, name, code: getCanonicalSubjectCode(c.subject, c.code) });
    });
  });
  return map;
}

// Runs once after a scanned timetable is confirmed, so Subject Hub and
// Study Vault follow the scan:
//  1. a subject the student hid earlier comes back if the new scan has it;
//  2. every scanned subject gets a Study Vault folder (existing folders and
//     their files are never touched);
//  3. subjects that are NOT in the new timetable are returned so the
//     student can choose to hide them. Nothing is hidden or removed here.
function syncSubjectsAfterTimetableSave(newTT) {
  const scanned = getTimetableSubjectMap(newTT);
  if (!scanned.size) return { added: 0, stale: [] };

  const hidden = safeGetStorage(KEY_HIDDEN_SUBJECTS, []) || [];
  const keptHidden = hidden.filter(k => !scanned.has(k));
  if (keptHidden.length !== hidden.length) safeSetStorage(KEY_HIDDEN_SUBJECTS, keptHidden);

  const links = loadCustomLinks();
  const linkKeys = new Set(links.map(l => getCanonicalSubjectKey(l.subject || '')).filter(Boolean));
  let added = 0;
  scanned.forEach(s => {
    if (linkKeys.has(s.key)) return;
    links.push({ subject: s.name, code: s.code || s.name.slice(0, 4).toUpperCase(), color: '#394B63', resources: [] });
    linkKeys.add(s.key);
    added++;
  });
  if (added || keptHidden.length !== hidden.length) {
    if (added) safeSetStorage(KEY_CUSTOM_LINKS, links);
    syncToCloud();
  }

  const baselines = loadAttendanceBaselines();
  const baselineKeys = new Set(Object.entries(baselines || {}).map(([k, b]) =>
    getCanonicalSubjectKey((b && typeof b === 'object' && b.subjectName) || k)).filter(Boolean));

  const stale = getSubjectList()
    .filter(s => !scanned.has(getCanonicalSubjectKey(s.name)))
    .map(s => {
      const key = getCanonicalSubjectKey(s.name);
      let held = baselineKeys.has(key) ? 1 : 0;
      try {
        const att = getSubjectAttendance(s) || {};
        held = Math.max(held, Number(att.held || att.total || 0));
      } catch (e) { held = 0; }
      const vaultFiles = links
        .filter(l => getCanonicalSubjectKey(l.subject || '') === key)
        .reduce((n, l) => n + ((l.resources || []).length), 0);
      return { key, name: s.name, hasAttendance: held > 0, vaultFiles };
    });

  return { added, stale };
}

let pendingStaleSubjects = [];

function showStaleSubjectsModal(stale) {
  pendingStaleSubjects = stale.slice();
  document.getElementById('stale-subjects-backdrop')?.remove();

  const rows = pendingStaleSubjects.map((s, i) => {
    const notes = [];
    if (s.hasAttendance) notes.push('has attendance');
    if (s.vaultFiles) notes.push(`${s.vaultFiles} vault file${s.vaultFiles !== 1 ? 's' : ''} kept`);
    return `
      <label class="stale-subject-row" for="stale-subj-${i}">
        <input type="checkbox" id="stale-subj-${i}" ${s.hasAttendance ? '' : 'checked'}>
        <span class="stale-subject-name">${escHtml_cd(s.name)}</span>
        ${notes.length ? `<span class="stale-subject-note">${notes.join(' · ')}</span>` : ''}
      </label>`;
  }).join('');

  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop';
  backdrop.id = 'stale-subjects-backdrop';
  backdrop.innerHTML = `
    <div class="modal" onclick="event.stopPropagation()" style="max-width:460px;width:95%">
      <div class="modal-header">
        <div>
          <h2 class="modal-title">Not in your new timetable</h2>
          <div style="font-size:var(--text-sm);color:var(--text-muted);margin-top:2px">
            Hide these from Subject Hub? Their attendance history and vault files are kept.
          </div>
        </div>
        <button class="modal-close" onclick="document.getElementById('stale-subjects-backdrop')?.remove()" aria-label="Close">${icons.x()}</button>
      </div>
      <div class="stale-subject-list">${rows}</div>
      <div style="display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap;margin-top:16px">
        <button class="btn-secondary" onclick="document.getElementById('stale-subjects-backdrop')?.remove()">Keep all</button>
        <button class="btn-primary" onclick="applyStaleSubjectCleanup()">Hide selected</button>
      </div>
    </div>`;
  wireBackdropClickClose(backdrop);
  document.body.appendChild(backdrop);
}

// Hides the chosen subjects (the same non-destructive list the card "X"
// safety net uses) and removes only their EMPTY Study Vault folders. A
// folder with files, attendance records, tasks and baselines stay as they
// are, and a later scan that includes the subject brings it back.
window.applyStaleSubjectCleanup = function() {
  const chosen = pendingStaleSubjects.filter((s, i) => document.getElementById(`stale-subj-${i}`)?.checked);
  document.getElementById('stale-subjects-backdrop')?.remove();
  pendingStaleSubjects = [];
  if (!chosen.length) return;

  const keys = new Set(chosen.map(s => s.key));
  const hidden = safeGetStorage(KEY_HIDDEN_SUBJECTS, []) || [];
  keys.forEach(k => { if (!hidden.includes(k)) hidden.push(k); });
  safeSetStorage(KEY_HIDDEN_SUBJECTS, hidden);

  const links = loadCustomLinks();
  const keptLinks = links.filter(l => !(keys.has(getCanonicalSubjectKey(l.subject || '')) && !(l.resources || []).length));
  if (keptLinks.length !== links.length) safeSetStorage(KEY_CUSTOM_LINKS, keptLinks);

  syncToCloud();
  showToast(`${chosen.length} old subject${chosen.length !== 1 ? 's' : ''} hidden`, 'info');
  renderPage(state.currentPage);
};

function handleAuthError(err) {
  if (!err) return;
  const code = err.code || '';
  const msg  = err.message || '';

  if (code === 'auth/popup-closed-by-user' || code === 'auth/cancelled-popup-request') {
    return;
  }

  if (code === 'auth/popup-blocked') {
    if (confirm("Sign-in popup was blocked by your browser.\n\nClick OK to try signing in with redirect instead.")) {
      loginWithGoogleRedirect();
    }
    return;
  }

  if (code === 'auth/unauthorized-domain') {
    const domain = window.location.hostname;
    alert(`Unauthorized Domain: '${domain}'\n\nTo allow Google Sign-In on this domain:\n1. Open Firebase Console → Authentication → Settings → Authorized Domains.\n2. Add '${domain}' to authorized domains.`);
    return;
  }

  if (code === 'auth/api-key-not-valid' || code === 'auth/invalid-api-key') {
    alert("Firebase API Key Error: The API key for this project is invalid or restricted in Google Cloud Console. Please verify authorized API key restrictions.");
    return;
  }

  if (code === 'auth/operation-not-allowed') {
    alert("Google Sign-In Disabled: Google auth provider is not enabled in Firebase Console.\n\nGo to Firebase Console → Authentication → Sign-in method → Enable Google.");
    return;
  }

  if (code === 'auth/network-request-failed') {
    alert("Network Error: Could not connect to Google Authentication servers. Please check your internet connection and try again.");
    return;
  }

  alert(`Google Sign-In Error (${code || 'unknown'}):\n${msg || 'An unexpected authentication error occurred.'}`);
}

function loginWithGoogle() {
  // Google refuses sign-in inside Instagram/Facebook browsers.
  if (detectDevice().inApp) { showInAppBanner(); return; }
  if (!auth) {
    initFirebase();
  }
  if (!auth) {
    const detail = firebaseInitError || "Firebase Auth service is not loaded.";
    alert(`Google Sign-In Unavailable:\n\n${detail}`);
    return;
  }
  const provider = new firebase.auth.GoogleAuthProvider();
  provider.setCustomParameters({ prompt: 'select_account' });
  trackUsage('signin_started', 'google', detectDevice().inApp ? 'inapp' : 'browser');

  auth.signInWithPopup(provider).then(result => {
    if (result && result.user) {
      trackUsage('signin_done', 'google');
      currentUser = result.user;
      updateSyncUI();
      if (state.currentPage === 'settings') renderSettings();
    }
  }).catch(err => {
    handleAuthError(err);
  });
}

function loginWithGoogleRedirect() {
  if (!auth) initFirebase();
  if (!auth) return;
  const provider = new firebase.auth.GoogleAuthProvider();
  provider.setCustomParameters({ prompt: 'select_account' });
  auth.signInWithRedirect(provider).catch(err => {
    handleAuthError(err);
  });
}

function logoutUser() {
  if (auth) {
    auth.signOut().then(() => {
      currentUser = null;
      updateSyncUI();
      showToast('Signed out of Clarity Desk', 'info');
      renderPage(state.currentPage);
    });
  }
}

// ── Email-link sign-in (no password) ─────────────────────────
// Firebase emails a one-time link. On iPhone that link always opens in
// Safari, which cannot see the home-screen app's storage, so a link is
// never used up without asking: the browser that asked for it finishes
// on its own, any other browser asks first, and the app has a paste box.
const EMAIL_LINK_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
let incomingEmailLink = null;
let emailLinkStartupChecked = false;

function loadEmailLinkPending() {
  const p = safeGetStorage(KEY_EMAIL_LINK_PENDING, null);
  return (p && typeof p === 'object' && typeof p.email === 'string' && EMAIL_LINK_RE.test(p.email)) ? p : null;
}

function isEmailSignInLink(link) {
  try {
    return !!(auth && typeof link === 'string' && link && auth.isSignInWithEmailLink(link));
  } catch (_) {
    return false;
  }
}

// Drop the one-time code from the address bar, keeping the screen (#hash).
function clearEmailLinkFromUrl() {
  if (window.location.search && isEmailSignInLink(window.location.href)) {
    history.replaceState(null, '', window.location.pathname + window.location.hash);
  }
}

function signInMethodLabel(user) {
  const ids = ((user && user.providerData) || []).map(p => p && p.providerId);
  if (ids.includes('google.com')) return 'Google';
  if (ids.includes('password')) return 'email';
  return 'your account';
}

function handleEmailAuthError(err) {
  const code = (err && err.code) || '';
  let msg;
  if (code === 'auth/invalid-action-code' || code === 'auth/expired-action-code') {
    msg = 'This sign-in link has expired or was already used. Ask for a new one.';
  } else if (code === 'auth/invalid-email' || code === 'auth/missing-email') {
    msg = 'That email does not match the link. Use the address the link was sent to.';
  } else if (code === 'auth/invalid-credential' || code === 'auth/invalid-login-credentials' || code === 'auth/wrong-password' || code === 'auth/user-not-found') {
    msg = 'Email or password is wrong. No account yet? Tap Create account.';
  } else if (code === 'auth/email-already-in-use') {
    msg = 'This email already has an account. Sign in instead, or use Forgot password.';
  } else if (code === 'auth/weak-password') {
    msg = 'Use a password of at least 6 characters.';
  } else if (code === 'auth/too-many-requests') {
    msg = 'Too many tries. Wait a few minutes and try again.';
  } else if (code === 'auth/operation-not-allowed') {
    msg = 'Email sign-in is not turned on yet. In Firebase Console, go to Authentication → Sign-in method → Email/Password and turn on Email link.';
  } else if (code === 'auth/unauthorized-continue-uri' || code === 'auth/unauthorized-domain') {
    msg = `'${window.location.hostname}' is not an authorized domain for sign-in in Firebase Console.`;
  } else if (code === 'auth/network-request-failed') {
    msg = 'No internet connection. Connect and try again.';
  } else {
    msg = `Email sign-in failed (${code || 'unknown'}). Try again.`;
  }
  const box = document.getElementById('email-signin-error');
  if (box) { box.textContent = msg; box.style.display = 'block'; }
  showToast(msg, 'error');
}

function showEmailSignInModal(step = 'email') {
  if (!auth) initFirebase();
  if (!auth) {
    alert(`Email Sign-In Unavailable:\n\n${firebaseInitError || 'Firebase Auth service is not loaded.'}`);
    return;
  }
  document.getElementById('email-signin-modal-backdrop')?.remove();
  const pending = loadEmailLinkPending();
  const emailVal = escHtml_cd(pending ? pending.email : '');
  const close = `document.getElementById('email-signin-modal-backdrop')?.remove()`;
  const note = 'font-size:var(--text-sm);color:var(--text-muted);line-height:1.45';
  const emailField = `
    <div class="form-group" style="margin-bottom:0">
      <label class="form-label" for="email-signin-email">Email</label>
      <input type="email" class="form-input" id="email-signin-email" value="${emailVal}" placeholder="you@college.edu" autocomplete="email" inputmode="email">
    </div>`;
  const pasteBox = `
    <div style="border-top:1px solid var(--border);padding-top:12px;display:flex;flex-direction:column;gap:8px">
      <label class="form-label" for="email-signin-paste" style="margin:0">Paste sign-in link</label>
      <div style="${note}">On iPhone, the link in your email opens in Safari. To sign in here instead, press and hold the link, tap Copy, then paste it below.</div>
      <input type="url" class="form-input" id="email-signin-paste" placeholder="https://…" autocomplete="off">
      <button class="btn-secondary" onclick="submitPastedEmailLink()">Sign in with pasted link</button>
    </div>`;

  let title, body, footer;
  if (step === 'sent' && pending) {
    title = 'Check your inbox';
    body = `
      <div style="font-size:var(--text-base);line-height:1.45">We sent a sign-in link to <strong>${emailVal}</strong>. Open it on this device to finish.</div>
      <div style="${note}">Not there? Check your spam folder, or <button type="button" class="dash-more-link" onclick="showEmailSignInModal('email')">send it again</button>.</div>
      ${pasteBox}`;
    footer = `<button class="btn-primary" onclick="${close}">Done</button>`;
  } else if (step === 'incoming' && incomingEmailLink) {
    title = 'Finish signing in';
    body = `
      <div style="font-size:var(--text-base);line-height:1.45">You opened a sign-in link in a browser that did not ask for it. Type the email it was sent to, to sign in here.</div>
      ${emailField}
      <div style="${note}">Using Clarity Desk from your iPhone home screen? It cannot see sign-ins made in Safari. Copy the link instead, open Clarity Desk from your home screen, and paste it in Settings → Sign in with email.</div>`;
    footer = `
      <button class="btn-secondary" onclick="copyIncomingEmailLink()">Copy link for my home-screen app</button>
      <button class="btn-primary" onclick="confirmIncomingEmailLink()">Sign in in this browser</button>`;
  } else if (step === 'password') {
    title = 'Sign in with password';
    body = `
      ${emailField}
      <div class="form-group" style="margin-bottom:0">
        <label class="form-label" for="email-signin-password">Password</label>
        <input type="password" class="form-input" id="email-signin-password" placeholder="At least 6 characters" autocomplete="current-password">
      </div>
      <div style="${note}"><button type="button" class="dash-more-link" onclick="sendPasswordReset()">Forgot password?</button> · <button type="button" class="dash-more-link" onclick="showEmailSignInModal('email')">Use an email link instead</button></div>`;
    footer = `
      <button class="btn-secondary" onclick="passwordSignIn(true)">Create account</button>
      <button class="btn-primary" onclick="passwordSignIn(false)">Sign in</button>`;
  } else {
    title = 'Sign in with email';
    body = `
      <div style="font-size:var(--text-base);color:var(--text-muted);line-height:1.45">We will email you a link. Tap it to sign in. No password needed, and any email works.</div>
      ${emailField}
      <div style="${note}">Prefer a password? <button type="button" class="dash-more-link" onclick="showEmailSignInModal('password')">Sign in with a password</button></div>
      ${pasteBox}`;
    footer = `
      <button class="btn-secondary" onclick="${close}">Cancel</button>
      <button class="btn-primary" id="email-signin-send" onclick="sendEmailSignInLink()">Send link</button>`;
  }

  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop';
  backdrop.id = 'email-signin-modal-backdrop';
  backdrop.innerHTML = `
    <div class="modal" onclick="event.stopPropagation()" style="max-width:440px;width:92vw">
      <div class="modal-header">
        <div style="display:flex;align-items:center;gap:8px">
          <span style="font-size:var(--text-xl)">✉️</span>
          <span class="modal-title">${title}</span>
        </div>
        <button class="modal-close" onclick="${close}" aria-label="Close">${icons.x()}</button>
      </div>
      <div class="modal-body" style="display:flex;flex-direction:column;gap:12px">
        ${body}
        <div id="email-signin-error" role="alert" style="display:none;font-size:var(--text-sm);color:var(--status-error)"></div>
      </div>
      <div class="modal-footer" style="margin-top:16px;display:flex;justify-content:flex-end;flex-wrap:wrap;gap:8px">
        ${footer}
      </div>
    </div>`;
  wireBackdropClickClose(backdrop);
  document.body.appendChild(backdrop);
}

function readEmailSignInInput() {
  const email = (document.getElementById('email-signin-email')?.value || '').trim();
  if (!EMAIL_LINK_RE.test(email)) {
    const box = document.getElementById('email-signin-error');
    if (box) { box.textContent = 'Type a full email address, like you@college.edu.'; box.style.display = 'block'; }
    return null;
  }
  return email;
}

function sendEmailSignInLink() {
  const email = readEmailSignInInput();
  if (!email || !auth) return;
  const btn = document.getElementById('email-signin-send');
  if (btn) { btn.disabled = true; btn.textContent = 'Sending…'; }
  trackUsage('signin_started', 'email_link', detectDevice().inApp ? 'inapp' : 'browser');
  auth.sendSignInLinkToEmail(email, {
    url: window.location.origin + window.location.pathname,
    handleCodeInApp: true
  }).then(() => {
    safeSetStorage(KEY_EMAIL_LINK_PENDING, { email, sentAt: new Date().toISOString() });
    showEmailSignInModal('sent');
  }).catch(err => {
    if (btn) { btn.disabled = false; btn.textContent = 'Send link'; }
    handleEmailAuthError(err);
  });
}

function completeEmailSignIn(email, link) {
  if (!auth) return Promise.resolve(null);
  return auth.signInWithEmailLink(email, link).then(result => {
    trackUsage('signin_done', 'email_link');
    localStorage.removeItem(KEY_EMAIL_LINK_PENDING);
    incomingEmailLink = null;
    clearEmailLinkFromUrl();
    document.getElementById('email-signin-modal-backdrop')?.remove();
    if (result && result.user) {
      currentUser = result.user;
      updateSyncUI();
      if (state.currentPage === 'settings') renderSettings();
    }
    showToast('Signed in. Your desk will sync across your devices.', 'success');
    return result;
  }).catch(err => {
    handleEmailAuthError(err);
    return null;
  });
}

function finishPasswordSignIn(result) {
  trackUsage('signin_done', 'password');
  document.getElementById('email-signin-modal-backdrop')?.remove();
  if (result && result.user) {
    currentUser = result.user;
    updateSyncUI();
    if (state.currentPage === 'settings') renderSettings();
  }
  showToast('Signed in. Your desk will sync across your devices.', 'success');
}

function passwordSignIn(create) {
  const email = readEmailSignInInput();
  if (!email || !auth) return;
  const password = document.getElementById('email-signin-password')?.value || '';
  if (password.length < 6) {
    const box = document.getElementById('email-signin-error');
    if (box) { box.textContent = 'Use a password of at least 6 characters.'; box.style.display = 'block'; }
    return;
  }
  trackUsage('signin_started', create ? 'password_new' : 'password', detectDevice().inApp ? 'inapp' : 'browser');
  const call = create ? auth.createUserWithEmailAndPassword(email, password) : auth.signInWithEmailAndPassword(email, password);
  call.then(finishPasswordSignIn).catch(handleEmailAuthError);
}

function sendPasswordReset() {
  const email = readEmailSignInInput();
  if (!email || !auth) return;
  auth.sendPasswordResetEmail(email).then(() => {
    showToast(`If ${email} has an account, a reset link is on its way. Check spam too.`, 'success');
  }).catch(handleEmailAuthError);
}

function submitPastedEmailLink() {
  const link = (document.getElementById('email-signin-paste')?.value || '').trim();
  if (!isEmailSignInLink(link)) {
    const box = document.getElementById('email-signin-error');
    if (box) { box.textContent = 'That is not a Clarity Desk sign-in link. Copy the whole link from the email.'; box.style.display = 'block'; }
    return;
  }
  const pending = loadEmailLinkPending();
  const email = pending ? pending.email : readEmailSignInInput();
  if (!email) return;
  completeEmailSignIn(email, link);
}

function confirmIncomingEmailLink() {
  const email = readEmailSignInInput();
  if (!email || !incomingEmailLink) return;
  completeEmailSignIn(email, incomingEmailLink);
}

function copyIncomingEmailLink() {
  const link = incomingEmailLink;
  if (!link) return;
  const done = () => showToast('Link copied. Open Clarity Desk from your home screen and paste it in Settings → Sign in with email.', 'success');
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(link).then(done).catch(() => {
      window.prompt('Copy this sign-in link:', link);
    });
  } else {
    window.prompt('Copy this sign-in link:', link);
  }
}

function handleEmailLinkOnStartup() {
  if (emailLinkStartupChecked) return;
  emailLinkStartupChecked = true;
  const link = window.location.href;
  if (!isEmailSignInLink(link)) return;
  const pending = loadEmailLinkPending();
  if (pending) {
    // This browser asked for the link: finish without asking. A failed
    // (expired or used) code is dropped from the address bar too.
    completeEmailSignIn(pending.email, link).then(clearEmailLinkFromUrl);
    return;
  }
  // Another browser asked for it. Keep the link in memory and ask, so it
  // is not used up here when the student wanted it in the home-screen app.
  incomingEmailLink = link;
  clearEmailLinkFromUrl();
  showEmailSignInModal('incoming');
}

const VALID_TASK_TYPES = ['assignment', 'mission', 'general', 'quiz', 'lab', 'project', 'exam', 'study'];

function sanitizeTask(t) {
  if (!t || typeof t !== 'object') return null;

  const rawType = String(t.taskType || t.type || '').toLowerCase();
  const taskType = VALID_TASK_TYPES.includes(rawType) ? rawType : 'assignment';

  const isNoDeadline = !!(t.noDeadline || (taskType === 'mission' && !t.dueDate));

  let finalDueDate = '';
  if (!isNoDeadline) {
    if (typeof t.dueDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(t.dueDate)) {
      finalDueDate = t.dueDate;
    } else {
      finalDueDate = todayStr();
    }
  }

  // Compute the final subject ONCE and reuse it for the code fallback --
  // previously the code fallback re-checked the ORIGINAL t.subject
  // (before the 'General' default was applied), so a task with a blank
  // subject ended up as subject:'General' but code:'OTH': two different-
  // looking labels for the exact same task, which is exactly the kind of
  // "General" vs "Other" duplicate classification that showed up as
  // confusing, redundant filter chips in the UI.
  const finalSubject = String(t.subject || 'General');
  const finalCode = String(t.code || (finalSubject === 'General' ? 'GEN' : finalSubject === 'Mission' ? 'MIS' : 'OTH'));

  // Optional fields added by the WhatsApp import (v192). Only written when
  // present and valid, so every older task keeps exactly its old shape and
  // older app versions just drop them.
  const isHHMM = (v) => typeof v === 'string' && /^([01]\d|2[0-3]):[0-5]\d$/.test(v);
  const extra = {};
  if (t.source === 'whatsapp') extra.source = 'whatsapp';
  if (t.keepInHoliday === true) extra.keepInHoliday = true;
  if (!isNoDeadline && isHHMM(t.startTime)) {
    extra.startTime = t.startTime;
    if (isHHMM(t.endTime) && t.endTime > t.startTime) extra.endTime = t.endTime;
  }

  return {
    id:          String(t.id || `c-${Date.now()}`),
    subject:     finalSubject,
    code:        finalCode,
    title:       String(t.title || 'Untitled Task').slice(0, 150),
    taskType:    taskType,
    noDeadline:  isNoDeadline,
    description: String(t.description !== undefined && t.description !== null ? t.description : '—').slice(0, 500),
    dueDate:     finalDueDate,
    priority:    ['high', 'medium', 'low'].includes(t.priority) ? t.priority : 'medium',
    status:      t.status === 'submitted' ? 'submitted' : 'pending',
    marks:       typeof t.marks === 'number' ? Math.max(0, Math.min(100, t.marks)) : (parseInt(t.marks) || 0),
    isCustom:    true,
    ...extra,
  };
}

let lastCloudPayloadHash = null;

// JSON with object keys sorted at every level. Firestore hands maps back
// with their keys in its own order, so a plain JSON.stringify of the same
// data could differ from what this device wrote and look like a "change".
function stableStringify(v) {
  if (Array.isArray(v)) return `[${v.map(stableStringify).join(',')}]`;
  if (v && typeof v === 'object') {
    return `{${Object.keys(v).sort().filter(k => v[k] !== undefined).map(k => `${JSON.stringify(k)}:${stableStringify(v[k])}`).join(',')}}`;
  }
  return JSON.stringify(v === undefined ? null : v);
}

function calculatePayloadHash(data) {
  try {
    return stableStringify({
      p: data.profile,
      // The whole task list, not just its count: a rename, due-date change
      // or tick made on another device keeps the count the same and used to
      // be ignored. Run through sanitizeTask so a cloud copy (already
      // sanitized) and this device's list compare in the same shape. Any
      // failure here falls to the outer catch -> null -> the snapshot is
      // applied, never skipped.
      t: Array.isArray(data.customTasks)
        ? data.customTasks.map(t => (t && t.id ? sanitizeTask(t) : t))
        : null,
      tc: data.timetableChoice || null,
      syl: Array.isArray(data.syllabus) && data.syllabus.length ? data.syllabus : null,
      np: data.notificationPrefs || null,
      nc: data.noticeChannels || null,
      tg: typeof data.attTarget === 'number' ? data.attTarget : null,
      // Full timetable and attendance, not just a day count: a mark or a
      // timetable edit made on another device must reach this one (it used
      // to be ignored until something else changed, even across reloads).
      tt: data.customTimetable || null,
      a: data.assignmentStatuses,
      att: data.attendance || null,
      attB: data.attendanceBaseline || null,
      attL: data.attendanceLive || null,
      hol: data.holiday || null
      // theme deliberately excluded: it's applied via initTheme()/CSS
      // variables, never needs a dashboard rebuild, and including it here
      // was causing every theme switch (and the first cloud echo after
      // a refresh) to force a full renderPage() -- the visible "flicker"
      // in the masthead/stat tiles.
    });
  } catch (e) {
    return null;
  }
}

function subscribeUserCloudData(uid) {
  if (!db || !uid) return;
  if (cloudUnsubscribe) cloudUnsubscribe();

  // Seed the dedup hash with the CURRENT local state (already rendered by
  // the synchronous boot render) instead of leaving it null. Previously,
  // every page refresh reset this to null, so the first cloud response
  // (cache read or server snapshot) always looked "different" and forced
  // a redundant renderPage() even when local storage already matched the
  // cloud exactly -- a second, needless rebuild right after the first
  // paint, visible as the masthead/stat tiles flickering in and out.
  lastCloudPayloadHash = calculatePayloadHash({
    profile: loadProfile(),
    customTasks: state.customTasks,
    customTimetable: safeGetStorage(KEY_CUSTOM_TIMETABLE, null),
    timetableChoice: safeGetStorage(KEY_TIMETABLE_CHOICE, null),
    syllabus: loadSyllabus(),
    notificationPrefs: safeGetStorage(KEY_NOTIF_PREFS, null),
    noticeChannels: safeGetStorage(KEY_NOTICE_CHANNELS, null),
    attTarget: getAttendanceTarget(),
    assignmentStatuses: safeGetStorage(KEY_ASSIGNMENTS, {}),
    attendance: safeGetStorage(KEY_ATTENDANCE, {}),
    attendanceBaseline: safeGetStorage(KEY_ATTENDANCE_BASELINE, {}),
    attendanceLive: safeGetStorage(KEY_ATTENDANCE_LIVE, {}),
    holiday: safeGetStorage(KEY_HOLIDAY, null)
  });

  const userRef = db.collection('users').doc(uid);

  // Cache-First Read: Immediate IndexedDB cache hit (0ms UI latency, 0 server reads)
  userRef.get({ source: 'cache' }).then(doc => {
    if (doc && doc.exists) {
      const data = doc.data() || {};
      const currentHash = calculatePayloadHash(data);
      // Same dedup as the server listener below -- without this, every
      // resubscribe (e.g. the app regaining visibility after being
      // backgrounded) unconditionally re-applied the cached doc and
      // rebuilt the current page's DOM even when nothing had changed,
      // which is what made the dashboard cards look like they were
      // popping in and out.
      if (currentHash && currentHash === lastCloudPayloadHash) return;
      lastCloudPayloadHash = currentHash;
      applyCloudDataToLocalState(data);
    }
  }).catch(() => {});

  // Server Listener with metadata echo filter
  cloudUnsubscribe = userRef.onSnapshot({ includeMetadataChanges: false }, doc => {
    if (!doc || !doc.exists) {
      pushLocalDataToCloud(uid);
      return;
    }

    // Skip parsing and UI re-renders on local pending write echo events
    if (doc.metadata && doc.metadata.hasPendingWrites) return;

    const data = doc.data() || {};
    const currentHash = calculatePayloadHash(data);
    if (currentHash && currentHash === lastCloudPayloadHash) return;
    lastCloudPayloadHash = currentHash;

    applyCloudDataToLocalState(data);
  }, err => {
    if (err.code === 'permission-denied') {
      updateSyncUI('denied');
      console.warn("Firestore access denied by Security Rules.");
    } else {
      console.warn("Cloud snapshot error:", err);
    }
  });
}

function applyCloudDataToLocalState(data) {
  if (!data || typeof data !== 'object') return;
  if (data.profile && typeof data.profile === 'object') {
    // Merge onto the current local profile instead of replacing it whole.
    // Two real bugs lived here: `batch` was never in this list at all, so
    // every cloud sync (including the one that fires right after this
    // device's own save) silently wiped whatever batch the user had just
    // set -- it simply never made the round trip. And because this built
    // a brand-new object from scratch, any field the cloud snapshot didn't
    // have (or hadn't caught up on yet) overwrote a fresher local value
    // with nothing instead of leaving it alone. Each field below now only
    // overwrites the local value when the incoming data actually has one.
    const cleanProfile = { ...loadProfile() };
    const applyIfPresent = (key, maxLen) => {
      const val = data.profile[key];
      if (val !== undefined && val !== null && String(val).trim()) {
        cleanProfile[key] = String(val).slice(0, maxLen);
      }
    };
    applyIfPresent('name', 80);
    applyIfPresent('college', 100);
    applyIfPresent('branch', 100);
    applyIfPresent('year', 50);
    applyIfPresent('rollNo', 50);
    applyIfPresent('batch', 30);
    applyIfPresent('examDate', 20);
    applyIfPresent('examLabel', 30);
    applyIfPresent('studyMode', 10);
    safeSetStorage(KEY_PROFILE, cleanProfile);
  }
  if (Array.isArray(data.customTasks)) {
    state.customTasks = data.customTasks.map(sanitizeTask).filter(Boolean);
    safeSetStorage(KEY_CUSTOM_TASKS, state.customTasks);
  }
  if (data.customTimetable && typeof data.customTimetable === 'object') {
    safeSetStorage(KEY_CUSTOM_TIMETABLE, data.customTimetable);
  }
  if (data.timetableChoice && typeof data.timetableChoice === 'string') {
    safeSetStorage(KEY_TIMETABLE_CHOICE, data.timetableChoice);
  }
  if (Array.isArray(data.customLinks)) {
    // Merge, never replace: the cloud holds placeholders for files that
    // live only on this device.
    safeSetStorage(KEY_CUSTOM_LINKS, mergeCloudLinks(data.customLinks, safeGetStorage(KEY_CUSTOM_LINKS, [])));
  }
  if (Array.isArray(data.syllabus)) {
    safeSetStorage(KEY_SYLLABUS, sanitizeSyllabus(data.syllabus));
  }
  if (data.assignmentStatuses && typeof data.assignmentStatuses === 'object') {
    safeSetStorage(KEY_ASSIGNMENTS, data.assignmentStatuses);
    state.assignments = loadAssignments();
  }
  if (data.attendance && typeof data.attendance === 'object') {
    safeSetStorage(KEY_ATTENDANCE, data.attendance);
    if (fixShiftedAttendanceDates() > 0) syncToCloud();
  }
  if (data.attendanceBaseline && typeof data.attendanceBaseline === 'object') {
    safeSetStorage(KEY_ATTENDANCE_BASELINE, data.attendanceBaseline);
  }
  if (data.attendanceLive && typeof data.attendanceLive === 'object') {
    safeSetStorage(KEY_ATTENDANCE_LIVE, data.attendanceLive);
  }
  // What the cloud has now: the base the next push diffs against, so a mark
  // another device added is never mistaken for one deleted here.
  rememberSyncedAttendance();
  if (data.theme && typeof data.theme === 'string') {
    let cloudTheme = data.theme;
    if (LEGACY_THEME_MAP[cloudTheme]) cloudTheme = LEGACY_THEME_MAP[cloudTheme];
    const localTheme = localStorage.getItem(KEY_THEME);
    
    // If local theme is not set yet, adopt cloud theme. (There used to be
    // an "else" branch here that wrote the LOCAL theme back to the cloud
    // whenever it differed from what a snapshot just delivered, on the
    // theory that "local wins". That's the actual cause of dashboard
    // content re-rendering with no click involved at all: with two
    // clients signed into the same account (e.g. a phone and this PC,
    // both used across this whole debugging session), each one saw the
    // OTHER's theme as a "stale" cloud value and wrote its own theme back
    // -- which the other client then saw as a fresh change and wrote
    // back again, forever, each write's round trip forcing a real
    // dashboard rebuild on both ends every few seconds with nobody
    // touching anything. A device's own explicit theme toggle already
    // pushes to the cloud instantly from setTheme() -- this reconciling
    // write-back was never needed for that case and only actively harmful
    // for the multi-device case, so it's gone. A cloud value that differs
    // from local now just leaves this device's local choice alone.
    if (!localTheme && ALL_THEMES.includes(cloudTheme)) {
      localStorage.setItem(KEY_THEME, cloudTheme);
      initTheme();
    }
  }
  if (data.accent && typeof data.accent === 'string') {
    const localAccent = localStorage.getItem(KEY_ACCENT);
    if (!localAccent && ALL_ACCENTS.includes(data.accent)) {
      localStorage.setItem(KEY_ACCENT, data.accent);
      initAccent();
    }
  }
  if (data.notificationPrefs && typeof data.notificationPrefs === 'object') {
    safeSetStorage(KEY_NOTIF_PREFS, data.notificationPrefs);
  }
  if (data.noticeChannels && typeof data.noticeChannels === 'object') {
    safeSetStorage(KEY_NOTICE_CHANNELS, data.noticeChannels);
  }
  if (typeof data.attTarget === 'number' && data.attTarget >= 50 && data.attTarget <= 100) {
    safeSetStorage(KEY_ATT_TARGET, data.attTarget);
  }
  if (data.holiday && typeof data.holiday === 'object' && !Array.isArray(data.holiday)) {
    safeSetStorage(KEY_HOLIDAY, data.holiday);
    checkHolidayExpiry();
  }
  updateTopbarProfile();
  setupFABDrag();
  updateNavBadges();
  if (['settings', 'assignments', 'dashboard', 'notices', 'timetable', 'review', 'subjects', 'calendar'].includes(state.currentPage)) {
    renderPage(state.currentPage);
  }
}

let syncDebounceTimer = null;

function pushLocalDataToCloud(uid) {
  if (!db || !uid) return;
  const sanitizedTasks = state.customTasks.map(sanitizeTask).filter(Boolean);
  const payload = {
    profile:            loadProfile(),
    customTasks:        sanitizedTasks,
    customTimetable:    safeGetStorage(KEY_CUSTOM_TIMETABLE, null),
    timetableChoice:    safeGetStorage(KEY_TIMETABLE_CHOICE, null),
    // Uploaded files stay on this device; the cloud gets placeholders.
    customLinks:        linksForCloud(safeGetStorage(KEY_CUSTOM_LINKS, null)),
    assignmentStatuses: safeGetStorage(KEY_ASSIGNMENTS, {}),
    attendance:         safeGetStorage(KEY_ATTENDANCE, {}),
    attendanceBaseline: safeGetStorage(KEY_ATTENDANCE_BASELINE, {}),
    attendanceLive:     safeGetStorage(KEY_ATTENDANCE_LIVE, {}),
    syllabus:           loadSyllabus(),
    theme:              localStorage.getItem(KEY_THEME) || 'paper-slate',
    accent:             localStorage.getItem(KEY_ACCENT) || 'terracotta',
    notificationPrefs:  safeGetStorage(KEY_NOTIF_PREFS, null),
    noticeChannels:     safeGetStorage(KEY_NOTICE_CHANNELS, null),
    attTarget:          getAttendanceTarget(),
    attSummary:         buildAttendanceCloudSummary(),
    holiday:            safeGetStorage(KEY_HOLIDAY, null),
    updatedAt:          firebase.firestore.FieldValue.serverTimestamp()
  };
  // Mark this write's hash as already-seen so its own ack echo (which
  // comes back through onSnapshot once the server confirms it) isn't
  // mistaken for an incoming remote change and doesn't trigger a needless
  // full re-render of whatever page is currently open.
  lastCloudPayloadHash = calculatePayloadHash(payload);
  const ref = db.collection('users').doc(uid);
  const deletes = computeSyncDeletePaths(safeGetStorage(KEY_SYNC_LAST_PUSHED, null), payload);
  ref.set(payload, { merge: true }).then(onCloudPushOk).catch(onCloudPushError);
  // set(merge:true) never removes a map key, so a cleared mark used to come
  // back from the cloud on the next sync. Delete exactly the paths that were
  // in the last synced copy and are gone now (queued offline like any write).
  if (deletes.length) {
    const FV = firebase.firestore.FieldValue, FP = firebase.firestore.FieldPath;
    for (let i = 0; i < deletes.length; i += 400) {
      const args = [];
      deletes.slice(i, i + 400).forEach(p => args.push(new FP(...p), FV.delete()));
      ref.update(...args).catch(err => console.warn('Cloud delete error:', err));
    }
  }
  rememberSyncedAttendance(payload);
}

// ── Sync deletions (step 5) ─────────────────────────────────────
// Local-only: the three attendance maps as last pushed to / received from
// the cloud. Missing (first push after the update, a new device): no
// deletes are sent, so nothing in the cloud can be removed by mistake.
function rememberSyncedAttendance(src) {
  const from = src || {
    attendance: safeGetStorage(KEY_ATTENDANCE, {}),
    attendanceBaseline: safeGetStorage(KEY_ATTENDANCE_BASELINE, {}),
    attendanceLive: safeGetStorage(KEY_ATTENDANCE_LIVE, {})
  };
  safeSetStorage(KEY_SYNC_LAST_PUSHED, {
    attendance: from.attendance || {},
    attendanceBaseline: from.attendanceBaseline || {},
    attendanceLive: from.attendanceLive || {}
  });
}

// Paths in `prev` that are gone from `cur`: [field, date(, classKey)] in
// attendance, [field, key] in the baseline and +1 maps. A map that is now
// completely empty while the last copy had data is skipped: that looks like
// a failed read or a wipe, not a student's edit.
function computeSyncDeletePaths(prev, cur) {
  const isObj = (o) => !!o && typeof o === 'object' && !Array.isArray(o);
  if (!isObj(prev) || !isObj(cur)) return [];
  const paths = [];
  const pa = isObj(prev.attendance) ? prev.attendance : {};
  const ca = isObj(cur.attendance) ? cur.attendance : {};
  if (Object.keys(ca).length || !Object.keys(pa).length) {
    Object.keys(pa).forEach(date => {
      if (!isObj(ca[date])) { paths.push(['attendance', date]); return; }
      if (!isObj(pa[date])) return;
      Object.keys(pa[date]).forEach(k => { if (!(k in ca[date])) paths.push(['attendance', date, k]); });
    });
  }
  ['attendanceBaseline', 'attendanceLive'].forEach(f => {
    const p = isObj(prev[f]) ? prev[f] : {};
    const c = isObj(cur[f]) ? cur[f] : {};
    if (!Object.keys(c).length && Object.keys(p).length > 1) return;
    Object.keys(p).forEach(k => { if (!(k in c)) paths.push([f, k]); });
  });
  return paths;
}

// ── Notice Channels (Official & WhatsApp Links) ───────────────
// NOTE: the whatsappTitle/whatsappUrl field names predate this card's
// current purpose (it used to open a WhatsApp class group; it's now the
// ERP Portal link) and are kept as-is on purpose so anyone who
// already configured a link under the old card keeps it instead of it
// silently disappearing under a renamed key.
function loadNoticeChannels() {
  const saved = safeGetStorage(KEY_NOTICE_CHANNELS, null);
  if (saved && typeof saved === 'object') {
    return {
      officialTitle: (saved.officialTitle || 'Official Updates').trim(),
      officialUrl:   (saved.officialUrl || '').trim(),
      whatsappTitle: (saved.whatsappTitle || 'ERP Portal').trim(),
      whatsappUrl:   (saved.whatsappUrl || '').trim()
    };
  }
  return {
    officialTitle: 'Official Updates',
    officialUrl:   '',
    whatsappTitle: 'ERP Portal',
    whatsappUrl:   ''
  };
}

function saveNoticeChannels(channels) {
  safeSetStorage(KEY_NOTICE_CHANNELS, channels);
  syncToCloud();
}

function showNoticeChannelModal(targetKey) {
  document.getElementById('notice-channel-modal-backdrop')?.remove();
  const channels = loadNoticeChannels();
  const isOfficial = targetKey === 'official';
  const currentTitle = isOfficial ? channels.officialTitle : channels.whatsappTitle;
  const currentUrl   = isOfficial ? channels.officialUrl : channels.whatsappUrl;

  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop';
  backdrop.id = 'notice-channel-modal-backdrop';
  backdrop.innerHTML = `
    <div class="modal" onclick="event.stopPropagation()" style="max-width:460px;width:92vw">
      <div class="modal-header">
        <div style="display:flex;align-items:center;gap:8px">
          <span style="font-size:var(--text-xl)">${isOfficial ? icons.bell() : icons.graduation()}</span>
          <span class="modal-title">${isOfficial ? 'Configure Notice Source' : 'Configure ERP Portal Link'}</span>
        </div>
        <button class="modal-close" onclick="document.getElementById('notice-channel-modal-backdrop')?.remove()">${icons.x()}</button>
      </div>
      <div class="modal-body" style="display:flex;flex-direction:column;gap:14px">
        <div style="font-size:var(--text-base);color:var(--text-muted);line-height:1.45">
          ${isOfficial 
            ? 'Set your college portal link, class channel, or department notice page URL.' 
            : 'Add your college ERP or student portal link for attendance, marks, fees and exam forms. Tapping the card opens it directly.'}
        </div>
        <div class="form-group" style="margin-bottom:0">
          <label class="form-label">${isOfficial ? 'Card Title' : 'Portal Title'}</label>
          <input type="text" class="form-input" id="nc-modal-title" value="${(currentTitle || '').replace(/"/g, '&quot;')}" placeholder="${isOfficial ? 'e.g. Official Updates or Department Portal' : 'e.g. ERP Portal'}">
        </div>
        <div class="form-group" style="margin-bottom:0">
          <label class="form-label">${isOfficial ? 'Destination Link / URL' : 'Portal Link / URL'}</label>
          <input type="url" class="form-input" id="nc-modal-url" value="${(currentUrl || '').replace(/"/g, '&quot;')}" placeholder="${isOfficial ? 'https://college.edu/notices' : 'https://erp.yourcollege.edu'}">
        </div>
        ${!isOfficial ? `
          <div style="font-size:var(--text-sm);color:var(--text-muted);background:var(--surface-2);border:1px solid var(--border);border-radius:var(--radius-xs,6px);padding:8px 10px;line-height:1.4">
            💡 <strong>Tip:</strong> This just opens your portal in a new tab. You sign in there as usual, and Clarity Desk never sees your ERP password.
          </div>
        ` : ''}
      </div>
      <div class="modal-footer" style="margin-top:16px;display:flex;justify-content:flex-end;gap:8px">
        <button class="btn-secondary" onclick="document.getElementById('notice-channel-modal-backdrop')?.remove()">Cancel</button>
        <button class="btn-primary" onclick="submitNoticeChannelModal('${targetKey}')">Save Changes</button>
      </div>
    </div>
  `;
  wireBackdropClickClose(backdrop);
  document.body.appendChild(backdrop);
}

function submitNoticeChannelModal(targetKey) {
  const titleEl = document.getElementById('nc-modal-title');
  const urlEl   = document.getElementById('nc-modal-url');
  const title   = (titleEl ? titleEl.value : '').trim();
  const url     = (urlEl ? urlEl.value : '').trim();

  const channels = loadNoticeChannels();
  if (targetKey === 'official') {
    channels.officialTitle = title || 'Official Updates';
    channels.officialUrl   = url;
  } else {
    channels.whatsappTitle = title || 'ERP Portal';
    channels.whatsappUrl   = url;
  }

  saveNoticeChannels(channels);
  document.getElementById('notice-channel-modal-backdrop')?.remove();
  showToast('Notice source updated ✓', 'success');
  if (state.currentPage === 'notices') renderNotices();
  if (state.currentPage === 'settings') renderSettings();
}

function handleNoticeSourceClick(targetKey) {
  const channels = loadNoticeChannels();
  const url = targetKey === 'official' ? channels.officialUrl : channels.whatsappUrl;
  if (url && (url.startsWith('http://') || url.startsWith('https://') || url.startsWith('tg://') || url.startsWith('whatsapp://'))) {
    window.open(url, '_blank', 'noopener,noreferrer');
  } else {
    showToast(targetKey === 'official' ? 'Configure your official notice link' : 'Add your ERP portal link to enable quick access', 'info');
    showNoticeChannelModal(targetKey);
  }
}

// ── Custom Quick Links / Resources ───────────────────────────
function loadCustomLinks() {
  const saved = safeGetStorage(KEY_CUSTOM_LINKS, null);
  if (Array.isArray(saved)) return saved;
  // QUICK_LINKS in data.js is this app's own author's personal SY-AIDS
  // resource bookmarks -- only seed it for a user who explicitly opted
  // into that same official timetable during onboarding (reuses the same
  // flag loadTimetable() checks). Previously this seeded every visitor
  // regardless of course, showing one student's own subjects/links to
  // everyone who installs the app.
  const choice = safeGetStorage(KEY_TIMETABLE_CHOICE, null);
  if (choice === 'aids') {
    return JSON.parse(JSON.stringify(QUICK_LINKS));
  }
  return [];
}

// True only when the vault really was saved; sync runs only then.
function saveCustomLinks(links) {
  if (!safeSetStorage(KEY_CUSTOM_LINKS, links)) return false;
  syncToCloud();
  return true;
}

// ── Study Vault files stay on this device ────────────────────
// An uploaded file is stored as a data: URL inside cos_custom_links. The
// cloud copy carries a placeholder instead ({ url: '', onDevice, fileId }),
// because the whole desk syncs as one Firestore record (1 MiB limit) and
// one big file used to stop sync for everything. fileId is worked out from
// the file itself, so the device that has the file finds it again even
// after another device renames the placeholder.
const VAULT_FILE_MAX_BYTES = 1024 * 1024;
const VAULT_FULL_MESSAGE = 'Not saved: Clarity Desk’s storage on this phone is full. Remove a file from the vault or add this as a link.';

function vaultFileTooBigMessage(bytes) {
  const max = vaultFileMaxBytes();
  if (!(bytes > max)) return '';
  return `This file is ${(bytes / 1048576).toFixed(1)} MB. Files up to ${max / 1048576} MB can be saved on this device. For bigger notes, upload to Google Drive and add the link instead.`;
}

function isVaultDeviceFile(r) {
  return !!r && typeof r.url === 'string' && r.url.startsWith('data:');
}

function isVaultPlaceholder(r) {
  return !!r && r.onDevice === true && !r.url;
}

// FNV-1a over the data: URL plus its length. Same file, same id, on any device.
function vaultFileId(url) {
  let h = 0x811c9dc5;
  for (let i = 0; i < url.length; i++) { h ^= url.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return `f${h.toString(16)}-${url.length}`;
}

// Same placeholder for a data: URL file and an IndexedDB file, so the cloud
// copy doesn't change when a file moves into IndexedDB.
function vaultPlaceholder(r) {
  const { url, idb, bytes, mime, fileId, onDevice, ...rest } = r;
  return { ...rest, url: '', onDevice: true, fileId: fileId || vaultFileId(url) };
}

// What goes to the cloud: links as they are, files as placeholders.
function linksForCloud(links) {
  if (!Array.isArray(links)) return links;
  return links.map(s => (s && Array.isArray(s.resources))
    ? { ...s, resources: s.resources.map(r => (isVaultDeviceFile(r) || isVaultIdbFile(r)) ? vaultPlaceholder(r) : r) }
    : s);
}

// What to keep from the cloud: its list, but every placeholder this
// device has the file for gets that file back. Never drops a local file
// the cloud still lists.
function mergeCloudLinks(cloudLinks, localLinks) {
  if (!Array.isArray(cloudLinks)) return cloudLinks;
  const files = new Map();
  (Array.isArray(localLinks) ? localLinks : []).forEach(s => (s && Array.isArray(s.resources) ? s.resources : []).forEach(r => {
    if (isVaultDeviceFile(r)) files.set(r.fileId || vaultFileId(r.url), r);
    else if (isVaultIdbFile(r)) files.set(r.fileId, r);
  }));
  return cloudLinks.map(s => (s && Array.isArray(s.resources))
    ? { ...s, resources: s.resources.map(r => {
        if (!isVaultPlaceholder(r) || !r.fileId || !files.has(r.fileId)) return r;
        // Back to the exact local shape: the id is worked out from the file.
        const { onDevice, fileId, ...rest } = r;
        const local = files.get(fileId);
        if (isVaultIdbFile(local)) return { ...rest, url: '', fileId, idb: true, bytes: local.bytes, mime: local.mime };
        return { ...rest, url: local.url };
      }) }
    : s);
}

// Restore: save the backup's vault; if its files don't fit on this phone,
// turn the biggest into placeholders until it does. The backup file itself
// is untouched. Returns { ok, dropped: [labels] }.
function saveLinksFittingStorage(links) {
  if (safeSetStorage(KEY_CUSTOM_LINKS, links)) return { ok: true, dropped: [] };
  const copy = (Array.isArray(links) ? links : []).map(s => (s && Array.isArray(s.resources)) ? { ...s, resources: [...s.resources] } : s);
  const spots = [];
  copy.forEach((s, si) => (s && Array.isArray(s.resources) ? s.resources : []).forEach((r, ri) => { if (isVaultDeviceFile(r)) spots.push({ si, ri, len: r.url.length }); }));
  spots.sort((x, y) => y.len - x.len);
  const dropped = [];
  for (const { si, ri } of spots) {
    const r = copy[si].resources[ri];
    dropped.push(r.label || 'file');
    copy[si].resources[ri] = vaultPlaceholder(r);
    if (safeSetStorage(KEY_CUSTOM_LINKS, copy)) return { ok: true, dropped };
  }
  return { ok: false, dropped };
}

// ── Study Vault files in IndexedDB (v229) ────────────────────
// File bytes live in IndexedDB (db cos_vault, store files, key fileId); the
// vault entry in cos_custom_links keeps the details:
//   { label, url: '', icon, isUpload, fileSize, fileId, idb: true, bytes, mime }
// It stays on this device: the cloud gets the same placeholder as before.
// If IndexedDB can't be used, files stay data: URLs with the 1 MB limit.
const VAULT_IDB_MAX_BYTES = 10 * 1024 * 1024;
const VAULT_BACKUP_FILE_CAP = 30 * 1024 * 1024;
const VAULT_NO_ROOM_MESSAGE = 'Not saved: there is no room left on this phone for this file. Remove a file from the vault or add it as a link.';
const VAULT_MISSING_MESSAGE = 'This file is missing on this device. Add it again or restore it from a backup.';
let vaultIdbOk = null;       // null = not known yet, then true / false
let _vaultIdb = null;        // Promise of the open database (or null)
let _vaultBlobIds = null;    // fileIds stored in IndexedDB, once known

function isVaultIdbFile(r) {
  return !!r && r.idb === true && /^[a-z0-9-]{1,40}$/i.test(String(r.fileId || '')) && !r.url;
}

function vaultFileMaxBytes() {
  return vaultIdbOk === true ? VAULT_IDB_MAX_BYTES : VAULT_FILE_MAX_BYTES;
}

function vaultIdbMissing(r) {
  return isVaultIdbFile(r) && !!_vaultBlobIds && !_vaultBlobIds.has(r.fileId);
}

// Same FNV-1a, over the file's bytes (a data: URL is never built for it).
function vaultBytesId(bytes) {
  let h = 0x811c9dc5;
  for (let i = 0; i < bytes.length; i++) { h ^= bytes[i]; h = Math.imul(h, 0x01000193) >>> 0; }
  return `b${h.toString(16)}-${bytes.length}`;
}

function vaultIdbStore(db, mode, fn) {
  return new Promise((resolve, reject) => {
    let result;
    const tx = db.transaction('files', mode);
    const req = fn(tx.objectStore('files'));
    req.onsuccess = () => { result = req.result; };
    tx.oncomplete = () => resolve(result);
    tx.onerror = tx.onabort = () => reject(tx.error || req.error || new Error('IndexedDB failed'));
  });
}

function vaultIdbOpen() {
  if (_vaultIdb) return _vaultIdb;
  let idb = null;
  try { idb = typeof indexedDB !== 'undefined' ? indexedDB : null; } catch (_) {}
  if (!idb) { vaultIdbOk = false; _vaultIdb = Promise.resolve(null); return _vaultIdb; }
  _vaultIdb = new Promise(resolve => {
    try {
      const req = idb.open('cos_vault', 1);
      req.onupgradeneeded = () => {
        if (!req.result.objectStoreNames.contains('files')) req.result.createObjectStore('files', { keyPath: 'fileId' });
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(null);
      req.onblocked = () => resolve(null);
    } catch (_) { resolve(null); }
  }).then(async db => {
    if (!db) { vaultIdbOk = false; return null; }
    try {
      _vaultBlobIds = new Set(await vaultIdbStore(db, 'readonly', s => s.getAllKeys()));
      vaultIdbOk = true;
      return db;
    } catch (_) { vaultIdbOk = false; return null; }
  });
  return _vaultIdb;
}

// Saves the blob and reads it back. With `expect` (bytes), the read-back
// copy must match byte for byte. True only when the copy is really there.
async function vaultPutBlob(fileId, blob, expect) {
  const db = await vaultIdbOpen();
  if (!db) return false;
  try {
    await vaultIdbStore(db, 'readwrite', s => s.put({ fileId, blob, bytes: blob.size, mime: blob.type || '', createdAt: Date.now() }));
    const back = await vaultIdbStore(db, 'readonly', s => s.get(fileId));
    if (!back || !back.blob || back.blob.size !== blob.size) return false;
    if (expect) {
      const got = new Uint8Array(await back.blob.arrayBuffer());
      if (got.length !== expect.length) return false;
      for (let i = 0; i < got.length; i++) if (got[i] !== expect[i]) return false;
    }
    _vaultBlobIds.add(fileId);
    return true;
  } catch (_) { return false; }
}

async function vaultGetBlob(fileId) {
  const db = await vaultIdbOpen();
  if (!db) return null;
  try { const rec = await vaultIdbStore(db, 'readonly', s => s.get(fileId)); return (rec && rec.blob) || null; } catch (_) { return null; }
}

// Every fileId the vault, or the declutter undo copy, still points at.
function vaultReferencedIds() {
  const ids = new Set();
  const add = (links) => (Array.isArray(links) ? links : []).forEach(s => (s && Array.isArray(s.resources) ? s.resources : []).forEach(r => {
    if (r && r.fileId) ids.add(r.fileId);
  }));
  add(safeGetStorage(KEY_CUSTOM_LINKS, null));
  const undo = safeGetStorage(KEY_CLEANUP_BACKUP, null);
  if (undo && typeof undo === 'object') add(undo.links);
  return ids;
}

// Removes a blob only when nothing points at it any more (and, for the
// open-time sweep, only when it is over a day old, so an undo still works).
async function vaultDeleteUnusedBlob(fileId, minAgeMs = 0) {
  if (!fileId || vaultReferencedIds().has(fileId)) return;
  const db = await vaultIdbOpen();
  if (!db) return;
  try {
    if (minAgeMs) {
      const rec = await vaultIdbStore(db, 'readonly', s => s.get(fileId));
      if (!rec || !(Date.now() - (rec.createdAt || 0) > minAgeMs)) return;
    }
    if (vaultReferencedIds().has(fileId)) return;
    await vaultIdbStore(db, 'readwrite', s => s.delete(fileId));
    _vaultBlobIds.delete(fileId);
  } catch (_) {}
}

function vaultDataUrlBytes(url) {
  const m = /^data:([^,]*),/i.exec(url);
  if (!m) return null;
  const meta = m[1], body = url.slice(m[0].length);
  const mime = (meta.split(';')[0] || '').trim();
  let bytes;
  if (/;base64$/i.test(meta)) {
    const bin = atob(body);
    bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  } else {
    bytes = new TextEncoder().encode(decodeURIComponent(body));
  }
  return { bytes, mime };
}

function vaultBlobToDataUrl(blob) {
  return new Promise((resolve, reject) => {
    const rd = new FileReader();
    rd.onload = () => resolve(String(rd.result || ''));
    rd.onerror = () => reject(rd.error);
    rd.readAsDataURL(blob);
  });
}

// Copies one data: URL file into IndexedDB and returns the vault entry for
// it, or null (the caller then keeps the data: URL as it is).
async function vaultDataUrlToIdb(r) {
  try {
    const dec = vaultDataUrlBytes(r.url);
    if (!dec) return null;
    const fileId = r.fileId || vaultFileId(r.url);
    if (!(await vaultPutBlob(fileId, new Blob([dec.bytes], { type: dec.mime }), dec.bytes))) return null;
    return { ...r, url: '', fileId, idb: true, bytes: dec.bytes.length, mime: dec.mime };
  } catch (_) { return null; }
}

// Stores a picked File; returns { fileId, bytes, mime } or null.
async function vaultStoreFile(file) {
  try {
    const buf = new Uint8Array(await file.arrayBuffer());
    const fileId = vaultBytesId(buf);
    const mime = file.type || '';
    if (!(_vaultBlobIds && _vaultBlobIds.has(fileId)) && !(await vaultPutBlob(fileId, new Blob([buf], { type: mime })))) return null;
    return { fileId, bytes: buf.length, mime };
  } catch (_) { return null; }
}

function vaultIdbEntry(base, stored) {
  return { ...base, url: '', isUpload: true, fileSize: formatBytes(stored.bytes), fileId: stored.fileId, idb: true, bytes: stored.bytes, mime: stored.mime };
}

function vaultReadDataUrl(file) {
  return new Promise(resolve => {
    const rd = new FileReader();
    rd.onload = () => resolve(String(rd.result || ''));
    rd.onerror = () => resolve('');
    rd.readAsDataURL(file);
  });
}

// Moves old data: URL files into IndexedDB, one at a time. An entry is only
// rewritten after its copy was read back and matched; anything that fails
// keeps its data: URL. The cloud copy doesn't change (same placeholder).
let _vaultMigrating = false;
async function vaultMigrateFiles() {
  if (_vaultMigrating || !(await vaultIdbOpen())) return 0;
  _vaultMigrating = true;
  let moved = 0;
  try {
    const todo = new Map();   // url -> fileId the cloud placeholder already uses
    (safeGetStorage(KEY_CUSTOM_LINKS, null) || []).forEach(s => (s && Array.isArray(s.resources) ? s.resources : []).forEach(r => {
      if (isVaultDeviceFile(r) && !todo.has(r.url)) todo.set(r.url, r.fileId || vaultFileId(r.url));
    }));
    for (const [url, fileId] of todo) {
      const done = await vaultDataUrlToIdb({ url, fileId });
      if (!done) continue;
      const links = safeGetStorage(KEY_CUSTOM_LINKS, null);
      if (!Array.isArray(links)) break;
      let changed = false;
      const next = links.map(s => (s && Array.isArray(s.resources))
        ? { ...s, resources: s.resources.map(r => {
            if (!r || r.url !== url) return r;
            changed = true;
            return { ...r, url: '', fileId, idb: true, bytes: done.bytes, mime: done.mime };
          }) }
        : s);
      if (changed && safeSetStorage(KEY_CUSTOM_LINKS, next)) moved++;
    }
  } finally { _vaultMigrating = false; }
  return moved;
}

// Backup copy of the vault: IndexedDB files go in as data: URLs (the same
// shape old backups have), smallest first, up to VAULT_BACKUP_FILE_CAP.
// The rest become placeholders. `plan` comes from vaultBackupPlan().
async function vaultLinksForBackup(links, plan) {
  const urls = new Map();
  for (const id of plan.include) {
    const blob = await vaultGetBlob(id);
    if (blob) { try { urls.set(id, await vaultBlobToDataUrl(blob)); } catch (_) {} }
  }
  return (Array.isArray(links) ? links : []).map(s => (s && Array.isArray(s.resources))
    ? { ...s, resources: s.resources.map(r => {
        if (!isVaultIdbFile(r)) return r;
        if (!urls.has(r.fileId)) return vaultPlaceholder(r);
        const { idb, bytes, mime, ...rest } = r;
        return { ...rest, url: urls.get(r.fileId) };
      }) }
    : s);
}

function vaultBackupPlan(links) {
  const sizes = new Map();
  (Array.isArray(links) ? links : []).forEach(s => (s && Array.isArray(s.resources) ? s.resources : []).forEach(r => {
    if (isVaultIdbFile(r) && !vaultIdbMissing(r)) sizes.set(r.fileId, { bytes: Number(r.bytes) || 0, label: r.label || 'file' });
  }));
  const include = [], left = [];
  let used = 0, leftBytes = 0;
  [...sizes.entries()].sort((a, b) => a[1].bytes - b[1].bytes).forEach(([id, x]) => {
    if (used + x.bytes <= VAULT_BACKUP_FILE_CAP) { include.push(id); used += x.bytes; }
    else { left.push(x.label); leftBytes += x.bytes; }
  });
  return { include, left, leftBytes, any: sizes.size > 0 };
}

// Restore: put the backup's data: URL files into IndexedDB when possible.
// Files that don't go in stay data: URLs for saveLinksFittingStorage().
async function vaultLinksIntoIdb(links) {
  if (!Array.isArray(links)) return links;
  const out = [];
  for (const s of links) {
    if (!(s && Array.isArray(s.resources))) { out.push(s); continue; }
    const resources = [];
    for (const r of s.resources) resources.push(isVaultDeviceFile(r) ? ((await vaultDataUrlToIdb(r)) || r) : r);
    out.push({ ...s, resources });
  }
  return out;
}

// On open: find out if IndexedDB works, move old files in, tidy up.
function vaultIdbStart() {
  vaultIdbOpen().then(async db => {
    if (!db) return;
    const moved = await vaultMigrateFiles();
    const refs = vaultReferencedIds();
    const missing = (safeGetStorage(KEY_CUSTOM_LINKS, null) || []).some(s => s && Array.isArray(s.resources) && s.resources.some(vaultIdbMissing));
    for (const id of [..._vaultBlobIds]) if (!refs.has(id)) await vaultDeleteUnusedBlob(id, 24 * 3600 * 1000);
    if ((moved || missing) && document.getElementById('vault-grid')) renderVaultGrid();
  }).catch(() => {});
}

window.vaultOpenFile = async function(fileId) {
  let label = 'file';
  (safeGetStorage(KEY_CUSTOM_LINKS, null) || []).forEach(s => (s && Array.isArray(s.resources) ? s.resources : []).forEach(r => {
    if (isVaultIdbFile(r) && r.fileId === fileId) label = r.label || label;
  }));
  const blob = await vaultGetBlob(fileId);
  if (!blob) { showToast(VAULT_MISSING_MESSAGE, 'error'); return; }
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = label;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 60000);
};

function syncToCloud() {
  schedulePushSync();
  if (!currentUser) return;
  clearTimeout(syncDebounceTimer);
  syncDebounceTimer = setTimeout(() => {
    pushLocalDataToCloud(currentUser.uid);
  }, 2500);
}

// Pause active cloud listener when tab is hidden to save Firestore read quota
document.addEventListener('visibilitychange', () => {
  if (!currentUser || !db) return;
  if (document.hidden) {
    if (cloudUnsubscribe) {
      cloudUnsubscribe();
      cloudUnsubscribe = null;
    }
  } else {
    subscribeUserCloudData(currentUser.uid);
  }
});

// ── Notification Preferences & Service ───────────────────────
// ── Notification Preferences & Service ───────────────────────
function loadNotifPrefs() {
  const saved = safeGetStorage(KEY_NOTIF_PREFS, null);
  const defaults = {
    enabled: typeof Notification !== 'undefined' && Notification.permission === 'granted',
    taskUpcoming: "day_before",  // "day_before" | "same_day" | "off"
    taskOverdue: "same_day",     // "same_day" | "instant" | "off"
    classReminders: "15_min",    // "15_min" | "30_min" | "1_hour" | "off"
    attendanceAlerts: "instant", // "instant" | "weekly" | "off"
    newNotices: "instant",       // "instant" | "same_day" | "off"
    dailySummaryTime: "08:00"
  };
  if (saved && typeof saved === 'object') {
    const mapped = { ...defaults, ...saved };
    if (saved.taskUpcoming === true) mapped.taskUpcoming = "day_before";
    if (saved.taskUpcoming === false) mapped.taskUpcoming = "off";
    if (saved.taskOverdue === true) mapped.taskOverdue = "same_day";
    if (saved.taskOverdue === false) mapped.taskOverdue = "off";
    if (saved.noticeMode === 'off') mapped.newNotices = "off";
    if (saved.noticeMode === 'instant') mapped.newNotices = "instant";
    return mapped;
  }
  return defaults;
}

function saveNotifPrefs(prefs) {
  safeSetStorage(KEY_NOTIF_PREFS, prefs);
  syncToCloud();
}

async function requestNotificationPermission() {
  if (typeof Notification === 'undefined') {
    showToast('Notifications not supported by your browser', 'error');
    return false;
  }

  const currentPermission = Notification.permission;
  if (currentPermission === 'denied') {
    showToast('Notifications blocked in browser settings. Please allow in address bar site settings.', 'error');
    const prefs = loadNotifPrefs();
    prefs.enabled = false;
    saveNotifPrefs(prefs);
    if (state.currentPage === 'settings') renderSettings();
    return false;
  }

  try {
    const permission = await Notification.requestPermission();
    const prefs = loadNotifPrefs();
    prefs.enabled = (permission === 'granted');
    saveNotifPrefs(prefs);
    if (permission === 'granted') {
      showToast('Notifications enabled!', 'success');
      dispatchNotification('Clarity Desk Notifications', {
        body: 'You will now receive alerts for class reminders, task deadlines, attendance warnings, and notices.',
        tag: 'welcome-notif'
      });
    } else if (permission === 'denied') {
      showToast('Notifications blocked. Please enable them in browser site settings.', 'error');
    }
    if (state.currentPage === 'settings') renderSettings();
    return permission === 'granted';
  } catch (err) {
    console.warn("Notification permission error:", err);
    return false;
  }
}


// ── Closed-app reminders (Web Push via push-worker/) ──────────
// No sign-in needed. The phone works out its upcoming class and deadline
// reminders (buildUpcomingReminders) and hands just their text and time to
// a free Cloudflare Worker, which sends each one at its moment, even when
// the app is closed. Chats and task descriptions never leave the phone.
// Without push (unsupported, blocked, offline) the in-app check above
// keeps working exactly as before.
// var, not let: syncToCloud() can run during start-up, before this line.
var pushSyncTimer = null;

function loadPushDevice() {
  const d = safeGetStorage(KEY_PUSH_DEVICE, null);
  return d && typeof d === 'object' && !Array.isArray(d) ? d : {};
}

function savePushDevice(patch) {
  safeSetStorage(KEY_PUSH_DEVICE, { ...loadPushDevice(), ...patch });
}

function getPushApiUrl() {
  const raw = typeof window !== 'undefined' ? window.CAMPUS_OS_PUSH_API : null;
  if (typeof raw !== 'string' || !/^https?:\/\/\S+$/i.test(raw.trim())) return null;
  return raw.trim().replace(/\/+$/, '');
}

function closedAppPushSupported() {
  return typeof navigator !== 'undefined' && 'serviceWorker' in navigator &&
    typeof window !== 'undefined' && 'PushManager' in window &&
    typeof Notification !== 'undefined' && !!getPushApiUrl();
}

// Synced reminders cover 14 days; past ~13 without a sync they run out,
// so the in-app check takes over again.
function isClosedAppPushActive() {
  const d = loadPushDevice();
  if (!d.id || !d.lastSyncOk || !d.lastSyncAt) return false;
  if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return false;
  return Date.now() - d.lastSyncAt < 13 * 86400000;
}

function b64urlToBytes(s) {
  const b64 = s.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((s.length + 3) % 4);
  return Uint8Array.from(atob(b64), ch => ch.charCodeAt(0));
}

async function pushApi(path, method, body) {
  const res = await fetch(`${getPushApiUrl()}${path}`, {
    method,
    headers: body ? { 'Content-Type': 'application/json' } : undefined,
    body: body ? JSON.stringify(body) : undefined
  });
  let data = null;
  try { data = await res.json(); } catch (_) {}
  return { status: res.status, ok: res.ok, data };
}

// The server's public push key, fetched once and kept for the session.
// Fetched early (when the sheet opens) so that on iPhone the subscribe step
// can follow the "Allow" tap without a network wait in between.
let _vapidKeyPromise = null;
function fetchVapidKey() {
  if (!_vapidKeyPromise) {
    _vapidKeyPromise = pushApi('/vapid', 'GET').then(r => {
      const key = r.data && r.data.publicKey;
      if (!r.ok || !key) throw new Error('no VAPID key');
      return key;
    }).catch(err => { _vapidKeyPromise = null; throw err; });
  }
  return _vapidKeyPromise;
}

// A phone whose push service never answers would otherwise leave "Turn on"
// silently waiting forever; give up with a clear message instead.
function withTimeout(promise, ms, what) {
  let timer;
  return Promise.race([
    promise,
    new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(`${what} timed out`)), ms); })
  ]).finally(() => clearTimeout(timer));
}
const PUSH_STEP_TIMEOUT_MS = 20000;

// Asks for permission if needed, subscribes this device and syncs.
async function enableClosedAppPush({ quiet = false } = {}) {
  if (!closedAppPushSupported()) {
    if (!quiet) showToast('Reminders when the app is closed are not supported in this browser.', 'error');
    return false;
  }
  const keyPromise = fetchVapidKey();
  keyPromise.catch(() => {}); // handled below; avoids an unhandled rejection while the prompt is up
  if (Notification.permission !== 'granted') {
    if (quiet) return false;
    const granted = await requestNotificationPermission();
    if (!granted) return false;
  }
  try {
    const publicKey = await withTimeout(keyPromise, PUSH_STEP_TIMEOUT_MS, 'push key');
    const reg = await withTimeout(navigator.serviceWorker.ready, PUSH_STEP_TIMEOUT_MS, 'service worker');
    const appKey = b64urlToBytes(publicKey);
    let sub = await reg.pushManager.getSubscription();
    // One push subscription per app. One made with another key (the older
    // Firebase push) can't carry these reminders, so it is replaced.
    const sameKey = (k) => {
      if (!k) return false;
      const a = new Uint8Array(k);
      return a.length === appKey.length && a.every((v, i) => v === appKey[i]);
    };
    if (sub && !sameKey(sub.options && sub.options.applicationServerKey)) {
      await sub.unsubscribe().catch(() => {});
      safeSetStorage(KEY_PUSH_REGISTERED, false);
      sub = null;
    }
    if (!sub) sub = await withTimeout(reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: appKey }), PUSH_STEP_TIMEOUT_MS, 'push sign-up');
    const json = sub.toJSON();
    const d = loadPushDevice();
    const res = await pushApi('/subscribe', 'POST', { device: d.id || null, secret: d.secret || null, endpoint: json.endpoint, keys: json.keys });
    if (!res.ok || !res.data || !res.data.device || !res.data.secret) throw new Error(`subscribe ${res.status}`);
    savePushDevice({ id: res.data.device, secret: res.data.secret, lastSyncOk: false });
    const synced = await syncPushReminders({ retried: true });
    if (!quiet) {
      showToast(synced ? 'Reminders will arrive even when the app is closed ✓' : 'Reminders are on. They will sync when you are back online.', 'success');
      setTimeout(() => showReminderSheet('tips'), 600);
    }
    if (state.currentPage === 'settings') renderSettings();
    return true;
  } catch (err) {
    console.warn('[Push] enable failed:', err);
    if (!quiet) showToast('Couldn’t turn on closed-app reminders right now. In-app reminders still work.', 'error');
    return false;
  }
}

async function disableClosedAppPush() {
  const d = loadPushDevice();
  try {
    if (d.id && d.secret && getPushApiUrl()) await pushApi('/device', 'DELETE', { device: d.id, secret: d.secret });
  } catch (_) {}
  try {
    const reg = await navigator.serviceWorker.ready;
    const sub = await reg.pushManager.getSubscription();
    if (sub) await sub.unsubscribe();
  } catch (_) {}
  savePushDevice({ id: null, secret: null, lastSyncOk: false, lastSyncAt: 0 });
  showToast('Closed-app reminders turned off. In-app reminders still work.', 'info');
  if (state.currentPage === 'settings') renderSettings();
}

// Debounced: called whenever tasks, the timetable or settings change
// (from syncToCloud) and when the app opens. A no-op until push is set up.
function schedulePushSync(delay = 3000) {
  const d = loadPushDevice();
  if (!d.id || !getPushApiUrl()) return;
  clearTimeout(pushSyncTimer);
  pushSyncTimer = setTimeout(() => { syncPushReminders().catch(err => console.warn('[Push] sync failed:', err)); }, delay);
}

async function syncPushReminders({ retried = false } = {}) {
  const d = loadPushDevice();
  if (!d.id || !d.secret || !getPushApiUrl()) return false;
  if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return false;
  if (typeof navigator !== 'undefined' && navigator.onLine === false) return false;
  const res = await pushApi('/sync', 'PUT', { device: d.id, secret: d.secret, reminders: buildUpcomingReminders() });
  if ((res.status === 404 || res.status === 401) && !retried) {
    // The server forgot this device (expired subscription): sign up again.
    savePushDevice({ id: null, secret: null, lastSyncOk: false });
    return enableClosedAppPush({ quiet: true });
  }
  if (res.status === 429) {
    schedulePushSync(12000);
    return false;
  }
  savePushDevice({ lastSyncAt: Date.now(), lastSyncOk: res.ok });
  return res.ok;
}

// ── Reminder permission sheet ─────────────────────────────────
// Offered once, at a moment it is useful (after the first WhatsApp import
// or the first deadline added), never on page load. Picks the step that
// can actually work in this browser.
function reminderSheetMode() {
  if (typeof navigator === 'undefined') return null;
  const ua = navigator.userAgent || '';
  if (isInAppBrowserUA(ua)) return 'inapp';
  const ios = /iPhone|iPad|iPod/i.test(ua) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  const standalone = (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) || navigator.standalone === true;
  if (ios && !standalone) return 'ios-install';
  if (!closedAppPushSupported()) return null;
  if (Notification.permission === 'denied') return 'denied';
  // Laptops and Android label a browser tab's reminders as Chrome/Edge.
  // Offer the install first when the browser can do it, so they arrive as
  // Clarity Desk with its logo. Never required: "Use browser" still works.
  if (!standalone && _installPromptEvent) return 'install';
  return 'ask';
}

// The browser's own install prompt (Chrome/Edge on laptops and Android).
// Kept, not prevented, so Android's own install banner still shows.
let _installPromptEvent = null;
if (typeof window !== 'undefined' && window.addEventListener) {
  window.addEventListener('beforeinstallprompt', (e) => { _installPromptEvent = e; scheduleInstallBanner(1500); });
  window.addEventListener('appinstalled', () => { _installPromptEvent = null; document.getElementById('install-banner')?.remove(); });
}

// Install, then come back to "Turn on" so the permission prompt gets its
// own tap. Installed or not, reminders are one tap away.
async function reminderSheetInstall(fromTips = false) {
  const e = _installPromptEvent;
  _installPromptEvent = null;
  document.getElementById('reminder-sheet-backdrop')?.remove();
  if (e) {
    try {
      e.prompt();
      await e.userChoice;
    } catch (err) {
      console.warn('[Push] install prompt failed:', err);
    }
  }
  if (!fromTips) showReminderSheet('ask');
}

// Browsers built into other apps (Instagram, Facebook, Snapchat, LinkedIn,
// LINE, WhatsApp, and Android WebViews in general). Their storage can be
// wiped when the app closes, and Google blocks sign-in inside them.
const IN_APP_UA_RE = /Instagram|FBAN|FBAV|FB_IAB|WhatsApp|Snapchat|LinkedInApp|\bLine\/|; wv\)/i;
function isInAppBrowserUA(ua) {
  return IN_APP_UA_RE.test(String(ua || ''));
}

// ── Which device is this? ─────────────────────────────────────
// Only used to pick plain-language steps (install, keep reminders
// arriving). Nothing is stored or sent.
function detectDevice(nav = (typeof navigator !== 'undefined' ? navigator : {}), win = (typeof window !== 'undefined' ? window : {})) {
  const ua = nav.userAgent || '';
  const inApp = isInAppBrowserUA(ua);
  const ios = /iPhone|iPad|iPod/i.test(ua) || (nav.platform === 'MacIntel' && nav.maxTouchPoints > 1);
  const os = ios ? 'ios' : /Android/i.test(ua) ? 'android' : /Windows/i.test(ua) ? 'windows' : /Macintosh|Mac OS X/i.test(ua) ? 'mac' : 'other';
  const browser = /SamsungBrowser/i.test(ua) ? 'samsung' : /Edg\//i.test(ua) ? 'edge' : /Firefox|FxiOS/i.test(ua) ? 'firefox'
    : /Chrome|CriOS|Chromium/i.test(ua) ? 'chrome' : /Safari/i.test(ua) ? 'safari' : 'other';
  const standalone = !!((win.matchMedia && win.matchMedia('(display-mode: standalone)').matches) || nav.standalone === true);
  return { os, browser, standalone, inApp };
}

// ── "Install Clarity Desk" card (on open) ─────────────────────
// A small card, never a blocking pop-up. Shows only where installing
// actually works: a one-tap install where the browser offers it
// (Android, Windows, Mac Chrome/Edge), short steps on iPhone/iPad and
// Mac Safari. "Not now" hides it for 14 days.
const INSTALL_SNOOZE_MS = 14 * 86400000;
let _installBannerTimer = null;

function installBannerKind(dev = detectDevice()) {
  if (dev.standalone || dev.inApp) return null;
  // Never offer to install an old address; the move card covers it.
  if (typeof location !== 'undefined' && isOldAddress(location.hostname)) return null;
  if (_installPromptEvent) return 'prompt';
  if (dev.os === 'ios') return 'ios';
  if (dev.os === 'mac' && dev.browser === 'safari') return 'mac-safari';
  return null;
}

// ── One address: claritydesk.web.app ─────────────────────────
// The app used to be live at several addresses. Saved data belongs to the
// address it was saved on, so a plain redirect would leave a student's
// desk behind. Only a browser with nothing saved here is sent to the new
// address; anyone else gets a card with ways to bring their desk along.
// Unknown hosts (localhost, preview channels) are left alone.
const CANONICAL_ORIGIN = 'https://claritydesk.web.app';
const OLD_HOSTS = ['campusos-83365.web.app', 'campusos-83365.firebaseapp.com', 'claritydesk.firebaseapp.com', 'sanghpalbhakte.github.io'];
// Preferences, and bookkeeping the app writes on its own during any visit,
// that are no loss to leave behind. Any other cos_* key counts as desk data.
const MOVE_SAFE_KEYS = ['cos_theme', 'cos_accent', 'cos_install_prompt', 'cos_onboarding_dismissed', 'cos_timetable_choice', KEY_MOVED_PROMPT,
  KEY_ATT_V2_STATE, KEY_ATT_DATEFIX_CUTOFF, 'cos_notified_history', 'cos_notified_notices', KEY_USAGE];
const MOVED_SNOOZE_MS = 3 * 86400000;

function isOldAddress(hostname) {
  return OLD_HOSTS.includes(String(hostname || '').toLowerCase());
}

function localStorageKeys() {
  const keys = [];
  try { for (let i = 0; i < localStorage.length; i++) keys.push(localStorage.key(i)); } catch (_) {}
  return keys;
}

function hasDeskDataToMove(keys = localStorageKeys()) {
  if (hasExistingUserData()) return true;
  return keys.some(k => typeof k === 'string' && k.startsWith('cos_') && !MOVE_SAFE_KEYS.includes(k));
}

// 'redirect' | 'card' | null. Read-only. Any query (email sign-in link,
// WhatsApp share, reminder tap) is finished here first, and automated
// browsers (the post-ship smoke test) keep testing the address they opened.
function addressMoveAction({ hostname, search = '', webdriver = false } = {}, keys) {
  if (!isOldAddress(hostname)) return null;
  if (webdriver) return null;
  if (!hasDeskDataToMove(keys) && !search) return 'redirect';
  const p = safeGetStorage(KEY_MOVED_PROMPT, null) || {};
  if (p.dismissedAt && Date.now() - p.dismissedAt < MOVED_SNOOZE_MS) return null;
  return 'card';
}

function newAddressUrl() {
  return CANONICAL_ORIGIN + '/' + (window.location.hash || '');
}

function showMovedBanner(tries = 6) {
  if (document.getElementById('moved-banner')) return;
  if (document.querySelector('.modal-backdrop')) {
    if (tries > 0) setTimeout(() => showMovedBanner(tries - 1), 10000);
    return;
  }
  const el = document.createElement('div');
  el.id = 'moved-banner';
  el.className = 'install-banner';
  el.setAttribute('role', 'region');
  el.setAttribute('aria-label', 'Clarity Desk has a new address');
  el.innerHTML = `
    <img class="install-banner-icon" src="./icon-192.png" alt="" width="40" height="40">
    <div class="install-banner-text"><strong>Clarity Desk has a new address</strong><span>Use claritydesk.web.app from now on. Your desk is saved on this address, so bring it with you first.</span></div>
    <div class="install-banner-actions">
      <button type="button" class="btn-secondary" onclick="dismissMovedBanner()">Not now</button>
      <button type="button" class="btn-primary" onclick="showMoveDeskModal()">Move my desk</button>
    </div>`;
  document.body.appendChild(el);
}

function dismissMovedBanner() {
  safeSetStorage(KEY_MOVED_PROMPT, { dismissedAt: Date.now() });
  document.getElementById('moved-banner')?.remove();
}

function showMoveDeskModal() {
  document.getElementById('moved-banner')?.remove();
  document.getElementById('move-desk-modal-backdrop')?.remove();
  const close = `document.getElementById('move-desk-modal-backdrop')?.remove()`;
  const note = 'font-size:var(--text-sm);color:var(--text-muted);line-height:1.45';
  const url = escHtml_cd(newAddressUrl());
  const body = currentUser
    ? `<div style="font-size:var(--text-base);line-height:1.45">You are signed in, so your desk is already saved to your account. Open the new address and sign in with the same ${escHtml_cd(signInMethodLabel(currentUser))} account.</div>`
    : `<div style="font-size:var(--text-base);line-height:1.45"><strong>Easiest:</strong> sign in here first. Then open the new address and sign in with the same account. Your desk comes with you.</div>
       <button class="btn-secondary" onclick="${close};navigateTo('settings')">Sign in here</button>
       <div style="border-top:1px solid var(--border);padding-top:12px;font-size:var(--text-base);line-height:1.45"><strong>No account?</strong> Download a backup, open the new address, then go to Settings → Restore Backup.</div>
       <button class="btn-secondary" onclick="exportData()">Download backup</button>`;
  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop';
  backdrop.id = 'move-desk-modal-backdrop';
  backdrop.innerHTML = `
    <div class="modal" onclick="event.stopPropagation()" style="max-width:440px;width:92vw">
      <div class="modal-header">
        <span class="modal-title">Move your desk</span>
        <button class="modal-close" onclick="${close}" aria-label="Close">${icons.x()}</button>
      </div>
      <div class="modal-body" style="display:flex;flex-direction:column;gap:12px">
        ${body}
        <div style="${note}">Added Clarity Desk to your home screen? Add the new address too, then remove the old icon.</div>
      </div>
      <div class="modal-footer" style="margin-top:16px;display:flex;justify-content:flex-end;flex-wrap:wrap;gap:8px">
        <button class="btn-secondary" onclick="dismissMovedBanner();${close}">Later</button>
        <a class="btn-primary" href="${url}" target="_blank" rel="noopener" style="text-decoration:none;display:inline-flex;align-items:center">Open new address</a>
      </div>
    </div>`;
  wireBackdropClickClose(backdrop);
  document.body.appendChild(backdrop);
}

// ── Opened inside Instagram / Facebook etc. ──────────────────
// Those built-in browsers can forget everything when the app closes, and
// Google sign-in is blocked there. A card (above any dialog) offers the
// way out: one tap into Chrome on Android, short steps on iPhone, and a
// copy-link fallback. Hidden for this visit by "Not now".
function inAppOpenUrl(loc = location) {
  return `${loc.protocol}//${loc.host}${loc.pathname}${loc.hash || ''}`;
}

// Android: an intent link opens the same page in Chrome.
function chromeIntentUrl(loc = location) {
  return `intent://${loc.host}${loc.pathname}${loc.hash || ''}#Intent;scheme=https;package=com.android.chrome;end`;
}

function inAppBannerHtml(dev = detectDevice()) {
  const where = /Instagram/i.test(navigator.userAgent || '') ? 'Instagram' : /FBAN|FBAV|FB_IAB/i.test(navigator.userAgent || '') ? 'Facebook' : 'another app';
  const steps = dev.os === 'ios'
    ? `Tap <strong>•••</strong> or the share icon, then <strong>Open in browser</strong>.`
    : `Open it in Chrome so your desk is saved and Google sign-in works.`;
  const openBtn = dev.os === 'android'
    ? `<a class="btn-primary" href="${escHtml_cd(chromeIntentUrl())}" style="text-decoration:none;display:inline-flex;align-items:center">Open in Chrome</a>` : '';
  return `
    <img class="install-banner-icon" src="./icon-192.png" alt="" width="40" height="40">
    <div class="install-banner-text"><strong>You’re inside ${where}</strong><span>Your desk may not be saved here. ${steps}</span></div>
    <div class="install-banner-actions">
      <button type="button" class="btn-secondary" onclick="document.getElementById('inapp-banner')?.remove()">Not now</button>
      <button type="button" class="btn-secondary" onclick="copyInAppLink()">Copy link</button>
      ${openBtn}
    </div>`;
}

function showInAppBanner() {
  if (document.getElementById('inapp-banner')) return;
  const el = document.createElement('div');
  el.id = 'inapp-banner';
  el.className = 'install-banner is-inapp';
  el.setAttribute('role', 'region');
  el.setAttribute('aria-label', 'Open Clarity Desk in your browser');
  el.innerHTML = inAppBannerHtml();
  document.body.appendChild(el);
}

async function copyInAppLink() {
  const url = inAppOpenUrl();
  try {
    await navigator.clipboard.writeText(url);
    showToast('Link copied. Paste it into Chrome or Safari.', 'success');
  } catch (_) {
    window.prompt('Copy this link and open it in Chrome or Safari:', url);
  }
}

// ── Anonymous usage counts (GoatCounter) ─────────────────────
// A few fixed events, to see where new students stop: welcome → scan →
// first class → back the next day. No ID, no cookie, no names or typed
// text: every event is a fixed path built only from the lists below.
// Off until GOATCOUNTER_CODE is set, live sites only, never in automated
// browsers, and students can turn it off in Settings.
const GOATCOUNTER_CODE = 'sanghpal';
const USAGE_HOSTS = ['claritydesk.web.app', 'claritydesk.firebaseapp.com', 'campusos-83365.web.app', 'campusos-83365.firebaseapp.com'];
const USAGE_EVENTS = ['app_open', 'welcome_shown', 'welcome_choice', 'scan_started', 'scan_review_shown', 'scan_failed',
  'first_class_saved', 'signin_started', 'signin_done', 'day2_return', 'bunk_calc_used', 'wa_links_saved'];
const USAGE_PART_RE = /^[a-z0-9_-]{1,24}$/;
const USAGE_QUEUE_MAX = 30;
let _scanStartedAt = 0;

function loadUsage() {
  const u = safeGetStorage(KEY_USAGE, null);
  const o = (u && typeof u === 'object') ? u : {};
  return {
    optOut: !!o.optOut,
    firstOpen: typeof o.firstOpen === 'string' ? o.firstOpen : '',
    day2: !!o.day2,
    once: (o.once && typeof o.once === 'object') ? o.once : {},
    queue: Array.isArray(o.queue) ? o.queue.filter(p => typeof p === 'string').slice(-USAGE_QUEUE_MAX) : []
  };
}

function usageActive() {
  if (!GOATCOUNTER_CODE) return false;
  if (typeof location === 'undefined' || !USAGE_HOSTS.includes(location.hostname)) return false;
  if (typeof navigator !== 'undefined' && navigator.webdriver) return false;
  return !loadUsage().optOut;
}

// 'welcome_choice', 'scan' -> 'welcome_choice/scan'; anything off-list -> null.
function usageEventPath(name, parts = []) {
  if (!USAGE_EVENTS.includes(name)) return null;
  const clean = parts.filter(p => p !== undefined && p !== null && p !== '').map(String);
  if (!clean.every(p => USAGE_PART_RE.test(p))) return null;
  return [name, ...clean].join('/');
}

function sendUsagePath(path) {
  if (typeof navigator === 'undefined' || navigator.onLine === false || typeof navigator.sendBeacon !== 'function') return false;
  const url = `https://${GOATCOUNTER_CODE}.goatcounter.com/count?e=true&p=${encodeURIComponent(path)}&rnd=${Math.random().toString(36).slice(2, 10)}`;
  try { return navigator.sendBeacon(url) === true; } catch (_) { return false; }
}

function trackUsage(name, ...parts) {
  if (!usageActive()) return false;
  const path = usageEventPath(name, parts);
  if (!path) return false;
  if (sendUsagePath(path)) return true;
  // Offline: keep it for later, at most the latest 30.
  const u = loadUsage();
  u.queue = [...u.queue, path].slice(-USAGE_QUEUE_MAX);
  safeSetStorage(KEY_USAGE, u);
  return false;
}

function flushUsageQueue() {
  if (!usageActive()) return;
  const u = loadUsage();
  if (!u.queue.length) return;
  u.queue = u.queue.filter(path => !sendUsagePath(path));
  safeSetStorage(KEY_USAGE, u);
}

// One-time events (first class saved): sent once per device.
function trackUsageOnce(flag, name, ...parts) {
  if (!usageActive()) return;
  const u = loadUsage();
  if (u.once[flag]) return;
  u.once[flag] = true;
  safeSetStorage(KEY_USAGE, u);
  trackUsage(name, ...parts);
}

function usageScanBucket() {
  const ms = _scanStartedAt ? Date.now() - _scanStartedAt : 0;
  return ms < 10000 ? 'under10s' : ms < 30000 ? 'under30s' : ms < 60000 ? 'under60s' : 'over60s';
}

// On open: the device kind, then "came back on a later day" once. A
// student who already had a desk when counting began is not counted as
// new (no first-class or next-day events for them).
function trackAppOpen() {
  if (!usageActive()) return;
  const dev = detectDevice();
  trackUsage('app_open', dev.os, dev.standalone ? 'app' : dev.inApp ? 'inapp' : 'browser');
  const u = loadUsage();
  const today = todayStr();
  if (!u.firstOpen) {
    u.firstOpen = today;
    if (hasExistingUserData()) { u.day2 = true; u.once.firstClass = true; }
    safeSetStorage(KEY_USAGE, u);
  } else if (!u.day2 && today > u.firstOpen) {
    u.day2 = true;
    safeSetStorage(KEY_USAGE, u);
    trackUsage('day2_return');
  }
  flushUsageQueue();
  // Delayed: FEEDBACK_URL is defined further down this file.
  setTimeout(() => { if (navigator.onLine !== false) flushFeedbackQueue(); }, 4000);
}

function onUsageToggle(box) {
  const u = loadUsage();
  u.optOut = !box.checked;
  if (u.optOut) u.queue = [];
  safeSetStorage(KEY_USAGE, u);
  showToast(u.optOut ? 'Usage counts turned off.' : 'Thanks. Anonymous usage counts are on.', 'success');
}

function scheduleInstallBanner(delay = 4000, tries = 6) {
  clearTimeout(_installBannerTimer);
  _installBannerTimer = setTimeout(() => {
    const p = safeGetStorage(KEY_INSTALL_PROMPT, null) || {};
    if (p.dismissedAt && Date.now() - p.dismissedAt < INSTALL_SNOOZE_MS) return;
    if (document.getElementById('install-banner')) return;
    const kind = installBannerKind();
    if (!kind) return;
    // Wait until the welcome screen or any other dialog is closed.
    if (document.querySelector('.modal-backdrop')) {
      if (tries > 0) scheduleInstallBanner(10000, tries - 1);
      return;
    }
    showInstallBanner(kind);
  }, delay);
}

function showInstallBanner(kind) {
  document.getElementById('install-banner')?.remove();
  const text = {
    prompt: 'Open it like an app, offline too. Reminders show up as Clarity Desk, even when it’s closed.',
    ios: 'Add it to your Home Screen to get class and deadline reminders on your iPhone.',
    'mac-safari': 'Add it to your Dock to open it like an app and get reminders on this Mac.'
  }[kind];
  const action = kind === 'prompt' ? 'Install' : 'Show me how';
  const el = document.createElement('div');
  el.id = 'install-banner';
  el.className = 'install-banner';
  el.setAttribute('role', 'region');
  el.setAttribute('aria-label', 'Install Clarity Desk');
  el.innerHTML = `
    <img class="install-banner-icon" src="./icon-192.png" alt="" width="40" height="40">
    <div class="install-banner-text"><strong>Install Clarity Desk</strong><span>${text}</span></div>
    <div class="install-banner-actions">
      <button type="button" class="btn-secondary" onclick="dismissInstallBanner()">Not now</button>
      <button type="button" class="btn-primary" onclick="installBannerAction('${kind}')">${action}</button>
    </div>`;
  document.body.appendChild(el);
}

function dismissInstallBanner() {
  safeSetStorage(KEY_INSTALL_PROMPT, { dismissedAt: Date.now() });
  document.getElementById('install-banner')?.remove();
}

async function installBannerAction(kind) {
  document.getElementById('install-banner')?.remove();
  if (kind === 'prompt' && _installPromptEvent) {
    const e = _installPromptEvent;
    _installPromptEvent = null;
    try {
      e.prompt();
      const choice = await e.userChoice;
      if (choice && choice.outcome !== 'accepted') safeSetStorage(KEY_INSTALL_PROMPT, { dismissedAt: Date.now() });
    } catch (err) {
      console.warn('[Install] prompt failed:', err);
    }
    return;
  }
  showReminderSheet(kind === 'ios' ? 'ios-install' : 'mac-install');
}

// ── "Make sure reminders arrive" (after turning them on) ──────
// Plain steps for the device in hand: the settings that most often
// stop a reminder from showing (battery savers, the browser not running,
// notification settings, Focus / Do Not Disturb).
function reminderTipsView(dev = detectDevice()) {
  const tab = !dev.standalone;
  const browserName = dev.browser === 'edge' ? 'Edge' : dev.browser === 'samsung' ? 'Samsung Internet' : dev.browser === 'firefox' ? 'Firefox' : dev.browser === 'safari' ? 'Safari' : 'Chrome';
  const appOrBrowser = tab ? browserName : 'Clarity Desk';
  const installStep = tab && _installPromptEvent
    ? `<li><strong>Install Clarity Desk</strong> (button below) so reminders show up as Clarity Desk with its logo, not as ${browserName}.</li>` : '';
  const steps = {
    android: [
      installStep,
      `<li><strong>Allow notifications:</strong> long-press the ${appOrBrowser} icon › <em>App info</em> › <em>Notifications</em> › on.</li>`,
      `<li><strong>Stop the battery saver from blocking it:</strong> <em>App info</em> › <em>Battery</em> › <em>Unrestricted</em> (or “Don’t optimise”).</li>`,
      `<li><strong>On Xiaomi, Redmi, POCO, Oppo, Vivo, Realme or OnePlus:</strong> also turn on <em>Autostart</em> for ${appOrBrowser} in the phone’s Settings.</li>`,
      `<li><strong>Do Not Disturb</strong> hides reminders while it’s on.</li>`
    ],
    windows: [
      installStep,
      `<li><strong>Keep ${browserName} running in the background:</strong> ${dev.browser === 'edge' ? 'Edge › Settings › <em>System and performance</em>' : 'Chrome › Settings › <em>System</em>'} › turn on <em>Continue running background apps when ${browserName === 'Edge' ? 'Microsoft Edge' : 'Google Chrome'} is closed</em>.</li>`,
      `<li><strong>Allow notifications in Windows:</strong> Start › Settings › <em>System</em> › <em>Notifications</em> › make sure ${appOrBrowser} is on.</li>`,
      `<li><strong>Do not disturb</strong> (or Focus) hides the pop-ups. Turn it off when you want reminders.</li>`
    ],
    mac: [
      tab && dev.browser === 'safari' ? `<li><strong>Add it to your Dock:</strong> in Safari, <em>File</em> › <em>Add to Dock…</em>, then turn reminders on from that app.</li>` : installStep,
      `<li><strong>Allow notifications:</strong> System Settings › <em>Notifications</em> › ${appOrBrowser} › on.</li>`,
      `<li><strong>So you don’t miss one:</strong> set <em>Alert Style</em> to <em>Persistent</em> and turn on <em>Notification Centre</em>.</li>`,
      `<li><strong>Presenting or recording your screen?</strong> Notifications › <em>when mirroring or sharing the display</em> › <em>Notifications On</em>.</li>`
    ],
    ios: [
      `<li><strong>Allow notifications:</strong> Settings › <em>Notifications</em> › <em>Clarity Desk</em> › <em>Allow Notifications</em> on, with Lock Screen and Banners.</li>`,
      `<li><strong>Keep banners on screen:</strong> set <em>Banner Style</em> to <em>Persistent</em>.</li>`,
      `<li><strong>Focus</strong> (Sleep, Do Not Disturb) hides reminders while it’s on.</li>`
    ]
  }[dev.os] || [
    `<li><strong>Allow notifications</strong> for this site in your browser’s settings.</li>`,
    `<li>Keep your browser running in the background so reminders can arrive.</li>`
  ];
  const installBtn = tab && _installPromptEvent && dev.os !== 'ios' ? `<button class="btn-secondary" onclick="reminderSheetInstall(true)">Install app</button>` : '';
  return {
    title: 'Make sure reminders arrive',
    body: `<p>Reminders are on for this device. A few phone or computer settings can still hide them, so check these once:</p><ol class="reminder-sheet-steps">${steps.filter(Boolean).join('')}</ol>`,
    actions: `${installBtn}<button class="btn-secondary" onclick="sendTestReminder()">Send a test</button><button class="btn-primary" onclick="document.getElementById('reminder-sheet-backdrop')?.remove()">Done</button>`
  };
}

