const NOTIF_DEFAULT_ICON = './icon-192.png';
const NOTIF_DEFAULT_BADGE = './badge-96.png'; // monochrome transparent PNG for Android status bar

function dispatchNotification(title, options = {}) {
  if (typeof Notification === 'undefined') return;

  if (Notification.permission !== 'granted') {
    if (options.showInAppFallback !== false) {
      if (Notification.permission === 'denied') {
        showToast('Notifications blocked in browser settings. Enable in site settings to receive alerts.', 'error');
      } else if (Notification.permission === 'default') {
        showToast('Notification permission not requested yet. Click Enable Notifications in Settings.', 'info');
      }
    }
    return;
  }

  const merged = { ...options };
  const notifOptions = {
    icon: NOTIF_DEFAULT_ICON,
    badge: NOTIF_DEFAULT_BADGE,
    vibrate: [100, 50, 100],
    ...merged,
    renotify: !!(merged.tag)
  };

  if ('serviceWorker' in navigator && navigator.serviceWorker.controller) {
    navigator.serviceWorker.ready.then(reg => {
      if (reg && reg.showNotification) {
        reg.showNotification(title, notifOptions);
      } else {
        new Notification(title, notifOptions);
      }
    }).catch(() => {
      try { new Notification(title, notifOptions); } catch(e) {}
    });
  } else {
    try { new Notification(title, notifOptions); } catch(e) {}
  }
}
window.dispatchNotification = dispatchNotification;

// ── Reminder builders ─────────────────────────────────────────
// The one place class and deadline reminder text is written. The in-app
// check below and the closed-app push sync (buildUpcomingReminders) both
// use these, so a reminder reads the same whichever path delivers it.
// Tags are the cos_notified_history keys (and what the GitHub push job
// sends), so one reminder arriving twice replaces itself.
function taskReminderUrl(t) {
  return t && t.isCustom && t.id ? `./?task=${encodeURIComponent(t.id)}#assignments` : './#assignments';
}

function buildTaskReminder(kind, t, dateKey, overdueDays = 1) {
  const subject = t.subject || 'Task';
  const url = taskReminderUrl(t);
  if (kind === 'day_before') {
    return { tag: `upcoming_daybefore_${t.id}_${dateKey}`, title: `Upcoming Task: ${t.title}`, body: `${subject} · Due tomorrow! Keep going.`, url };
  }
  if (kind === 'same_day') {
    return { tag: `upcoming_sameday_${t.id}_${dateKey}`, title: `Task Due Today: ${t.title}`, body: `${subject} · Due today!`, url };
  }
  return { tag: `overdue_${t.id}_${dateKey}`, title: `Task Overdue: ${t.title}`, body: `${subject} is ${overdueDays} day${overdueDays > 1 ? 's' : ''} overdue.`, url };
}

function buildClassReminder(c, dateKey) {
  return {
    tag: `class_rem_${c.code || c.subject}_${c.time}_${dateKey}`,
    title: `Class Starting Soon: ${c.subject}`,
    body: `Starts at ${formatDisplayTime(c.time)} in ${c.room || 'class'} with ${c.teacher || 'faculty'}`,
    url: './#timetable'
  };
}

function classReminderLead(prefs) {
  return prefs.classReminders === '1_hour' ? 60 : prefs.classReminders === '30_min' ? 30 : 15;
}

// Morning time for deadline reminders: the daily summary time, else 8 AM.
function taskMorningTime(prefs) {
  const t = prefs && prefs.dailySummaryTime;
  return typeof t === 'string' && /^\d{2}:\d{2}$/.test(t) ? t : '08:00';
}

// A weekday's classes as reminders see them: teaching classes only, for
// General + the student's own group (same filter as the Calendar).
function reminderClassesFor(dayIdx) {
  const batch = calendarUserBatch();
  return ((loadTimetable() || {})[dayIdx] || []).filter(c => isTeachingClass(c) && shouldKeepClassForUserBatch(c, batch));
}

// Every class and deadline reminder due in the next `days` days, with the
// moment it should fire (worked out here, in the phone's own time, and
// sent to the push server as a UTC timestamp). Only what a notification
// needs: title, body, tag and the screen to open. Never task descriptions.
const PUSH_SYNC_DAYS = 14;
const PUSH_MAX_REMINDERS = 200;

function buildUpcomingReminders(now = new Date(), days = PUSH_SYNC_DAYS) {
  const prefs = loadNotifPrefs();
  const nowMs = now.getTime();
  const out = [];
  const at = (dateKey, minutes) => {
    const d = new Date(`${dateKey}T00:00:00`);
    d.setMinutes(minutes);
    return d.getTime();
  };
  const add = (r, fireAt) => { if (fireAt > nowMs) out.push({ id: r.tag, fireAt, title: r.title, body: r.body, url: r.url, tag: r.tag }); };
  const dayKey = (offset) => { const d = new Date(now); d.setHours(12, 0, 0, 0); d.setDate(d.getDate() + offset); return localDateKey(d); };
  const firstKey = dayKey(0);
  const lastKey = dayKey(days);

  if (prefs.taskUpcoming !== 'off') {
    const morning = timeToMinutes(taskMorningTime(prefs));
    allTasks().filter(t => t && t.status === 'pending' && !t.noDeadline && t.dueDate && t.dueDate >= firstKey && t.dueDate <= lastKey).forEach(t => {
      // An early start (a 7:30 AM quiz) gets its reminder an hour before.
      const start = t.startTime ? timeToMinutes(t.startTime) : null;
      const dueMorning = start !== null && start - 60 < morning ? Math.max(start - 60, 0) : morning;
      add(buildTaskReminder('same_day', t, t.dueDate), at(t.dueDate, dueMorning));
      if (prefs.taskUpcoming === 'day_before') {
        const before = new Date(`${t.dueDate}T12:00:00`);
        before.setDate(before.getDate() - 1);
        const beforeKey = localDateKey(before);
        add(buildTaskReminder('day_before', t, beforeKey), at(beforeKey, morning));
      }
    });
  }

  if (prefs.classReminders !== 'off') {
    const lead = classReminderLead(prefs);
    for (let i = 0; i < days; i++) {
      const key = dayKey(i);
      if (isHolidayActive(key)) continue;
      const weekday = new Date(`${key}T12:00:00`).getDay();
      reminderClassesFor(weekday).forEach(c => {
        add(buildClassReminder(c, key), at(key, timeToMinutes(c.time || '10:00') - lead));
      });
    }
  }

  out.sort((a, b) => a.fireAt - b.fireAt);
  const seen = new Set();
  return out.filter(r => !seen.has(r.tag) && seen.add(r.tag)).slice(0, PUSH_MAX_REMINDERS);
}

function checkScheduledNotifications() {
  if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return;
  const prefs = loadNotifPrefs();

  const today = todayStr();
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowStr = localDateKey(tomorrow);
  const now = new Date();
  const currentMin = currentTimeMinutes();
  const currentHHMM = `${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;

  const tasks = allTasks().filter(t => t.status === 'pending');
  const notifiedMap = safeGetStorage('cos_notified_history', {}) || {};

  // Class and deadline reminders come from the closed-app push path once
  // it is set up on this device (see syncPushReminders); this in-app
  // check then only covers what push does not send.
  const pushCovers = isClosedAppPushActive();

  // 1. Upcoming Tasks
  if (prefs.taskUpcoming === 'day_before' && !pushCovers) {
    tasks.filter(t => !t.noDeadline && t.dueDate === tomorrowStr).forEach(t => {
      const r = buildTaskReminder('day_before', t, today);
      if (!notifiedMap[r.tag]) {
        dispatchNotification(r.title, { body: r.body, tag: r.tag, data: { url: r.url } });
        notifiedMap[r.tag] = true;
      }
    });
  }
  // Due-today reminder: any time today for "same_day"; with "day_before"
  // it also comes on the morning itself (from the daily summary time).
  if (!pushCovers && (prefs.taskUpcoming === 'same_day' || (prefs.taskUpcoming === 'day_before' && currentHHMM >= taskMorningTime(prefs)))) {
    tasks.filter(t => !t.noDeadline && t.dueDate === today).forEach(t => {
      const r = buildTaskReminder('same_day', t, today);
      if (!notifiedMap[r.tag]) {
        dispatchNotification(r.title, { body: r.body, tag: r.tag, data: { url: r.url } });
        notifiedMap[r.tag] = true;
      }
    });
  }

  // 2. Overdue Tasks
  if (prefs.taskOverdue !== 'off') {
    tasks.filter(t => isTaskOverdue(t)).forEach(t => {
      const days = Math.abs(dueDaysLeft(t.dueDate) || 1);
      const r = buildTaskReminder('overdue', t, today, days);
      if (!notifiedMap[r.tag]) {
        dispatchNotification(r.title, { body: r.body, tag: r.tag, data: { url: r.url } });
        notifiedMap[r.tag] = true;
      }
    });
  }

  // Holiday mode: no class reminders and no "attend more classes" alert.
  const onHoliday = isHolidayActive(today);

  // 3. Class Reminders
  if (prefs.classReminders !== 'off' && !onHoliday && !pushCovers) {
    const leadWindow = classReminderLead(prefs);

    reminderClassesFor(now.getDay()).forEach(c => {
      const startMin = timeToMinutes(c.time || '10:00');
      const diff = startMin - currentMin;
      if (diff > 0 && diff <= leadWindow) {
        const r = buildClassReminder(c, today);
        if (!notifiedMap[r.tag]) {
          dispatchNotification(r.title, { body: r.body, tag: r.tag, data: { url: r.url } });
          notifiedMap[r.tag] = true;
        }
      }
    });
  }

  // 4. Low-Attendance Warning Alert
  if (prefs.attendanceAlerts !== 'off' && !onHoliday) {
    const attendanceData = safeGetStorage(KEY_ATTENDANCE, {}) || {};
    let totalAttended = 0;
    let totalSkipped = 0;
    Object.values(attendanceData).forEach(dayObj => {
      if (dayObj && typeof dayObj === 'object') {
        Object.values(dayObj).forEach(st => {
          if (st === 'attended') totalAttended++;
          else if (st === 'skipped') totalSkipped++;
        });
      }
    });
    const totalMarked = totalAttended + totalSkipped;
    let pct = totalMarked > 0 ? Math.round((totalAttended / totalMarked) * 100) : null;
    let below = pct !== null && pct < getAttendanceTarget();
    // v2: the same overall % the app shows (baselines and labs included,
    // exact comparison), not the daily marks alone.
    if (isAttendanceV2Active()) {
      const o = getOverallAttendanceV2();
      pct = o.pctLabel;
      below = o.isSafe === false;
    }

    if (below) {
      const attKey = `att_warning_${today}`;
      if (!notifiedMap[attKey]) {
        dispatchNotification(`Attendance Alert: ${pct}%`, {
          body: `You're at ${pct}%, target ${getAttendanceTarget()}%. A few classes in a row will bring it back up. Tap to see how many.`,
          tag: attKey,
          data: { url: './#review' }
        });
        notifiedMap[attKey] = true;
      }
    }
  }

  // 4b. Countdown milestones: one calm nudge at 30, 14, 7, 3 and 1 days
  // left and on the day itself. Rides on the daily summary switch and time,
  // so there is no new setting, and each fires at most once.
  if (liveProfile.examDate && prefs.dailySummaryTime && prefs.dailySummaryTime !== 'off' && currentHHMM >= prefs.dailySummaryTime) {
    const cdDays = Math.round((new Date(liveProfile.examDate + 'T00:00:00') - new Date(today + 'T00:00:00')) / 86400000);
    if ([30, 14, 7, 3, 1, 0].includes(cdDays) && !holidayHidesCountdown(cdDays)) {
      const cdKey = `countdown_${cdDays}_${liveProfile.examDate}`;
      if (!notifiedMap[cdKey]) {
        const cdLabel = getCountdownLabel();
        dispatchNotification(cdDays === 0 ? `${cdLabel} is today` : `${cdDays} day${cdDays === 1 ? '' : 's'} to ${cdLabel}`, {
          body: countdownCheer(cdDays),
          tag: cdKey,
          data: { url: './#dashboard' }
        });
        notifiedMap[cdKey] = true;
      }
    }
  }

  // 5. Daily Summary Notification Check
  if (prefs.dailySummaryTime && prefs.dailySummaryTime !== 'off') {
    const summaryKey = `daily_summary_${today}`;
    if (currentHHMM >= prefs.dailySummaryTime && !notifiedMap[summaryKey]) {
      // Holiday: resting ongoing tasks are left out of the count.
      const pendingCountVal = tasks.filter(t => !(onHoliday && isTaskPausedForHoliday(t, today))).length;
      const dueTodayCount = tasks.filter(t => t.dueDate === today).length;
      dispatchNotification(onHoliday ? 'Clarity Desk: Holiday check-in' : `Clarity Desk: Daily Summary`, {
        body: onHoliday
          ? (pendingCountVal > 0 ? `Enjoy the break. ${pendingCountVal} task${pendingCountVal !== 1 ? 's' : ''} to keep an eye on (${dueTodayCount} due today).` : 'Nothing due. Enjoy the break.')
          : `You have ${pendingCountVal} pending task${pendingCountVal !== 1 ? 's' : ''} (${dueTodayCount} due today).`,
        tag: summaryKey,
        data: { url: './#dashboard' }
      });
      notifiedMap[summaryKey] = true;
    }
  }

  const keys = Object.keys(notifiedMap);
  if (keys.length > 100) {
    const pruned = {};
    keys.slice(-50).forEach(k => { pruned[k] = notifiedMap[k]; });
    safeSetStorage('cos_notified_history', pruned);
  } else {
    safeSetStorage('cos_notified_history', notifiedMap);
  }
}

function triggerNoticeNotification(notice) {
  if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return;
  const prefs = loadNotifPrefs();
  if (prefs.newNotices === 'off') return;

  if (prefs.newNotices === 'instant' || prefs.newNotices === 'same_day') {
    dispatchNotification(`New Notice: ${notice.title}`, {
      body: (notice.content || '').slice(0, 120),
      tag: `notice_${notice.id}`,
      data: { url: './#notices' }
    });
  }
}

// Notices can opt into disappearing once a one-time setup step is done
// (exam date set, timetable customized) via an optional `hideWhen` key --
// otherwise the board keeps nagging about something already handled.
// Every place that reads NOTICES for display, notifications, or the
// assistant should go through this instead of the raw array.
//
// Built-in sample notices (`builtIn: true` in data.js) also drop off once
// their date has passed, so a new student doesn't open a board of months-old
// announcements. Only that flag hides by date; anything without it stays.
function getVisibleNotices() {
  const today = todayStr();
  return NOTICES.filter(n => {
    if (n.builtIn && n.date && n.date < today) return false;
    if (n.hideWhen === 'examDateSet') return !(liveProfile.examDate && liveProfile.examDate.trim());
    if (n.hideWhen === 'timetableCustomized') return !isCustomTimetableActive();
    return true;
  });
}

function checkNoticeNotifications() {
  if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return;
  const prefs = loadNotifPrefs();
  if (prefs.newNotices === 'off') return;

  const notifiedNotices = safeGetStorage('cos_notified_notices', {}) || {};
  getVisibleNotices().forEach(n => {
    if (!notifiedNotices[n.id]) {
      triggerNoticeNotification(n);
      notifiedNotices[n.id] = true;
    }
  });
  safeSetStorage('cos_notified_notices', notifiedNotices);
}

// ── Custom Tasks (fully persisted) ────────────────────────────
function loadCustomTasks() {
  const raw = safeGetStorage(KEY_CUSTOM_TASKS, []) || [];
  if (!Array.isArray(raw)) return [];
  return raw.map(sanitizeTask).filter(Boolean);
}

function saveCustomTasks() {
  // Prune completed dated tasks older than 14 days; never prune ongoing/standing missions
  const fourteenDaysAgo = new Date();
  fourteenDaysAgo.setDate(fourteenDaysAgo.getDate() - 14);
  const cutoffStr = `${fourteenDaysAgo.getFullYear()}-${String(fourteenDaysAgo.getMonth()+1).padStart(2,'0')}-${String(fourteenDaysAgo.getDate()).padStart(2,'0')}`;

  state.customTasks = state.customTasks
    .map(sanitizeTask)
    .filter(Boolean)
    .filter(t => {
      if (t.noDeadline || (t.taskType === 'mission' && !t.dueDate)) return true;
      if (t.status === 'submitted' && t.dueDate && t.dueDate < cutoffStr) return false;
      return true;
    });

  safeSetStorage(KEY_CUSTOM_TASKS, state.customTasks);
  syncToCloud();
}

// ── State ─────────────────────────────────────────────────────
const state = {
  currentPage:         'dashboard',
  ttDay:               new Date().getDay(),
  assignFilter:        'all',
  assignTypeFilter:    'all',
  assignSubjectFilter: 'all',
  assignFiltersOpen:   false,
  noticeSearch:        '',
  assignments:         loadAssignments(),
  customTasks:         loadCustomTasks(),   // persisted across reloads
};
window.state = state;

window.filterAndNavigateToAssignments = function(filter, typeFilter = null, subjectFilter = null) {
  if (filter) state.assignFilter = filter;
  if (typeFilter) state.assignTypeFilter = typeFilter;
  if (subjectFilter) state.assignSubjectFilter = subjectFilter;
  navigateTo('assignments');
};

window.resetAssignmentFilters = function() {
  state.assignFilter = 'all';
  state.assignTypeFilter = 'all';
  state.assignSubjectFilter = 'all';
  renderAssignments();
};

// ── Canonical 2-Mode + 4-Accent System ─────────────────────────
// "Theme" (data-theme) is now the light/dark MODE only; "Accent"
// (data-accent) is an independent personalization axis that works
// in both modes, so switching mode never resets a chosen accent.
const ALL_THEMES = ['paper-slate', 'midnight-ink'];

const THEME_LABELS = {
  'paper-slate':  'Paper Slate',
  'midnight-ink': 'Midnight Ink'
};

const ALL_ACCENTS = ['terracotta', 'rose', 'lavender', 'apricot'];

const ACCENT_LABELS = {
  'terracotta': 'Terracotta',
  'rose':       'Rose',
  'lavender':   'Lavender',
  'apricot':    'Apricot'
};

// Retired flat 5-theme names (each baked mode+accent into one value)
// migrate to: mode -> paper-slate, accent -> the mapped color.
const LEGACY_ACCENT_THEME_MAP = {
  'dusty-rose':       'rose',
  'honeyed-lavender': 'lavender',
  'apricot-cream':    'apricot'
};

const LEGACY_THEME_MAP = {
  // Retired theme remapping
  'sandstone-notes':    'paper-slate',
  'sandstone':          'paper-slate',
  'stone':              'paper-slate',
  'warm-study':         'paper-slate',
  'sunset':             'paper-slate',
  'academic-amber':     'paper-slate',
  'crimson-bold':       'paper-slate',
  'nordic-frost':       'paper-slate',
  'forest-study':       'paper-slate',
  'emerald':            'paper-slate',
  'emerald-focus':      'paper-slate',
  'misty-mint':         'paper-slate',
  'mint':               'paper-slate',
  'espresso-desk':      'midnight-ink',
  'espresso-paper':     'midnight-ink',
  'cafe':               'midnight-ink',
  'cafe-night':         'midnight-ink',
  'cocoa-night':        'midnight-ink',
  'rose-pine':          'midnight-ink',
  'paper':              'paper-slate',
  'soft-neutral':       'paper-slate',
  'light':              'paper-slate',
  'cloud':              'paper-slate',
  'mist-blue':          'paper-slate',
  'glass':              'paper-slate',
  'quiet-dark':         'midnight-ink',
  'dark':               'midnight-ink',
  'midnight-executive': 'midnight-ink'
};

// Installed Android PWAs bake the status bar's actual BACKGROUND color once
// from manifest.json's theme_color -- it never tracks this live meta tag.
// But Chrome still reads this live tag to pick the status bar's ICON color
// (light icons on an assumed-dark bg, dark icons on an assumed-light bg).
// Letting this tag flip with the in-app theme therefore picks icon color
// for the WRONG assumed background once installed: toggling to the light
// theme sets this tag light, so Chrome picks dark icons -- but the real,
// fixed native background is dark (manifest.json), so dark-on-dark is
// unreadable. Toggling to dark theme has the same problem in reverse.
// Pin the tag to the manifest's actual fixed dark background for the
// installed app (so icon color is always computed against the real bg,
// always readable) -- a plain browser tab has no separate baked
// background, so it still gets the live per-theme tint there.
function applyThemeColorMeta(theme) {
  const meta = document.querySelector('meta[name="theme-color"]');
  if (!meta) return;
  const isStandalone = window.matchMedia && window.matchMedia('(display-mode: standalone)').matches;
  meta.setAttribute('content', isStandalone ? '#171412' : (theme === 'midnight-ink' ? '#171412' : '#F6F1E8'));
}

function initTheme() {
  const saved = localStorage.getItem(KEY_THEME);
  let theme   = saved;
  let migratedAccent = null;
  if (theme && LEGACY_ACCENT_THEME_MAP[theme]) {
    // Old flat theme (e.g. 'dusty-rose') baked mode+accent together —
    // split it: mode becomes Paper Slate, accent carries the color.
    migratedAccent = LEGACY_ACCENT_THEME_MAP[theme];
    theme = 'paper-slate';
  }
  if (theme && LEGACY_THEME_MAP[theme]) theme = LEGACY_THEME_MAP[theme];
  if (!theme && window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
    theme = 'midnight-ink';
  }
  theme = theme || 'paper-slate';
  if (!ALL_THEMES.includes(theme)) theme = 'paper-slate';

  if (!saved || saved !== theme) {
    localStorage.setItem(KEY_THEME, theme);
  }
  if (migratedAccent) localStorage.setItem(KEY_ACCENT, migratedAccent);

  document.documentElement.setAttribute('data-theme', theme);
  applyThemeColorMeta(theme);
  updateThemeSelector(theme);
}

function initAccent() {
  let accent = localStorage.getItem(KEY_ACCENT);
  if (!accent) {
    const legacyTheme = localStorage.getItem(KEY_THEME);
    accent = LEGACY_ACCENT_THEME_MAP[legacyTheme] || null;
  }
  if (!accent || !ALL_ACCENTS.includes(accent)) accent = 'terracotta';
  localStorage.setItem(KEY_ACCENT, accent);
  document.documentElement.setAttribute('data-accent', accent);
}

function setAccent(accent, originEvent) {
  if (!ALL_ACCENTS.includes(accent)) return;
  document.documentElement.setAttribute('data-accent', accent);
  localStorage.setItem(KEY_ACCENT, accent);

  // Keep any rendered accent-dot row in sync without a full renderSettings()
  // rebuild, same efficient pattern as updateThemeSelector()'s swatch sync.
  document.querySelectorAll('.accent-dot').forEach(dot => {
    const isMatch = dot.getAttribute('onclick')?.includes(`'${accent}'`);
    dot.classList.toggle('active', !!isMatch);
    dot.setAttribute('aria-pressed', isMatch ? 'true' : 'false');
  });

  if (currentUser && db) {
    db.collection('users').doc(currentUser.uid).set({
      accent: accent,
      updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    }, { merge: true }).catch(() => {});
  }
}

function toggleTheme(originEvent) {
  // Simple binary day/night switch. Accent is a separate, independent
  // choice (see setAccent()) so toggling mode never touches it.
  const current = document.documentElement.getAttribute('data-theme') || 'paper-slate';
  const next = current === 'midnight-ink' ? 'paper-slate' : 'midnight-ink';
  setTheme(next, originEvent);
}

function setTheme(theme, originEvent) {
  if (LEGACY_THEME_MAP[theme]) theme = LEGACY_THEME_MAP[theme];
  if (!ALL_THEMES.includes(theme)) return;

  const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function applyTheme() {
    document.documentElement.setAttribute('data-theme', theme);
    applyThemeColorMeta(theme);
    localStorage.setItem(KEY_THEME, theme);
    updateThemeSelector(theme);
    // No renderPage() here: every themed value in the page already flows
    // from CSS custom properties, so the DOM needs no rebuild on a theme
    // switch. Rebuilding used to tear down and instantly repaint the main
    // content in the new theme's final colors while the surrounding chrome
    // (topbar/sidebar, untouched by the rebuild) was still mid-transition -
    // that two-speed mismatch was the visible "flash". The one place JS
    // reads the theme for rendering (Settings' theme swatches) is already
    // kept in sync by updateThemeSelector() above.
  }

  // Reveal the new theme with an expanding circle from the toggle button
  // instead of blending the whole screen at once. A plain crossfade (what
  // this used to do) and the CSS property transition before it are both,
  // for a pure color swap with no layout change, the same thing pixel-for-
  // pixel: blending old-color and new-color at the same coordinates. For
  // Paper Slate's cream and Midnight Ink's near-black that blend's midpoint
  // is a muddy, desaturated grey, and because it happens across the whole
  // screen at once, no amount of tuning the easing/duration removed the
  // "everything changes together" pop - it only changed how long the pop
  // took. A circular wipe sidesteps the blend instead of tuning it: the old
  // theme stays fully opaque and correctly colored outside the growing
  // circle, the new theme is fully opaque and correctly colored inside it,
  // and the only place old and new pixels ever meet is the thin, moving
  // edge between them - never the full screen at once.
  //
  // The circle's geometry is set as CSS custom properties and the reveal
  // itself is a plain @keyframes animation in style.css (see
  // ::view-transition-new(root)), not driven from here with .animate().
  // The first version used .animate({pseudoElement: ...}) after awaiting
  // transition.ready, and on a slow device that gap between the pseudo-
  // elements existing and that promise resolving was long enough to paint
  // at least one real frame of ::view-transition-new(root) at its default,
  // un-clipped state - fully covering the old theme before the circle had
  // even started - which read as an extra flash layered on top of the
  // wipe. That's exactly the kind of thing that shows up "more on mobile,
  // less on PC": a timing race that a slower device is more likely to
  // actually render a frame of. A static starting clip-path plus a CSS
  // animation are both applied by the browser's style engine in the same
  // pass that creates the pseudo-elements, with no JS scheduling gap for a
  // wrong frame to land in.
  if (!reduceMotion && document.startViewTransition) {
    const x = (originEvent && typeof originEvent.clientX === 'number') ? originEvent.clientX : window.innerWidth - 32;
    const y = (originEvent && typeof originEvent.clientY === 'number') ? originEvent.clientY : 24;
    const endRadius = Math.hypot(
      Math.max(x, window.innerWidth - x),
      Math.max(y, window.innerHeight - y)
    );
    document.documentElement.style.setProperty('--theme-origin-x', x + 'px');
    document.documentElement.style.setProperty('--theme-origin-y', y + 'px');
    document.documentElement.style.setProperty('--theme-radius', endRadius + 'px');
    // Every button/card/etc. still has its own hover/press transition
    // (0.12s-0.3s, scattered across the stylesheet) - those are unrelated
    // to theme switching normally, since they only fire on :hover/:active
    // changing. But they also fire on ANY change to the color values they
    // reference, theme switch included. A CSS transition's rendered value
    // at the instant it starts is still the OLD color - zero time has
    // passed - so the "new" snapshot startViewTransition() captures right
    // after applyTheme() runs would freeze every one of those elements
    // still showing their old color, mid-transition, with nothing to make
    // them finish until the live DOM is shown again after the wipe. That
    // produced a second, scattered wave of elements visibly catching up
    // to their real color right after the wipe completed - a second
    // flash stacked after the first. Suppressing transitions completely
    // for the moment applyTheme() runs makes every element jump straight
    // to its final color, so the snapshot the wipe reveals is already
    // fully correct and there's nothing left to catch up afterward.
    document.documentElement.classList.add('theme-instant');
    const transition = document.startViewTransition(applyTheme);
    transition.finished.catch(() => {}).finally(() => {
      document.documentElement.classList.remove('theme-instant');
    });
  } else if (!reduceMotion) {
    // Fallback for browsers without View Transitions support.
    document.documentElement.classList.add('theme-transitioning');
    clearTimeout(window._themeTransitionTimer);
    window._themeTransitionTimer = setTimeout(() => {
      document.documentElement.classList.remove('theme-transitioning');
    }, 150);
    applyTheme();
  } else {
    applyTheme();
  }

  // Instant cloud persistence (no 2.5s delay)
  if (currentUser && db) {
    // Mark this write's resulting hash as already-seen so the server's ack
    // echo (arriving via onSnapshot a moment later) isn't mistaken for an
    // incoming remote change -- that mistake was causing an unconditional,
    // unrelated full dashboard re-render shortly after every theme toggle.
    lastCloudPayloadHash = calculatePayloadHash({
      profile: loadProfile(),
      customTasks: state.customTasks,
      customTimetable: safeGetStorage(KEY_CUSTOM_TIMETABLE, null),
      assignmentStatuses: safeGetStorage(KEY_ASSIGNMENTS, {}),
      theme: theme
    });
    db.collection('users').doc(currentUser.uid).set({
      theme: theme,
      updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    }, { merge: true }).catch(() => {});
  }
}

function updateThemeSelector(theme) {
  const btn = document.getElementById('theme-toggle-btn');
  const icon = document.getElementById('theme-toggle-icon');
  const label = document.getElementById('theme-toggle-label');
  
  const isDark = theme === 'midnight-ink';
  const themeName = THEME_LABELS[theme] || 'Paper Slate';
  const nextThemeName = isDark ? 'Paper Slate' : 'Midnight Ink';
  if (btn) {
    btn.setAttribute('aria-label', `Current theme: ${themeName}. Click to switch to ${nextThemeName}.`);
    btn.setAttribute('title', `Switch to ${nextThemeName}`);
    btn.setAttribute('data-theme-active', theme);
  }
  if (icon) {
    icon.innerHTML = isDark ? icons.moon() : icons.sun();
  }
  if (label) {
    label.textContent = themeName;
  }

  // Sync Settings page theme swatches if currently rendered
  const swatches = document.querySelectorAll('.theme-swatch');
  swatches.forEach(sw => {
    const isMatch = sw.getAttribute('onclick')?.includes(`'${theme}'`);
    sw.classList.toggle('active', !!isMatch);
    sw.setAttribute('aria-pressed', isMatch ? 'true' : 'false');
  });
}

// ── Routing ───────────────────────────────────────────────────
const PAGES = ['dashboard', 'timetable', 'subjects', 'assignments', 'calendar', 'notices', 'resources', 'links', 'summary', 'settings', 'review'];
const sectionHistory = [];

// Subject rings animate once per view (opening the tab or a hub), not on
// every background re-render (sync, focus, manage mode).
let subjectViewSeq = 0;
let subjectRingsAnimatedSeq = -1;

function navigate(page, isBack = false, keepActiveSubject = false) {
  if (page !== 'assignments' && (taskSelectMode || taskSelection.size)) { taskSelectMode = false; taskSelection.clear(); }
  if (!PAGES.includes(page)) page = 'dashboard';
  subjectViewSeq++;

  // Unless explicitly instructed to keep active subject, clear activeSubject state
  if (!keepActiveSubject) {
    state.activeSubject = null;
  }

  const current = state.currentPage;
  if (!isBack && current && current !== page) {
    if (sectionHistory.length === 0 || sectionHistory[sectionHistory.length - 1] !== current) {
      sectionHistory.push(current);
    }
  }

  if (page === 'links' || page === 'summary') {
    state.resourcesTab = page;
    page = 'resources';
  } else if (page === 'resources') {
    if (!state.resourcesTab) state.resourcesTab = 'links';
  }

  state.currentPage = page;
  window.location.hash = (page === 'resources') ? (state.resourcesTab || 'resources') : page;

  document.querySelectorAll('.section-page').forEach(el =>
    el.classList.toggle('active', el.dataset.page === page)
  );

  document.querySelectorAll('[data-nav]').forEach(el => {
    const navVal = el.dataset.nav;
    if (page === 'resources') {
      el.classList.toggle('active', navVal === 'resources' || navVal === state.resourcesTab);
    } else {
      el.classList.toggle('active', navVal === page);
    }
  });

  updateBackButtonUI();
  if (page !== current) dashboardSettled = false;   // arriving: greeting settles in once
  renderPage(page);
  // A new page starts at the top. Without this, Today opened at whatever
  // offset the previous page was scrolled to, so on a phone the greeting
  // and stat tiles were already scrolled out of view.
  // ('instant': html has scroll-behavior: smooth, which would glide there.)
  if (current && page !== current) window.scrollTo({ top: 0, left: 0, behavior: 'instant' });

  // The Tasks & Deadlines page already has its own persistent "+ Add Task"
  // header button doing the exact same thing, so the floating quick-add FAB
  // is pure redundant clutter there (and visibly collides with that page's
  // own empty-state CTA). Same on Today: its Tasks panel has the inline
  // quick-add field, so a second floating "Add Task" there is a duplicate.
  const fabEl = document.querySelector('.fab');
  if (fabEl) {
    // Calendar has its own "Add deadline for <date>" action, and the FAB
    // covered its empty state's "Set Up Timetable" button on phones.
    fabEl.style.display = (page === 'assignments' || page === 'dashboard' || page === 'calendar') ? 'none' : '';
    // On the Timetable page the + adds a class; everywhere else it adds a task.
    const addsClass = page === 'timetable';
    fabEl.setAttribute('aria-label', addsClass ? 'Add class' : 'Add new task');
    const fabLabel = fabEl.querySelector('.fab-label');
    if (fabLabel) fabLabel.textContent = addsClass ? 'Add Class' : 'Add Task';
  }
}

window.fabAction = function() {
  if (state.currentPage === 'timetable') showTimetableEntryModal(state.ttDay, null);
  else showAddTaskModal();
};

// Immediately attach to window so inline onclick handlers work without waiting for full script load
window.navigateTo = function(page) { navigate(page, false, false); };
window.navigate   = function(page) { navigate(page, false, false); };
window.navigateBack = function() {
  // If currently inside a single subject hub detail view, back action returns to list or previous route
  if (state.currentPage === 'subjects' && state.activeSubject) {
    state.activeSubject = null;
    subjectViewSeq++;
    if (sectionHistory.length > 0) {
      const prev = sectionHistory.pop();
      if (prev === 'subjects_overview' || prev === 'subjects') {
        updateBackButtonUI();
        renderSubjects();
        return;
      } else {
        navigate(prev, true);
        return;
      }
    } else {
      updateBackButtonUI();
      renderSubjects();
      return;
    }
  }

  if (sectionHistory.length > 0) {
    let prev = sectionHistory.pop();
    if (prev === 'subjects_overview') prev = 'subjects';
    state.activeSubject = null;
    navigate(prev, true);
  }
};

function updateBackButtonUI() {
  const backBtn = document.getElementById('nav-back-btn');
  if (!backBtn) return;
  const hasHistory = sectionHistory.length > 0 || (state.currentPage === 'subjects' && !!state.activeSubject);
  if (hasHistory) {
    backBtn.style.display = 'inline-flex';
    backBtn.disabled = false;
  } else {
    backBtn.style.display = 'none';
    backBtn.disabled = true;
  }
}

let __lastRenderPage = null;
let __lastRenderTime = 0;

// Text the student has typed into a page's own fields (not modals), so a
// re-render can put it back. Only non-empty fields with an id are kept.
function captureTypedDrafts() {
  try {
    const page = document.querySelector('.section-page.active');
    if (!page) return null;
    const fields = [...page.querySelectorAll('input[id]:not([type]), input[id][type="text"], input[id][type="search"], textarea[id]')]
      .filter(el => el.value && el.value.trim());
    const a = document.activeElement;
    const focused = a && a.id && page.contains(a) && /^(INPUT|TEXTAREA)$/.test(a.tagName)
      ? { id: a.id, start: a.selectionStart, end: a.selectionEnd } : null;
    const qa = page.querySelector('#quick-add-container');
    const qaPrompt = qa && qa.innerHTML.trim() && window._qaFinalize
      ? { html: qa.innerHTML, date: (qa.querySelector('#quick-add-date') || {}).value || '', dateFocused: !!(a && a.id === 'quick-add-date') } : null;
    const rs = page.querySelector('input[id^="resched-"]');
    const resched = rs ? { taskId: rs.id.slice(8), date: rs.value } : null;
    // Prefilled fields the student changed but hasn't saved yet (Settings:
    // exam date, name, reminder choices). A cloud sync used to put the old
    // saved value back. Fields with their own change handler are left alone.
    const edited = page.id !== 'page-settings' ? [] : [...page.querySelectorAll('input[id], select[id], textarea[id]')]
      .filter(el => !el.hasAttribute('onchange') && !el.hasAttribute('oninput') && isFieldEdited(el))
      .map(el => [el.id, el.value]);
    if (!fields.length && !focused && !qaPrompt && !resched && !edited.length) return null;
    return { values: fields.map(el => [el.id, el.value]), focused, qaPrompt, resched, edited };
  } catch (e) { return null; }
}
function restoreTypedDrafts(d) {
  if (!d) return;
  try {
    d.values.forEach(([id, value]) => {
      const el = document.getElementById(id);
      if (el && !el.value) el.value = value;
    });
    (d.edited || []).forEach(([id, value]) => {
      const el = document.getElementById(id);
      if (el && !isFieldEdited(el) && el.value !== value) el.value = value;
    });
    if (d.resched && !document.getElementById('resched-' + d.resched.taskId) && document.getElementById('rollover-card-' + d.resched.taskId)) {
      window.handleRolloverAction(d.resched.taskId, 'reschedule');
      const re = document.getElementById('resched-' + d.resched.taskId);
      if (re && d.resched.date) re.value = d.resched.date;
    }
    // The "when is it due?" prompt is injected DOM, so a background render wiped it.
    if (d.qaPrompt && window._qaFinalize && !document.getElementById('quick-add-container')) {
      const input = [...document.querySelectorAll('#quick-add-input')].find(el => el.offsetParent !== null);
      if (input) {
        const box = document.createElement('div');
        box.id = 'quick-add-container';
        box.className = 'quick-add-prompt';
        box.innerHTML = d.qaPrompt.html;
        (input.parentElement || input).insertAdjacentElement('afterend', box);
        const de = box.querySelector('#quick-add-date');
        if (de) {
          if (d.qaPrompt.date) de.value = d.qaPrompt.date;
          if (d.qaPrompt.dateFocused) de.focus({ preventScroll: true });
        }
      }
    }
    if (d.focused) {
      const el = document.getElementById(d.focused.id);
      if (el && document.activeElement !== el) {
        el.focus({ preventScroll: true });
        if (typeof d.focused.start === 'number') el.setSelectionRange(d.focused.start, d.focused.end);
      }
    }
  } catch (e) { /* never block a render */ }
}

// While the student is choosing a date (Add task prompt, Reschedule) the page
// must not be rebuilt under them: the native date picker closes and the field
// resets. Background refreshes wait; they run as soon as the prompt closes.
// The same goes for any date, time or dropdown field on the page while it is
// in use (Settings exam date, daily briefing time): a cloud sync arriving then
// closed the picker. Fields with their own change handler are not held, so
// their own refresh still runs straight away.
let __renderDeferred = null;
const PICKER_INPUT_TYPES = ['date', 'time', 'datetime-local', 'month', 'week'];
function isPickerField(el) {
  return !!el && (el.tagName === 'SELECT' || (el.tagName === 'INPUT' && PICKER_INPUT_TYPES.includes(el.type)));
}
function isFieldEdited(el) {
  if (el.tagName === 'SELECT') return [...el.options].some(o => o.selected !== o.defaultSelected);
  if (el.type === 'checkbox' || el.type === 'radio' || el.type === 'file' || el.type === 'hidden') return false;
  return el.value !== el.defaultValue;
}
function isDatePromptOpen(page) {
  try {
    const el = document.getElementById('page-' + page);
    if (!el || !el.classList.contains('active')) return false;
    if (el.querySelector('#quick-add-date') || el.querySelector('input[id^="resched-"]')) return true;
    const a = document.activeElement;
    return isPickerField(a) && el.contains(a) && !a.hasAttribute('onchange') && !a.hasAttribute('oninput');
  } catch (e) { return false; }
}
// Run the held refresh once the student leaves the field. The short wait lets
// a tap on Save land before the page is rebuilt under it.
document.addEventListener('focusout', (e) => {
  if (__renderDeferred && isPickerField(e.target)) setTimeout(flushDeferredRender, 400);
});
function flushDeferredRender() {
  if (__renderDeferred && !isDatePromptOpen(__renderDeferred)) {
    const p = __renderDeferred; __renderDeferred = null; renderPage(p);
  }
}

function renderPage(page) {
  if (isDatePromptOpen(page)) { __renderDeferred = page; return; }
  // Coalesce accidental duplicate calls: two calls for the SAME page
  // within a few tens of milliseconds of each other are treated as one
  // and the second is skipped, instead of tearing the page's DOM down
  // and rebuilding it twice in a row. This is a permanent backstop
  // against this whole class of bug (we already found and fixed one
  // cause -- a nav item that fired navigate() twice per click -- but a
  // guard here means any other accidental double-fire, now or in the
  // future, from anywhere in the app can't reproduce the same visible
  // "popping in and out" of a page's content again). A real second
  // render for a genuine later change is unaffected -- it always arrives
  // well outside this window.
  const now = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
  if (page === __lastRenderPage && (now - __lastRenderTime) < 50) {
    return;
  }
  applyHolidayVibe();
  __lastRenderPage = page;
  __lastRenderTime = now;

  // Background re-renders (cloud sync arriving, class starting, day change)
  // rebuild the page's HTML. Without this, whatever the student was typing
  // into the Add task / Ask Desk box vanished mid-word. Keep it.
  const drafts = captureTypedDrafts();

  try {
    switch (page) {
      case 'dashboard':   renderDashboard();   break;
      case 'review':      renderReview();      break;
      case 'timetable':   renderTimetable();   break;
      case 'subjects':    renderSubjects();    break;
      case 'assignments': renderAssignments(); break;
      case 'calendar':    renderCalendar();    break;
      case 'notices':     renderNotices();     break;
      case 'resources':
      case 'links':
      case 'summary':     renderResources();   break;
      case 'settings':    renderSettings();    break;
    }
    restoreTypedDrafts(drafts);
  } catch (err) {
    console.error(`Error rendering page [${page}]:`, err);
    const targetEl = document.getElementById(`page-${page}`) || document.getElementById('page-resources');
    if (targetEl) {
      targetEl.innerHTML = `
        <div class="card" style="text-align:center;padding:40px 20px;margin-top:20px;border-left:3px solid var(--red)">
          <div style="font-size:var(--text-hero);margin-bottom:10px">${icons.alert()}</div>
          <div style="font-weight:700;font-size:var(--text-lg);margin-bottom:6px">Unable to render section</div>
          <div style="font-size:var(--text-base);color:var(--text-muted);margin-bottom:16px">${err.message || 'An unexpected rendering error occurred.'}</div>
          <button class="btn-primary" onclick="location.reload()" style="font-size:var(--text-base)">Reload Campus OS</button>
        </div>
      `;
    }
  }
}

// ── Helpers ───────────────────────────────────────────────────
const DAY_NAMES   = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const DAY_SHORT   = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const MONTH_NAMES = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

function formatDate(dateStr) {
  if (!dateStr) return '';
  const d = new Date(dateStr + 'T00:00:00');
  if (isNaN(d.getTime())) return String(dateStr);
  return `${d.getDate()} ${MONTH_NAMES[d.getMonth()]} ${d.getFullYear()}`;
}

const DAY_NAMES_SHORT = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

// Dashboard masthead live clock: 12-hour, no seconds, ticking about once a
// minute. Deliberately mutates one text node directly (see
// updateLiveClockDisplay) rather than re-rendering anything -- this session
// spent a lot of effort eliminating spurious dashboard re-renders, so a
// ticking clock must never become a new source of them.
function formatLiveClockParts(d) {
  const dateStr = `${DAY_NAMES_SHORT[d.getDay()]}, ${d.getDate()} ${MONTH_NAMES[d.getMonth()]}`;
  let hours = d.getHours();
  const ampm = hours >= 12 ? 'PM' : 'AM';
  hours = hours % 12;
  if (hours === 0) hours = 12;
  const mins = String(d.getMinutes()).padStart(2, '0');
  return { dateStr, timeStr: `${hours}:${mins} ${ampm}` };
}

function updateLiveClockDisplay() {
  // Lives in the persistent topbar (index.html/404.html), not per-page
  // content, so this same element is present on every page -- no more
  // confined to the dashboard.
  const el = document.getElementById('topbar-clock-text');
  if (!el) return;
  const { dateStr, timeStr } = formatLiveClockParts(new Date());
  el.textContent = `${dateStr} · ${timeStr}`;
}

// ── Class countdown on Today's Next Up / In Session card ─────────────────
// Whole-minute arithmetic on purpose: the card's own state test is
// `currentMin >= start && currentMin < end`, so the countdown can never read
// "0 min" or disagree with which state the card is in.
function formatCountdown(mins) {
  const m = Math.max(0, Math.round(mins));
  if (m < 60) return `${m} min`;
  return `${Math.floor(m / 60)}h ${String(m % 60).padStart(2, '0')}m`;
}

function beaconProgressPct(startMin, endMin, nowMin) {
  const span = endMin - startMin;
  if (!(span > 0)) return 0;
  return Math.min(100, Math.max(0, Math.round(((nowMin - startMin) / span) * 100)));
}

// When today has no class left (day finished, or a rest day) the card looks
// ahead instead of just saying "done": the first teaching class on the next
// day that has one. Reads the saved timetable exactly like the rest of Today
// does -- it was already filtered to the student's own batch when it was saved.
function findNextClassDay(tt, fromDayIdx) {
  for (let off = 1; off <= 7; off++) {
    const idx = (fromDayIdx + off) % 7;
    const list = ((tt && tt[idx]) || []).filter(isTeachingClass);
    if (!list.length) continue;
    const first = list.reduce((a, c) => (timeToMinutes(c.time || '00:00') < timeToMinutes(a.time || '00:00') ? c : a));
    const label = off === 1 ? 'Tomorrow' : off === 7 ? `Next ${DAY_NAMES[idx]}` : DAY_NAMES[idx];
    return { offset: off, label, cls: first };
  }
  return null;
}

// Once a minute (and when the app comes back to the foreground) this mutates
// only the countdown text and the progress bar -- never a re-render, so it
// cannot bring back the "top of Today keeps refreshing" problem. The one
// exception is a class boundary (Next Up -> In Session -> done), where the
// card, the schedule ledger and the "classes left" count all really do change,
// so Today is rebuilt once, not on a timer.
function tickBeacon() {
  if (typeof state === 'undefined' || state.currentPage !== 'dashboard') return;
  if (refreshIfDayChanged()) return;
  const card = document.querySelector('#page-dashboard .chrono-beacon[data-beacon]');
  if (!card) return;
  const kind = card.dataset.beacon;
  const startMin = Number(card.dataset.start);
  const endMin = Number(card.dataset.end);
  const nowMin = currentTimeMinutes();
  const outOfDate = (kind === 'next' && nowMin >= startMin) || (kind === 'live' && nowMin >= endMin);
  if (outOfDate) {
    // Never rebuild Today underneath someone who is typing (e.g. Ask Desk).
    const a = document.activeElement;
    if (a && a.closest && a.closest('#page-dashboard') && /^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName)) return;
    renderPage('dashboard');
    return;
  }
  const num = card.querySelector('[data-beacon-count]');
  if (num) num.textContent = formatCountdown((kind === 'next' ? startMin : endMin) - nowMin);
  const bar = card.querySelector('[data-beacon-bar]');
  if (bar && kind === 'live' && bar.firstElementChild) {
    const pct = beaconProgressPct(startMin, endMin, nowMin);
    bar.firstElementChild.style.width = pct + '%';
    bar.setAttribute('aria-valuenow', String(pct));
  }
}

// Lands just after the next wall-clock minute so the countdown and the topbar
// clock flip together (the old 60 s interval started at load, so it could lag
// the real minute by up to 59 s).
let beaconTickTimer = null;
function scheduleBeaconTick() {
  clearTimeout(beaconTickTimer);
  beaconTickTimer = setTimeout(() => {
    updateLiveClockDisplay();
    tickBeacon();
    scheduleBeaconTick();
  }, 60000 - (Date.now() % 60000) + 200);
}

function dueDaysLeft(dateStr) {
  if (!dateStr) return null;
  const now = new Date(); now.setHours(0,0,0,0);
  const due = new Date(dateStr + 'T00:00:00');
  if (isNaN(due.getTime())) return null;
  return Math.round((due - now) / 86400000);
}

function formatRelativeDueDate(dateStr) {
  const days = dueDaysLeft(dateStr);
  if (days === null) return { label: 'No deadline', cls: 'ongoing' };
  if (days < 0) return { label: `${Math.abs(days)}d overdue`, cls: 'overdue' };
  if (days === 0) return { label: 'Due Today', cls: 'today' };
  if (days === 1) return { label: 'Due Tomorrow', cls: 'soon' };
  if (days <= 7) return { label: `Due in ${days}d`, cls: 'soon' };
  return { label: formatDate(dateStr), cls: '' };
}

function isTaskOverdue(task) {
  if (!task || task.status !== 'pending') return false;
  if (task.noDeadline || (task.taskType === 'mission' && !task.dueDate)) return false;
  if (!task.dueDate) return false;
  return task.dueDate < todayStr();
}

function todayStr() {
  return localDateKey(new Date());
}

// Calendar date (YYYY-MM-DD) of `d` in the student's own timezone -- the key
// attendance marks are stored under. Never use d.toISOString().split('T')[0]
// for this: that is the UTC date, and for a local-midnight Date east of UTC
// (India is UTC+5:30) it is the PREVIOUS day. The timetable page did exactly
// that, so a Tuesday tab read Monday's marks and "Monday's attendance
// carried over" into the next day, while Today used the correct date.
// The one key a class's Present/Absent mark is stored under, for a given
// date. Today, the Next Up card, the timetable, the weekly review and the
// date-key repair all read and write marks through this, so a mark made in
// one place is the same record everywhere else.
function attendanceKeyFor(c) {
  return `${c.code || c.subject}_${c.time}`.replace(/[^a-zA-Z0-9_]/g, '');
}

function localDateKey(d) {
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

// Repairs marks saved under that wrong (previous-day) key before this fix.
// A mark is moved one day forward only when its class is NOT on the stored
// date's weekday but IS on the next day's -- i.e. it can only belong to the
// next day. Anything ambiguous (same class and time on both days) is left
// alone, as is every mark dated on/after the day this repair first ran, so
// marks saved with the correct key are never touched. Re-runs after a
// cloud sync or backup import (either can bring the old keys back) and is
// a no-op once repaired. The untouched original is kept locally in
// KEY_ATT_DATEFIX_BACKUP. Returns the number of marks moved.
function fixShiftedAttendanceDates() {
  // Only timezones east of UTC produced the shifted keys.
  if (new Date().getTimezoneOffset() >= 0) return 0;
  let cutoff = safeGetStorage(KEY_ATT_DATEFIX_CUTOFF, null);
  if (typeof cutoff !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(cutoff)) {
    cutoff = todayStr();
    safeSetStorage(KEY_ATT_DATEFIX_CUTOFF, JSON.stringify(cutoff));
  }
  const data = safeGetStorage(KEY_ATTENDANCE, {}) || {};
  const tt = loadTimetable();
  const classKeysOn = (weekday) => new Set((tt[weekday] || []).filter(isTeachingClass)
    .map(c => attendanceKeyFor(c)));
  const original = JSON.stringify(data);
  let moved = 0;

  Object.keys(data).sort().forEach(dateKey => {
    const dayObj = data[dateKey];
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateKey) || dateKey >= cutoff || !dayObj || typeof dayObj !== 'object') return;
    const day = new Date(`${dateKey}T00:00:00`);
    const next = new Date(day);
    next.setDate(day.getDate() + 1);
    const nextKey = localDateKey(next);
    const onThisDay = classKeysOn(day.getDay());
    const onNextDay = classKeysOn(next.getDay());
    Object.keys(dayObj).forEach(classKey => {
      if (onThisDay.has(classKey) || !onNextDay.has(classKey)) return;
      if (!data[nextKey]) data[nextKey] = {};
      // A mark already saved correctly for that class (from Today) wins;
      // the shifted copy was the same class counted twice.
      if (!(classKey in data[nextKey])) data[nextKey][classKey] = dayObj[classKey];
      delete dayObj[classKey];
      moved++;
    });
    if (Object.keys(dayObj).length === 0) delete data[dateKey];
  });

  if (moved > 0) {
    if (!safeGetStorage(KEY_ATT_DATEFIX_BACKUP, null)) localStorage.setItem(KEY_ATT_DATEFIX_BACKUP, original);
    safeSetStorage(KEY_ATTENDANCE, data);
    console.info(`[Attendance] Moved ${moved} mark(s) saved under the previous day's date to the right day.`);
  }
  return moved;
}

// Re-renders date-dependent pages once the calendar day changes while the
// app stays open (PWAs are often resumed hours later): Today's schedule and
// the timetable's Present/Absent state are keyed by date, so without this
// they kept showing the previous day until a manual reload.
let lastRenderedDayKey = todayStr();
function refreshIfDayChanged() {
  const nowKey = todayStr();
  if (nowKey === lastRenderedDayKey) return false;
  const previousWeekday = new Date(`${lastRenderedDayKey}T00:00:00`).getDay();
  lastRenderedDayKey = nowKey;
  checkHolidayExpiry();
  // The timetable follows "today" unless the student had picked another day.
  if (state.ttDay === previousWeekday) state.ttDay = new Date().getDay();
  // The calendar's month and selected date live only in `state`, so a tab
  // left open overnight kept whatever month it was on (e.g. November after
  // a Next tap, with the 1st selected) and ringed yesterday as "today".
  state.calMonth = nowKey.slice(0, 7);
  state.calSelected = nowKey;
  if (['dashboard', 'timetable', 'review', 'calendar'].includes(state.currentPage)) renderPage(state.currentPage);
  return true;
}

function currentTimeMinutes() {
  const d = new Date();
  return d.getHours() * 60 + d.getMinutes();
}

function timeToMinutes(t) {
  if (!t || typeof t !== 'string') return 0;
  const parts = t.split(':').map(Number);
  if (parts.length < 2 || isNaN(parts[0]) || isNaN(parts[1])) return 0;
  return parts[0] * 60 + parts[1];
}

// A varied, time-(and occasionally situation-)aware dashboard greeting,
// instead of one fixed "Good morning/afternoon/evening/night" per time
// bucket. Each bucket has a few alternate phrasings; which one shows picks
// deterministically off the date+hour (so it doesn't change mid-visit on a
// re-render, but does vary day to day) rather than fully at random.
// Returns ready-to-insert HTML (name pre-wrapped in the existing
// .desk-greeting-name accent span) so the render site can drop it straight
// into .desk-greeting with no extra punctuation glued on afterward.
function getDynamicGreeting(firstName, opts = {}) {
  const overdue = opts.overdue || 0;
  const h = new Date().getHours();
  const has = !!firstName;

  let pool;
  if (opts.holiday) {
    pool = [['Happy holidays, {n}.', 'Happy holidays.'], ['Enjoy the break, {n}.', 'Enjoy the break.'], ['Easy day, {n}.', 'Easy day.']];
  } else if (h < 5) {
    // Late night: acknowledge unfinished work if there's any, otherwise
    // just the "still up" vibe -- both read as company, not a nag.
    pool = overdue > 0
      ? [['Still up, {n}?', 'Still up?'], ['Burning the midnight oil, {n}?', 'Burning the midnight oil?'], ['Late night catch-up, {n}.', 'Late night catch-up.'],
         ['Still at it, {n}?', 'Still at it?'], ['Late one tonight, {n}.', 'Late one tonight.']]
      : [['Up late, {n}?', 'Up late?'], ['Night owl mode, {n}.', 'Night owl mode.'], ['Still awake, {n}?', 'Still awake?'],
         ["Can't sleep, {n}?", "Can't sleep?"], ['Hello, night owl.', 'Hello, night owl.'], ['Quiet hours, {n}.', 'Quiet hours.']];
  } else if (h < 8) {
    pool = [['Up early, {n}.', 'Up early.'], ['Rise and shine, {n}.', 'Rise and shine.'], ['Early start, {n}.', 'Early start.'],
      ['Bright and early, {n}.', 'Bright and early.'], ['Beat the alarm, {n}?', 'Beat the alarm?'], ['Early bird, {n}.', 'Early bird.']];
  } else if (h < 12) {
    pool = [['Good morning, {n}.', 'Good morning.'], ['Morning, {n}.', 'Morning.'], ["Let's get into it, {n}.", "Let's get into it."],
      ['Morning, {n}. Chai first?', 'Morning. Chai first?'], ['Hey {n}, good morning.', 'Hey, good morning.'], ['Hello again, {n}.', 'Hello again.']];
  } else if (h < 17) {
    pool = [['Good afternoon, {n}.', 'Good afternoon.'], ['Afternoon, {n}.', 'Afternoon.'], ['Midday check-in, {n}.', 'Midday check-in.'],
      ["Hey {n}, how's the day going?", "Hey, how's the day going?"], ['Post-lunch slump, {n}?', 'Post-lunch slump?'], ['Halfway there, {n}.', 'Halfway there.']];
  } else if (h < 21) {
    pool = [['Good evening, {n}.', 'Good evening.'], ['Evening, {n}.', 'Evening.'], ['Winding down, {n}?', 'Winding down?'],
      ['Long day, {n}?', 'Long day?'], ['Back at the desk, {n}.', 'Back at the desk.'], ['Hey {n}, made it through the day.', 'Hey, made it through the day.']];
  } else {
    pool = [['Good night, {n}.', 'Good night.'], ['Working late, {n}?', 'Working late?'], ['Still going, {n}?', 'Still going?'],
      ['One more thing before bed, {n}?', 'One more thing before bed?'], ['Late study session, {n}?', 'Late study session?'], ['Night shift, {n}?', 'Night shift?']];
  }

  const seed = new Date().getDate() + h;
  const [withName, withoutName] = pool[seed % pool.length];

  if (!has) return withoutName;
  const nameHtml = `<span class="desk-greeting-name">${escHtml_cd(firstName)}</span>`;
  return withName.replace('{n}', nameHtml);
}

// Returns user's configured attendance target (default 75)
function getAttendanceTarget() {
  const stored = parseInt(safeGetStorage(KEY_ATT_TARGET, 75) || '75', 10);
  if (isNaN(stored) || stored < 50 || stored > 100) return 75;
  return stored;
}

// Builds a situation-aware context line for the dashboard masthead.
// Priority: attendance risk > overdue tasks > exam imminent > normal > all clear.
// What the Today countdown is counting down to. Blank keeps the original
// End-Sem wording, so nothing changes for students who never set it.
function getCountdownLabel() {
  const l = String((liveProfile && liveProfile.examLabel) || '').trim();
  return l || 'End-Sem exams';
}

function isSelfStudyMode() {
  return !!(liveProfile && liveProfile.studyMode === 'self');
}

// One short, calm line of encouragement picked by how far away the
// countdown date is. Used on Today and in the countdown reminder.
function countdownCheer(days) {
  if (days === null || days === undefined || isNaN(days) || days < 0) return '';
  if (days === 0) return 'Today is the day. You are ready.';
  if (days === 1) return 'One more day. Make it count.';
  if (days <= 7) return 'Final stretch. You can do this.';
  if (days <= 30) return 'One topic at a time. You can do this.';
  if (days <= 60) return 'Steady beats rushed. Keep going.';
  return 'Plenty of time. A little every day adds up.';
}

// On Today, the countdown milestone days (30, 14, 7, 3, 1 and the day
// itself) get one in-app card each. Seen-markers share the reminder
// history map, with their own "card_" prefix.
function maybeShowCountdownCelebration() {
  if (!liveProfile || !liveProfile.examDate) return;
  const today = todayStr();
  const days = Math.round((new Date(liveProfile.examDate + 'T00:00:00') - new Date(today + 'T00:00:00')) / 86400000);
  if (![30, 14, 7, 3, 1, 0].includes(days)) return;
  if (holidayHidesCountdown(days)) return;
  const seen = safeGetStorage('cos_notified_history', {}) || {};
  const key = `card_countdown_${days}_${liveProfile.examDate}`;
  if (seen[key]) return;
  seen[key] = true;
  safeSetStorage('cos_notified_history', seen);
  const label = getCountdownLabel();
  const title = days === 0 ? `${label} is today` : `${days} day${days === 1 ? '' : 's'} to ${label}`;
  setTimeout(() => showCelebration(days === 0 ? '🌟' : '📅', title, countdownCheer(days)), 600);
}

function buildDashboardContextLine(opts = {}) {
  const { attendancePct, attendancePctLabel, attendanceAtRisk, attTarget, overdue, pending, classesLeft, totalClasses, examDaysLeft, firstName, dayClasses } = opts;
  const isWeekend = dayClasses !== undefined && dayClasses.length === 0;

  // Holiday mode: talk about the break and tasks, never about classes.
  if (opts.holiday) {
    if (examDaysLeft !== null && examDaysLeft >= 0 && examDaysLeft <= 7) {
      const examLabel = escHtml_cd(opts.examLabel || 'End-Sem exams');
      return examDaysLeft === 0 ? `${examLabel}: <strong>today</strong>. You are ready.`
        : `<strong>${examDaysLeft} day${examDaysLeft !== 1 ? 's' : ''}</strong> to ${examLabel}. A little each day is enough.`;
    }
    if (overdue > 0) return `${overdue} overdue task${overdue !== 1 ? 's' : ''} need${overdue === 1 ? 's' : ''} attention.`;
    return pending > 0
      ? `No classes, no rush. ${pending} task${pending !== 1 ? 's' : ''} on your desk when you're ready.`
      : 'No classes, no rush. Your timetable is safe for when classes start again.';
  }

  // Attendance at risk — highest urgency, surfaces immediately
  if (attendanceAtRisk ?? (attendancePct !== null && attendancePct < attTarget)) {
    return `Attendance is <strong>below your ${attTarget}% target</strong>. Try not to miss today's classes.`;
  }

  // Overdue tasks — second priority
  if (overdue > 0) {
    return `${overdue} overdue task${overdue !== 1 ? 's' : ''} need${overdue === 1 ? 's' : ''} attention before anything else.`;
  }

  // Exam imminent (≤ 7 days)
  if (examDaysLeft !== null && examDaysLeft >= 0 && examDaysLeft <= 7) {
    const examLabel = escHtml_cd(opts.examLabel || 'End-Sem exams');
    if (examDaysLeft === 0) return `${examLabel}: <strong>today</strong>.`;
    if (examDaysLeft === 1) return `${examLabel}: <strong>tomorrow</strong>.`;
    return `<strong>${examDaysLeft} days</strong> to ${examLabel}.`;
  }

  // Brand-new desk: no timetable yet, so "no classes today" would be wrong
  // Self-study with no timetable: talk about the plan, never about classes
  if (opts.selfStudy && opts.hasTimetable === false) {
    return pending > 0
      ? `${pending} task${pending !== 1 ? 's' : ''} on your plan.`
      : 'Add a study task for today to plan your day.';
  }

  // No timetable and no tasks: the Get started card below says it already.
  if (opts.hasTimetable === false && pending === 0) {
    return '';
  }

  // Weekend or free day with no tasks
  if (isWeekend && pending === 0) {
    return 'No classes today and no tasks pending.';
  }

  // Normal day with classes remaining
  if (classesLeft > 0) {
    return `${classesLeft} class${classesLeft !== 1 ? 'es' : ''} remaining today.${pending > 0 ? ` ${pending} task${pending !== 1 ? 's' : ''} pending.` : ''}`;
  }

  // All classes done, tasks pending
  if (pending > 0) {
    return `Classes done for today. ${pending} task${pending !== 1 ? 's' : ''} still pending.`;
  }

  // Everything clear
  return 'Classes are over for today and no tasks are pending.';
}

// ── Today's next step (a gentle nudge) ─────────────────────────────────
// One line under the class card: the single most useful thing to do right
// now, picked from data the page already has. Read-only: no attendance or
// task is changed, and nothing is written except "Not now" for the day.
// Order: a class that has ended and was never marked > a task that is due
// today or overdue > the subject furthest below the attendance target.
function buildTodayFocus(o = {}) {
  const { dayClasses = [], attendanceData = {}, dateStr = '', currentMin = 0, task = null, riskSubject = null, dismissed = [] } = o;
  const skip = new Set(dismissed);

  const marks = attendanceData[dateStr] || {};
  const unmarked = dayClasses.filter(c => c.end && timeToMinutes(c.end) <= currentMin && !marks[attendanceKeyFor(c)]);
  if (unmarked.length) {
    const last = unmarked[unmarked.length - 1];
    const id = `unmarked:${attendanceKeyFor(last)}`;
    if (!skip.has(id)) {
      return {
        kind: 'unmarked', id, go: 'Mark',
        // One class: the row marks it in place (Present / Absent), so Today
        // has a single place to mark it. Several: the row links to Timetable.
        markKey: unmarked.length === 1 ? attendanceKeyFor(last) : null,
        title: unmarked.length === 1 ? `Mark ${last.subject}` : `${unmarked.length} classes aren't marked yet`,
        sub: unmarked.length === 1 ? `Ended at ${formatDisplayTime(last.end)}. Your attendance % only counts marked classes.` : 'Your attendance % only counts marked classes.'
      };
    }
  }

  if (task && task.dueDate) {
    const days = dueDaysLeft(task.dueDate);
    const id = `task:${task.id}`;
    if (days !== null && days <= 0 && !skip.has(id)) {
      return {
        kind: 'task', id, go: 'Open',
        title: task.title,
        sub: days === 0 ? 'Due today' : `${-days} day${days === -1 ? '' : 's'} overdue`
      };
    }
  }

  if (riskSubject && riskSubject.classesToAttend >= 1 && riskSubject.classesToAttend <= 60) {
    const id = `risk:${riskSubject.name}`;
    if (!skip.has(id)) {
      const n = riskSubject.classesToAttend;
      return {
        kind: 'risk', id, go: 'Open', subject: riskSubject.name,
        title: `Attend the next ${n} ${riskSubject.name} class${n === 1 ? '' : 'es'}`,
        sub: `Now ${riskSubject.pctLabel ?? riskSubject.pct}%, target ${riskSubject.targetPct}%`
      };
    }
  }
  return null;
}

const FOCUS_DISMISS_KEY = 'cd_focus_dismissed';   // local only, not a cos_* key, not synced
function readDismissedFocus() {
  try {
    const o = JSON.parse(localStorage.getItem(FOCUS_DISMISS_KEY) || 'null');
    return o && o.day === todayStr() && Array.isArray(o.ids) ? o.ids : [];
  } catch (e) { return []; }
}
window.dismissTodayFocus = function(id) {
  try {
    const ids = readDismissedFocus();
    if (id && !ids.includes(id)) ids.push(id);
    localStorage.setItem(FOCUS_DISMISS_KEY, JSON.stringify({ day: todayStr(), ids }));
  } catch (e) { /* private mode: it simply comes back next render */ }
  if (state.currentPage === 'dashboard') renderDashboard();
};

// Markup for the row. Wrapped so a bad record can never blank Today.
// out.markKey is set to the class this row marks, so the schedule below can
// leave out its own Present / Absent for that class.
function todayFocusHTML({ dayClasses, attendanceData, dateStr, currentMin, dayIdx, urgentTasks, out = {} }) {
  try {
    const attrSafe = (v) => escHtml_cd(v).replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    const task = (urgentTasks || []).find(a => a.dueDate && !a.noDeadline);
    let riskSubject = null;
    if (!isHolidayActive()) getSubjectList().forEach(sj => {
      const att = getSubjectAttendance(sj);
      if (att.pct === null || att.isSafe) return;
      if (!riskSubject || att.exactPct < riskSubject.exactPct) {
        riskSubject = { name: sj.name, pct: att.pct, pctLabel: att.pctLabel, exactPct: att.exactPct, targetPct: att.targetPct, classesToAttend: att.classesToAttend };
      }
    });
    const f = buildTodayFocus({ dayClasses, attendanceData, dateStr, currentMin, task, riskSubject, dismissed: readDismissedFocus() });
    if (!f) return '';
    const overdue = f.kind === 'task' && /overdue/i.test(f.sub || '');
    const call = f.kind === 'unmarked' ? `setTTDay(${dayIdx}); navigateTo('timetable')`
      : f.kind === 'task' ? `navigateTo('assignments')`
      : `openSubjectHub(this.dataset.subject)`;
    const markKey = f.kind === 'unmarked' && f.markKey ? f.markKey : null;
    out.markKey = markKey;
    const markHTML = markKey ? `
      <div class="today-focus-mark">
        <button type="button" class="btn btn-secondary beacon-att" aria-pressed="false" aria-label="${attrSafe(f.title)} as attended" data-key="${attrSafe(markKey)}" onclick="setAttendance('${dateStr}', this.dataset.key, 'attended')">${icons.check()}<span>Present</span></button>
        <button type="button" class="btn btn-secondary beacon-att" aria-pressed="false" aria-label="${attrSafe(f.title)} as skipped" data-key="${attrSafe(markKey)}" onclick="setAttendance('${dateStr}', this.dataset.key, 'skipped')">${icons.x()}<span>Absent</span></button>
      </div>` : '';
    return `
    <div class="today-focus is-${f.kind}"${markKey ? ' data-mark' : ''} role="region" aria-label="Next step">
      <button type="button" class="today-focus-main" data-subject="${attrSafe(f.subject || '')}" onclick="${call}">
        <span class="today-focus-text">
          <span class="today-focus-title">${escHtml_cd(f.title)}</span>
          <span class="today-focus-sub${overdue ? ' is-overdue' : ''}">${escHtml_cd(f.sub)}</span>
        </span>
        ${markKey ? '' : `<span class="today-focus-go">${f.go} ${svg('<path d="M9 6l6 6-6 6"/>', 14)}</span>`}
      </button>
      <button type="button" class="today-focus-x" data-id="${attrSafe(f.id)}" onclick="dismissTodayFocus(this.dataset.id)" aria-label="Not now" title="Not now">${icons.x()}</button>${markHTML}
    </div>`;
  } catch (e) {
    return '';
  }
}

function allTasks() {
  return [...state.assignments, ...state.customTasks];
}

// ── Calendar (read-only) ──────────────────────────────────────
// Everything the calendar shows comes from here: classes from the saved
// timetable (repeated weekly, only for the dates asked for -- the expanded
// list is never stored) and dated tasks, including WhatsApp-imported ones.
// Reads only, writes nothing. Storage is read once per call, not per day.
const CAL_DEADLINE_TYPES = ['assignment', 'quiz', 'lab', 'project', 'exam'];

function calendarUserBatch() {
  const p = liveProfile || loadProfile() || {};
  return p.batch || safeGetStorage(KEY_USER_BATCH, '') || 'all';
}

function getCalendarItems(startKey, endKey, src = {}) {
  const tt = src.tt || loadTimetable() || {};
  const tasks = src.tasks || allTasks();
  const batch = src.batch || calendarUserBatch();
  const holiday = 'holiday' in src ? src.holiday : loadHoliday();
  const out = [];
  if (!startKey || !endKey || startKey > endKey) return out;

  // Same classes Today shows, plus the group filter (a no-op on a timetable
  // saved through the preview, which was filtered then).
  const classesByDay = {};
  for (let d = 0; d < 7; d++) {
    classesByDay[d] = (Array.isArray(tt[d]) ? tt[d] : [])
      .filter(c => isTeachingClass(c) && shouldKeepClassForUserBatch(c, batch))
      .sort((a, b) => timeToMinutes(a.time) - timeToMinutes(b.time));
  }

  const tasksByDate = {};
  (tasks || []).forEach(t => {
    if (!t || t.noDeadline || !t.dueDate || t.dueDate < startKey || t.dueDate > endKey) return;
    (tasksByDate[t.dueDate] ||= []).push(t);
  });

  const day = new Date(startKey + 'T00:00:00');
  for (let key = localDateKey(day); key <= endKey; day.setDate(day.getDate() + 1), key = localDateKey(day)) {
    const dayIdx = day.getDay();
    const dayItems = [];
    // Holiday mode hides classes on its dates only; tasks always show.
    if (!isHolidayActive(key, holiday)) classesByDay[dayIdx].forEach(c => {
      dayItems.push({ min: timeToMinutes(c.time), item: { date: key, time: formatDisplayTime(c.time || ''), title: c.subject || 'Class', type: 'class', sourceId: String(dayIdx) } });
    });
    (tasksByDate[key] || []).forEach(t => {
      const item = {
        date: key,
        title: t.title || 'Untitled Task',
        type: CAL_DEADLINE_TYPES.includes(t.taskType) ? 'deadline' : 'task',
        sourceId: String(t.id),
      };
      if (t.startTime) item.time = formatDisplayTime(t.startTime);
      if (t.status === 'submitted') item.done = true;
      // Untimed tasks go after the day's timed items.
      dayItems.push({ min: t.startTime ? timeToMinutes(t.startTime) : 24 * 60, item });
    });
    dayItems.sort((a, b) => a.min - b.min).forEach(x => out.push(x.item));
  }
  return out;
}

function pendingCount() {
  return allTasks().filter(a => a.status === 'pending').length;
}

function overdueCount() {
  return allTasks().filter(a => isTaskOverdue(a)).length;
}

// ── Dynamic Timetable Loading ─────────────────────────────────
function isBreakEntry(c) {
  if (!c || typeof c !== 'object') return true;
  if (c.isBreak === true) return true;
  const type = (c.type || '').toLowerCase();
  const subject = (c.subject || '').toLowerCase();
  const code = (c.code || '').toLowerCase();

  if (type === 'off' || type === 'break' || type === 'recess') return true;
  if (subject === 'recess' || subject === 'break' || subject.includes('lunch')) return true;
  if (code === 'rec' || code === 'break') return true;
  return false;
}

function isTeachingClass(c) {
  return !isBreakEntry(c);
}

function getEmptyTimetable() {
  return { 0: [], 1: [], 2: [], 3: [], 4: [], 5: [], 6: [] };
}

function loadTimetable() {
  const saved = safeGetStorage(KEY_CUSTOM_TIMETABLE, null);
  if (saved && typeof saved === 'object') return saved;
  const choice = safeGetStorage(KEY_TIMETABLE_CHOICE, null);
  if (choice === 'aids') {
    return TIMETABLE;
  }
  return getEmptyTimetable();
}

// True when Today has any classes to show: a saved timetable, or the
// built-in sample a student chose before custom timetables existed.
function hasAnyTimetable() {
  const tt = loadTimetable();
  return !!tt && typeof tt === 'object' && Object.values(tt).some(arr => Array.isArray(arr) && arr.length > 0);
}

function isCustomTimetableActive() {
  const saved = safeGetStorage(KEY_CUSTOM_TIMETABLE, null);
  if (!saved || typeof saved !== 'object') return false;
  return Object.values(saved).some(arr => Array.isArray(arr) && arr.length > 0);
}

function saveTimetable(ttMap) {
  safeSetStorage(KEY_CUSTOM_TIMETABLE, ttMap);
  syncToCloud();
}

// See the call site in confirmSaveExtractedTimetable for why this exists.
// Walks today's week and several weeks ahead (attendance can be viewed and
// marked for future weeks too, via setAttendanceWeekOffset) and deletes any
// stored attendance mark whose (date, code+time) key is about to be
// reused by the just-confirmed schedule -- never touches today or a date
// before it, so no already-happened attendance/streak history is lost
// (it used to include today, wiping marks taken that morning).
function clearUpcomingAttendanceForNewSchedule(newTT) {
  const attendanceData = safeGetStorage(KEY_ATTENDANCE, {}) || {};
  const todayKey = todayStr();
  let changed = false;

  for (let weekOffset = 0; weekOffset < 8; weekOffset++) {
    getWeekDays(weekOffset).forEach(dateObj => {
      const dateStr = localDateKey(dateObj);
      if (dateStr <= todayKey) return;
      const existing = attendanceData[dateStr];
      if (!existing) return;

      const dayClasses = newTT[dateObj.getDay()] || [];
      const upcomingKeys = new Set(
        dayClasses.filter(isTeachingClass).map(c => attendanceKeyFor(c))
      );

      Object.keys(existing).forEach(key => {
        if (upcomingKeys.has(key)) {
          delete existing[key];
          changed = true;
        }
      });
      if (Object.keys(existing).length === 0) delete attendanceData[dateStr];
    });
  }

  if (changed) safeSetStorage(KEY_ATTENDANCE, attendanceData);
}

function resetTimetableToDefault() {
  if (!confirm("Clear your timetable schedule and start with a clean slate?")) return;
  safeSetStorage(KEY_CUSTOM_TIMETABLE, getEmptyTimetable());
  safeSetStorage(KEY_TIMETABLE_CHOICE, 'clean');
  syncToCloud();
  renderPage(state.currentPage);
  showToast("Timetable schedule cleared ✓", "info");
}

// In-app confirm, not confirm(): embedded/in-app browsers auto-cancel the
// native dialog, so the button silently did nothing there.
function loadOfficialAidsTimetable() {
  document.getElementById('sample-tt-modal-backdrop')?.remove();
  const close = `document.getElementById('sample-tt-modal-backdrop')?.remove()`;
  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop';
  backdrop.id = 'sample-tt-modal-backdrop';
  backdrop.innerHTML = `
    <div class="modal" onclick="event.stopPropagation()" style="max-width:420px;width:92vw">
      <div class="modal-header">
        <span class="modal-title">Load sample timetable</span>
        <button class="modal-close" onclick="${close}" aria-label="Close">${icons.x()}</button>
      </div>
      <div class="modal-body" style="font-size:var(--text-base);color:var(--text-muted);line-height:1.45">Load the official Sem 3 SY AI-DS timetable schedule? You'll get a chance to review it and filter it down to your own practical batch before saving.</div>
      <div class="modal-footer" style="margin-top:16px;display:flex;justify-content:flex-end;gap:8px">
        <button class="btn-secondary" onclick="${close}">Cancel</button>
        <button class="btn-primary" onclick="${close}; confirmLoadOfficialAidsTimetable()">Load</button>
      </div>
    </div>`;
  wireBackdropClickClose(backdrop);
  document.body.appendChild(backdrop);
}

function confirmLoadOfficialAidsTimetable() {
  safeSetStorage(KEY_TIMETABLE_CHOICE, 'aids');
  // Combined lab slots (e.g. "DS-AI-A2 (VJM) + WEB DEV.-AI-C2 (MKP)") need
  // to be split per batch and the whole schedule reviewed/filtered before
  // saving -- see buildSampleTimetableSchedule() and the batch selector
  // already built into this preview modal -- rather than saving the raw
  // TIMETABLE object (with every batch's classes glued together) directly.
  // Not an OCR result, so the unverified-scan banner never applies here.
  pendingExtractionNeedsReview = false;
  showTimetablePreviewModal(buildSampleTimetableSchedule());
}

function todayClasses() {
  const tt = loadTimetable();
  const currentMin = currentTimeMinutes();
  return (tt[new Date().getDay()] || []).filter(c => isTeachingClass(c) && timeToMinutes(c.end || '23:59') > currentMin).length;
}

// ── Holiday mode ──────────────────────────────────────────────
// A display switch only: while it is on, nothing built from the timetable
// shows on Today, the Calendar, reminders or Ask Desk, and ongoing
// (no-deadline) tasks rest unless marked "keep during holiday". The
// timetable, attendance, group, subjects and tasks are never changed here,
// so turning it off brings everything back exactly as it was. Dated tasks
// always show: a real deadline is never hidden.
// `since` is the first holiday day (may be in the future: the break then
// starts by itself). `until` is the first day classes come back (local
// date, exclusive); the dialog shows the last holiday day, `until` - 1.
const HOLIDAY_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
function loadHoliday() {
  const h = safeGetStorage(KEY_HOLIDAY, null);
  if (!h || typeof h !== 'object' || Array.isArray(h) || h.on !== true) return null;
  if (typeof h.since !== 'string' || !HOLIDAY_DATE_RE.test(h.since)) return null;
  const until = (typeof h.until === 'string' && HOLIDAY_DATE_RE.test(h.until)) ? h.until : null;
  if (h.until != null && !until) return null;
  return { on: true, since: h.since, until };
}

function isHolidayActive(dateKey = todayStr(), h = loadHoliday()) {
  if (!h || !dateKey) return false;
  if (dateKey < h.since) return false;
  return !h.until || dateKey < h.until;
}

// A break that is planned but has not started yet.
function isHolidayScheduled(h = loadHoliday()) {
  return !!h && todayStr() < h.since && (!h.until || h.since < h.until);
}

// The timetable as screens should show it today. Editors, sync, backup and
// attendance keep calling loadTimetable() so nothing is ever saved empty.
function timetableForDisplay() {
  return isHolidayActive() ? getEmptyTimetable() : loadTimetable();
}

function isOngoingTask(t) {
  return !!t && (!!t.noDeadline || (t.taskType === 'mission' && !t.dueDate));
}

// Ongoing tasks rest during a holiday unless marked "keep during holiday".
// Display only: the task itself is never changed.
function isTaskPausedForHoliday(t, dateKey = todayStr(), h = loadHoliday()) {
  return isOngoingTask(t) && t.keepInHoliday !== true && isHolidayActive(dateKey, h);
}

function holidayDayLabel(key, withDay = false) {
  const d = new Date(key + 'T00:00:00');
  return `${withDay ? DAY_NAMES[d.getDay()].slice(0, 3) + ', ' : ''}${d.getDate()} ${MONTH_NAMES[d.getMonth()]}`;
}

function holidayLabel(h = loadHoliday()) {
  if (!h) return '';
  if (!h.until) return 'On break';
  return `Back on ${holidayDayLabel(h.until)}`;
}

// Whole days of break left, today included (null when open-ended).
function holidayDaysLeft(h = loadHoliday()) {
  if (!h || !h.until) return null;
  const from = todayStr() > h.since ? todayStr() : h.since;
  return Math.max(0, Math.round((new Date(h.until + 'T00:00:00') - new Date(from + 'T00:00:00')) / 86400000));
}

// One calm line for the banner, picked by date so it stays put all day.
const HOLIDAY_MOOD_LINES = [
  "Rest up. You've earned this break.",
  'Slow mornings, no bells.',
  'Recharge mode: on.',
  'No lectures today. Just breathe.',
  'Books down, feet up.',
  'Sleep in. The desk will wait.',
  'Go outside. The sun misses you.',
];
// Starts the sway where the clock says it should be, so a redraw of Today
// continues the swing instead of snapping back to the start.
function holidaySwayStyle() {
  return ` style="animation-delay:-${((Date.now() % 7000) / 1000).toFixed(2)}s"`;
}

function holidayMoodLine() {
  const d = new Date();
  return HOLIDAY_MOOD_LINES[(d.getDate() + d.getMonth()) % HOLIDAY_MOOD_LINES.length];
}

function setHoliday(on, until = null, since = null) {
  if (on) {
    const today = todayStr();
    const s = (typeof since === 'string' && HOLIDAY_DATE_RE.test(since) && since > today) ? since : today;
    const u = (typeof until === 'string' && HOLIDAY_DATE_RE.test(until) && until > today && until > s) ? until : null;
    safeSetStorage(KEY_HOLIDAY, { on: true, since: s, until: u });
  } else {
    // `endedOn` (optional, additive) marks the day a break that had started
    // ended, for the one-day welcome-back card. Cancelling a planned break
    // that never started leaves it out.
    const prev = loadHoliday();
    const today = todayStr();
    safeSetStorage(KEY_HOLIDAY, prev && prev.since <= today
      ? { on: false, since: null, until: null, endedOn: today }
      : { on: false, since: null, until: null });
  }
  syncToCloud();
}

// The day the last break ended ('' if none), from the stored off value.
function holidayEndedOn() {
  const h = safeGetStorage(KEY_HOLIDAY, null);
  if (!h || typeof h !== 'object' || Array.isArray(h) || h.on === true) return '';
  return (typeof h.endedOn === 'string' && HOLIDAY_DATE_RE.test(h.endedOn)) ? h.endedOn : '';
}

// Exam countdown during a break: only inside the final week (a real
// deadline); further out it rests with everything else.
function holidayHidesCountdown(days) {
  return isHolidayActive() && !(days !== null && days >= 0 && days <= 7);
}

function dismissHolidayWelcome() {
  const seen = safeGetStorage('cos_notified_history', {}) || {};
  seen[`card_holiday_back_${todayStr()}`] = true;
  safeSetStorage('cos_notified_history', seen);
  renderPage(state.currentPage);
}
window.dismissHolidayWelcome = dismissHolidayWelcome;

// Turns holiday mode off once its end date arrives (on open, focus, a new
// day, a restore or a sync). Returns true when it switched off.
function checkHolidayExpiry() {
  const h = loadHoliday();
  if (!h || !h.until || todayStr() < h.until) return false;
  setHoliday(false);   // Today shows the welcome-back card
  return true;
}

// Warm colours and calm copy while the break is on (see .holiday-mode in style.css).
function applyHolidayVibe() {
  document.body?.classList?.toggle('holiday-mode', isHolidayActive());
}

function showHolidayModal() {
  document.getElementById('holiday-modal-backdrop')?.remove();
  const today = todayStr();
  const h = loadHoliday();
  const plusDays = (key, n) => { const d = new Date(key + 'T12:00:00'); d.setDate(d.getDate() + n); return localDateKey(d); };
  const start = h && h.since > today ? h.since : today;
  const end = h && h.until ? plusDays(h.until, -1) : plusDays(start, 6);
  const openEnded = !!h && !h.until;
  const close = `document.getElementById('holiday-modal-backdrop')?.remove()`;
  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop';
  backdrop.id = 'holiday-modal-backdrop';
  backdrop.innerHTML = `
    <div class="modal holiday-modal" onclick="event.stopPropagation()" style="max-width:420px;width:92vw">
      <div class="modal-header">
        <div style="display:flex;align-items:center;gap:8px">
          <span class="holiday-modal-art" aria-hidden="true">🌴</span>
          <span class="modal-title">${h ? 'Change your break' : 'Plan a break'}</span>
        </div>
        <button class="modal-close" onclick="${close}" aria-label="Close">${icons.x()}</button>
      </div>
      <div class="modal-body" style="display:flex;flex-direction:column;gap:10px">
        <div style="font-size:var(--text-base);color:var(--text-muted);line-height:1.45">Classes, class reminders and ongoing tasks rest while you're away. Real deadlines stay visible. Nothing is deleted, and your attendance % stays as it is.</div>
        <div class="form-row">
          <div class="form-group">
            <label class="form-label" for="holiday-start">First day off</label>
            <input type="date" class="form-input" id="holiday-start" min="${today}" value="${start}">
          </div>
          <div class="form-group">
            <label class="form-label" for="holiday-end">Last day off</label>
            <input type="date" class="form-input" id="holiday-end" min="${today}" value="${end}" ${openEnded ? 'disabled' : ''}>
          </div>
        </div>
        <label class="checkbox-inline">
          <input type="checkbox" id="holiday-open" ${openEnded ? 'checked' : ''} onchange="document.getElementById('holiday-end').disabled = this.checked">
          <span>No end date, I'll end it myself</span>
        </label>
        <div style="font-size:var(--text-sm);color:var(--text-muted)">Classes come back by themselves the day after your last day off.</div>
      </div>
      <div class="modal-footer" style="margin-top:16px;display:flex;justify-content:flex-end;gap:8px">
        <button class="btn-secondary" onclick="${close}">Cancel</button>
        <button class="btn-primary" onclick="confirmHolidayModal()">${h ? 'Save' : 'Start holiday'}</button>
      </div>
    </div>`;
  wireBackdropClickClose(backdrop);
  document.body.appendChild(backdrop);
}
window.showHolidayModal = showHolidayModal;

function confirmHolidayModal() {
  const today = todayStr();
  const start = document.getElementById('holiday-start')?.value || today;
  const openEnded = !!document.getElementById('holiday-open')?.checked;
  const end = document.getElementById('holiday-end')?.value || '';
  if (!HOLIDAY_DATE_RE.test(start) || start < today) {
    showToast('Pick a first day off from today on.', 'error');
    return;
  }
  let until = null;
  if (!openEnded) {
    if (!HOLIDAY_DATE_RE.test(end) || end < start) {
      showToast('The last day off must be on or after the first.', 'error');
      return;
    }
    const d = new Date(end + 'T12:00:00');
    d.setDate(d.getDate() + 1);
    until = localDateKey(d);
  }
  setHoliday(true, until, start);
  document.getElementById('holiday-modal-backdrop')?.remove();
  showToast(start > today
    ? `Holiday planned. It starts on ${holidayDayLabel(start, true)}.`
    : 'Holiday mode is on. Enjoy the break 🌴', 'success');
  renderPage(state.currentPage);
}
window.confirmHolidayModal = confirmHolidayModal;

function resumeClasses() {
  setHoliday(false);
  // On Today the welcome-back card says it; elsewhere a toast does.
  if (state.currentPage !== 'dashboard') showToast('Welcome back, classes are showing again', 'success');
  renderPage(state.currentPage);
}
window.resumeClasses = resumeClasses;

function endHolidayEarly() {
  if (!confirm('End your holiday now?\n\nClasses, class reminders and ongoing tasks come back today.')) return;
  resumeClasses();
}
window.endHolidayEarly = endHolidayEarly;

function cancelPlannedHoliday() {
  setHoliday(false);
  showToast('Planned holiday cancelled', 'success');
  renderPage(state.currentPage);
}
window.cancelPlannedHoliday = cancelPlannedHoliday;

