function clearAssistantChat() {
  renderAssistantWelcome();
  showToast('Chat cleared', 'info');
}

function openAssistant() {
  _assistantOpen = true;
  const panel   = document.getElementById('cd-assistant-panel');
  const overlay = document.getElementById('cd-assistant-overlay');
  const btn     = document.getElementById('assistant-toggle-btn');
  if (!panel) return;

  panel.classList.add('open');
  panel.setAttribute('aria-hidden', 'false');
  overlay?.classList.add('open');
  btn?.setAttribute('aria-expanded', 'true');

  const thread = document.getElementById('cd-chat-thread');
  if (thread && thread.children.length === 0) {
    renderAssistantWelcome();
  }

  setTimeout(() => document.getElementById('cd-input')?.focus(), 250);
}

function closeAssistant() {
  _assistantOpen = false;
  const panel   = document.getElementById('cd-assistant-panel');
  const overlay = document.getElementById('cd-assistant-overlay');
  const btn     = document.getElementById('assistant-toggle-btn');
  if (!panel) return;
  panel.classList.remove('open');
  panel.setAttribute('aria-hidden', 'true');
  overlay?.classList.remove('open');
  btn?.setAttribute('aria-expanded', 'false');
}

function toggleAssistant() {
  _assistantOpen ? closeAssistant() : openAssistant();
}

function sendAssistantMessage(presetText) {
  const input = document.getElementById('cd-input');
  const q = (presetText || (input ? input.value : '')).trim();
  if (!q) return;
  if (input) input.value = '';

  // Buttons in a Today-box answer ask follow-ups here, so show the panel.
  if (!_assistantOpen) openAssistant();

  const thread = document.getElementById('cd-chat-thread');
  if (!thread) return;

  // Clear welcome card on first real message
  const welcome = thread.querySelector('.cd-welcome-card, .cd-welcome');
  if (welcome) welcome.remove();

  // Render user bubble
  const userMsg = document.createElement('div');
  userMsg.className = 'cd-msg cd-msg-user';
  userMsg.innerHTML = `<div class="cd-bubble">${escHtml_cd(q)}</div>`;
  thread.appendChild(userMsg);

  // Typing indicator
  const typingEl = document.createElement('div');
  typingEl.className = 'cd-msg cd-msg-bot';
  typingEl.innerHTML = `<div class="cd-typing"><span></span><span></span><span></span></div>`;
  thread.appendChild(typingEl);
  thread.scrollTop = thread.scrollHeight;

  // Answers are computed on the device; the short pause only lets the
  // typing dots show so the reply doesn't feel like a page jump.
  setTimeout(() => {
    typingEl.remove();
    const response = ClarityAssistant.respond(q);

    const botMsg = document.createElement('div');
    botMsg.className = 'cd-msg cd-msg-bot';
    botMsg.innerHTML = `<div class="cd-bubble">${response}</div>`;
    thread.appendChild(botMsg);
    thread.scrollTop = thread.scrollHeight;
  }, 150);
}

function escHtml_cd(s) {
  return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

// An answer's button that opens a page or a form (Add task, Open DBMS,
// Scan timetable...) closes the panel first. The panel sits above every
// form (z-index 1101 vs 200), so on a phone the form used to open hidden
// behind the chat and the button looked like it did nothing. Buttons that
// ask Ask Desk another question keep the panel open.
document.addEventListener('click', (e) => {
  const target = e.target && e.target.closest ? e.target.closest('#cd-chat-thread .cd-msg-bot button, #cd-chat-thread .cd-msg-bot a') : null;
  if (!target || !_assistantOpen) return;
  const action = target.getAttribute('onclick') || '';
  if (action && !action.includes('sendAssistantMessage')) closeAssistant();
}, true);

// Keyboard shortcut: Ctrl+/ to toggle assistant
document.addEventListener('keydown', (e) => {
  if (e.ctrlKey && e.key === '/') {
    e.preventDefault();
    toggleAssistant();
  }
  if (e.key === 'Escape' && _assistantOpen) {
    closeAssistant();
  }
});

// ── Accessibility: activate role="button" elements from the keyboard ───
// A few controls (the desktop sidebar nav items in particular) are <div>s
// with onclick for layout reasons and carry role="button" tabindex="0"
// instead of being real <button> elements. This makes Enter/Space on any
// of them behave like a native button click, matching what the mobile
// bottom-nav's real <button> elements already do for free.
document.addEventListener('keydown', (e) => {
  if ((e.key === 'Enter' || e.key === ' ') && e.target.matches('[role="button"]')) {
    e.preventDefault();
    e.target.click();
  }
});

// ── Accessibility: retrofit dialog semantics onto every modal ──────────
// Modals here are hand-built per-feature (~20 show*Modal functions, each
// creating its own `.modal-backdrop > .modal` pair) rather than going
// through one shared builder. Instead of editing every one of them, this
// watches for any `.modal-backdrop` appearing in the DOM and adds
// role="dialog"/aria-modal/aria-labelledby plus a Tab focus trap to
// whatever it finds inside -- safe for every modal, present and future,
// without changing how any of them open, close, or submit.
// Shared close-on-backdrop-click wiring, extracted from the several
// modal-building functions that repeated this exact line. requireDirectClick
// (default true) mirrors each call site's prior behavior: most modals only
// close when the click lands on the backdrop itself (not bubbled from modal
// content); a few older ones closed on any click inside the backdrop area
// and keep that exact behavior via requireDirectClick=false.
function wireBackdropClickClose(backdrop, requireDirectClick = true) {
  backdrop.addEventListener('click', (e) => {
    if (!requireDirectClick || e.target === backdrop) backdrop.remove();
  });
}

function enhanceModalA11y(backdrop) {
  const modal = backdrop.querySelector('.modal');
  if (!modal || modal.hasAttribute('data-a11y-enhanced')) return;
  modal.setAttribute('data-a11y-enhanced', 'true');
  modal.setAttribute('role', 'dialog');
  modal.setAttribute('aria-modal', 'true');
  if (!modal.hasAttribute('tabindex')) modal.setAttribute('tabindex', '-1');

  const titleEl = modal.querySelector('.modal-title');
  if (titleEl) {
    if (!titleEl.id) titleEl.id = 'modal-title-' + Math.random().toString(36).slice(2, 9);
    modal.setAttribute('aria-labelledby', titleEl.id);
  }

  const focusableSel = 'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';
  modal.addEventListener('keydown', (e) => {
    if (e.key !== 'Tab') return;
    const focusable = Array.from(modal.querySelectorAll(focusableSel)).filter(el => el.offsetParent !== null);
    if (!focusable.length) return;
    const first = focusable[0], last = focusable[focusable.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault(); last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault(); first.focus();
    }
  });
}

if (typeof MutationObserver !== 'undefined' && document.body) {
  new MutationObserver((mutations) => {
    for (const m of mutations) {
      for (const node of m.addedNodes) {
        if (node.nodeType === 1 && node.classList && node.classList.contains('modal-backdrop')) {
          enhanceModalA11y(node);
        }
      }
    }
  }).observe(document.body, { childList: true });
}

