// The last pending task gets the "all caught up" card; any other gets the usual toast.
function celebrateTaskDone() {
  if (pendingCount() === 0) showCelebration('🎉', 'All caught up', 'Every task is done. Nice work.');
  else showToast('Task marked completed ✓', 'success');
}

window.toggleAssignment = (id) => {
  // Custom task
  const ct = state.customTasks.find(x => x.id === id);
  if (ct) {
    const isNowDone = ct.status !== 'submitted';
    ct.status = isNowDone ? 'submitted' : 'pending';
    saveCustomTasks();
    if (isNowDone) {
      celebrateTaskDone();
    } else {
      showToast('Task moved back to pending', 'info');
    }
    renderPage(state.currentPage);
    updateNavBadges();
    return;
  }
  // Data.js assignment
  const a = state.assignments.find(x => x.id === id);
  if (!a) return;
  const isNowDone = a.status !== 'submitted';
  a.status = isNowDone ? 'submitted' : 'pending';
  saveAssignments();
  if (isNowDone) {
    celebrateTaskDone();
  } else {
    showToast('Task moved back to pending', 'info');
  }
  renderPage(state.currentPage);
  updateNavBadges();
};

window.deleteCustomTask = (id) => {
  if (!confirm('Delete this task?')) return;
  state.customTasks = state.customTasks.filter(t => t.id !== id);
  saveCustomTasks();
  showToast('Task removed from desk', 'info');
  renderPage(state.currentPage);
  updateNavBadges();
};

function handleGlobalSearch(q) {
  q = q.trim().toLowerCase();
  if (!q) return;
  state.noticeSearch = q;
  navigate('notices');
}

// ── Nav Badge Update ──────────────────────────────────────────
function updateNavBadges() {
  const pending = pendingCount();

  // Update browser tab title with pending count
  document.title = pending > 0 ? `(${pending}) Clarity Desk` : 'Clarity Desk';

  document.querySelectorAll('[data-nav="assignments"]').forEach(el => {
    // Sidebar: dot indicator (no badge number)
    const dot = el.querySelector('.nav-alert-dot');
    if (dot) dot.style.display = pending > 0 ? 'block' : 'none';
    el.classList.toggle('has-overdue', pending > 0);
    // Bottom nav: keep the dot behavior
    const bnavDot = el.querySelector('.bnav-dot');
    if (bnavDot) bnavDot.style.display = pending > 0 ? 'block' : 'none';
  });
}
window.updateNavBadges = updateNavBadges;

window.requestNotificationPermission = requestNotificationPermission;
window.enableClosedAppPush = enableClosedAppPush;
window.disableClosedAppPush = disableClosedAppPush;
window.showReminderSheet = showReminderSheet;
window.reminderSheetInstall = reminderSheetInstall;
window.reminderSheetCopyLink = reminderSheetCopyLink;
window.reminderSheetCalendar = reminderSheetCalendar;
window.dismissInstallBanner = dismissInstallBanner;
window.installBannerAction = installBannerAction;
window.dismissMovedBanner = dismissMovedBanner;
window.showMoveDeskModal = showMoveDeskModal;
window.onUsageToggle = onUsageToggle;
window.showInAppBanner = showInAppBanner;
window.copyInAppLink = copyInAppLink;
window.sendTestReminder = sendTestReminder;

// ── Init ──────────────────────────────────────────────────────
function init() {
  // Old address with nothing saved here: go to the new one before drawing
  // anything. A desk saved here stays, and the move card offers ways over.
  const moveAction = addressMoveAction({
    hostname: location.hostname,
    search: location.search,
    webdriver: !!navigator.webdriver
  });
  if (moveAction === 'redirect') {
    location.replace(newAddressUrl());
    return;
  }
  try { trackAppOpen(); } catch (e) { console.warn('[Usage] skipped:', e); }

  // Always open at the top of the page (a reload or PWA relaunch used to
  // restore a stale mid-page scroll offset).
  try { if ('scrollRestoration' in history) history.scrollRestoration = 'manual'; } catch (e) {}
  try { fixShiftedAttendanceDates(); } catch (e) { console.warn('[Attendance] date-key repair skipped:', e); }
  try { checkHolidayExpiry(); } catch (e) { console.warn('[Holiday] expiry check skipped:', e); }
  try { vaultIdbStart(); } catch (e) { console.warn('[Vault] file store skipped:', e); }
  initTheme();
  initAccent();
  updateTopbarProfile();
  updateLiveClockDisplay(); // populate the topbar clock immediately, don't wait for the first 60s tick
  setupFABDrag();

  // NOTE: every [data-nav] element already carries its own inline
  // onclick="navigateTo(...)" attribute in index.html/404.html. An
  // addEventListener('click', ...) used to be attached here on top of
  // that, so a single click ran navigate() twice back-to-back -- tearing
  // down and rebuilding the target page's DOM (e.g. the whole dashboard)
  // twice per click, which is what made its content look like it was
  // popping in and out. Removed; the inline handlers already cover it.

  document.getElementById('global-search')?.addEventListener('keydown', e => {
    if (e.key === 'Enter') handleGlobalSearch(e.target.value);
  });

  const pending = window._pendingNav;
  if (pending) {
    delete window._pendingNav;
    navigate(pending);
  } else {
    const hash = window.location.hash.replace('#', '') || 'dashboard';
    navigate(hash);
  }

  // Deep-link routing for notification clicks and browser back/forward hash navigation
  window.addEventListener('hashchange', () => {
    const targetHash = window.location.hash.replace('#', '') || 'dashboard';
    if (targetHash && targetHash !== state.currentPage && targetHash !== state.resourcesTab) {
      navigate(targetHash);
    }
  });

  updateNavBadges();
  checkOnboarding();
  checkAttendanceV2Preview();

  // Opened from the Android share sheet (manifest share_target -> sw.js).
  if (new URLSearchParams(window.location.search).get('share') === 'whatsapp') {
    history.replaceState(null, '', window.location.pathname + window.location.hash);
    waReceiveShare();
  }

  // Opened from a deadline reminder (./?task=<id>#assignments): open that task.
  const reminderTaskId = new URLSearchParams(window.location.search).get('task');
  if (reminderTaskId) {
    history.replaceState(null, '', window.location.pathname + window.location.hash);
    if (state.customTasks.some(t => t.id === reminderTaskId)) setTimeout(() => showAddTaskModal(reminderTaskId), 300);
  }

  // Check and schedule task & notice notifications
  checkScheduledNotifications();
  checkNoticeNotifications();
  schedulePushSync(5000);
  scheduleInstallBanner();
  if (moveAction === 'card') setTimeout(() => showMovedBanner(), 2500);
  if (detectDevice().inApp) setTimeout(() => showInAppBanner(), 1200);
  setInterval(() => {
    checkScheduledNotifications();
    checkNoticeNotifications();
    updateLiveClockDisplay();
    refreshIfDayChanged();
  }, 60000);
  // A backgrounded PWA's timers are paused; check the date as soon as it's shown again.
  document.addEventListener('visibilitychange', () => { if (!document.hidden) refreshIfDayChanged(); });
  window.addEventListener('focus', refreshIfDayChanged);
  window.addEventListener('pageshow', refreshIfDayChanged);
  // Countdown + topbar clock: re-sync right away when the app is shown again
  // (a backgrounded PWA's timers are paused), then keep ticking on the minute.
  const catchUpClock = () => {
    if (document.hidden) return;
    updateLiveClockDisplay();
    tickBeacon();
    scheduleBeaconTick();
  };
  document.addEventListener('visibilitychange', catchUpClock);
  window.addEventListener('focus', catchUpClock);
  window.addEventListener('pageshow', catchUpClock);
  scheduleBeaconTick();

  // Initialize Firebase Auth & Firestore sync
  initFirebase();

  // Register PWA Service Worker for offline support
  if ('serviceWorker' in navigator && location.protocol !== 'file:') {
    navigator.serviceWorker.register('./sw.js').then(reg => {
      reg.update();

      // A new SW version can finish installing while this page is still
      // open (common on mobile, where the app is backgrounded rather than
      // fully closed for long stretches) -- without this, the update just
      // sits ready-but-inactive until the user happens to fully close and
      // reopen the app. Surface a one-tap "Refresh" banner instead, so a
      // fresh deploy never requires an uninstall/reinstall.
      reg.addEventListener('updatefound', () => {
        const newWorker = reg.installing;
        if (!newWorker) return;
        newWorker.addEventListener('statechange', () => {
          if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
            showUpdateAvailableBanner();
          }
        });
      });
    }).catch(err => {
      console.warn('ServiceWorker registration skipped or failed:', err);
    });
  }

  // Network connectivity status listeners
  window.addEventListener('online', () => {
    showToast('Back online. Cloud sync is on ✓', 'success');
    updateSyncUI();
    flushFeedbackQueue();
    flushUsageQueue();
  });
  window.addEventListener('offline', () => {
    showToast('You’re offline. Changes are saved on this device.', 'info');
    updateSyncUI('offline');
  });

  try { performance.mark('cd-app-ready'); } catch (e) {}
  if (new URLSearchParams(location.search).has('timing')) {
    window.addEventListener('load', () => setTimeout(showTimingReport, 1500));
    if (document.readyState === 'complete') setTimeout(showTimingReport, 1500);
  }
}

document.addEventListener('DOMContentLoaded', init);

// Opened as ./?timing: shows what this visit waited on, from the browser's own
// timing data. For finding slow first visits on a phone. Nothing is saved or
// sent; the panel lives only on this screen.
let timingShown = false;
// Read when app.js starts: by the time the report shows, a new service worker
// has already taken over the page, even on a first visit.
const TIMING_SAVED_COPY = !!(navigator.serviceWorker && navigator.serviceWorker.controller);
function showTimingReport() {
  if (timingShown) return;
  timingShown = true;
  const ms = (v) => (v == null || !isFinite(v)) ? '–' : v >= 1000 ? (v / 1000).toFixed(1) + ' s' : Math.round(v) + ' ms';
  const nav = performance.getEntriesByType('navigation')[0] || {};
  const paint = performance.getEntriesByName('first-contentful-paint')[0];
  const ready = performance.getEntriesByName('cd-app-ready')[0];
  const res = performance.getEntriesByType('resource');
  const hostOf = (u) => { try { return new URL(u).host; } catch (_) { return '?'; } };
  const sw = TIMING_SAVED_COPY ? 'yes (opened from the saved copy)' : 'no (first visit, or saved copy not ready)';

  const lines = [
    `Clarity Desk timing · ${new Date().toISOString().slice(0, 16)} · v${((document.querySelector('script[type=module]') || {}).outerHTML || '').match(/v=(\d+)/)?.[1] || '?'}`,
    `Saved copy in use: ${sw}`,
    `Network: ${(navigator.connection && navigator.connection.effectiveType) || 'unknown'}`,
    '',
    `Page: connect ${ms(nav.connectEnd - nav.startTime)}, first byte ${ms(nav.responseStart)}, all of it ${ms(nav.responseEnd)}`,
    `First paint ${ms(paint && paint.startTime)} · page parsed ${ms(nav.domContentLoadedEventEnd)} · app ready ${ms(ready && ready.startTime)} · everything loaded ${ms(nav.loadEventEnd)}`,
    ''
  ];
  const byHost = new Map();
  for (const r of res) {
    const h = hostOf(r.name);
    const g = byHost.get(h) || { n: 0, kb: 0, last: 0, slow: 0 };
    g.n++; g.kb += (r.transferSize || 0) / 1024; g.last = Math.max(g.last, r.responseEnd); g.slow = Math.max(g.slow, r.duration);
    byHost.set(h, g);
  }
  lines.push('By server (files · size · slowest file · done at):');
  for (const [h, g] of [...byHost].sort((x, y) => y[1].last - x[1].last)) {
    lines.push(`  ${h}: ${g.n} · ${g.kb ? Math.round(g.kb) + ' KB' : 'size hidden'} · ${ms(g.slow)} · ${ms(g.last)}`);
  }
  lines.push('', 'Slowest files (start → done):');
  for (const r of [...res].sort((x, y) => y.duration - x.duration).slice(0, 8)) {
    const name = r.name.replace(/^https?:\/\//, '').replace(/\?.*$/, '').replace(/^(.{0,22}).*\/(.{0,30})$/, '$1…/$2');
    lines.push(`  ${ms(r.duration).padStart(7)}  ${ms(r.startTime)} → ${ms(r.responseEnd)}  ${name}`);
  }
  const text = lines.join('\n');

  const panel = document.createElement('div');
  panel.id = 'cd-timing-report';
  panel.setAttribute('role', 'dialog');
  panel.setAttribute('aria-label', 'Load timing');
  panel.style.cssText = 'position:fixed;left:8px;right:8px;bottom:8px;max-height:70vh;overflow:auto;z-index:99999;' +
    'background:var(--surface,#fff);color:var(--text-primary,#222);border:1px solid var(--border,#ccc);border-radius:12px;' +
    'padding:12px;box-shadow:0 8px 30px rgba(0,0,0,.25);font:12px/1.45 ui-monospace,Menlo,monospace';
  panel.innerHTML = `<pre style="margin:0 0 10px;white-space:pre-wrap;font:inherit">${escHtml_cd(text)}</pre>` +
    '<div style="display:flex;gap:8px"><button type="button" class="btn-secondary" data-act="copy">Copy</button>' +
    '<button type="button" class="btn-secondary" data-act="close">Close</button></div>';
  panel.addEventListener('click', async (e) => {
    const act = e.target && e.target.dataset && e.target.dataset.act;
    if (act === 'close') panel.remove();
    if (act === 'copy') {
      try { await navigator.clipboard.writeText(text); e.target.textContent = 'Copied'; }
      catch (_) { e.target.textContent = 'Select the text and copy it'; }
    }
  });
  document.body.appendChild(panel);
}

function setupFABDrag() {
  const fab = document.querySelector('.fab');
  if (!fab) return;

  let isDragging = false;
  let hasMoved = false;
  let startX = 0;
  let initialLeft = 0;
  let clickPrevented = false;
  // First-time hint
  let hintEl = null;
  let hintTimeoutId = null;
  let hintOutsideHandler = null;

  const dismissHint = () => {
    if (!hintEl) return;
    hintEl.remove();
    hintEl = null;
    if (hintTimeoutId) { clearTimeout(hintTimeoutId); hintTimeoutId = null; }
    if (hintOutsideHandler) {
      document.removeEventListener('pointerdown', hintOutsideHandler, true);
      hintOutsideHandler = null;
    }
    localStorage.setItem('fabHintDismissed', 'true');
  };

  if (window.innerWidth <= 768 && !localStorage.getItem('fabHintDismissed')) {
    hintEl = document.createElement('div');
    hintEl.className = 'fab-hint';
    hintEl.innerText = 'Drag me left/right';
    fab.appendChild(hintEl);

    // Exit 1: tap the hint itself
    hintEl.addEventListener('click', (e) => {
      e.stopPropagation();
      dismissHint();
    });

    // Exit 2: tap anywhere outside the FAB/hint cluster (modal dialogs, e.g. the
    // onboarding welcome card, are a separate blocking layer and don't count as
    // "browsing the dashboard", so a tap inside one is ignored here)
    hintOutsideHandler = (e) => {
      if (fab.contains(e.target)) return;
      if (e.target.closest && e.target.closest('.modal-backdrop')) return;
      dismissHint();
    };
    document.addEventListener('pointerdown', hintOutsideHandler, true);

    // Exit 3: auto-hide after a few seconds if the user takes no action
    hintTimeoutId = setTimeout(dismissHint, 3500);
  }

  const applySnapPosition = (pos) => {
    if (window.innerWidth > 768) return;
    fab.style.right = 'auto';
    if (pos === 'left') {
      fab.style.left = '16px';
      fab.style.transform = 'none';
    } else if (pos === 'right') {
      fab.style.left = 'auto';
      fab.style.right = '16px';
      fab.style.transform = 'none';
    } else if (pos === 'center') {
      fab.style.left = '50%';
      fab.style.transform = 'translateX(-50%)';
    }
  };
  const savedPos = localStorage.getItem('fabPosition');
  if (savedPos) applySnapPosition(savedPos);

  const getClientX = (e) => e.touches ? e.touches[0].clientX : e.clientX;

  const onStart = (e) => {
    if (window.innerWidth > 768) return; // Only drag on mobile
    isDragging = true;
    hasMoved = false;
    clickPrevented = false;
    startX = getClientX(e);
    const rect = fab.getBoundingClientRect();
    initialLeft = rect.left;
    
    // Convert current position to left-based so drag is 1:1
    fab.style.right = 'auto';
    fab.style.left = initialLeft + 'px';
    fab.style.transform = 'none';
  };

  const onMove = (e) => {
    if (!isDragging || window.innerWidth > 768) return;
    const currentX = getClientX(e);
    const diff = currentX - startX;
    
    if (Math.abs(diff) > 5) {
      hasMoved = true;
      dismissHint();
      fab.classList.add('dragging');
      if (e.cancelable) e.preventDefault(); // Prevent scrolling while actively dragging horizontally
    }
    
    if (hasMoved) {
      let newLeft = initialLeft + diff;
      const maxLeft = window.innerWidth - fab.offsetWidth - 16;
      if (newLeft < 16) newLeft = 16;
      if (newLeft > maxLeft) newLeft = maxLeft;
      fab.style.left = newLeft + 'px';
    }
  };

  const onEnd = (e) => {
    if (!isDragging) return;
    isDragging = false;
    fab.classList.remove('dragging');
    
    if (hasMoved) {
      clickPrevented = true; // Mark to prevent the next click
      const rect = fab.getBoundingClientRect();
      const center = rect.left + (rect.width / 2);
      const w = window.innerWidth;
      
      fab.style.right = 'auto';
      let snapPos = 'right';
      if (center < w * 0.33) snapPos = 'left';
      else if (center > w * 0.66) snapPos = 'right';
      else snapPos = 'center';
      applySnapPosition(snapPos);
      localStorage.setItem('fabPosition', snapPos);
    }
  };

  fab.addEventListener('mousedown', onStart);
  document.addEventListener('mousemove', onMove, { passive: false });
  document.addEventListener('mouseup', onEnd);
  
  fab.addEventListener('touchstart', onStart, { passive: true });
  document.addEventListener('touchmove', onMove, { passive: false });
  document.addEventListener('touchend', onEnd);

  // Handle desktop resize reset
  window.addEventListener('resize', () => {
    if (window.innerWidth > 768) {
      fab.style.left = '';
      fab.style.right = '';
      fab.style.transform = '';
      fab.classList.remove('dragging');
    }
  });

  // Intercept the click event on FAB to prevent opening if we dragged
  fab.addEventListener('click', (e) => {
    if (clickPrevented) {
      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();
      clickPrevented = false; // Reset for next tap
    }
  }, true); // use capture phase
}

// ── Calm navigation: collapsible sidebar, mobile "More" sheet, chip overflow ──
// Self-contained on purpose: it never touches navigate() or any cos_* data.
// The rail state is a UI-only preference under its own key (cd_sidebar_collapsed),
// read early in index.html's head script so there is no layout flash on load.
(function () {
  var root = (typeof document !== 'undefined') && document.documentElement;
  if (!root || !root.classList) return; // headless test harness: nothing to wire

  function syncSidebarBtn() {
    var btn = document.getElementById('sidebar-collapse-btn');
    if (!btn) return;
    var collapsed = root.classList.contains('sidebar-collapsed');
    btn.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
    btn.setAttribute('aria-label', collapsed ? 'Expand sidebar' : 'Collapse sidebar');
    btn.title = (collapsed ? 'Expand' : 'Collapse') + ' sidebar ( [ )';
  }

  window.toggleSidebar = function () {
    var collapsed = root.classList.toggle('sidebar-collapsed');
    try { localStorage.setItem('cd_sidebar_collapsed', collapsed ? '1' : '0'); } catch (e) {}
    syncSidebarBtn();
  };

  function isTyping(t) {
    return t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName));
  }

  document.addEventListener('keydown', function (e) {
    if (e.key === '[' && !e.ctrlKey && !e.metaKey && !e.altKey && !isTyping(e.target)
        && !document.querySelector('.modal-backdrop')) {
      e.preventDefault();
      window.toggleSidebar();
    }
    if (e.key === 'Escape' && root.classList.contains('more-sheet-open')) window.closeMoreSheet();
  });

  // Mobile "More" sheet
  window.openMoreSheet = function () {
    root.classList.add('more-sheet-open');
    var sheet = document.getElementById('more-sheet');
    var btn = document.getElementById('bnav-more');
    if (sheet) sheet.setAttribute('aria-hidden', 'false');
    if (btn) btn.setAttribute('aria-expanded', 'true');
    var first = sheet && sheet.querySelector('.more-sheet-item');
    if (first) first.focus({ preventScroll: true });
  };
  window.closeMoreSheet = function () {
    if (!root.classList.contains('more-sheet-open')) return;
    root.classList.remove('more-sheet-open');
    var sheet = document.getElementById('more-sheet');
    var btn = document.getElementById('bnav-more');
    if (sheet) sheet.setAttribute('aria-hidden', 'true');
    if (btn) btn.setAttribute('aria-expanded', 'false');
  };
  window.toggleMoreSheet = function () {
    root.classList.contains('more-sheet-open') ? window.closeMoreSheet() : window.openMoreSheet();
  };

  // "More" lights up when the current page lives inside the sheet. navigate()
  // already toggles .active on every [data-nav] element (sheet items included),
  // so this just mirrors that instead of hooking into navigation.
  function syncMoreActive() {
    var btn = document.getElementById('bnav-more');
    if (btn) btn.classList.toggle('active', !!document.querySelector('#more-sheet .more-sheet-item.active'));
  }

  // Ask Desk: three starter chips, the rest behind "More ideas"
  window.toggleMoreChips = function () {
    var row = document.getElementById('cd-chip-row');
    if (!row) return;
    var open = row.classList.toggle('show-all');
    var btn = row.querySelector('.cd-chip-more');
    if (btn) {
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
      btn.textContent = open ? 'Fewer' : 'More ideas';
    }
  };

  function init() {
    syncSidebarBtn();
    syncMoreActive();
    var sheet = document.getElementById('more-sheet');
    if (sheet && 'MutationObserver' in window) {
      new MutationObserver(syncMoreActive).observe(sheet, { subtree: true, attributes: true, attributeFilter: ['class'] });
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
